import { Book } from "@/lib/types";

export const isaiah: Book = {
  id: "isaiah",
  name: "Jesaja",
  shortName: "Jes",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Die Vision, die Jesaja*, der Sohn des Amoz*, über Juda und Jerusalem geschaut hat* in den Tagen von Usija, Jotam, Ahas, Hiskia, den Königen von Juda*.", heading: "Judas Gottvergessenheit und ihre Folgen", footnotes: ["d. h. der HERR hilft, o. der HERR ist Heil", "℘ 2Chr 26,22", "℘ Kap. 2,1; 13,1", "℘ Hos 1,1; Mt 1,8-10"] },
      { number: 2, text: "Höre, du Himmel, und horch auf, du Erde!* Denn der HERR hat geredet*: Ich habe Kinder großgezogen und auferzogen, sie aber haben mit mir gebrochen*.", footnotes: ["℘ 5Mo 32,1; Ps 50,4; Mi 1,1.2", "℘ Jer 6,19; 13,15; Hebr 1,1", "℘ Kap. 30,1; Jer 2,12.13"] },
      { number: 3, text: "Ein Rind kennt seinen Besitzer und ein Esel die Krippe seines Herrn. Israel aber hat keine Erkenntnis, mein Volk hat keine Einsicht*.", footnotes: ["℘ Kap. 27,11; Jer 4,22; 50,6"] },
      { number: 4, text: "Wehe, sündige Nation, schuldbeladenes Volk, Geschlecht* von Übeltätern, Verderben bringende Kinder!* Sie haben den HERRN verlassen*, haben den Heiligen Israels verworfen*, sie haben sich nach hinten abgewandt*. —", footnotes: ["w. Same", "℘ Kap. 30,9; 57,4; 2Chr 27,2", "℘ 2Kö 21,22", "℘ 5Mo 32,5.15; Ps 78,41", "℘ Ps 78,57; Jer 2,13; Zef 1,6"] },
      { number: 5, text: "Wohin wollt ihr noch geschlagen werden, die ihr eure Widerspenstigkeit nur vermehrt*? Das ganze Haupt ist krank, und das ganze Herz ist siech.", footnotes: ["℘ 2Chr 28,22"] },
      { number: 6, text: "Von der Fußsohle bis zum Haupt ist keine heile Stelle an ihm: Wunden und Striemen und frische Schläge; sie sind nicht ausgedrückt und nicht verbunden, noch mit Öl gelindert.*", footnotes: ["℘ Jer 6,7; 8,22; Lk 10,34"] },
      { number: 7, text: "Euer Land ist eine Öde, eure Städte sind mit Feuer verbrannt; euer Ackerland — Fremde verzehren seine Frucht vor euren Augen; eine Öde ist es wie bei einer Umkehrung durch Fremde*.*", footnotes: ["Mit Änderung zweier Buchstaben übersetzen andere: wie bei der Umkehrung von Sodom", "℘ 5Mo 28,33"] },
      { number: 8, text: "Und die Tochter Zion ist übrig geblieben wie eine Laubhütte im Weinberg, wie eine Nachthütte im Gurkenfeld, wie eine belagerte Stadt*.", footnotes: ["so mit LXX; Mas. T.: wie eine behütete o. bewachte Stadt\n℘ Kap. 29,3; 30,17"] },
      { number: 9, text: "Hätte der HERR der Heerscharen uns nicht einen ganz kleinen Rest gelassen*, wie Sodom wären wir, Gomorra wären wir gleich*.", footnotes: ["℘ Kap. 10,20; 24,6; 37,4", "℘ 1Mo 19,24.25; Röm 9,29"] },
      { number: 10, text: "Hört das Wort des HERRN, ihr Anführer von Sodom! Horcht auf die Weisung* unseres Gottes, Volk von Gomorra*!", heading: "Wahrer und falscher Gottesdienst", footnotes: ["o. das Gesetz", "℘ 5Mo 32,32; Jer 23,14"] },
      { number: 11, text: "Wozu soll mir die Menge eurer Schlachtopfer dienen?, spricht der HERR. Ich habe die Brandopfer von Widdern und das Fett der Mastkälber satt, und am Blut von Stieren, Lämmern und jungen Böcken habe ich kein Gefallen*.", footnotes: ["℘ 1Sam 15,22; Spr 15,8; 21,27; Jer 6,20; Hos 8,13; Am 4,5"] },
      { number: 12, text: "Wenn ihr kommt, um vor meinem Angesicht zu erscheinen — wer hat das von eurer Hand gefordert, meine Vorhöfe zu zertreten*?", footnotes: ["℘ Pred 4,17"] },
      { number: 13, text: "Bringt nicht länger nichtige* Speisopfer! Das Räucherwerk ist mir ein Gräuel*. Neumond* und Sabbat*, das Einberufen von Versammlungen*: Sünde* und Festversammlung ertrage ich nicht.", footnotes: ["o. heuchlerische", "℘ Kap. 66,3", "℘ 4Mo 28,10.14", "℘ Kap. 1,15", "℘ Joe 2,15", "o. abgöttischen Kult"] },
      { number: 14, text: "Eure Neumonde und eure Feste* hasst meine Seele*. Sie sind mir zur Last geworden, ich bin es müde, sie zu ertragen.", footnotes: ["℘ Kap. 29,1", "℘ Am 5,21"] },
      { number: 15, text: "Und wenn ihr eure Hände ausbreitet, verhülle ich meine Augen vor euch. Auch wenn ihr noch so viel betet, höre ich nicht* — eure Hände sind voll Blut*.", footnotes: ["℘ Spr 1,28; Jer 14,12; Joh 9,31", "℘ Kap. 59,2.3"] },
      { number: 16, text: "Wascht euch, reinigt euch*! Schafft mir eure bösen Taten aus den Augen, hört auf, Böses zu tun*!", footnotes: ["℘ Jer 4,14; Jak 4,8", "℘ Kap. 55,7; 2Kö 17,13"] },
      { number: 17, text: "Lernt Gutes tun*, fragt nach dem Recht*, weist den Unterdrücker zurecht*! Schafft Recht der Waise, führt den Rechtsstreit der Witwe*!", footnotes: ["℘ Tit 3,14", "℘ Spr 21,3; Hes 45,9", "w. leitet den Unterdrücker. — LXX, die aram., syr. und lat. Üs. lesen: leitet den Unterdrückten", "℘ V. 23; Kap. 10,2; 2Mo 22,21; Spr 15,25; Hes 22,7.27"] },
      { number: 18, text: "Kommt denn und lasst uns miteinander rechten*!, spricht der HERR. Wenn eure Sünden rot wie Karmesin sind, wie Schnee sollen sie weiß werden.* Wenn sie rot sind wie Purpur, wie Wolle sollen sie werden.*", heading: "Anklagen, Gerichtsankündigungen und Neuanfang", footnotes: ["℘ Kap. 3,13; 41,21; 43,26", "Manche fassen den Hauptsatz als Frage: können sie weiß werden wie Schnee?", "o. können sie wie Wolle werden?\n℘ Ps 51,9; Offb 3,4; 7,14"] },
      { number: 19, text: "Wenn ihr willig seid und hört, sollt ihr das Gute des Landes essen*.", footnotes: ["℘ Kap. 55,1.2; 3Mo 26,3-5; Jer 7,3"] },
      { number: 20, text: "Wenn ihr euch aber weigert und widerspenstig seid*, sollt ihr vom Schwert gefressen werden*. Denn der Mund des HERRN hat geredet*.", footnotes: ["℘ 2Mo 9,2", "℘ 3Mo 26,25; Hi 36,12", "℘ Kap. 40,5; 58,14"] },
      { number: 21, text: "Wie ist zur Hure geworden* die treue Stadt! Sie war voller Recht; Gerechtigkeit wohnte darin, und jetzt Mörder*!", footnotes: ["℘ Jer 2,20", "℘ Kap. 5,7; 26,10; Hes 22,3.4"] },
      { number: 22, text: "Dein Silber ist zu Schlacke geworden*, dein edler Wein* mit Wasser gepanscht.", footnotes: ["℘ Jer 6,30; Hes 22,18.22", "o. dein Weizenbier"] },
      { number: 23, text: "Deine Obersten sind Widerspenstige* und Diebesgesellen, jeder von ihnen liebt Bestechungen* und jagt Geschenken nach. Der Waise verschaffen sie nicht Recht, und der Rechtsstreit der Witwe kommt nicht vor sie*.", footnotes: ["℘ Kap. 28,14; Hos 9,15", "℘ 1Sam 8,3", "℘ V. 18"] },
      { number: 24, text: "Darum spricht der Herr, der HERR der Heerscharen*, der Mächtige Israels: Wehe! Ich werde mich weiden an meinen Gegnern* und Rache nehmen an meinen Feinden*.", footnotes: ["w. ist der Ausspruch des Herrn, des HERRN der Heerscharen", "w. ich werde mir Trost verschaffen an meinen Gegnern; d. h. an ihrer Bestrafung", "℘ 5Mo 28,63"] },
      { number: 25, text: "Und ich werde meine Hand gegen dich wenden und werde deine Schlacken ausschmelzen wie mit Pottasche und all deine Schlacke* beseitigen*.", footnotes: ["o. dein Zinn", "℘ Kap. 4,4"] },
      { number: 26, text: "Ich will deine Richter wiederherstellen wie in der ersten Zeit und deine Ratgeber wie im Anfang. Danach wird man dich nennen: Stadt der Gerechtigkeit*, treue Stadt*.", footnotes: ["℘ Kap. 33,5", "℘ Sach 8,3"] },
      { number: 27, text: "Zion wird erlöst werden durch Recht und die, die in ihm umkehren*, durch Gerechtigkeit.", footnotes: ["o. die zu ihm zurückkehren"] },
      { number: 28, text: "Aber Zerbruch trifft die Abtrünnigen und Sünder alle miteinander; und die den HERRN verlassen, werden umkommen*.", footnotes: ["℘ Kap. 64,6; Hi 34,26.27"] },
      { number: 29, text: "Denn sie werden* beschämt werden wegen der Terebinthen, die ihr begehrt*, und ihr werdet schamrot werden wegen der Gärten, die ihr erwählt habt*.", footnotes: ["3 Handschr. haben: ihr werdet", "℘ Kap. 57,5; 65,3; Hos 4,19", "℘ Kap. 1,15"] },
      { number: 30, text: "Denn ihr werdet sein wie eine Terebinthe, deren Laub verwelkt ist*, und wie ein Garten, der kein Wasser hat.", footnotes: ["℘ Kap. 64,5"] },
      { number: 31, text: "Und der Starke wird zu Werg werden und sein Tun zum Funken; und beide miteinander werden sie brennen, und niemand wird löschen*.", footnotes: ["℘ Kap. 66,24"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Das Wort, das Jesaja, der Sohn des Amoz, über Juda und Jerusalem geschaut hat*:", heading: "Das zukünftige Friedensreich", footnotes: ["℘ Mi 4,1-5", "℘ Kap. 1,1"] },
      { number: 2, text: "Und es wird geschehen am Ende der Tage, da wird der Berg des Hauses des HERRN fest stehen als Haupt* der Berge und erhaben sein über die Hügel*; und alle Nationen werden zu ihm strömen*.", footnotes: ["o. auf dem Gipfel", "℘ Ps 48,2.3; 68,17; 87,2; Hes 40,2", "℘ Kap. 60,3; 66,23; Jer 3,17; 16,19"] },
      { number: 3, text: "Und viele Völker werden hingehen und sagen: Kommt, lasst uns hinaufziehen zum Berg des HERRN, zum Haus des Gottes Jakobs*, dass er uns aufgrund seiner Wege belehre und wir auf seinen Pfaden gehen*! Denn von Zion wird Weisung* ausgehen und das Wort des HERRN von Jerusalem*.", footnotes: ["℘ Kap. 19,23; 44,5; 5Mo 33,19; Ps 102,23; Sach 8,21.22", "℘ Jer 12,16", "o. das Gesetz", "℘ Kap. 1,26; 11,10; Sach 2,15; Joh 4,22"] },
      { number: 4, text: "Und er wird richten zwischen den Nationen* und für viele Völker Recht sprechen*. Dann werden sie ihre Schwerter zu Pflugscharen umschmieden* und ihre Speere zu Winzermessern*. Nicht mehr wird Nation gegen Nation das Schwert erheben, und sie werden den Krieg nicht mehr lernen*.", footnotes: ["℘ Ps 96,13; 110,6", "℘ Kap. 11,4; 42,1", "w. ihre Schwerter in Stücke schlagen für Pflugscharen", "℘ Joe 4,10", "℘ Ps 46,10; Hos 2,20; Sach 9,10"] },
      { number: 5, text: "Haus Jakob, kommt, lasst uns im Licht des HERRN leben*!*", footnotes: ["w. gehen", "℘ Ps 36,10; 89,16; 1Jo 1,7"] },
      { number: 6, text: "Ja, du hast dein Volk, das Haus Jakob, aufgegeben*. Denn sie sind voll von Wahrsagern aus dem Osten und sind Zauberer wie die Philister*, und mit den Kindern der Fremden schlagen sie in die Hände*.", heading: "Gericht am Tag des HERRN", footnotes: ["℘ 5Mo 31,17; 2Kö 17,20", "℘ 5Mo 18,14; 1Sam 6,2; Mi 5,11", "o. sie haben Überfluss an fremden Kindern"] },
      { number: 7, text: "Sein Land wurde voll von Silber und Gold, und seine Schätze haben kein Ende. Sein Land wurde voll von Pferden, und seine Wagen haben kein Ende." },
      { number: 8, text: "Sein Land wurde voll von Götzen. Man wirft sich nieder vor dem Werk seiner Hände, vor dem, was seine Finger gemacht haben*.", footnotes: ["℘ Kap. 44,15-19; 2Kö 17,10.16; 2Chr 28,2; Jer 1,16"] },
      { number: 9, text: "Da wird der Mensch gebeugt und der Mann erniedrigt.* Und du mögest ihnen nicht vergeben*!", footnotes: ["Kap. 2,11.17 und Kap. 5,15 legen die obige Üs. nahe. Als Fortsetzung der Schilderung des Götzendienstes in Kap. 2,8 wäre auch die Üs. möglich: Da bückte sich der Mensch, und der Mann sank nieder.", "℘ Jos 24,19"] },
      { number: 10, text: "Verkriech dich in den Fels und halte dich im Staub versteckt vor dem Schrecken des HERRN und vor der Pracht seiner Majestät!" },
      { number: 11, text: "Die stolzen Augen des Menschen werden erniedrigt*, und der Hochmut des Mannes wird gebeugt werden. Aber der HERR wird hoch erhaben sein, er allein, an jenem Tag*.", footnotes: ["℘ Kap. 5,15; 10,12; 13,11; 14,15; 23,9; 40,23; Ps 18,28; 94,2; Spr 16,5; Jer 12,9; Mt 23,12", "℘ Kap. 5,16; Ps 46,11"] },
      { number: 12, text: "Denn der HERR der Heerscharen hat sich einen Tag* vorbehalten über alles Hochmütige und Hohe und über alles Erhabene, dass es erniedrigt werde*;", footnotes: ["℘ Kap. 13,6.9; Ps 37,13; Jer 46,10; 50,31", "℘ Kap. 5,15; 10,12; 13,11; 14,15; 23,9; 40,23; Ps 18,28; 94,2; Spr 16,5; Jer 12,9; Mt 23,12"] },
      { number: 13, text: "über alle Zedern des Libanon, die hohen und erhabenen*, und über alle Eichen Baschans*;", footnotes: ["℘ Kap. 10,33.34; Ps 29,5", "℘ Sach 11,2"] },
      { number: 14, text: "über alle hohen Berge und über alle erhabenen Hügel;" },
      { number: 15, text: "über jeden hohen Turm* und über jede steile Mauer;", footnotes: ["℘ Kap. 30,25; Zef 1,16"] },
      { number: 16, text: "über alle Tarsisschiffe* und über alle kostbaren Boote.", footnotes: ["d. h. große Überseeschiffe, die nach Tarsis (vermutlich in Südspanien) fahren\n℘ Kap. 23,1.14; 60,9"] },
      { number: 17, text: "Und der Stolz des Menschen wird gebeugt und der Hochmut des Mannes erniedrigt werden. Und der HERR wird hoch erhaben sein, er allein, an jenem Tag*.", footnotes: ["℘ Kap. 5,16; Ps 46,11"] },
      { number: 18, text: "Und die Götzen* — mit ihnen ist es völlig aus*.", footnotes: ["w. die Nichtse", "℘ Jer 10,11; 51,18; Hes 6,6; Sach 13,2"] },
      { number: 19, text: "Da wird man sich in Felsenhöhlen und in Erdlöchern verkriechen vor dem Schrecken des HERRN und vor der Pracht seiner Majestät, wenn er sich aufmacht, die Erde zu schrecken*.", footnotes: ["℘ Hos 10,8; Offb 6,15"] },
      { number: 20, text: "An jenem Tag wird der Mensch seine silbernen Götzen und seine goldenen Götzen, die man ihm zum Anbeten gemacht hat, den Spitzmäusen und den Fledermäusen hinwerfen,*", footnotes: ["o. Wird der Mensch seine . . . Götzen . . . wegwerfen, die man ihm gemacht hat, damit er sich niederwerfe vor ihnen, den »Spitzmäusen« und »Fledermäusen« . . .?\n℘ Kap. 10,3; 30,22; 31,7; 1Mo 35,4; Zef 2,11"] },
      { number: 21, text: "um sich in die Felsspalten und Steinklüfte zu verkriechen vor dem Schrecken des HERRN und vor der Pracht seiner Majestät*, wenn er sich aufmacht, die Erde zu schrecken*.", footnotes: ["℘ 2Thes 1,9", "℘ Hos 10,8; Offb 6,15"] },
      { number: 22, text: "Lasst ab vom Menschen, in dessen Nase nur ein Hauch* ist*! Denn wofür ist er zu achten*?", footnotes: ["o. Atem", "℘ Ps 146,3.4", "℘ Ps 144,3.4"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Denn siehe, der Herr, der HERR der Heerscharen, nimmt von Jerusalem und von Juda Stütze und Stab hinweg, jede Stütze des Brotes* und jede Stütze des Wassers*:", heading: "Gericht über die politischen und geistlichen Führer Jerusalems und die reichen Frauen", footnotes: ["s. Anm. zu Ps 105,16", "℘ 3Mo 26,26; 2Kö 25,3"] },
      { number: 2, text: "Held und Kriegsmann*, Richter und Prophet und Wahrsager und Ältesten;", footnotes: ["℘ 1Chr 9,1"] },
      { number: 3, text: "den Obersten von fünfzig Mann und den Angesehenen und den Ratgeber und den geschickten Zauberer* und den Beschwörungskünstler.", footnotes: ["o. den geschickten Handwerker"] },
      { number: 4, text: "Dann mache ich junge Männer zu ihren Obersten, und Mutwillige sollen über sie herrschen*.", footnotes: ["℘ Pred 10,16"] },
      { number: 5, text: "Da wird sich das Volk bedrängen, Mann gegen Mann und jeder gegen seinen Nächsten*. Sie werden frech auftreten, der Junge gegen den Alten* und der Verachtete gegen den Geehrten.", footnotes: ["℘ Kap. 9,18.19; 19,2; Sach 11,6", "℘ Mi 7,2.3.6"] },
      { number: 6, text: "Dann wird jemand seinen Bruder im Haus seines Vaters packen und sagen: Du hast noch einen Mantel, Anführer sollst du uns sein! Und dieser Trümmerhaufen sei unter deiner Hand!" },
      { number: 7, text: "Doch der wird an jenem Tag seine Stimme erheben: Ich will kein Wundarzt sein, und in meinem Haus ist kein Brot und kein Mantel. Macht mich nicht zum Anführer des Volkes! —" },
      { number: 8, text: "Denn Jerusalem ist gestürzt und Juda gefallen, weil ihre Zunge und ihre Taten gegen den HERRN sind*, um den Augen seiner Herrlichkeit zu trotzen*.", footnotes: ["℘ Jer 23,36", "℘ Kla 5,16; Mal 3,13"] },
      { number: 9, text: "Dass sie die Person* ansehen, zeugt gegen sie*. Und von ihrer Sünde sprechen sie offen wie Sodom, sie verschweigen sie nicht*. Wehe ihrer Seele! Denn sich selbst tun sie Böses an*.", footnotes: ["Andere üs.: die Frechheit ihrer Gesichter", "℘ Hos 5,5", "℘ 1Mo 18,20", "℘ Jer 2,19"] },
      { number: 10, text: "Sagt vom Gerechten, dass es ihm gut gehen wird*, denn die Frucht ihrer Taten werden sie genießen*.", footnotes: ["Die meisten nehmen ein Abschreibversehen an und übersetzen: Heil dem Gerechten, denn es geht ihm gut; vgl. V. 11\n℘ Jer 22,15", "℘ Ps 58,12; 128,2"] },
      { number: 11, text: "Wehe dem Gottlosen! Es wird ihm schlecht gehen, denn das Tun seiner Hände wird ihm vergolten*.", footnotes: ["℘ Kap. 13,11; 4Mo 32,23; Ri 9,57; 2Sam 3,39; 1Kö 21,21; Hi 10,15; Spr 26,27"] },
      { number: 12, text: "Ach, mein Volk, seine Antreiber* sind Mutwillige, und Frauen* beherrschen es. Mein Volk, deine Führer sind Verführer*, und den Weg, den du gehen sollst*, verwirren sie*.", footnotes: ["o. Machthaber", "LXX: Wucherer", "℘ Kap. 9,15", "w. den Weg deiner Pfade", "℘ Mi 3,5"] },
      { number: 13, text: "Der HERR steht da zum Rechtsstreit*, und er tritt auf, um die Völker* zu richten.", footnotes: ["℘ Kap. 1,18; Mi 6,1.2", "Die griech. und syr. Üs. lesen: mein Volk"] },
      { number: 14, text: "Der HERR wird ins Gericht gehen mit den Ältesten seines Volkes und dessen Obersten: Ihr, ihr habt den Weinberg abgeweidet*, das dem Elenden Geraubte ist in euren Häusern*.", footnotes: ["℘ Jer 12,10", "℘ 3Mo 25,17; Jer 5,27; Mi 2,1.2"] },
      { number: 15, text: "Was fällt euch ein? Mein Volk zertretet ihr, und das Gesicht der Elenden zermalmt ihr*!, spricht der Herr, der HERR der Heerscharen*.", footnotes: ["℘ Am 2,7; Mi 3,3", "w. ist der Ausspruch des Herrn, des HERRN der Heerscharen"] },
      { number: 16, text: "Und der HERR sprach: Weil die Töchter Zions hochmütig sind* und mit hochgerecktem Hals dahergehen und verführerische Blicke werfen*, weil sie trippelnd einherstolzieren und mit ihren Fußspangen klirren:", footnotes: ["℘ Spr 21,4", "o. sich die Augen schminken"] },
      { number: 17, text: "deshalb wird der Herr den Scheitel der Töchter Zions grindig machen, und der HERR wird ihre Stirn* entblößen*.", footnotes: ["o. ihre Scham", "℘ Kap. 47,3"] },
      { number: 18, text: "An jenem Tag wird der Herr wegnehmen den Schmuck der Fußspangen und Stirnbänder* und Halbmonde*;", footnotes: ["o. der Sönnchen", "℘ Ri 8,21.26"] },
      { number: 19, text: "die Ohrgehänge* und Armketten und Schleier;", footnotes: ["℘ 2Mo 32,2.3"] },
      { number: 20, text: "die Kopfbunde und Schrittkettchen und Gürtel und Riechfläschchen* und Amulette;", footnotes: ["w. die Gehäuse der Seele"] },
      { number: 21, text: "die Fingerringe und Nasenringe*;", footnotes: ["℘ 1Mo 24,47; Hes 16,12"] },
      { number: 22, text: "die Prachtkleider* und Mäntel und Umschlagtücher und Beutel;", footnotes: ["℘ 1Petr 3,3"] },
      { number: 23, text: "die Handspiegel* und Hemden und Turbane und Überwürfe*.", footnotes: ["℘ 2Mo 38,8", "d. h. weite Schleier, die über Kopf und Schulter geworfen werden"] },
      { number: 24, text: "Und es wird geschehen, statt des Wohlgeruchs* wird Moder sein und statt des Gürtels ein Strick, statt des Lockenwerks eine Glatze* und statt des Prunkgewandes ein umgürteter Sack*, ein Brandmal statt Schönheit.", footnotes: ["o. Balsamöls", "℘ Kap. 15,2.3", "℘ Jer 6,26"] },
      { number: 25, text: "Deine Männer werden durchs Schwert fallen und deine Helden im Krieg*.", footnotes: ["℘ 2Chr 28,6"] },
      { number: 26, text: "Da werden ihre* Tore klagen und trauern*, und vereinsamt sitzt sie am Boden*.", footnotes: ["d. h. der Tochter Zion", "℘ Kap. 32,14; Kla 1,4", "℘ Kla 2,10"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und an jenem Tag werden sieben Frauen einen Mann ergreifen und sagen: Wir wollen unser eigenes Brot essen und uns mit unserem eigenen Mantel bekleiden. Wenn nur dein Name über uns ausgerufen wird! Nimm unsere Schmach hinweg*!", footnotes: ["℘ Kap. 54,4; 1Mo 30,23"] },
      { number: 2, text: "An jenem Tag wird der Spross des HERRN zur Zierde und zur Herrlichkeit sein* und die Frucht des Landes* zum Stolz und zum Schmuck* für die Entkommenen Israels.", heading: "Der geheiligte Rest in Zion", footnotes: ["℘ Kap. 11,1; Jer 23,5; Sach 3,8; 6,12", "o. der Erde", "o. Ruhm"] },
      { number: 3, text: "Und es wird geschehen: Wer in Zion übrig geblieben und wer in Jerusalem übrig gelassen ist, wird heilig heißen*, jeder, der zum Leben aufgeschrieben ist* in Jerusalem.", footnotes: ["℘ Kap. 6,13; 60,21; Joe 4,17", "℘ 2Mo 32,32.33; Sach 14,2"] },
      { number: 4, text: "Wenn der Herr den Kot der Töchter Zions abgewaschen und die Blutschuld Jerusalems aus dessen Mitte hinweggespült hat* durch den Geist des Gerichts und durch den Geist des Ausrottens*,", footnotes: ["℘ Jer 9,6", "o. des Niederbrennens o. Säuberns\n℘ Kap. 1,25; 27,9; Mal 3,2"] },
      { number: 5, text: "dann wird der HERR über der ganzen Stätte des Berges Zion und über seinen* Versammlungen* eine Wolke schaffen bei Tag und Rauch sowie Glanz eines flammenden Feuers bei Nacht*; denn über der ganzen Herrlichkeit wird ein Schutzdach sein.", footnotes: ["d. i. Zions", "℘ Kap. 33,20", "℘ 2Mo 13,21; 40,34; Sach 2,9"] },
      { number: 6, text: "Und ein Laubdach* wird zum Schatten dienen bei Tag vor der Hitze, und als Zuflucht und Obdach vor Wolkenbruch und Regen*.", footnotes: ["o. eine Laubhütte", "℘ Kap. 25,4; 30,30; 32,2"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Singen will ich von meinem Freund*, das Lied meines Liebsten von seinem Weinberg*: Einen Weinberg hatte mein Freund auf einem fetten Hügel*.", heading: "Gleichnis vom unfruchtbaren Weinberg", footnotes: ["o. für meinen Freund", "℘ Kap. 27,2; Hes 19,10", "w. Horn; d. h. einem freistehenden Hügel\n℘ 5Mo 8,7-10"] },
      { number: 2, text: "Und er grub ihn um und säuberte ihn von Steinen und bepflanzte ihn mit Edelreben*. Er baute einen Turm in seine Mitte* und hieb auch eine Kelterkufe darin aus. Dann erwartete er, dass er Trauben bringe. Doch er brachte schlechte Beeren.", footnotes: ["℘ Ps 80,9; Jer 2,21", "℘ Mt 21,33"] },
      { number: 3, text: "Und nun, Bewohner von Jerusalem und Männer von Juda, richtet doch zwischen mir und meinem Weinberg*!", footnotes: ["℘ Mi 6,2.3"] },
      { number: 4, text: "Was war an meinem Weinberg noch zu tun, und ich hätte es nicht an ihm getan? Warum habe ich erwartet, dass er Trauben bringe, und er brachte schlechte Beeren?" },
      { number: 5, text: "Nun, so will ich euch denn mitteilen, was ich mit meinem Weinberg tun werde: Seinen Zaun will ich entfernen, dass er abgeweidet wird, seine Mauer niederreißen, dass er zertreten wird*.", footnotes: ["℘ Ps 80,13; 89,41; Jer 45,4; Hos 2,14"] },
      { number: 6, text: "Ich werde ihn zur Wüstenei machen. Er soll nicht beschnitten und nicht behackt werden, in Dornen und Disteln soll er aufgehen*. Und ich will den Wolken befehlen, dass sie keinen Regen auf ihn regnen lassen.", footnotes: ["℘ Kap. 32,13.14; Spr 24,31; Kla 2,6"] },
      { number: 7, text: "Denn der Weinberg des HERRN der Heerscharen ist das Haus Israel, und die Männer von Juda sind die Pflanzung seiner Lust*. Und er wartete auf Rechtsspruch, und siehe da: Rechtsbruch; auf Gerechtigkeit, und siehe da: Geschrei über Schlechtigkeit*.", footnotes: ["℘ Hos 10,1; Mt 21,45", "w. siehe da: Klagegeschrei. — Im Hebr. findet sich ein Wortspiel, das die Üs. nachzuahmen versucht.\n℘ Kap. 1,21; 46,12; Neh 5,1; Lk 20,10"] },
      { number: 8, text: "Wehe denen, die Haus an Haus reihen, Feld an Feld rücken, bis kein Raum mehr ist und ihr allein ansässig seid* mitten im Land*!", heading: "Sechs Weherufe über Juda", footnotes: ["d. h. allein Grundbesitzer seid", "℘ Mi 2,1.2; Hab 2,6"] },
      { number: 9, text: "So hat der HERR der Heerscharen in meine Ohren geschworen*: Wenn nicht die vielen Häuser zur Einöde werden und die großen und schönen ohne Bewohner sind*!", footnotes: ["℘ Kap. 22,14", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte, eine Verwünschung, nicht ausgesprochen wurde.\n℘ Hi 20,21; Spr 15,27"] },
      { number: 10, text: "Denn zehn Joch Weinberge werden nur ein Bat bringen, und ein Homer Samen wird nur ein Efa* bringen*. —", footnotes: ["1 Homer = 12 Efa; s. Tabelle »Maße«", "℘ Hag 1,6-10"] },
      { number: 11, text: "Wehe denen, die sich früh am Morgen aufmachen, um Rauschtrank nachzujagen, die bis spät am Abend bleiben*, dass der Wein sie erhitze*!", footnotes: ["℘ V. 22; Pred 10,16", "℘ Spr 20,1"] },
      { number: 12, text: "Zither und Harfe, Tamburin und Flöte und Wein gehören zu ihrem Gelage*. Aber auf das Tun des HERRN schauen sie nicht, und das Werk seiner Hände sehen sie nicht*.", footnotes: ["℘ Kap. 22,13; Am 6,4-6", "℘ Ps 28,5; Lk 21,34"] },
      { number: 13, text: "Darum wird mein Volk gefangen wegziehen aus Mangel an Erkenntnis*. Seine Vornehmen* sind Hungerleider*, und seine lärmende Menge ist ausgedörrt vor Durst*.", footnotes: ["℘ Spr 10,21", "w. Seine Ehre", "w. Männer des Hungers. — Andere nehmen an, dass der Text ursprünglich lautete: sind entkräftet vor Hunger", "℘ Kla 4,4"] },
      { number: 14, text: "Darum sperrt der Scheol seinen Schlund weit auf und reißt seinen Rachen auf ohne Maß*. Und hinab fährt seine* Pracht und sein Getümmel und sein Lärm* und wer darin jauchzt.", footnotes: ["o. Ordnung\n℘ Spr 27,20; 30,16", "d. i. Jerusalems", "d. h. seine Volksmenge, sein ausgelassenes Treiben"] },
      { number: 15, text: "Da wird der Mensch gebeugt und der Mann erniedrigt, und die Augen der Hochmütigen werden erniedrigt*.", footnotes: ["℘ Kap. 2,9.11.17"] },
      { number: 16, text: "Und der HERR der Heerscharen wird im Gericht erhaben sein*, und Gott, der Heilige, sich heilig erweisen in Gerechtigkeit*. —", footnotes: ["℘ Kap. 2,9.11.17", "℘ 4Mo 20,13; Hes 28,22; Offb 15,4"] },
      { number: 17, text: "Und Lämmer werden dort weiden wie auf ihrer Trift*, und Ziegen nähren sich in den Trümmerstätten der Vertriebenen*.", footnotes: ["℘ Kap. 7,25", "so mit LXX; Mas. T.: Und Fremde essen die Trümmerstätten der Fettschafe\n℘ Kla 5,2"] },
      { number: 18, text: "Wehe denen, die die Schuld herbeiziehen mit Stricken des Nichts, und die Sünde wie mit Wagenseilen!" },
      { number: 19, text: "Die da sagen: Es eile, es komme rasch sein Werk, damit wir es sehen! Und der Ratschluss des Heiligen Israels nahe heran und komme, damit wir ihn erkennen*!", footnotes: ["℘ Kap. 66,5; Jer 17,15; Am 5,18"] },
      { number: 20, text: "Wehe denen, die das Böse gut nennen und das Gute böse*; die Finsternis zu Licht machen und Licht zu Finsternis; die Bitteres zu Süßem machen und Süßes zu Bitterem*!", footnotes: ["℘ 5Mo 25,1; Hes 13,19; Mi 3,2", "℘ Kap. 32,5; Spr 4,17; Am 5,7"] },
      { number: 21, text: "Wehe denen, die in ihren eigenen Augen weise sind und sich selbst für verständig halten*!", footnotes: ["℘ Kap. 10,13; Spr 3,7"] },
      { number: 22, text: "Wehe denen, die Helden sind im Weintrinken und tapfere Männer im Mischen von Rauschtrank*;", footnotes: ["℘ V. 11; Kap. 56,12; 1Kö 20,16"] },
      { number: 23, text: "die den Ungerechten* wegen eines Bestechungsgeschenkes gerecht sprechen, den Gerechten aber ihre Gerechtigkeit absprechen*!*", footnotes: ["o. den Gottlosen", "w. von den Gerechten . . . entfernen", "℘ Kap. 10,2; 28,7; 29,21; 32,7; 2Mo 23,6-8; Spr 17,23; 31,5"] },
      { number: 24, text: "Darum, wie des Feuers Zunge die Stoppeln verzehrt und dürres Gras in der Flamme zusammensinkt, so wird ihre Wurzel wie Moder werden und ihre Blüte auffliegen wie Staub*. Denn sie haben das Gesetz des HERRN der Heerscharen verworfen und das Wort des Heiligen Israels verschmäht*.", footnotes: ["℘ Kap. 9,17; 2Mo 15,7; Hi 18,16", "℘ Kap. 30,9-13; Jer 6,19; Am 2,4.9"] },
      { number: 25, text: "Darum ist der Zorn des HERRN gegen sein Volk entbrannt, und er hat seine Hand gegen sie ausgestreckt und sie geschlagen*. Und die Berge erbebten*, und ihre Leichen lagen wie Kehricht mitten auf den Straßen*. Bei alledem hat sein Zorn sich nicht gewandt, und noch ist seine Hand ausgestreckt.", footnotes: ["℘ 5Mo 31,17; Hes 6,14; 15,6", "℘ Jer 4,24", "℘ Kap. 9,11; 3Mo 26,18.21; Hi 9,13; Jer 4,8; 6,12"] },
      { number: 26, text: "Und er wird ein Feldzeichen aufrichten für die Nation in der Ferne*, und er wird sie herbeipfeifen vom Ende der Erde; und siehe, eilends, schnell wird sie kommen*.", heading: "Gott ruft den assyrischen Feind zum Gericht herbei", footnotes: ["Mas. T.: für die Nationen von fern", "℘ Kap. 7,18.19; 10,3; 5Mo 28,49; Jer 5,15"] },
      { number: 27, text: "Kein Erschöpfter und kein Stürzender ist bei ihr; nicht schlummert noch schläft sie; keinem löst sich der Gürtel* von seinen Lenden, und keinem zerreißt der Riemen seiner Schuhe.", footnotes: ["w. keinem öffnet sich der Hüftschurz"] },
      { number: 28, text: "Ihre Pfeile sind geschärft und all ihre Bogen gespannt, die Hufe ihrer Pferde sind Kieselsteinen gleich und ihre Räder gleich dem Wirbelwind*.", footnotes: ["℘ Jer 47,3"] },
      { number: 29, text: "Ihr Gebrüll ist wie das einer Löwin, sie brüllt wie die Junglöwen*. Und sie knurrt* und packt die Beute und bringt sie in Sicherheit, und kein Retter ist da*.", footnotes: ["℘ Jer 2,15", "o. tost. — Das Hebr. hat hier für »Knurren« und »Tosen« nur ein Wort; vgl. in V. 30: wie das Tosen des Meeres", "℘ Kap. 42,22"] },
      { number: 30, text: "Und sie knurrt* über ihr an jenem Tag wie das Tosen des Meeres*. Dann blickt man zur Erde, und siehe, angstvolle Finsternis; und das Licht ist verfinstert durch ihr* Gewölk*.", footnotes: ["o. tost. — Das Hebr. hat hier für »Knurren« und »Tosen« nur ein Wort; vgl. in V. 30: wie das Tosen des Meeres", "℘ Kap. 17,12; Jer 6,23", "d. h. der Erde", "℘ Kap. 8,22; Jer 4,23"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Im Todesjahr des Königs Usija*, da sah ich den Herrn sitzen auf hohem und erhabenem Thron*, und die Säume seines Gewandes füllten den Tempel.", heading: "Jesajas Berufung zum Propheten", footnotes: ["℘ 2Chr 26,23", "℘ 1Kö 22,19"] },
      { number: 2, text: "Serafim standen über ihm. Jeder von ihnen hatte sechs Flügel: mit zweien bedeckte er sein Gesicht, mit zweien bedeckte er seine Füße, und mit zweien flog er*.", footnotes: ["℘ Hes 1,11"] },
      { number: 3, text: "Und einer rief dem andern zu und sprach: Heilig, heilig, heilig ist der HERR der Heerscharen*! Die ganze Erde ist erfüllt mit seiner Herrlichkeit*!*", footnotes: ["℘ 2Mo 15,11; Ps 99,9; 1Petr 1,15", "so mit der griech., syr. und lat. Üs.; Mas. T.: Seine Herrlichkeit ist das, was die Erde erfüllt; o. Die Fülle der ganzen Erde ist seine Herrlichkeit.", "℘ Kap. 40,5; Ps 8,2; 72,19; Hes 43,2; Joh 12,41"] },
      { number: 4, text: "Da erbebten die Türpfosten* in den Schwellen* von der Stimme des Rufenden, und das Haus wurde mit Rauch erfüllt*.", footnotes: ["w. die Zapfen in den Türangelsteinen", "℘ Am 9,1", "℘ 1Kö 8,10-12; Offb 4,8; 15,8"] },
      { number: 5, text: "Da sprach ich: Wehe mir, denn ich bin verloren*. Denn ein Mann mit unreinen Lippen bin ich*, und mitten in einem Volk mit unreinen Lippen wohne ich. Denn meine Augen haben den König, den HERRN der Heerscharen*, gesehen*.", footnotes: ["o. ich werde vernichtet; o. ich muss verstummen\n℘ Kap. 24,16", "℘ 2Mo 6,12; Hi 42,5.6", "℘ Ps 24,10", "℘ 2Mo 3,6; Ri 6,22"] },
      { number: 6, text: "Da flog einer der Serafim zu mir; und in seiner Hand war eine glühende Kohle, die er mit einer Zange vom Altar genommen hatte." },
      { number: 7, text: "Und er berührte damit meinen Mund* und sprach: Siehe, dies hat deine Lippen berührt; so ist deine Schuld gewichen und deine Sünde gesühnt*.", footnotes: ["℘ Dan 10,16", "o. bedeckt\n℘ Zef 3,9; Sach 3,4"] },
      { number: 8, text: "Und ich hörte die Stimme des Herrn, der sprach: Wen soll ich senden, und wer wird für uns gehen*? Da sprach ich: Hier bin ich, sende mich!", footnotes: ["℘ 1Kö 22,20"] },
      { number: 9, text: "Und er sprach: Geh hin und sprich zu diesem Volk: Hören, ja, hören sollt ihr und nicht verstehen! Sehen, ja, sehen sollt ihr und nicht erkennen*!", footnotes: ["℘ Kap. 42,20; 43,8; Lk 8,10; 19,42"] },
      { number: 10, text: "Mache das Herz dieses Volkes fett*, mache seine Ohren schwerhörig und verklebe seine Augen*, damit es mit seinen Augen nicht sieht und mit seinen Ohren nicht hört und sein Herz nicht einsichtig wird und es nicht umkehrt und Heilung für sich findet*!", footnotes: ["d. h. mache unempfindlich\n℘ Ps 119,70", "℘ Kap. 29,9.10; 2Kor 3,14", "℘ Kap. 28,13; 5Mo 29,3; Mt 13,13-15; Joh 12,40"] },
      { number: 11, text: "Da sagte ich: Wie lange, Herr? Und er sprach: Bis die Städte verwüstet sind, ohne Bewohner, und die Häuser ohne Menschen und das Land zur Öde verwüstet ist*.", footnotes: ["℘ 3Mo 26,33; Mi 7,13"] },
      { number: 12, text: "Der HERR wird die Menschen weit fortschicken, und die Verlassenheit mitten im Land wird groß sein." },
      { number: 13, text: "Und ist noch ein Zehntel darin, so wird es wieder dem Niederbrennen* verfallen* wie die Terebinthe und wie die Eiche, an denen beim Fällen ein Stumpf bleibt* — ein heiliger Same ist sein Stumpf*.", footnotes: ["o. dem Abweiden durch Schaf- und Ziegenherden", "℘ 5Mo 28,62", "℘ Hi 14,7-9; Hes 6,8", "o. an denen, wenn sie gefällt sind, ein neuer Trieb kommt — ein heiliger Same ist sein neuer Trieb\n℘ Kap. 4,3; 10,22; 65,8.9; Esr 9,8; Zef 3,12.13; Sach 13,8; Röm 11,16"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und es geschah in den Tagen des Ahas*, des Sohnes Jotams, des Sohnes Usijas, des Königs von Juda, da zog Rezin, der König von Aram, und Pekach, der Sohn des Remalja*, der König von Israel, nach Jerusalem hinauf zum Kampf gegen es*; aber er konnte nicht gegen es kämpfen*.", heading: "Des Königs Ahas Verzagtheit und Unglaube — Verheißung des Immanuel", footnotes: ["℘ 2Kö 16,1", "℘ Kap. 8,6; 2Kö 15,27", "℘ 2Chr 28,5.6", "℘ 2Kö 16,5"] },
      { number: 2, text: "Als nun dem Haus David gemeldet wurde: Aram hat sich auf dem Gebiet von Ephraim niedergelassen, da bebte sein Herz und das Herz seines Volkes, wie die Bäume des Waldes vor dem Wind beben." },
      { number: 3, text: "Der HERR aber sprach zu Jesaja: Geh doch hinaus, Ahas* entgegen, du und dein Sohn Schear-Jaschub*, an das Ende der Wasserleitung des oberen Teiches*, zur Straße des Walkerfeldes*,", footnotes: ["℘ 2Kö 16,1", "d. h. ein Rest kehrt um; vgl. Kap. 10,21", "℘ Kap. 22,10.11", "℘ Kap. 36,2; 2Kö 18,17"] },
      { number: 4, text: "und sage ihm: Hüte dich und halte dich ruhig*! Fürchte dich nicht, und dein Herz verzage nicht vor diesen beiden Stummeln, diesen qualmenden Holzstücken, nämlich vor der Zornglut Rezins und Arams und des Sohnes Remaljas*!", footnotes: ["℘ Kap. 30,15; Kla 3,26", "℘ Kap. 8,6; 2Kö 15,27"] },
      { number: 5, text: "Weil Aram Böses gegen dich beschlossen hat ebenso wie Ephraim und der Sohn des Remalja, indem sie sagen:" },
      { number: 6, text: "»Lasst uns gegen Juda hinaufziehen und ihm Grauen einjagen* und es für uns erobern* und dort den Sohn des Tabeal zum König machen!«,", footnotes: ["o. es auseinanderreißen", "w. aufbrechen; o. spalten; gemeint sind die Mauern von Jerusalem"] },
      { number: 7, text: "so spricht der Herr, HERR: Es wird nicht zustande kommen und nicht geschehen*.", footnotes: ["℘ Kap. 8,10"] },
      { number: 8, text: "Denn das Haupt von Aram ist Damaskus*, und das Haupt von Damaskus ist Rezin — und noch 65 Jahre, dann ist Ephraim zerschlagen, dann ist es kein Volk mehr* —,", footnotes: ["℘ Hes 27,18", "℘ 2Kö 17,23; Hos 13,1"] },
      { number: 9, text: "und das Haupt von Ephraim ist Samaria und das Haupt von Samaria ist der Sohn des Remalja*. Glaubt ihr nicht, dann bleibt ihr nicht*!", footnotes: ["℘ Kap. 8,6; 2Kö 15,27", "w. Wenn ihr mich nicht als zuverlässig anseht, werdet ihr euch nicht als zuverlässig erweisen; im Hebr. ein starker Gleichklang der Wörter\n℘ Röm 11,20"] },
      { number: 10, text: "Und der HERR fuhr fort, zu Ahas* zu reden, und sprach:", footnotes: ["℘ 2Kö 16,1"] },
      { number: 11, text: "Fordere dir ein Zeichen* vom HERRN, deinem Gott*! In der Tiefe fordere es* oder oben in der Höhe*!", footnotes: ["℘ 2Kö 19,29", "℘ Kap. 38,7.22; Ri 6,36-40; 1Kö 13,3", "3 griech. Üs. lesen: In der Tiefe der Totenwelt", "℘ Mt 12,38"] },
      { number: 12, text: "Ahas aber sagte: Ich will nicht fordern und will den HERRN nicht prüfen." },
      { number: 13, text: "Da sprach er*: Hört doch, Haus David! Ist es euch zu wenig, Menschen zu ermüden, dass ihr auch meinen Gott ermüdet*?", footnotes: ["d. h. Jesaja", "℘ Kap. 43,24"] },
      { number: 14, text: "Darum wird der Herr selbst euch ein Zeichen geben*: Siehe, die Jungfrau* wird schwanger werden und* einen Sohn gebären* und wird seinen Namen Immanuel* nennen*.", footnotes: ["℘ Kap. 38,7.22; Ri 6,36-40; 1Kö 13,3", "o. die junge Frau, das Mädchen", "o. ist schwanger und wird", "℘ Mi 5,2; Lk 1,31.35; Offb 12,5", "d. h. Gott mit uns", "℘ Kap. 8,8.10; Ps 46,8; Mt 1,23"] },
      { number: 15, text: "Rahm* und Honig wird er essen*, bis er weiß, das Böse zu verwerfen und das Gute zu wählen.", footnotes: ["o. dicke Milch; o. Butter", "℘ V. 22"] },
      { number: 16, text: "Denn ehe der Junge weiß, das Böse zu verwerfen und das Gute zu wählen, wird das Land verlassen sein, vor dessen beiden Königen dir graut*.", footnotes: ["℘ Kap. 8,4; 2Kö 15,29.30; 16,9"] },
      { number: 17, text: "Der HERR wird über dich, über dein Volk und über das Haus deines Vaters Tage kommen lassen, wie sie nicht gekommen sind seit dem Tag, an dem Ephraim sich von Juda getrennt hat*: den König von Assur*.", footnotes: ["w. Ephraim von Juda abgewichen ist\n℘ 1Kö 12,19", "℘ Kap. 8,7.8; 36,1; 2Kö 18,13"] },
      { number: 18, text: "Und es wird geschehen an jenem Tag, da wird der HERR die Fliege, die am Ende der Ströme* Ägyptens, und die Biene, die im Land Assur ist, herbeipfeifen*.", footnotes: ["Das hebr. Wort bezeichnet die Kanäle und Arme des Nil.", "℘ Kap. 5,26; Ps 105,31"] },
      { number: 19, text: "Dann werden sie kommen und sich alle niederlassen in den Tälern der Schluchten und in den Spalten der Felsen, in allen Dornsträuchern und an allen Tränkplätzen." },
      { number: 20, text: "An jenem Tag wird der Herr durch das Schermesser, das auf der anderen Seite des Stromes angeheuert wurde, nämlich durch den König von Assur*, das Haupt scheren und das Haar der Beine*, ja, auch den Bart wird es wegnehmen*.", footnotes: ["℘ Kap. 8,7.8; 36,1; 2Kö 18,13", "w. Haar der Füße; verhüllende Rede für »Schamhaare«", "℘ Kap. 9,13.14; 10,5.6; Hes 5,1"] },
      { number: 21, text: "An jenem Tag wird es geschehen, da wird einer* eine junge Kuh und zwei Schafe* am Leben erhalten.", footnotes: ["o. jeder", "o. Ziegen"] },
      { number: 22, text: "Und es wird geschehen, wegen der Menge der Milch, die sie geben, wird er Rahm* essen, ja, Rahm und Honig wird jeder essen, der im Land übrig geblieben ist.", footnotes: ["o. dicke Milch; o. Butter"] },
      { number: 23, text: "Und es wird an jenem Tag geschehen, dass jeder Ort, wo tausend Weinstöcke im Wert von tausend Silberschekeln stehen*, den Dornen und Disteln gehört*.", footnotes: ["℘ Hl 8,11", "℘ Kap. 32,13"] },
      { number: 24, text: "Nur mit Pfeilen und Bogen wird man dorthin kommen, denn zu Dornen und Disteln wird das ganze Land werden*.", footnotes: ["℘ 1Mo 3,18"] },
      { number: 25, text: "Und auf alle Berge, die mit der Hacke behackt werden, dahin wirst du nicht kommen aus Furcht vor Dornen und Disteln. Und sie werden ein Ort sein, an den man Rinder treibt und der von Schafen zertreten wird*.", footnotes: ["℘ Kap. 5,17"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und der HERR sprach zu mir: Nimm dir eine große Tafel und schreibe darauf mit Menschengriffel*: »Für Schnell-Raub Eile-Beute«*!", heading: "Der Sohn des Propheten als Zeichen des Gerichts durch Assur", footnotes: ["Mit geringfügiger Änderung lesen andere: mit einem Griffel des Unheils\n℘ Kap. 30,8; Jer 30,2; Hab 2,2; Offb 1,11.19", "hebr. Maher-Schalal Chasch-Bas; o. als Inschrift »Schnell-Raub, Eile-Beute«"] },
      { number: 2, text: "Da nahm ich mir zuverlässige Zeugen: den Priester Uria* und Secharja, den Sohn des Jeberechja. —", footnotes: ["℘ 2Kö 16,10.11"] },
      { number: 3, text: "Und ich nahte der Prophetin, und sie wurde schwanger und gebar einen Sohn. Und der HERR sprach zu mir: Gib ihm den Namen*: »Schnell-Raub Eile-Beute«!", footnotes: ["℘ Hos 1,4"] },
      { number: 4, text: "Denn ehe der Junge zu rufen versteht*: »Mein Vater!« und: »Meine Mutter!«, wird man den Reichtum von Damaskus* und die Beute von Samaria vor dem König von Assur hertragen*.", footnotes: ["o. zu rufen erkannt hat", "℘ Kap. 17,1; Am 1,5", "℘ Kap. 7,16; 10,6; 28,4; 2Kö 17,6"] },
      { number: 5, text: "Und der HERR fuhr fort, weiter zu mir zu reden:" },
      { number: 6, text: "Weil dieses Volk das Wasser von Siloah* verworfen, das still dahinfließt, und Freude hat an Rezin* und dem Sohn des Remalja*:", footnotes: ["℘ Neh 3,15", "Andere vermuten, dass der Text ursprünglich lautete: die still dahinfließen, aber selbst zerfließt vor der Hoheit Rezins", "℘ Kap. 7,1"] },
      { number: 7, text: "darum, siehe, lässt der Herr das mächtige und große Wasser des Stromes über sie heraufsteigen — den König von Assur und all seine Herrlichkeit. Er wird heraufsteigen über all seine Betten und über all seine Ufer gehen*.", footnotes: ["℘ Kap. 7,17; 17,12; 59,19; Jer 46,7; Mi 5,4.5; Offb 17,15"] },
      { number: 8, text: "Und er wird über Juda dahinfahren, alles überschwemmen und überfluten; bis an den Hals wird er reichen*. Und die Spanne seiner Flügel wird die Weite deines Landes füllen, Immanuel*!", footnotes: ["℘ Kap. 7,14; 10,28-32; 28,15; 2Kö 17,3-6; Jer 51,42", "℘ Kap. 36,1"] },
      { number: 9, text: "Tobt, ihr Völker, und erschreckt*! Und horcht auf, all ihr fernen Bewohner der Erde! Gürtet euch* und erschreckt*, gürtet euch* und erschreckt*!", footnotes: ["o. werdet schreckerfüllt; o. zerbrecht", "℘ Jer 46,3.4; Hes 38,7", "o. werdet schreckerfüllt; o. zerbrecht", "℘ 1Mo 3,18", "o. werdet schreckerfüllt; o. zerbrecht"] },
      { number: 10, text: "Plant einen Plan, er geht in die Brüche! Beschließt einen Beschluss*, er wird nicht zustande kommen*! Denn Gott ist mit uns*.", footnotes: ["w. Beredet eine Sache", "℘ Kap. 7,7; 14,27; Ps 21,12; 33,10", "hebr. immanuel\n℘ Kap. 7,14; 4Mo 14,9; 2Kö 6,12; 2Chr 13,12; Hag 1,13; Mt 1,23"] },
      { number: 11, text: "Denn so hat der HERR zu mir gesprochen, als seine Hand mich packte* und er mich davor warnte, auf dem Weg dieses Volkes zu gehen*:", footnotes: ["℘ Jer 20,7; Hes 3,14", "℘ Hes 2,8"] },
      { number: 12, text: "Ihr sollt nicht alles Verschwörung nennen, was dieses Volk Verschwörung nennt. Das, was sie fürchten*, sollt ihr nicht fürchten und nicht davor erschrecken*.", footnotes: ["w. ihre Furcht; o. wie sie fürchten", "℘ Kap. 51,12; Jos 1,9"] },
      { number: 13, text: "Den HERRN der Heerscharen, den sollt ihr heiligen*! Er sei eure Furcht, und er sei euer Schrecken*!", footnotes: ["Andere üs. mit geringfügiger Textänderung: den sollt ihr Verschwörer nennen\n℘ Kap. 29,23; 3Mo 22,32; 1Petr 3,14.15", "℘ 1Sam 11,7; Lk 12,5"] },
      { number: 14, text: "Und er wird zum Heiligtum* sein und zum Stein des Anstoßes* und zum Fels des Strauchelns für die beiden Häuser Israel*, zum Klappnetz und zur Falle für die Bewohner Jerusalems.", footnotes: ["Die aram. Üs. liest entsprechend der zweiten Vershälfte: zur Falle. Andere üs. in Anlehnung an die Verse 12 u. 13 mit geringfügiger Änderung: zur Verschwörung", "o. Hindernisses; d. h. etwas, worüber man fällt", "℘ Mt 11,6; Lk 2,34; 1Petr 2,8"] },
      { number: 15, text: "Und viele unter ihnen werden stürzen, werden fallen und zerbrechen, verstrickt und gefangen werden*. —", footnotes: ["℘ Kap. 28,13; Jer 6,21; Mt 21,44"] },
      { number: 16, text: "Binde die Offenbarung* zusammen, versiegle die Weisung* unter meinen Jüngern*! —", footnotes: ["w. Bezeugung", "o. Ich schließe die Bezeugung ein und versiegle das Gesetz", "℘ Dan 12,4"] },
      { number: 17, text: "Und ich will auf den HERRN harren*, der sein Angesicht vor dem Haus Jakob verbirgt*, und will auf ihn hoffen*.", footnotes: ["℘ Hi 14,14; 35,14; Ps 27,14", "℘ Kap. 54,8; 57,17; 64,6", "℘ Kap. 33,2; 50,10; Mi 7,7"] },
      { number: 18, text: "Siehe, ich und die Kinder, die der HERR mir gegeben hat*, wir sind zu Zeichen und zu Wundern* in Israel geworden vom HERRN der Heerscharen, der auf dem Berg Zion wohnt*.", footnotes: ["℘ Hebr 2,13", "o. Wahrzeichen\n℘ Ps 71,7; Sach 3,8", "℘ Ps 9,12"] },
      { number: 19, text: "Und wenn sie zu euch sagen: Befragt die Totengeister und die Wahrsagegeister*, die da flüstern und murmeln*!, so antwortet: Soll nicht ein Volk seinen Gott befragen*? Soll es etwa für die Lebenden die Toten befragen*?", footnotes: ["o. Befragt die Zwitscherer und Murmelgeister, die heraufbeschworenen Toten", "℘ 5Mo 18,10.11; Jer 27,9", "℘ 2Kö 1,3", "℘ 1Sam 28,7.8"] },
      { number: 20, text: "Hin zur Weisung* und zur Offenbarung*! Wenn sie nicht nach diesem Wort sprechen, dann gibt es für sie keine Morgenröte*.", footnotes: ["o. zum Gesetz", "w. Bezeugung\n℘ Esr 10,3; Mal 3,22; Lk 10,26; 16,29", "d. h. keine Hoffnung; o. wenn sie zu euch sagen: . . . soll ein Volk nicht seine Götter befragen?, . . . 20 dann antwortet: Zur Weisung und zur Bezeugung! Fürwahr, nach diesem Wort soll man sprechen, zu dem der keine Zauberkraft hat (d. h. zu den Totenbeschwörern).\n℘ Mi 3,6"] },
      { number: 21, text: "Man wird darin* umherziehen, bedrückt und hungrig. Und es wird geschehen, wenn man Hunger leidet, dann wird man von Wut übermannt werden und seinen König und seinen Gott verfluchen*. Und man wird sich nach oben wenden", footnotes: ["d. h. entweder »ohne Hoffnung« oder »im Land«", "℘ 3Mo 24,11; Hi 1,11"] },
      { number: 22, text: "und wird zur Erde blicken: und siehe, da ist Not und Finsternis, bedrängendes Dunkel, und in dichte Finsternis ist man hineingestoßen*.", footnotes: ["℘ Kap. 5,30; 50,3; 60,2; Offb 16,9.10"] },
      { number: 23, text: "Doch nicht bleibt das Dunkel* über dem, der von der Finsternis* bedrängt ist. Wie die frühere Zeit dem Land Sebulon und dem Land Naftali Schmach gebracht hat*, so bringt die spätere den Weg am Meer, das Land jenseits des Jordan und den Kreis der Nationen* zu Ehren*.", heading: "Verheißung des Reiches unter dem Friedefürst", footnotes: ["o. Denn es gibt kein Entkommen; o. Denn es gibt keinen Hoffnungsschimmer", "w. von ihr", "℘ 2Kö 15,29", "hebr. gelil haggojim; d. i. der nördliche Grenzdistrikt Palästinas, ein Teil des späteren Galiläa", "℘ Mt 4,15.16; 2Kor 4,6"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Das Volk, das im Dunkel lebt*, sieht ein großes Licht. Die im Land der Finsternis* wohnen, Licht leuchtet über ihnen*.", footnotes: ["o. durch das Dunkel geht", "Andere üs.: des Todesschattens", "℘ Mt 4,15.16; 2Kor 4,6"] },
      { number: 2, text: "Du vermehrst den Jubel, du machst die Freude groß*. Sie freuen sich vor dir, wie man sich freut in der Ernte*, wie man jauchzt beim Verteilen der Beute*.", footnotes: ["T.; Mas. T. enthält wohl einen Schreibfehler: Du vermehrst nicht die Nation, du machst die Freude groß. — Andere Handschr., die syr. und aram. Üs. lesen: Du vermehrst die Nation, machst ihr die Freude groß\n℘ Lk 2,10", "℘ Ps 4,8", "℘ Ri 5,30"] },
      { number: 3, text: "Denn das Joch ihrer* Last, den Stab auf ihrer* Schulter, den Stock ihres* Treibers zerbrichst* du wie am Tag Midians*.", footnotes: ["w. seiner bzw. seines; d. i. des Volkes", "w. seiner bzw. seines; d. i. des Volkes", "w. seiner bzw. seines; d. i. des Volkes", "w. zerschmetterst", "℘ Kap. 10,26.27; 14,5; 3Mo 26,13; Ri 7,22; 8,12"] },
      { number: 4, text: "Denn jeder Stiefel, der dröhnend einherstampft, und jeder Mantel, in Blut gewälzt, verfällt dem Brand, wird ein Fraß des Feuers*.", footnotes: ["℘ Kap. 10,16.17"] },
      { number: 5, text: "Denn ein Kind ist uns geboren, ein Sohn uns gegeben*, und die Herrschaft ruht auf seiner Schulter*; und man nennt seinen Namen: *Wunderbarer* Ratgeber, starker Gott*, Vater der Ewigkeit*, Fürst* des Friedens*.", footnotes: ["℘ Lk 2,7; Röm 9,5", "℘ Sach 6,13; Mt 28,18", "o. Planer des Wunders; Gott, Held", "℘ Ri 13,18", "o. Planer des Wunders; Gott, Held\n℘ Hebr 1,8", "℘ Mi 5,1", "w. Oberster", "℘ Hebr 7,2"] },
      { number: 6, text: "Groß ist die Herrschaft*, und der Friede wird kein Ende haben auf dem Thron Davids und über seinem Königreich*, es zu festigen und zu stützen durch Recht und Gerechtigkeit* von nun an bis in Ewigkeit*. Der Eifer des HERRN der Heerscharen wird dies tun*.", footnotes: ["so mit LXX. Manche vermuten einen fünften Herrschernamen und lesen: Vermehrer des Reiches", "℘ 2Sam 7,16; Lk 2,14", "℘ Kap. 11,5; 32,1; 1Kö 10,9; Ps 45,7.8; Jer 23,5", "℘ 1Kö 2,33.45; Ps 89,5; Dan 7,14; Lk 1,33", "℘ Kap. 37,32"] },
      { number: 7, text: "Ein Wort sendet der Herr gegen Jakob, und in Israel fällt es nieder.", heading: "Drohendes Gericht über Israel" },
      { number: 8, text: "Und das ganze Volk erkennt es, Ephraim und die Bewohner von Samaria, die in Hochmut und mit überheblichen Herzen sagen*:", footnotes: ["℘ Jer 43,2"] },
      { number: 9, text: "Die Ziegelsteine sind gefallen, aber mit Quadern bauen wir auf. Die Sykomoren sind abgehauen, aber wir setzen Zedern an ihre Stelle*.", footnotes: ["o. Die Sykomorenbalken sind in Stücke geschlagen, aber wir setzen Zedernholz an ihre Stelle\n℘ Kap. 28,1"] },
      { number: 10, text: "Doch der HERR wird die Gegner, nämlich Rezin*, über es erhöhen und seine Feinde aufstacheln:", footnotes: ["℘ 2Kö 16,9"] },
      { number: 11, text: "Aram von Osten und die Philister von Westen; die werden Israel fressen mit vollem Maul*. — Bei alldem wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt*.", footnotes: ["℘ Kap. 28,1", "℘ Kap. 5,25; 10,4"] },
      { number: 12, text: "Aber das Volk kehrt nicht um zu dem, der es schlägt*, und den HERRN der Heerscharen suchen sie nicht*.", footnotes: ["℘ Hos 7,10; Am 4,6-11", "℘ Kap. 31,1; Jer 15,7; Zef 1,6"] },
      { number: 13, text: "Da haut der HERR von Israel Kopf und Schwanz ab, Palmzweig und Binse an einem Tag*.", footnotes: ["℘ Kap. 7,20; 19,15"] },
      { number: 14, text: "Der Älteste und Angesehene, er ist der Kopf; und der Prophet, der Lüge lehrt, er ist der Schwanz." },
      { number: 15, text: "Denn die Führer dieses Volkes werden zu Verführern und die von ihnen Geführten zu Verwirrten*.", footnotes: ["℘ Kap. 3,12; Kla 2,14"] },
      { number: 16, text: "Darum wird sich der Herr über dessen junge Männer nicht freuen*, und über seine Waisen und Witwen wird er sich nicht erbarmen*. Denn sie alle sind Gottlose und Übeltäter, und jeder Mund redet Torheit*. — Bei alldem wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt*.", footnotes: ["Mit geringfügiger Änderung: nicht großmütig sein gegen die jungen Männer; Qu.: kein Mitleid empfinden mit den jungen Männern", "℘ Jer 18,21", "℘ Jer 9,4-8", "℘ Kap. 5,25; 10,4"] },
      { number: 17, text: "Denn die Gottlosigkeit brennt wie Feuer: Dornen und Disteln verzehrt sie und zündet in den Dickichten des Waldes, dass sie emporwirbeln als hoch aufsteigender Rauch*.", footnotes: ["℘ Kap. 5,24; 33,11.12"] },
      { number: 18, text: "Durch den Grimm des HERRN der Heerscharen ist das Land verbrannt, und das Volk ist wie ein Fraß des Feuers geworden; keiner hat Mitleid mit dem andern*.", footnotes: ["℘ Kap. 3,5; 1Kö 16,21; Jer 9,3"] },
      { number: 19, text: "Und man verschlingt zur Rechten und hungert, und man frisst zur Linken und wird nicht satt*. Jeder frisst das Fleisch seines Nächsten*:", footnotes: ["℘ 3Mo 26,26", "so mit einer LXX-Ausgabe und Targum; Mas. T.: seines Armes\n℘ Sach 11,9"] },
      { number: 20, text: "Manasse den Ephraim, und Ephraim den Manasse; diese miteinander zusammen aber fallen über Juda her. — Bei alldem wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt.*", footnotes: ["℘ Kap. 5,25; 10,4"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Wehe denen, die Ordnungen des Unheils anordnen, und den Schreibern, die Mühsal schreiben*,", footnotes: ["Die aram. Üs. liest: die Schriftstücke der Mühsal verfassen"] },
      { number: 2, text: "um die Geringen* von ihrem Rechtsanspruch zu verdrängen und den Elenden meines Volkes ihr Recht zu rauben*, damit die Witwen ihr Plündergut werden und sie die Waisen plündern*!", footnotes: ["o. Hilflosen", "℘ Kap. 5,23; 2Mo 23,6; Hi 31,16; Spr 22,22; Am 2,6.7", "℘ Kap. 1,17.23; Ps 94,6; Mi 3,1-3"] },
      { number: 3, text: "Und was wollt ihr tun am Tag der Heimsuchung und beim Sturm*, der von weither kommt*? Zu wem wollt ihr fliehen um Hilfe* und wo euren Reichtum lassen*?", footnotes: ["o. plötzlichen Untergang", "℘ Kap. 5,26; Jer 4,30", "℘ Am 5,19", "andere mit T.: und wohin wollt ihr euren Reichtum in Sicherheit bringen?\n℘ Kap. 2,20.21; 28,20; Spr 11,4; Zef 1,18"] },
      { number: 4, text: "Beugt man sich nicht unter Gefangenen, so muss man unter Erschlagenen fallen*. — Bei alldem wendet sich sein Zorn nicht ab, und noch ist seine Hand ausgestreckt*.", footnotes: ["o. Umsonst! Bei Gefangenen bricht man zusammen, und bei den Erschlagenen fallen sie\n℘ Jer 15,2; Jak 2,13", "℘ Kap. 9,11"] },
      { number: 5, text: "*Wehe, Assur, Rute meines Zorns! Und der Stock meines Zorns* — in ihrer Hand ist er*.", heading: "Weheruf über Assur und dessen Niederlage", footnotes: ["℘ Nah 1-3; Zef 2,13-15", "℘ Kap. 7,20; Hab 1,12", "w. Und ein Stock ist er; in ihrer Hand ist mein Zorn"] },
      { number: 6, text: "Gegen eine gottlose Nation* sende ich ihn*, und gegen das Volk meines Grimmes entbiete ich ihn, Raub zu rauben und Beute zu erbeuten* und es zertreten zu lassen wie Straßenkot*.", footnotes: ["℘ Kap. 30,9", "℘ 2Kö 18,25", "℘ Kap. 8,4", "℘ 2Sam 22,43"] },
      { number: 7, text: "Er aber meint es nicht so, und sein Herz denkt nicht so*, sondern zu verheeren hat er im Sinn und nicht wenige Nationen auszurotten*.", footnotes: ["℘ Mi 4,12", "℘ Kap. 36,18-20; 37,19"] },
      { number: 8, text: "Denn er sagt: Sind meine Obersten nicht allesamt Könige*?", footnotes: ["℘ Hos 8,10"] },
      { number: 9, text: "Ist Kalne* nicht wie Karkemisch*, Hamat* nicht wie Arpad*, Samaria nicht wie Damaskus*?", footnotes: ["℘ 1Mo 10,10; Am 6,2", "℘ 2Chr 35,20; Jer 46,2", "℘ Kap. 5,25; 10,4", "℘ Jer 49,23", "℘ Kap. 33,8; 2Kö 16,9; 18,10.34"] },
      { number: 10, text: "Wie meine Hand die Königreiche der Götzen erreicht* hat — und ihre geschnitzten Bilder waren mehr als die von Jerusalem und von Samaria —,", footnotes: ["o. gefunden; d. h. in die Gewalt bekommen"] },
      { number: 11, text: "werde ich nicht, wie ich Samaria* und seinen Götzen getan habe, ebenso Jerusalem und seinen Götzenbildern tun*?", footnotes: ["℘ Hes 16,46", "℘ Kap. 36,18-20; 37,19"] },
      { number: 12, text: "Aber es wird geschehen, wenn der Herr sein ganzes Werk am Berg Zion und an Jerusalem vollendet* hat*, wird er* die Frucht des überheblichen Herzens des Königs von Assur heimsuchen und den hochmütigen Stolz seiner Augen*.", footnotes: ["Im Hebr. findet sich bei dem Wort für »vollendet« die umgekehrte Buchstabenfolge wie bei dem Wort für »Götzenbildern« in V. 11.", "℘ Kap. 46,10.11; Dan 11,45; 1Petr 4,17", "so mit LXX; Mas. T.: werde ich", "℘ Kap. 2,12; 4Mo 24,24; Jer 50,18.31"] },
      { number: 13, text: "Denn er hat gesagt: Durch die Kraft meiner Hand habe ich es getan und durch meine Weisheit, denn ich bin verständig*. Und ich beseitige die Grenzen der Völker und plündere ihre Schätze und stoße die Bewohner hinab wie ein Starker*.", footnotes: ["℘ Kap. 5,21; Ri 7,2; Spr 28,11; Hab 1,11", "o. wie ein Stier. — Andere nehmen an, dass der Text ursprünglich gelautet hat: hinab in den Staub\n℘ 2Kö 19,23"] },
      { number: 14, text: "Meine Hand hat den Reichtum der Völker erreicht* wie ein Nest. Und wie man verlassene Eier zusammenrafft, so habe ich die ganze Erde zusammengerafft: da war keiner, der mit dem Flügel schlug oder den Schnabel aufriss und piepste*. —", footnotes: ["o. gefunden; d. h. in die Gewalt bekommen", "℘ Kap. 37,25; 2Chr 32,13.14"] },
      { number: 15, text: "Rühmt sich die Axt gegen den, der damit haut? Oder brüstet sich die Säge gegen den, der sie zieht? Als schwänge ein Stock den, der ihn hochhebt*, als ob ein Stab den hochhöbe, der kein Holz ist*!", footnotes: ["so mit einigen hebr. Handschr.; Mas. T.: die, die ihn hochheben", "℘ Kap. 37,23"] },
      { number: 16, text: "Darum wird der Herr, der HERR der Heerscharen, Schwindsucht senden unter seine Fetten*, und unter seiner Herrlichkeit wird ein Brand auflodern wie ein Feuerbrand*.", footnotes: ["℘ Kap. 17,4", "℘ Kap. 9,4; 26,11; 30,30-33; 31,9"] },
      { number: 17, text: "Und das Licht Israels wird zum Feuer werden und sein Heiliger zur Flamme; die wird seine Dornen und seine Disteln in Brand setzen und verzehren an einem Tag*.", footnotes: ["℘ 5Mo 4,24; Zef 1,18"] },
      { number: 18, text: "Und man wird die Herrlichkeit seines Waldes und seines Fruchtgartens von der Seele bis zum Fleisch vernichten, und es wird sein, wie wenn ein Kranker dahinsiecht." },
      { number: 19, text: "Dann wird der Rest der Bäume seines Waldes zu zählen sein; ein Junge könnte sie aufschreiben*.", footnotes: ["℘ Kap. 13,12"] },
      { number: 20, text: "An jenem Tag wird es geschehen: Da wird der Rest* Israels, und was vom Haus Jakob entkommen ist, sich nicht mehr länger auf den stützen, der es schlägt*, sondern es wird sich auf den HERRN, den Heiligen Israels, stützen in Treue*.", heading: "Rettung des Restes Israels und Jerusalems", footnotes: ["℘ Kap. 1,9; 46,3", "℘ 2Chr 28,16", "℘ Kap. 17,7; Jer 3,23"] },
      { number: 21, text: "Ein Rest wird umkehren*, ein Rest* Jakobs, zu dem starken Gott.", footnotes: ["hebr. schear jaschub; vgl. Kap. 7,3", "℘ Esr 1,4; Jer 50,20"] },
      { number: 22, text: "Denn wenn auch dein Volk, Israel, wie der Sand des Meeres wäre; nur ein Rest davon wird umkehren*. Vernichtung ist beschlossen, einherflutend mit Gerechtigkeit.", footnotes: ["℘ Kap. 6,13; 37,31.32; 59,20; 2Kö 19,31; Jer 3,14; 44,28"] },
      { number: 23, text: "Denn der Herr, der HERR der Heerscharen, vollzieht fest beschlossene Vernichtung inmitten der ganzen Erde*.", footnotes: ["℘ Kap. 28,22; Ps 46,9; Dan 9,27; 11,36; Röm 9,27.28"] },
      { number: 24, text: "Darum, so spricht der Herr, der HERR der Heerscharen: Fürchte dich nicht, mein Volk, das in Zion wohnt, vor Assur*, der dich mit dem Stock schlägt und seinen Stab gegen dich erhebt in der Art Ägyptens*!", footnotes: ["℘ Kap. 37,6; 2Kö 19,6", "℘ 2Mo 1,14"] },
      { number: 25, text: "Denn nur noch eine ganz kurze Weile*, dann wird der Grimm* zu Ende sein, und mein Zorn richtet sich auf ihre Vernichtung*.", footnotes: ["w. denn noch eine winzige Kleinigkeit", "w. die Verwünschung", "℘ Kap. 14,25; 31,8.9; 37,36; Spr 22,8; Dan 11,36"] },
      { number: 26, text: "Und der HERR der Heerscharen wird über ihn die Geißel schwingen* wie bei der Niederlage Midians am Felsen Oreb* und seinen Stab über das Meer, und er wird ihn erheben in der Art Ägyptens.", footnotes: ["℘ Kap. 30,30-32", "d. h. Rabenfels; vgl. Ri 7,25\n℘ Kap. 9,3; Ri 7,25"] },
      { number: 27, text: "An jenem Tag wird es geschehen, da weicht seine Last von deiner Schulter, und sein Joch wird von deinem Hals weggerissen, und vernichtet wird das Joch vor dem Fett*.", footnotes: ["Viele lesen mit Einfügung zweier Buchstaben »und sein Joch von seinem Hals weggerissen. Er zieht herauf von Samaria o. Rimmon« und ziehen den letzten Satz zu V. 28.\n℘ Jer 30,8"] },
      { number: 28, text: "Er kommt auf Ajat* zu, zieht durch Migron*; in Michmas* lässt er seinen Tross.", footnotes: ["℘ Jos 7,2", "℘ 1Sam 14,2", "℘ 1Sam 13,2.5.23"] },
      { number: 29, text: "Sie ziehen durch die Schlucht*, »Geba* sei unser Nachtquartier!« Rama* bebt, Gibea Sauls* flieht.", footnotes: ["℘ 1Sam 13,23", "℘ 1Sam 14,5", "℘ Jos 18,25; Hos 5,8", "℘ 1Sam 14,2"] },
      { number: 30, text: "Schreie gellend, Tochter Gallims*! Horche auf, Lajescha! Elendes Anatot*!*", footnotes: ["℘ 1Sam 25,44", "o. Antworte ihr, Anatot", "℘ Neh 11,32"] },
      { number: 31, text: "Madmena eilt davon, die Bewohner von Gebim bringen sich in Sicherheit." },
      { number: 32, text: "Noch heute macht er halt in Nob*. — Er schwingt seine Hand gegen den Berg der Tochter Zion, den Hügel Jerusalems*. —", footnotes: ["℘ 1Sam 21,1", "℘ Kap. 8,8; 2Chr 32,1.2; Mi 1,9"] },
      { number: 33, text: "Siehe, der Herr, der HERR der Heerscharen, haut mit Schreckensgewalt die Äste herunter. Und die Hochgewachsenen werden gefällt*, und die Emporragenden werden niedersinken.", footnotes: ["℘ Kap. 2,12.13; 18,5; 32,19; Jer 22,7"] },
      { number: 34, text: "Und er schlägt das Dickicht des Waldes mit dem Eisen nieder, und der Libanon fällt durch einen Mächtigen*.", footnotes: ["o. Herrlichen"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und ein Spross wird hervorgehen aus dem Stumpf Isais*, und ein Schössling aus seinen Wurzeln wird Frucht bringen*.", heading: "Das endzeitliche Friedensreich", footnotes: ["℘ Mt 1,5; 2,23; Sach 6,12", "℘ Kap. 4,2; 53,2; Hes 17,22; Apg 13,23; Offb 5,5"] },
      { number: 2, text: "Und auf ihm wird ruhen der Geist des HERRN*, der Geist der Weisheit und des Verstandes*, der Geist des Rates und der Kraft*, der Geist der Erkenntnis* und Furcht des HERRN*;", footnotes: ["℘ Mt 3,16; 12,18", "℘ 5Mo 34,9; Lk 2,40", "℘ Kap. 42,1; Apg 10,38", "℘ Eph 1,17", "℘ 2Sam 23,3"] },
      { number: 3, text: "und er wird sein Wohlgefallen haben an der Furcht des HERRN. Er wird nicht richten nach dem, was seine Augen sehen, und nicht zurechtweisen nach dem, was seine Ohren hören*,", footnotes: ["w. nach dem Sehen seiner Augen und nicht Recht sprechen nach dem Gerücht seiner Ohren\n℘ Joh 7,24"] },
      { number: 4, text: "sondern er wird die Geringen richten in Gerechtigkeit und die Elenden* des Landes zurechtweisen in Geradheit*. Und er wird den Gewalttätigen* schlagen mit dem Stab seines Mundes* und mit dem Hauch seiner Lippen den Gottlosen töten*.", footnotes: ["o. Demütigen", "℘ Kap. 2,4; 16,5; 32,1; 33,22; Ps 76,10; Offb 19,11", "T.; Mas. T.: das Land", "℘ Offb 1,16", "℘ Hi 15,30; 2Thes 2,8"] },
      { number: 5, text: "Gerechtigkeit wird der Schurz* seiner Hüften sein und die Treue* der Schurz* seiner Lenden*. —", footnotes: ["o. Hüftschurz; d. i. ein enganliegendes Untergewand", "o. Wahrheit", "o. Wahrheit", "℘ Kap. 9,6; Ps 45,4.5; 89,9; Eph 6,14"] },
      { number: 6, text: "Und der Wolf wird beim Lamm weilen und der Leopard beim Böckchen lagern*. Das Kalb und der Junglöwe und das Mastvieh werden zusammen sein, und ein kleiner Junge wird sie treiben.", footnotes: ["℘ Kap. 65,25"] },
      { number: 7, text: "Kuh und Bärin werden miteinander weiden, ihre Jungen werden zusammen lagern. Und der Löwe wird Stroh fressen wie das Rind*.", footnotes: ["℘ Kap. 65,25"] },
      { number: 8, text: "Und der Säugling wird spielen an dem Loch der Viper und das entwöhnte Kind seine Hand ausstrecken nach der Höhle der Otter*.", footnotes: ["℘ Hi 5,23"] },
      { number: 9, text: "Man wird nichts Böses tun noch verderblich handeln auf meinem ganzen heiligen Berg*. Denn das Land wird voll von Erkenntnis des HERRN sein, wie von Wasser, das das Meer bedeckt*. —", footnotes: ["℘ Kap. 32,16; 60,18.21; 65,25", "℘ Kap. 33,6"] },
      { number: 10, text: "Und an jenem Tag wird es geschehen: der Wurzelspross* Isais, der als Feldzeichen der Völker dasteht, nach ihm werden die Nationen fragen*; und seine Ruhestätte wird Herrlichkeit sein*.", footnotes: ["Das hebr. Wort bedeutet auch »Wurzel«.", "℘ Kap. 2,2-4; 42,4; Mt 12,21; Röm 15,12", "℘ Ps 145,11"] },
      { number: 11, text: "Und an jenem Tag wird es geschehen, da wird der Herr noch einmal seine Hand erheben*, um den Rest seines Volkes, der übrig bleibt, loszukaufen* aus Assur und Ägypten*, aus Patros* und Kusch, aus Elam*, Schinar* und Hamat* und von den Inseln des Meeres*.", footnotes: ["T. mit LXX; Mas. T.: da wird der Herr zum zweiten Mal seine Hand hinzufügen\n℘ 5Mo 9,29", "℘ Joe 3,5", "℘ Kap. 27,13; Hos 11,10.11", "d. i. Oberägypten\n℘ Jer 44,1", "d. i. die persische Provinz, deren Hauptstadt Susa war\n℘ Kap. 21,2; 22,6", "d. i. Babylonien\n℘ Dan 1,2", "℘ 2Kö 17,24", "Das sind die Inseln und Küstengebiete des Mittelländischen Meeres.\n℘ Est 10,1"] },
      { number: 12, text: "Und er wird den Nationen ein Feldzeichen aufrichten* und die Vertriebenen Israels zusammenbringen, und die Verstreuten Judas wird er sammeln von den vier Enden der Erde*.", footnotes: ["℘ Kap. 18,3; 49,22; 62,10; Jer 51,12", "℘ Kap. 27,13; 43,6; 49,12; Sach 8,7"] },
      { number: 13, text: "Dann wird die Eifersucht Ephraims weichen, und die Bedränger Judas werden* ausgerottet werden. Ephraim wird auf Juda nicht eifersüchtig sein, und Juda wird Ephraim nicht bedrängen*.", footnotes: ["o. die Bedrängnis Judas wird", "℘ Jer 3,18"] },
      { number: 14, text: "Und sie werden nach Westen auf die Berglehne der Philister fliegen*. Miteinander werden sie die Söhne des Ostens ausplündern*. Edom* und Moab* werden ihre Hand greifen, und die Söhne Ammons* werden ihnen hörig sein*.", footnotes: ["℘ Ob 19; Zef 2,7", "℘ Ri 6,3.33", "℘ Hes 25,14; Am 9,12", "℘ Jer 48", "℘ Dan 11,41; Jer 49,2", "℘ Est 10,1"] },
      { number: 15, text: "Dann wird der HERR die Meereszunge Ägyptens spalten*. Und er wird seine Hand über den Strom* schwingen* mit der Gewalt seines Hauches und ihn in sieben Bäche zerschlagen, so dass man mit Schuhen hindurchgehen kann.", footnotes: ["LXX liest: austrocknen", "d. i. der Euphrat", "℘ Kap. 19,16; Offb 16,12"] },
      { number: 16, text: "So wird es eine Straße geben für den Rest seines Volkes*, der aus Assur übrig bleibt, wie es eine Straße für Israel gab an dem Tag, als es aus dem Land Ägypten heraufzog*.", footnotes: ["℘ Kap. 19,23; 27,13", "℘ 2Mo 14,22"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und an jenem Tag wirst du sagen: Ich preise dich, HERR! Ja, du hast mir gezürnt. Möge dein Zorn sich wenden*, dass du mich tröstest*!*", heading: "Das Loblied der Gerechten", footnotes: ["℘ Ps 85,4; Hos 14,5", "℘ Kap. 60,10; Ps 30,5.6; 86,17", "Andere üs.: Doch dein Zorn hat sich gewendet, und du hast mich getröstet."] },
      { number: 2, text: "Siehe, Gott ist mein Heil*, ich bin voller Vertrauen und fürchte mich nicht*. Denn Jah, der HERR, ist meine Stärke und mein Loblied*, und er ist mir zum Heil geworden*. —", footnotes: ["o. meine Rettung; so auch nachher\n℘ Jer 3,23", "℘ Kap. 51,12", "o. meine Zuflucht und meine Kraft", "℘ Kap. 33,22; 38,20; Ps 68,20; 118,14"] },
      { number: 3, text: "Und mit Freuden werdet ihr Wasser schöpfen aus den Quellen des Heils*", footnotes: ["℘ Ps 87,7; Joh 4,14"] },
      { number: 4, text: "und werdet an jenem Tage sprechen: Preist den HERRN, ruft seinen Namen aus, macht unter den Völkern seine Taten bekannt*, verkündet*, dass sein Name hoch erhaben ist*!", footnotes: ["℘ Ps 105,1", "w. erwähnt rühmend", "℘ Ps 148,13"] },
      { number: 5, text: "Lobsingt dem HERRN, denn Herrliches* hat er getan*! Das soll auf der ganzen Erde bekannt werden*.", footnotes: ["o. Erhabenes", "℘ Offb 15,3", "℘ Ps 98,1-3"] },
      { number: 6, text: "Jauchze und juble, Bewohnerin von Zion*! Denn groß ist in deiner Mitte der Heilige Israels*.", footnotes: ["℘ Kap. 52,8.9", "℘ 4Mo 23,21"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*Ausspruch über Babel, den Jesaja, der Sohn des Amoz, geschaut hat*.", heading: "Gericht über Babel am Tag des HERRN", footnotes: ["℘ Kap. 21,1-10; 47,1-15; Jer 50; 51", "℘ Kap. 1,1; Jer 28,8.11"] },
      { number: 2, text: "Auf kahlem Berg richtet ein Feldzeichen auf*, mit lauter Stimme ruft ihnen zu, winkt mit der Hand, dass sie einziehen durch die Tore der Edlen*!", footnotes: ["℘ Kap. 18,3", "℘ Kap. 45,1.2"] },
      { number: 3, text: "Ich habe meine Geheiligten entboten, auch meine Helden zu meinem Zorngericht gerufen*, die über meine Hoheit jauchzen.", footnotes: ["℘ Joe 4,11"] },
      { number: 4, text: "Horch! Getümmel auf den Bergen wie von einem großen Volk! Horch! Getöse von Königreichen, von versammelten Nationen*! Der HERR der Heerscharen mustert ein Kriegsheer.", footnotes: ["℘ Jer 25,14"] },
      { number: 5, text: "Aus fernem Land kommen sie, vom Ende des Himmels — der HERR mit den Werkzeugen seiner Verwünschung, um das ganze Land zugrunde zu richten*.", footnotes: ["℘ Jer 50,25"] },
      { number: 6, text: "Heult, denn nahe ist der Tag des HERRN*! Er kommt wie eine Verwüstung vom Allmächtigen*.", footnotes: ["℘ Kap. 2,12; 34,8; Hes 30,3; Joe 2,1", "℘ Joe 1,15"] },
      { number: 7, text: "Darum werden alle Hände erschlaffen, und jedes Menschenherz wird zerschmelzen*.", footnotes: ["℘ Hes 21,12; Nah 2,11"] },
      { number: 8, text: "Und sie werden bestürzt sein. Krämpfe und Wehen werden sie packen, sie werden sich winden wie eine Gebärende*. Einer starrt den andern an, ihre Gesichter glühen wie Flammen*.", footnotes: ["℘ Kap. 21,3; 26,17; Ps 48,7", "w. ihre Gesichter sind Flammengesichter"] },
      { number: 9, text: "Siehe, der Tag des HERRN* kommt, grausam mit Grimm und Zornglut, um die Erde zur Wüste* zu machen; und ihre Sünder wird er von ihr austilgen*.", footnotes: ["℘ Kap. 2,12; 34,8; Hes 30,3; Joe 2,1", "o. zum Schreckensort", "℘ Kap. 63,4; 66,17; Ps 104,35; Zef 1,15"] },
      { number: 10, text: "Denn die Sterne des Himmels und seine Sternbilder* werden ihr Licht nicht leuchten lassen. Die Sonne wird finster sein bei ihrem Aufgang, und der Mond wird sein Licht nicht scheinen lassen*.", footnotes: ["w. seine Orione; d. h. der Orion mit den ihm zugehörigen Sternbildern", "℘ Kap. 24,23; 50,3; Hes 32,7.8; Joe 2,10; Am 8,9"] },
      { number: 11, text: "Und ich werde am Erdkreis die Bosheit heimsuchen und an den Gottlosen ihre Schuld*. Ich werde der Anmaßung der Stolzen ein Ende machen und den Hochmut der Gewalttätigen erniedrigen*.", footnotes: ["℘ Kap. 3,11; Spr 11,31", "℘ Kap. 2,12; 25,5; Dan 4,34"] },
      { number: 12, text: "Ich will den Sterblichen* seltener machen als gediegenes Gold und den Menschen seltener als Ofirgold*.", footnotes: ["w. den Menschen; hebr. änosch, ein dichterischer Ausdruck", "℘ Kap. 10,19"] },
      { number: 13, text: "Darum werde ich den Himmel erzittern lassen, und die Erde wird aufbeben von ihrer Stelle* beim Grimm des HERRN der Heerscharen und am Tage seiner Zornglut*.", footnotes: ["℘ Hi 9,6; Jer 4,24; Hag 2,6", "℘ Nah 1,6"] },
      { number: 14, text: "Und es wird wie mit einer verscheuchten Gazelle sein und wie mit einer Herde, die niemand sammelt; jeder wird sich zu seinem Volk wenden und jeder in sein Land fliehen." },
      { number: 15, text: "Wer irgend gefunden wird, soll durchbohrt werden; und wer irgend ergriffen wird*, soll durchs Schwert fallen.", footnotes: ["w. weggerafft wird; nämlich aus der Schar der Fliehenden"] },
      { number: 16, text: "Ihre Kinder werden vor ihren Augen zerschmettert*, ihre Häuser geplündert und ihre Frauen geschändet werden*.", footnotes: ["℘ Ps 137,9; Nah 3,10", "℘ Kla 5,11"] },
      { number: 17, text: "Siehe, ich erwecke gegen sie die Meder*, die Silber nicht achten und an Gold kein Gefallen haben.", footnotes: ["℘ Dan 5,28"] },
      { number: 18, text: "Ihre Bogen werden junge Männer niederstrecken*, und über die Leibesfrucht werden sie sich nicht erbarmen, und der Kinder wegen werden sie nicht betrübt sein*.", footnotes: ["Andere meinen, der Text habe ursprünglich gelautet: Die Bogen der jungen Männer werden zerschmettert", "w. und wegen der Kinder soll ihr Auge nicht fließen; d. h. weinen\n℘ Dan 7,5"] },
      { number: 19, text: "So wird es Babel, der Zierde der Königreiche, der stolzen Pracht der Chaldäer, ergehen wie nach der Umkehrung von Sodom und Gomorra durch Gott*.", footnotes: ["w. Und Babel . . . wird werden wie die Umstürzung Sodoms und Gomorras durch Gott.\n℘ 1Mo 19,24.25; 2Petr 2,6"] },
      { number: 20, text: "Nie mehr wird es bewohnt sein, und es bleibt unbesiedelt von Generation zu Generation. Und der Araber wird dort nicht zelten, und Hirten werden ihre Herden dort nicht lagern lassen*.", footnotes: ["℘ Kap. 25,2; Offb 18,2"] },
      { number: 21, text: "Aber Wüstentiere* werden dort lagern, und voller Eulen werden ihre Häuser sein. Strauße werden dort wohnen und Bocksdämonen* dort tanzen*.", footnotes: ["o. Dämonen", "w. Haarige", "℘ Kap. 25,2; Offb 18,2"] },
      { number: 22, text: "Wilde Hunde werden heulen in seinen Palästen* und Schakale in den Lustschlössern. Und seine Zeit steht nahe bevor, und seine Tage werden nicht verlängert werden*.", footnotes: ["℘ Kap. 14,23; 34,14; Zef 2,14", "℘ 5Mo 32,35"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Denn der HERR wird sich über Jakob erbarmen* und Israel noch einmal erwählen* und wird sie in ihr Land setzen*. Und der Fremde wird sich ihnen anschließen, und sie werden sich dem Haus Jakob zugesellen*.", heading: "Freude und Staunen über den Sturz Babels und seines Königs", footnotes: ["℘ Kap. 21,1-10; 47,1-15; Jer 50; 51", "℘ 3Mo 26,42; Ps 102,14; Hes 16,60; 39,25", "℘ Sach 1,17; Jer 31,4", "o. auf ihrem Land zur Ruhe bringen\n℘ Jer 16,15; 24,6; 29,14", "℘ Kap. 19,18; 56,3; Rt 1,16"] },
      { number: 2, text: "Und die Völker werden sie nehmen und sie an ihren Ort bringen*. Dann wird das Haus Israel diese als Knechte und Mägde in Erbbesitz nehmen im Land des HERRN*. Und sie werden die gefangen wegführen, die sie gefangen wegführten, und sie werden ihre Unterdrücker* niedertreten*.", footnotes: ["℘ Kap. 49,22; 60,4.9; 66,12.20", "℘ Kap. 61,5; 3Mo 25,44; Joe 4,8", "o. Antreiber", "℘ Kap. 60,14; Jer 49,2; Sach 2,13"] },
      { number: 3, text: "Und es wird geschehen, an dem Tag, an dem der HERR dir Ruhe verschafft von deiner Mühsal und deiner Unruhe und von dem harten Dienst, den man dir auferlegt hat*,", footnotes: ["℘ Kap. 40,2; Jer 30,8.10; Hebr 4,9"] },
      { number: 4, text: "da wirst du dieses Spottlied anstimmen über den König von Babel und sagen: Wie hat aufgehört der Unterdrücker*, aufgehört das Anstürmen*!", footnotes: ["o. Antreiber", "So mit Qu., LXX und syr. Üs. — Die Bedeutung des im Mas. T. stehenden Wortes ist unbekannt."] },
      { number: 5, text: "Zerbrochen hat der HERR den Stab der Gottlosen*, den Herrscherstab,", footnotes: ["℘ Kap. 9,3"] },
      { number: 6, text: "der Völker schlug im Grimm mit Schlägen ohne Unterlass, Nationen unterjochte* im Zorn mit Verfolgung* ohne Schonung*.", footnotes: ["w. niedertrat", "so mit der syr. Üs.; Mas. T.: der verfolgt wurde", "℘ Spr 28,15; Jer 48,17; Hab 2,5"] },
      { number: 7, text: "Es ruht, es rastet die ganze Erde. Man bricht in Jubel aus*.", footnotes: ["℘ Kap. 21,2; Hes 35,14; Offb 18,20; 19,1-3"] },
      { number: 8, text: "Auch die Wacholderbäume freuen sich über dich, die Zedern des Libanon: »Seitdem du daliegst, kommt der Holzfäller nicht mehr zu uns herauf.«" },
      { number: 9, text: "Der Scheol drunten ist in Bewegung deinetwegen, in Erwartung deiner Ankunft. Er stört deinetwegen die Schatten* auf, alle Mächtigen* der Erde, er lässt von ihren Thronen alle Könige der Nationen aufstehen.", footnotes: ["o. die Totengeister", "w. Leitböcke"] },
      { number: 10, text: "Sie alle beginnen und sagen zu dir: »Auch du bist kraftlos geworden wie wir, bist uns gleich*!«", footnotes: ["℘ Hes 32,21"] },
      { number: 11, text: "In den Scheol hinabgestürzt ist deine Pracht und der Klang deiner Harfen. Maden sind unter dir zum Lager ausgebreitet, und Würmer sind deine Decke*.", footnotes: ["℘ Hi 21,26"] },
      { number: 12, text: "Wie bist du vom Himmel gefallen*, du Glanzstern, Sohn der Morgenröte! Wie bist du zu Boden geschmettert, Überwältiger der Nationen!", footnotes: ["℘ Kap. 34,4; Offb 8,10"] },
      { number: 13, text: "Und du, du sagtest in deinem Herzen: »Zum Himmel will ich hinaufsteigen, hoch über den Sternen Gottes meinen Thron aufrichten* und mich niedersetzen auf den Versammlungsberg im äußersten Norden*.", footnotes: ["℘ Hi 20,6; Dan 8,10", "Dort dachten sich die Assyrer den Sitz ihrer Götterversammlung.\n℘ Hes 28,14"] },
      { number: 14, text: "Ich will hinaufsteigen auf Wolkenhöhen, dem Höchsten mich gleichmachen*.« —", footnotes: ["℘ 1Mo 3,5; Hes 28,2; Dan 11,36"] },
      { number: 15, text: "Doch in den Scheol wirst du hinabgestürzt, in die tiefste Grube*.", footnotes: ["℘ Kap. 2,12; Hes 31,14.16; Ob 3; Mt 11,23"] },
      { number: 16, text: "Die dich sehen, betrachten dich, sehen dich genau an: »Ist das der Mann, der die Erde erbeben ließ, Königreiche erschütterte?«" },
      { number: 17, text: "Er machte den Erdkreis der Wüste gleich und riss ihre Städte nieder. Seine Gefangenen entließ er nicht nach Hause*.", footnotes: ["℘ Hes 32,23; Hab 1,7-11"] },
      { number: 18, text: "Alle Könige* der Nationen, sie alle ruhen in Ehren, jeder in seinem Haus*.", footnotes: ["o. Seinen Gefangenen öffnete er nicht das Haus ihrer Gefangenschaft. 18 Die Könige", "℘ Hi 3,14"] },
      { number: 19, text: "Du aber bist hingeworfen fern von deiner Grabstätte wie ein verabscheuter Schössling*, bedeckt mit Erschlagenen*, vom Schwert Durchbohrten wie ein zertretenes Aas.", footnotes: ["Eine griech. Üs. liest: eine verabscheute Fehlgeburt", "w. dich bedecken wie ein Kleid die Erschlagenen"] },
      { number: 20, text: "Mit denen, die zu den Steinen der Grube hinabgefahren sind, mit ihnen* wirst du nicht vereint werden im Grab*. Denn du hast dein Land zugrunde gerichtet, dein Volk erschlagen. Das Geschlecht* von Übeltätern wird in Ewigkeit nicht mehr genannt werden*.", footnotes: ["So mit Umstellung der letzten beiden Gedankengänge in V. 19. Mas. T.: bedeckt mit . . . Durchbohrten, die zu den Steinen der Grube hinabgefahren sind, wie ein zertretenes Aas. 20 Mit ihnen", "℘ 2Kö 9,35", "w. Der Same", "℘ Hi 18,17"] },
      { number: 21, text: "Bereitet für seine Söhne die Schlachtbank zu um der Schuld ihrer Väter willen! Sie sollen sich nicht mehr erheben und die Erde in Besitz nehmen und die Fläche des Erdkreises mit Städten füllen." },
      { number: 22, text: "Und ich werde mich gegen sie erheben, spricht der HERR* der Heerscharen*, und werde von Babel ausrotten Namen und Rest und Spross und Nachkommen, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 12,6", "w. ist der Ausspruch des HERRN\n℘ Hi 18,19"] },
      { number: 23, text: "Ich werde es zum Besitz der Igel machen* und zu Wassersümpfen. Und ich werde es ausfegen mit dem Besen der Vertilgung, spricht der HERR* der Heerscharen*.", footnotes: ["℘ Kap. 34,11", "w. ist der Ausspruch des HERRN", "℘ Kap. 13,21.22"] },
      { number: 24, text: "Der HERR der Heerscharen hat geschworen und gesagt: Fürwahr, wie ich es erwog, so geschieht es, und wie ich es beschlossen habe, so kommt es zustande*:", heading: "Drohendes Gericht über Assur und die Philister", footnotes: ["℘ Kap. 46,10; 1Mo 41,32; Jos 11,20; Spr 19,21; Jer 23,20"] },
      { number: 25, text: "dass ich Assur in meinem Land zerschmettere und es auf meinen Bergen zertrete*. Dann weicht von ihnen sein Joch, und seine Last weicht von ihrer Schulter*.", footnotes: ["℘ Hes 32,22; Mi 5,5", "so mit LXX und Vulg.; Mas. T.: von seiner Schulter\n℘ Kap. 10,25-27; 2Chr 32,21; Sach 10,11"] },
      { number: 26, text: "Das ist der Ratschluss, der über die ganze Erde beschlossen ist, und das ist die Hand, die über alle Nationen ausgestreckt ist*.", footnotes: ["℘ Kap. 23,11; Jer 25,15-26; Zef 3,8"] },
      { number: 27, text: "Denn der HERR der Heerscharen hat es beschlossen. Wer wird es ungültig machen*? Und seine Hand ist ausgestreckt*. Wer wendet sie zurück?", footnotes: ["℘ Kap. 8,10; 43,13; 46,11; 2Chr 20,6; Hi 11,10; 42,2", "so mit der syr. Üs.; Mas. T.: seine ausgestreckte Hand; o. Ihm gehört die ausgestreckte Hand"] },
      { number: 28, text: "*Im Todesjahr des Königs Ahas* geschah dieser Ausspruch:", footnotes: ["℘ Hes 25,15-17; Sach 9,5-7", "℘ 2Chr 28,27"] },
      { number: 29, text: "Freue dich nicht, ganz Philistäa, dass der Stock zerbrochen ist, der dich schlug! Denn aus der Wurzel der Schlange* wird eine Otter hervorkommen, und ihre Frucht wird eine fliegende feurige Schlange sein.", footnotes: ["℘ Kap. 30,6"] },
      { number: 30, text: "Da werden die Erstgeborenen der Geringen* weiden und die Armen sich in Sicherheit lagern. Aber deine Wurzel werde ich durch Hunger töten, und deinen Rest werde ich* erschlagen.", footnotes: ["d. h. die Geringsten der Geringen", "so mit Qu.; Mas. T.: wird sie; »sie« bezöge sich dann auf die Schlange in V. 29"] },
      { number: 31, text: "Heule, Tor! Schrei um Hilfe, Stadt! Verzage, ganz Philistäa! Denn von Norden her kommt Rauch*, und keiner sondert sich ab von* seinen Scharen.", footnotes: ["℘ Kap. 20,1", "w. es gibt keinen Vereinzelten unter"] },
      { number: 32, text: "Und was antwortet man den Boten der Nation? Ja, der HERR hat die Grundmauern Zions gelegt*, und darin finden die Elenden seines Volkes Zuflucht*.", footnotes: ["℘ Ps 87,1.2", "℘ Kap. 25,4; Ps 48,4; Zef 3,12"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Ausspruch über Moab. Ja, über Nacht ist Ar-Moab* verwüstet, vernichtet; ja, über Nacht ist Kir-Moab verwüstet, vernichtet.", heading: "Drohendes Gericht über Moab", footnotes: ["℘ Kap. 16,6-14; Jer 48; Hes 25,8-11; Am 2,1-3; Zef 2,8-11", "℘ 4Mo 21,28; 5Mo 2,9.19"] },
      { number: 2, text: "Man* steigt zum Götzentempel* hinauf und nach Dibon* auf die Höhen, um zu weinen; auf* Nebo* und auf* Medeba* jammert Moab. Auf allen seinen Köpfen ist eine Glatze, jeder Bart ist abgeschoren*.", footnotes: ["o. Es (Moab)", "o. nach Bajit", "o. und Dibon steigt hinauf. — Andere ändern geringfügig entsprechend Jer 48,18 und lesen: Die Tochter Dibon steigt hinauf\n℘ 4Mo 21,30", "o. über", "℘ 4Mo 32,3", "o. über", "℘ Kap. 13,21.22", "℘ Kap. 3,24; 3Mo 21,5; Hes 7,18; Am 8,10"] },
      { number: 3, text: "Auf seinen Gassen gürten sie sich Sacktuch um*; auf seinen Dächern und auf seinen Marktplätzen jammert alles, in Tränen zerfließend.", footnotes: ["℘ Kla 2,10"] },
      { number: 4, text: "Heschbon und Elale* schreien um Hilfe; bis Jahaz* hört man ihre Stimme. Darum erheben die Gerüsteten* Moabs das Kriegsgeschrei, es zittert um sein Leben*.", footnotes: ["℘ 4Mo 32,3", "℘ 4Mo 21,23", "Mit geringfügiger Veränderung (z. T. mit LXX und syr. Üs.) lesen andere: Deshalb zittern Moabs Lenden", "w. seine Seele zittert in Bezug auf sich. — Qu. liest: es ergeht seiner Seele schlecht."] },
      { number: 5, text: "Mein Herz schreit um Hilfe für Moab — seine Flüchtlinge fliehen bis nach Zoar*, nach Eglat-Schelischija. Ja, die Anhöhe* von Luhit steigt man mit Weinen hinauf; ja, auf dem Weg nach Horonajim erhebt man Geschrei über den Zusammenbruch*.", footnotes: ["℘ 1Mo 19,22", "w. den Aufgang zur Stadt", "w. Zerbruchsgeschrei"] },
      { number: 6, text: "Ja, die Wasser von Nimrim* sollen zu Wüsten werden. Ja, verdorrt ist das Gras, verwelkt das Kraut; das Grün ist nicht mehr da.", footnotes: ["℘ 4Mo 32,3"] },
      { number: 7, text: "Darum trägt man über den Pappelbach, was man übrig hat und was man aufbewahrt hat." },
      { number: 8, text: "Ja, das Wehgeschrei umkreist* das Gebiet von Moab; bis nach Eglajim dringt sein Jammern und nach Beer-Elim* sein Jammern.", footnotes: ["o. durchkreist", "℘ 4Mo 21,16"] },
      { number: 9, text: "Ja, die Wasser von Dimon* sind voller Blut. Denn ich verhänge noch mehr Unheil über Dimon: einen Löwen über die Entkommenen Moabs und über den Rest des Landes.", footnotes: ["℘ 4Mo 21,30"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Sendet einen Widder des Landesherrn* von Sela* in der Wüste zum Berg* der Tochter Zion!", footnotes: ["℘ 2Kö 3,4", "℘ 2Kö 14,7", "o. vom Fels"] },
      { number: 2, text: "Und es geschieht: wie umherflatternde Vögel, wie ein aufgescheuchtes Nest sind die Töchter* Moabs an den Übergängen des Arnon*.", footnotes: ["Das sind die Ortschaften o. Bewohner.", "℘ 4Mo 21,13"] },
      { number: 3, text: "Schaffe Rat, triff Entscheidung! Am hellen Mittag mache deinen Schatten der Nacht gleich, verbirg die Vertriebenen, den Flüchtling verrate nicht!" },
      { number: 4, text: "Lass die Vertriebenen Moabs* sich bei dir als Fremde aufhalten! Sei ihnen ein Versteck vor dem Verwüster! — Wenn der Unterdrücker nicht mehr da ist, die Verwüstung aufgehört hat, die Zertreter aus dem Lande verschwunden sind,", footnotes: ["so mit 2 Handschr. sowie der griech. und syr. Üs.; Mas. T.: Lass meine Vertriebenen, Moab"] },
      { number: 5, text: "dann wird in Güte* ein Thron aufgerichtet werden. Und auf ihm — im Zelt Davids — wird einer in Beständigkeit* sitzen, der da richtet und nach Recht trachtet und der in Gerechtigkeit erfahren ist*.", footnotes: ["o. aus Gnade", "o. in Wahrheit; o. in Treue", "℘ Kap. 11,4; 2Chr 31,20.21"] },
      { number: 6, text: "*Wir haben gehört von dem Hochmut Moabs, dem sehr hochfahrenden, von seinem Stolz, seinem Hochmut und seiner Überheblichkeit, von seinem eitlen Prahlen*.", footnotes: ["℘ Kap. 15,1-9", "℘ Kap. 25,10-12"] },
      { number: 7, text: "Darum wird Moab heulen über Moab; alles wird heulen. Um die Traubenkuchen von Kir-Hareset* werdet ihr seufzen, ganz zerschlagen.", footnotes: ["℘ 2Kö 3,25"] },
      { number: 8, text: "Denn Heschbons Terrassengärten sind verwelkt, die Weinstöcke von Sibma*, deren edle Trauben die Herren der Nationen mit Trunkenheit bezwangen. Bis nach Jaser* reichten sie, verloren sich in die Wüste*. Seine Ranken breiteten sich aus, gingen über das Meer*.", footnotes: ["℘ 4Mo 21,32; 32,35.38", "℘ 4Mo 21,30", "o. der Weinstock von Sibma. Die Herren der Nationen schlugen seine edlen Trauben nieder, die bis Jaser reichten, sich in die Wüste verloren.", "d. i. das Tote Meer"] },
      { number: 9, text: "Darum beweine ich, wie Jaser weint, den Weinstock von Sibma, mit meinen Tränen tränke ich dich satt, Heschbon und Elale. Denn über dein Sommerobst und über deinen Ernteertrag ist das Jauchzen der Feinde gefallen." },
      { number: 10, text: "Da sind Freude und Jubel aus den Fruchtgärten abgeerntet, und in den Weinbergen wird nicht gejubelt, nicht gejauchzt. In den Kelterkufen tritt kein Kelterer den Wein; dem Jauchzen* habe ich ein Ende gemacht*.", footnotes: ["d. h. dem Jubelruf der Kelterer, während sie die Trauben ausstampfen; vgl. Jer 25,30; 48,33", "℘ Hes 7,7"] },
      { number: 11, text: "Darum klagen* meine Eingeweide über Moab wie eine Zither und mein Inneres* über Kir-Heres.", footnotes: ["w. lärmen", "℘ Kap. 21,3"] },
      { number: 12, text: "Und es wird geschehen, wenn Moab erscheint, sich abmüht auf der Opferhöhe und in sein Heiligtum eintritt, um zu beten, dann wird es nichts ausrichten*.", footnotes: ["℘ Jer 10,5; 48,13"] },
      { number: 13, text: "Das ist das Wort, das der HERR einst über Moab geredet hat." },
      { number: 14, text: "Jetzt aber redet der HERR und spricht: In drei Jahren, wie die Jahre eines Tagelöhners*, wird die Herrlichkeit Moabs verächtlich sein samt all der großen Menge. Und der Rest wird winzig klein, gar nicht groß sein.", footnotes: ["℘ Kap. 21,16; Hi 7,1"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "*Ausspruch über Damaskus. Siehe, Damaskus hört auf, eine Stadt zu sein, und wird ein Trümmerhaufen*.", heading: "Drohendes Gericht über Damaskus und das Reich Israel", footnotes: ["℘ Jer 49,23-27; Am 1,3-5", "℘ Kap. 8,4"] },
      { number: 2, text: "Verlassen sind die Städte von Aroër*, sie werden den Herden preisgegeben*; die lagern dort und niemand schreckt sie auf.", footnotes: ["LXX: Verlassen ist sie für ewig\n℘ Jos 13,25", "℘ Hes 25,5"] },
      { number: 3, text: "Und verschwinden wird die feste Stadt aus Ephraim und das Königtum aus Damaskus. Und dem Rest von Aram ergeht es* wie der Herrlichkeit der Söhne Israel, spricht der HERR* der Heerscharen.", footnotes: ["so mit Qu.; Mas. T.: verschwinden wird die Festung . . . und das Königtum . . . und der Rest Arams. Ihnen ergeht es", "w. ist der Ausspruch des HERRN"] },
      { number: 4, text: "Und es wird geschehen an jenem Tag, da wird die Herrlichkeit Jakobs armselig sein* und das Fett seines Fleisches mager werden*.", footnotes: ["℘ 2Kö 17,3-6", "℘ Kap. 10,16"] },
      { number: 5, text: "Es wird sein, wie wenn einer bei der Ernte* Getreidehalme zusammenfasst und sein Arm Ähren abmäht*. Es wird sein, wie wenn einer Ähren sammelt in der Talebene Refaïm*.", footnotes: ["Mit geringfügiger Änderung lesen andere: wenn ein Schnitter", "℘ Joe 4,13", "℘ Jos 15,8"] },
      { number: 6, text: "— Doch wird eine Nachlese an ihm* übrig bleiben wie beim Abschlagen der Oliven: zwei, drei reife Oliven oben im Geäst, vier, fünf an den Zweigen des Fruchtbaums, spricht der HERR*, der Gott Israels*. —", footnotes: ["d. i. an Jakob; vgl. V. 4", "w. ist der Ausspruch des HERRN", "℘ Kap. 24,13; Jer 4,27"] },
      { number: 7, text: "An jenem Tag wird der Mensch auf den hinschauen, der ihn gemacht hat, und seine Augen werden auf den Heiligen Israels sehen*.", footnotes: ["℘ Kap. 10,20; Am 3,12"] },
      { number: 8, text: "Und er wird nicht schauen auf die Altäre, das Werk seiner Hände. Und was seine Finger gemacht haben, wird er nicht ansehen, weder die Ascherim noch die Räucheraltäre*. —", footnotes: ["℘ Kap. 27,9; 2Chr 31,1; Hos 14,9"] },
      { number: 9, text: "An jenem Tag werden seine Festungsstädte sein wie die verlassenen Orte des Waldes und des Berggipfels, die man vor den Söhnen Israel verließ*; und es wird eine Öde sein*. —", footnotes: ["LXX: werden deine Städte verlassen sein, wie sie die Hiwiter und Amoriter vor den Söhnen Israel verließen", "℘ Mi 7,13"] },
      { number: 10, text: "Ja, du hast vergessen den Gott deines Heils* und nicht gedacht an den Felsen deiner Zuflucht*. Deshalb pflanze nur Pflanzungen des »Lieblichen«* und besäe sie nur mit ausländischen Weinranken!", footnotes: ["℘ Kap. 51,13; 5Mo 6,12; 32,18; Ps 106,21; Hos 8,14", "℘ Kap. 44,8; Hes 22,12; Hos 8,14", "Wahrscheinlich sind Gärten zu Ehren des syr.-phöniz. Frühlingsgottes Adonis gemeint."] },
      { number: 11, text: "Am Tag, da du gepflanzt, ziehst du sie groß*, und am Morgen, da du gesät, bringst du sie zum Blühen: hin ist die Ernte* am Tag des Siechtums und des unheilbaren Schmerzes.", footnotes: ["o. zäunst du sie ein", "o. geflohen ist die Ernte; so liest Vulg.; Mas. T.: ein Wall der Ernte"] },
      { number: 12, text: "Wehe, ein Getöse vieler Völker; wie das Tosen der Meere tosen sie; und ein Rauschen von Völkerschaften; wie das Rauschen gewaltiger Wasser rauschen sie*.", footnotes: ["℘ Kap. 5,30; 8,7.8; Dan 7,2; Offb 17,15"] },
      { number: 13, text: "Völkerschaften rauschen wie das Rauschen vieler Wasser. Doch er bedroht sie, und sie fliehen* in die Ferne*. Und sie werden gejagt wie Spreu auf den Bergen vor dem Wind und wie die Raddistel* vor dem Sturm*.", footnotes: ["w. er schreit ihn an und er flieht", "℘ Kap. 31,8.9; Ps 65,8", "Das sind ihre radförmigen, abgestorbenen Stengel.", "℘ Kap. 29,5; 33,3; 40,24; Hi 21,18; Ps 83,14"] },
      { number: 14, text: "Zur Abendzeit, siehe da, jähes Erschrecken. Ehe es Morgen wird, gibt es sie nicht mehr*. Das ist das Geschick* derer, die uns plündern, und das Los derer, die uns berauben*.", footnotes: ["℘ 2Kö 19,35; Ps 37,36", "w. der Beuteanteil", "℘ Kap. 30,28; 33,1; Sach 2,12"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Wehe, Land des Flügelgeschwirrs, jenseits der Ströme von Kusch*,", heading: "Drohendes Gericht über Kusch", footnotes: ["℘ 2Kö 19,9; Hes 30,9; Zef 3,10"] },
      { number: 2, text: "das Boten auf dem Meer* entsendet und in Papyruskähnen über der Wasserfläche! Geht hin, schnelle Boten, zu der Nation, die hochgewachsen und blank* ist, zu dem Volk, das weit und breit gefürchtet ist, zu der Nation, die mit gespannter Kraft* alles zertritt, deren Land Ströme durchschneiden*!", footnotes: ["Eine im Altertum gebräuchliche Bezeichnung für große Ströme. Hier ist der Nil gemeint; vgl. Anm. zu Jer 51,36.", "o. glänzend. — Vielleicht ist die glänzende, mit Öl eingeriebene Haut gemeint.", "so mit Qu.; Mas. T.: Nationen der Messschnur auf Messschnur", "o. fortschwemmen. — Damit könnten die Überschwemmungen des Nil gemeint sein."] },
      { number: 3, text: "Ihr alle, Bewohner des Festlandes und die ihr auf der Erde ansässig seid, wenn man ein Feldzeichen auf den Bergen aufrichtet*, seht hin! Und wenn man ins Horn stößt, hört hin!", footnotes: ["℘ Kap. 11,12; 13,2"] },
      { number: 4, text: "Denn so hat der HERR zu mir gesprochen*: Ich will mich ruhig verhalten und will zuschauen an meiner Stätte*, wie flimmernde Glut bei Sonnenschein, wie Taugewölk in der Ernteglut.", footnotes: ["℘ Am 3,7", "℘ Kap. 57,15; 2Chr 6,21"] },
      { number: 5, text: "Denn vor der Ernte, wenn die Blüte vorbei ist und die Blume zur reifenden Traube wird, wird er die Reben abschneiden mit Winzermessern und die Ranken entfernen und abreißen*.", footnotes: ["℘ Kap. 10,33.34"] },
      { number: 6, text: "Sie werden allesamt den Raubvögeln der Berge und den Tieren der Erde überlassen werden*. Und die Raubvögel werden den Sommer darauf zubringen, und alle Tiere der Erde werden darauf überwintern.", footnotes: ["℘ Hes 31,13"] },
      { number: 7, text: "In jener Zeit wird dem HERRN der Heerscharen ein Geschenk dargebracht werden: von einem Volk*, das hochgewachsen und blank* ist, und von einem Volk, das weit und breit gefürchtet ist, von einer Nation, die mit gespannter Kraft* alles zertritt, deren Land Ströme durchschneiden* — zur Stätte des Namens des HERRN der Heerscharen, zum Berg Zion*.", footnotes: ["so mit Qu., LXX und Vulg.; Mas. T.: wird dem HERRN . . . als Geschenk gebracht ein Volk", "o. glänzend. — Vielleicht ist die glänzende, mit Öl eingeriebene Haut gemeint.", "so mit Qu.; Mas. T.: Nationen der Messschnur auf Messschnur", "o. fortschwemmen. — Damit könnten die Überschwemmungen des Nil gemeint sein.", "℘ Kap. 45,14; Ps 68,32; Zef 3,10"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Ausspruch über Ägypten. Siehe, der HERR fährt auf einer schnellen Wolke* und kommt nach Ägypten. Da beben die Götzen Ägyptens vor ihm*, und das Herz Ägyptens zerschmilzt in seinem Innern.", heading: "Drohendes Gericht über Ägypten", footnotes: ["℘ Jer 46,2-26; Hes 29-32", "℘ 5Mo 33,26", "℘ 4Mo 33,4; Jer 43,12"] },
      { number: 2, text: "Und ich will Ägypten gegen Ägypten aufstacheln, dass sie kämpfen werden, jeder gegen seinen Bruder und jeder gegen seinen Nächsten, Stadt gegen Stadt, Königreich gegen Königreich*.", footnotes: ["℘ Kap. 3,5; 2Chr 15,6"] },
      { number: 3, text: "Dann wird der Geist Ägyptens in seinem Innern verstört werden, und seinen Ratschlag will ich verwirren*: da werden sie die Götzen und die Totenbeschwörer, die Totengeister und die Wahrsager* befragen*.", footnotes: ["℘ Kap. 44,25; Hi 5,12.13", "w. die Wissenden", "℘ Kap. 47,12; 2Kö 1,2"] },
      { number: 4, text: "Und ich will Ägypten ausliefern in die Hand eines harten Herrn. Und ein grausamer König wird über sie herrschen, spricht der Herr, der HERR der Heerscharen*. —", footnotes: ["w. ist der Ausspruch des Herrn, des HERRN der Heerscharen\n℘ Kap. 20,3.4"] },
      { number: 5, text: "Und das Wasser wird im Meer* versiegen*, und der Strom wird verdunsten und austrocknen*,", footnotes: ["Eine im Altertum gebräuchliche Bezeichnung für große Ströme. Hier ist der Nil gemeint; vgl. Anm. zu Jer 51,36.", "w. werden aus dem Meer ausgetrocknet werden\n℘ Jer 51,36", "℘ Kap. 37,25"] },
      { number: 6, text: "und die Ströme werden stinkend werden. Die Kanäle Mazors* werden armselig werden und vertrocknen, Rohr und Schilf werden schwarz* werden.", footnotes: ["Mazor ist ein anderes Wort für Ägypten, viell. speziell für Unterägypten. Innerhalb der Gerichtsankündigung ist die gleichzeitige Bedeutung von Mazor, »Bedrängnis, Belagerung«, zu beachten.\n℘ 2Kö 19,24", "℘ Hi 8,11.12"] },
      { number: 7, text: "Die Binsen am Nil, an der Mündung des Nil, und jedes Saatfeld am Nil verdorrt, wird verweht und besteht nicht mehr." },
      { number: 8, text: "Da klagen die Fischer, und es trauern alle, die die Angel in den Nil auswerfen. Und die auf der Wasserfläche das Netz ausbreiten, werden hinfällig*.", footnotes: ["w. welken\n℘ 2Mo 7,21"] },
      { number: 9, text: "Und zuschanden werden die, die Flachsstängel zu Gekämmtem verarbeiten, und die Weber erbleichen*.", footnotes: ["so mit Qu.; LXX: und die, die Byssus herstellen; Mas. T. vielleicht: und die Weber von Leinentüchern"] },
      { number: 10, text: "Und seine Grundpfeiler sind zerschlagen*. Alle, die um Lohn arbeiten, sind in ihrer Seele betrübt.", footnotes: ["Andere üs. mit Textänderung: Und seine Weber sind niedergeschlagen."] },
      { number: 11, text: "Lauter Toren sind die Obersten von Zoan*, die weisen Ratgeber des Pharao. Ihr Ratschlag hat sich als dumm erwiesen*. Wie sagt ihr zum Pharao: Ein Sohn der Weisen bin ich, ein Sohn von Königen der Vorzeit*?", footnotes: ["℘ Kap. 30,4; 4Mo 13,22", "℘ Kap. 29,14; 2Mo 8,14", "℘ 1Kö 5,10"] },
      { number: 12, text: "Wo sind sie denn, deine Weisen*? Mögen sie dir doch verkünden und erkennen, was der HERR der Heerscharen über Ägypten beschlossen hat*.", footnotes: ["℘ 1Kor 1,20; Ob 8", "℘ Kap. 41,23; 44,7"] },
      { number: 13, text: "Die Obersten von Zoan sind zu Toren geworden, die Obersten von Nof* sind betrogen. Die Anführer* seiner Stämme haben Ägypten zum Taumeln gebracht.", footnotes: ["d. i. Memfis\n℘ Jer 44,1; Hos 9,6", "w. Der Eckstein o. Eckturm"] },
      { number: 14, text: "Der HERR hat in seiner Mitte einen Geist des Schwindels gebraut*, dass sie Ägypten zum Taumeln gebracht haben in all seinem Tun, wie ein Trunkener taumelt in seinem Erbrochenen*.", footnotes: ["w. gemischt\n℘ 1Kö 22,22; 2Chr 18,22", "℘ Kap. 29,9; Hi 12,25; Jer 48,26"] },
      { number: 15, text: "Und Ägypten wird keine Tat mehr gelingen, die Kopf oder Schwanz, Palmzweig oder Binse verrichten wollen*.", footnotes: ["℘ Kap. 9,13.14"] },
      { number: 16, text: "An jenem Tag werden die Ägypter wie Frauen sein*. Sie werden zittern und beben vor dem Schwingen der Hand des HERRN der Heerscharen, die er gegen sie schwingen wird*.", heading: "Ägypten und Assur mit Israel im zukünftigen Friedensreich", footnotes: ["℘ Jer 51,30; Nah 3,13", "℘ Kap. 11,15; 2Mo 11,6; Sach 2,13; 10,11"] },
      { number: 17, text: "Und das Land Juda wird für Ägypten zum Schrecken werden. Sooft jemand es bei den Ägyptern erwähnt, werden sie* beben vor dem Ratschluss des HERRN der Heerscharen, den er über sie beschlossen hat.", footnotes: ["w. es vor ihm erwähnt, wird es"] },
      { number: 18, text: "An jenem Tag werden fünf Städte im Land Ägypten sein, die die Sprache Kanaans reden und dem HERRN der Heerscharen schwören werden*. Eine wird Ir-Heres* heißen.", footnotes: ["d. h. sich dem HERRN . . . durch einen Schwur weihen\n℘ Kap. 14,1; Zef 3,9", "d. h. Stadt des Niederreißens. Andere deuten sie auch als Sonnenstadt (Heliopolis)."] },
      { number: 19, text: "An jenem Tag wird mitten im Land Ägypten dem HERRN ein Altar geweiht sein* und ein Gedenkstein für den HERRN nahe an seiner Grenze.", footnotes: ["℘ Jos 22,27"] },
      { number: 20, text: "Und er wird zu einem Zeichen und zu einem Zeugnis für den HERRN der Heerscharen im Land Ägypten werden: Wenn sie zum HERRN schreien werden wegen der Unterdrücker, dann wird er ihnen einen Retter senden; der wird den Streit führen und sie retten." },
      { number: 21, text: "Und der HERR wird sich den Ägyptern zu erkennen geben, und die Ägypter werden an jenem Tag den HERRN erkennen. Dann werden sie dienen mit Schlachtopfern und Speisopfern und werden dem HERRN Gelübde tun und sie erfüllen*.", footnotes: ["℘ Ps 68,32; Mal 1,11"] },
      { number: 22, text: "Und der HERR wird die Ägypter schlagen, schlagen und heilen. Und sie werden sich zum HERRN wenden, und er wird sich von ihnen erbitten lassen und sie heilen*.", footnotes: ["℘ 5Mo 32,39; 2Kö 20,5; Hi 5,18"] },
      { number: 23, text: "An jenem Tag wird es eine Straße von Ägypten nach Assur geben*. Assur wird nach Ägypten und die Ägypter nach Assur kommen, und die Ägypter werden mit Assur dem HERRN dienen*.", footnotes: ["℘ Kap. 11,16; Mi 7,12", "℘ Kap. 2,3"] },
      { number: 24, text: "An jenem Tag wird Israel der Dritte sein mit Ägypten und mit Assur, ein Segen inmitten der Erde*.", footnotes: ["℘ Sach 8,13"] },
      { number: 25, text: "Denn der HERR der Heerscharen segnet es* und spricht: Gesegnet sei Ägypten, mein Volk, und Assur, meiner Hände Werk, und Israel, mein Erbteil!*", footnotes: ["LXX liest: inmitten der Erde, 25 die der HERR . . . segnet", "℘ Kap. 63,17; 5Mo 32,9; Jer 2,7; 10,16; Sach 2,16"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*In dem Jahr, in dem der Tartan* nach Aschdod* kam, als Sargon, der König von Assur, ihn gesandt hatte und er gegen Aschdod kämpfte* und es einnahm,", heading: "Ankündigung des Sieges Assurs über Ägypten und Kusch", footnotes: ["℘ Hes 29-32", "d. i. ein assyrischer Titel des Oberfeldherrn\n℘ 2Kö 18,17", "℘ 1Sam 5,1; 2Chr 26,6", "℘ Kap. 14,31"] },
      { number: 2, text: "in dieser Zeit redete der HERR durch Jesaja, den Sohn des Amoz: Geh und löse das Sacktuch von deinen Hüften und ziehe deine Sandalen von deinen Füßen! Und er tat es, ging nackt* und barfuß.", footnotes: ["d. h. ohne Oberkleid\n℘ 1Sam 19,24; Mi 1,8"] },
      { number: 3, text: "Da sprach der HERR: Ebenso wie mein Knecht Jesaja nackt und barfuß gegangen ist, drei Jahre lang als Zeichen und Wahrzeichen* über Ägypten und über Kusch*,", footnotes: ["℘ Jer 13,1; Hes 4,1.3", "℘ Hes 30,4"] },
      { number: 4, text: "so wird der König von Assur die Gefangenen Ägyptens und die Weggeführten von Kusch wegtreiben, junge Männer und Greise, nackt und barfuß und mit entblößtem Gesäß, zur Schande Ägyptens*.", footnotes: ["℘ Kap. 19,4; 2Sam 10,4; Jer 46,19"] },
      { number: 5, text: "Und sie werden schreckerfüllt und beschämt sein wegen Kuschs, ihrer Hoffnung, und wegen Ägyptens, ihres Stolzes*.", footnotes: ["℘ Kap. 30,3.5.7; 36,6; Zef 2,12"] },
      { number: 6, text: "Und die Bewohner dieses Küstenlandes* werden an jenem Tag sagen: Siehe, so ist es mit unserer Hoffnung, zu der wir um Hilfe flohen, um vor dem König von Assur gerettet zu werden! Wie sollten wir da entrinnen?*", footnotes: ["d. i. Palästinas", "℘ Kap. 31,3"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Ausspruch über die Wüste des Meeres*. Wie Stürme, wenn sie im Süden daherfahren*, so kommt es aus der Wüste, aus einem furchtbaren Land.", heading: "Weissagung der Verwüstung Babels", footnotes: ["℘ Kap. 13; 14; 47,1-15; Jer 50; 51", "Gemeint ist wahrscheinlich Babel. Im Akkadischen findet sich die Bezeichnung »Meerland« für Babylonien.", "℘ Hi 37,9"] },
      { number: 2, text: "Ein hartes Gesicht wurde mir kundgetan: Der Räuber raubt*, und der Verwüster verwüstet. Auf, Elam*! Belagere, Medien*! All ihrem Seufzen mache ich ein Ende*.", footnotes: ["w. Der Treulose handelt treulos\n℘ Kap. 24,16", "℘ Kap. 11,11; 1Mo 10,22; Jer 49,34.35; Dan 8,2", "℘ Jer 25,25", "℘ Kap. 14,4-7"] },
      { number: 3, text: "Darum sind meine Hüften voll Beben, Wehen haben mich gepackt wie die Wehen einer Gebärenden. Ich krümme mich, dass ich nicht hören, bin bestürzt, dass ich nicht sehen kann*.", footnotes: ["o. Ich bin verstört von dem, was ich höre, bin von Sinnen vor dem, was ich sehe.\n℘ Kap. 13,8; 16,11"] },
      { number: 4, text: "Mein Herz rast, Schauder hat mich überfallen*. Die Dämmerung, die ich liebe, hat er mir in Schrecken verwandelt.", footnotes: ["℘ Ps 55,6; Jer 4,19"] },
      { number: 5, text: "Man rüstet den Tisch, man ordnet die Polster*, man isst, man trinkt*: »Steht auf, ihr Obersten! Salbt den Schild*!« —", footnotes: ["w. das Überzogene. — Andere üs.: es späht der Späher", "℘ Dan 5,1", "℘ 2Sam 1,21"] },
      { number: 6, text: "Denn so hat der Herr zu mir gesprochen: Geh hin, stell einen Späher auf! Was er sieht, soll er berichten*.", footnotes: ["℘ 2Sam 18,25; Hab 2,1"] },
      { number: 7, text: "Und sieht er einen Wagenzug, ein Pferdegespann, einen Zug Esel, einen Zug Kamele, dann horche er gespannt auf, mit großer Aufmerksamkeit!" },
      { number: 8, text: "Da rief er wie ein Löwe*: Auf der Turmwarte, Herr, stehe ich beständig am Tag, und auf meinem Wachtposten stehe ich bereit alle Nächte hindurch!", footnotes: ["mit Qu. und syr. Üs.: Da rief der Seher"] },
      { number: 9, text: "Und siehe da, es kam ein Wagenzug von Männern, ein Pferdegespann . . . Und er fing an und sprach: Gefallen, gefallen ist Babel*, und alle Götzenbilder* seiner Götter sind* zu Boden geschmettert!*", footnotes: ["℘ Offb 14,8", "d. h. Standbilder aus Holz, Stein oder Metall", "so mit Qu.; Mas. T.: hat er", "℘ Kap. 46,1; Jer 51,47"] },
      { number: 10, text: "Du mein gedroschenes Volk und Sohn meiner Tenne! Was ich vom HERRN der Heerscharen, dem Gott Israels, gehört, habe ich euch verkündigt*.", footnotes: ["℘ Jer 23,28; Am 3,8"] },
      { number: 11, text: "*Ausspruch über Duma*. Aus Seïr* ruft man mir zu: Wächter*, wie weit ist es in der Nacht? Wächter, wie weit in der Nacht?", heading: "Ausspruch über Duma und Arabien", footnotes: ["℘ Kap. 34,5-17; Jer 49,7-22; Hes 25,12-14; 35,1-15; Am 1,11.12; Ob", "Duma kann mit »Totenstille« üs. werden, was sich als Bild auf Edom (Seïr) übertragen ließe. Manche nehmen für Duma eine Verschreibung aus »Edom« an, was das folgende Seïr, das häufig für »Edom« steht, nahelegt.", "℘ 1Mo 32,4", "℘ Hes 33,7"] },
      { number: 12, text: "Der Wächter sagt: Der Morgen ist gekommen*, und doch ist auch noch Nacht. Wollt ihr fragen, so fragt! Kommt noch einmal her*!*", footnotes: ["℘ Röm 13,12", "w. Kehrt zurück, kommt", "℘ Hes 33,11"] },
      { number: 13, text: "*Ausspruch gegen Arabien*. In der Wildnis von Arabien* müsst ihr übernachten, Karawanen der Dedaniter*.", footnotes: ["℘ Jer 49,28-33", "o. Ausspruch in der Steppe", "o. Im Gestrüpp, in der Steppe\n℘ Jer 25,24", "℘ 1Mo 25,3; Jer 49,8"] },
      { number: 14, text: "Bringt dem Durstigen Wasser entgegen, Bewohner des Landes Tema!* Geht dem Flüchtling entgegen mit Brot für ihn!", footnotes: ["℘ 1Chr 1,30; Hi 6,19"] },
      { number: 15, text: "Denn sie flohen vor den Schwertern, vor dem gezückten Schwert, vor dem gespannten Bogen und vor der Wucht des Krieges." },
      { number: 16, text: "Denn so hat der Herr zu mir gesprochen: In noch einem Jahr*, hart wie die Jahre eines Tagelöhners*, wird alle Herrlichkeit Kedars* verschwinden.", footnotes: ["Qu. liest mit Kap. 16,14: In noch drei Jahren", "℘ Kap. 16,14", "℘ Kap. 60,7; 1Mo 25,13"] },
      { number: 17, text: "Und die übrig gebliebene Zahl der Bogen der Helden von den Söhnen Kedar wird gering sein. Denn der HERR, der Gott Israels, hat geredet*.", footnotes: ["℘ Kap. 31,2; 34,16; 45,23; 4Mo 23,19"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Ausspruch über das Tal der Offenbarung*. Was ist dir denn, dass du insgesamt auf die Dächer gestiegen bist?*", heading: "Gegen Sorglosigkeit und Verblendung in Jerusalem", footnotes: ["o. der Vision; wahrscheinlich ist Jerusalem gemeint\n℘ Jer 21,13", "℘ Jer 19,13; 32,29; Zef 1,5"] },
      { number: 2, text: "Du lärmende Stadt voller Getümmel, du ausgelassene Stadt*, deine Erschlagenen sind nicht mit dem Schwert Erschlagene* und nicht in der Schlacht Getötete!*", footnotes: ["℘ Kap. 32,13", "w. deine Durchbohrten sind nicht Schwertdurchbohrte", "℘ Kla 4,9.10"] },
      { number: 3, text: "All deine Anführer sind miteinander geflohen, ohne einen Bogenschuss wurden sie gefangen, alle, die man in dir fand, wurden miteinander gefangen, weit fort wollten sie fliehen*.", footnotes: ["℘ 2Kö 25,4-7; Jer 39,4.5"] },
      { number: 4, text: "Darum sage ich: Schau weg von mir! Bitterlich weinen muss ich*. Dringt nicht darauf, mich zu trösten über die Verwüstung der Tochter meines Volkes!", footnotes: ["℘ Est 4,1; Jer 8,23"] },
      { number: 5, text: "Denn ein Tag der Bestürzung, der Zertretung und der Verwirrung kam vom Herrn, dem HERRN der Heerscharen*, im Tal der Offenbarung*. Es bricht die Mauer*, und Hilfegeschrei hallt zum Gebirge hin.*", footnotes: ["℘ Zef 1,15", "o. der Vision; wahrscheinlich ist Jerusalem gemeint", "℘ Kla 2,2.8", "o. Im Tal der Offenbarung lärmt der Lärm, Hilfegeschrei am Berg!"] },
      { number: 6, text: "Und Elam* erhebt den Köcher mit bemannten Wagen und Reitern; und Kir* enthüllt den Schild.", footnotes: ["℘ Kap. 11,11", "℘ 2Kö 16,9"] },
      { number: 7, text: "Und es wird geschehen, deine auserlesenen Talebenen werden voller Wagen sein, und die Reiter nehmen Stellung gegen das Tor*.", footnotes: ["℘ Hes 4,2.3"] },
      { number: 8, text: "Da nimmt man Judas Schutz weg*. Aber du blickst an jenem Tag nach den Waffen des Waldhauses*.", footnotes: ["w. Und man deckt Judas Decke auf", "℘ 1Kö 10,17"] },
      { number: 9, text: "Und ihr seht die Risse der Stadt Davids, dass sie zahlreich sind, und ihr sammelt das Wasser des unteren Teiches*.", footnotes: ["℘ 2Chr 32,4.5"] },
      { number: 10, text: "Auch zählt ihr die Häuser von Jerusalem und brecht die Häuser ab, um die Mauer unzugänglich zu machen*.", footnotes: ["℘ Jer 33,4"] },
      { number: 11, text: "Und ihr macht ein Sammelbecken zwischen den beiden Mauern für die Wasser des alten Teiches*. Aber ihr blickt nicht auf den, der es getan, und seht den nicht an, der es lange vorher* gebildet hat*. —", footnotes: ["℘ Kap. 7,3; 2Kö 20,20", "o. von ferne", "o. geplant hat\n℘ Kap. 37,26"] },
      { number: 12, text: "Und an jenem Tag ruft der Herr, der HERR der Heerscharen, zum Weinen und zur Wehklage auf, zum Kahlscheren und zum Umgürten von Sacktuch*.", footnotes: ["℘ Kap. 37,1.2; Joe 1,13; 2,12; Mi 1,16; Jak 4,9"] },
      { number: 13, text: "Aber siehe, Wonne und Freude, Rindertöten und Schafeschlachten, Fleischessen und Weintrinken*: Lasst uns essen und trinken, denn morgen sterben wir!*", footnotes: ["℘ Kap. 5,11.12; 56,12", "℘ 1Kor 15,32"] },
      { number: 14, text: "Aber der HERR der Heerscharen hat sich meinen Ohren offenbart*: Wenn euch diese Schuld vergeben wird, bis ihr sterbt*, spricht der Herr, der HERR der Heerscharen.", footnotes: ["℘ Kap. 5,9", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Am 8,7"] },
      { number: 15, text: "So sprach der Herr, der HERR der Heerscharen: Auf! Geh zu diesem Verwalter da, zu Schebna*, der über das Haus des Königs bestellt ist, und sprich:", heading: "Absetzung des Schebna, Einsetzung des Eljakim", footnotes: ["℘ Kap. 36,3; 37,2; 2Kö 18,18"] },
      { number: 16, text: "Was hast du hier, und wen hast du hier, dass du dir hier ein Grab aushaust? — du, der sein Grab aushaut hier auf der Höhe, sich eine Wohnung in den Felsen meißelt?*", footnotes: ["℘ Hi 3,14"] },
      { number: 17, text: "Siehe, der HERR wird dich weit wegschleudern*, dich hin- und herschütteln, Mann*! Er wird dich fest packen,", footnotes: ["℘ Jer 10,18", "T.; Mas. T.: mit dem Hin- und Herschütteln eines Mannes"] },
      { number: 18, text: "zu *einem Knäuel wird er dich fest zusammenwickeln, wie den Ball dich wegschleudern* in ein Land, das nach beiden Seiten weit ausgedehnt ist. Dort wirst du sterben*, und dorthin kommen deine Prunkwagen, du Schande für das Haus deines Herrn!", footnotes: ["Andere üs. in Anlehnung an ähnlich klingende arabische Wörter: mit kräftigem Fußtritt wird er dich wegtreten wie einen Ball", "Andere üs. in Anlehnung an ähnlich klingende arabische Wörter: mit kräftigem Fußtritt wird er dich wegtreten wie einen Ball", "℘ Am 7,17"] },
      { number: 19, text: "Und ich werde dich von deinem Posten wegstoßen, und aus deiner Stellung wird man dich herunterreißen. —" },
      { number: 20, text: "Und es wird geschehen an jenem Tag, da werde ich meinen Knecht Eljakim rufen, den Sohn des Hilkija*.", footnotes: ["℘ Kap. 36,3; 37,2; 2Kö 18,18"] },
      { number: 21, text: "Und ich werde ihn mit deinem Leibrock bekleiden und ihm deinen Gürtel* fest umbinden und werde deine Herrschaft in seine Hand geben. Und er wird den Bewohnern von Jerusalem und dem Haus Juda zum Vater sein*.", footnotes: ["Der hebr. Ausdruck bezeichnet nur den Gürtel oder die Schärpe der Priester und Amtspersonen.", "℘ 1Mo 45,8"] },
      { number: 22, text: "Und ich werde den Schlüssel des Hauses David auf seine Schulter legen. Er wird öffnen, und niemand wird schließen, er wird schließen, und niemand wird öffnen*.", footnotes: ["℘ Hi 12,14; Offb 3,7"] },
      { number: 23, text: "Und ich werde ihn als Pflock einschlagen* an einen festen Ort; und er wird seinem Vaterhaus zum Thron der Würde* sein.", footnotes: ["℘ Esr 9,8; Sach 10,4", "hebr. kabod; kann sowohl »Ehre«, »Würde«, als auch »Gewicht«, »Bürde« heißen"] },
      { number: 24, text: "Dann werden sie sich an ihn hängen — die ganze Bürde* seines Vaterhauses: die Sprösslinge und die Schösslinge, alle kleinen Gefäße, von den Beckengefäßen bis zu allen Kruggefäßen*.", footnotes: ["hebr. kabod; kann sowohl »Ehre«, »Würde«, als auch »Gewicht«, »Bürde« heißen", "℘ 1Mo 47,11.12"] },
      { number: 25, text: "An jenem Tag, spricht der HERR* der Heerscharen, wird der Pflock weichen, der an einem festen Ort eingeschlagen war, und er wird abgehauen werden und fallen, und die Last, die er trug, wird beseitigt werden*. Denn der HERR hat geredet.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 146,3.4"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Ausspruch über Tyrus. Heult, ihr Schiffe von Tarsis*! Denn es* ist verwüstet, ohne Haus. Beim Heimkommen aus dem Land Kittim* ist es ihnen kundgeworden.", heading: "Ausspruch über Tyrus", footnotes: ["℘ V. 1-14: Jer 25,22; Hes 26-28; Am 1,9.10; Sach 9,2-4", "℘ Kap. 2,16", "d. i. Tyrus", "d. i. Zypern\n℘ 1Mo 10,4; Jer 2,10"] },
      { number: 2, text: "Wehklagt*, ihr Bewohner der Küste, Kaufmann von Sidon, der über das Meer fuhr — sie haben dich angefüllt —", footnotes: ["o. Verstummt, Schweigt"] },
      { number: 3, text: "und über gewaltige Wasser*! Die Saat des Schihor*, die Ernte des Nil war ihr Ertrag; und sie war der Handelsgewinn der Nationen*.", footnotes: ["In Anlehnung an Qu. ist wohl ursprünglich zu lesen: Kaufmann von Sidon, dessen Boten dahinfahren 3 über gewaltige Wasser", "d. h. trüber Fluss; gemeint ist wie in Jer 2,18 der Nil\n℘ Jer 2,18", "d. h. der Gewinn aus dem Handel mit den Nationen"] },
      { number: 4, text: "Sei beschämt, Sidon*! Denn das Meer spricht, das Meer, deine Zuflucht: Ich habe keine Wehen gehabt und nicht geboren und keine jungen Männer großgezogen noch Jungfrauen auferzogen.", footnotes: ["℘ Hes 28,21"] },
      { number: 5, text: "Sobald die Nachricht nach Ägypten kommt, werden sie sich winden wie bei der Nachricht von Tyrus." },
      { number: 6, text: "Fahrt hinüber nach Tarsis! Heult, ihr Bewohner der Küste!" },
      { number: 7, text: "Ist das eure ausgelassene Stadt, deren Ursprung in den Tagen der Urzeit liegt, deren Füße sie hintragen, in der Ferne als Fremde zu wohnen?" },
      { number: 8, text: "Wer hat dies beschlossen über Tyrus, die Kronenspenderin*, deren Kaufleute Oberste, deren Händler* die Geehrten der Erde waren?*", footnotes: ["o. die Kronentragende", "hebr. Kanaaniter; vgl. V. 11", "℘ Sach 9,3; Offb 18,23"] },
      { number: 9, text: "Der HERR der Heerscharen hat es beschlossen, um den Hochmut aller Herrlichkeit zu entweihen, um alle Geehrten der Erde verächtlich zu machen*.", footnotes: ["℘ Kap. 2,12; Hi 12,21"] },
      { number: 10, text: "Bearbeite* dein Land, wie man es am Nil tut, Tochter Tarsis! Es gibt keine Werft* mehr.", footnotes: ["so mit Qu. und LXX; Mas. T.: Zieh durch", "Andere üs. mit Umstellung zweier Buchstaben: keinen Hafen"] },
      { number: 11, text: "Er hat seine Hand über das Meer ausgestreckt*, hat Königreiche in Beben versetzt; der HERR hat gegen Kanaan* aufgetragen, seine Festungen zu zerstören.", footnotes: ["℘ Kap. 14,26", "d. h. Händlerland und meint Phönizien\n℘ 1Mo 10,19"] },
      { number: 12, text: "Und er sprach: Du sollst nicht mehr jubeln, du geschändete Jungfrau, Tochter Sidon! Mache dich auf nach Kittim*, fahre hinüber! Auch dort wirst du keine Ruhe haben.", footnotes: ["℘ 1Mo 10,4; Jer 2,10"] },
      { number: 13, text: "Siehe, das Land der Kittäer*, dieses Volk gibt es nicht mehr! — Assur hatte es für seine Schiffe bestimmt*. — Man hat Belagerungstürme gegen es errichtet, seine Paläste bloßgelegt, es zu einem Trümmerhaufen gemacht.", footnotes: ["T.; Mas. T.: Chaldäer", "d. h. es als Flottenbasis ausgebaut"] },
      { number: 14, text: "Heult, ihr Schiffe von Tarsis! Denn eure Festung ist verwüstet*.", footnotes: ["℘ Lk 10,13.14; Offb 18,17-19"] },
      { number: 15, text: "Und es wird geschehen an jenem Tag, da wird Tyrus siebzig Jahre* vergessen sein, solange wie die Lebenstage eines Königs währen. Am Ende von siebzig Jahren aber wird es Tyrus ergehen, wie es in dem Lied von der Hure heißt:", footnotes: ["℘ Jer 25,11.12"] },
      { number: 16, text: "Nimm die Zither, geh umher in der Stadt, vergessene Hure! Spiel, so gut du kannst, sing Lied um Lied, dass man sich an dich erinnert*!", footnotes: ["℘ Nah 3,4"] },
      { number: 17, text: "Denn es wird am Ende von siebzig Jahren* geschehen, da wird der HERR Tyrus wieder heimsuchen. Und sie wird wieder zu ihrem Hurenlohn kommen und wird Hurerei treiben mit allen Königreichen der Erde, die auf der Fläche des Erdbodens sind*.", footnotes: ["℘ Jer 25,11.12", "℘ Offb 17,2"] },
      { number: 18, text: "Und ihr Handelsgewinn und ihr Hurenlohn wird dem HERRN heilig sein. Er wird nicht angehäuft und nicht aufbewahrt werden, sondern ihr Handelsgewinn wird für die sein, die vor dem HERRN wohnen, damit sie essen, bis sie satt sind, und prächtig gekleidet seien." },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Siehe, der HERR entleert die Erde und verheert sie und kehrt ihre Oberfläche um und zerstreut ihre Bewohner*.", heading: "Das kommende Weltgericht", footnotes: ["℘ Kap. 32,12-14; Hes 6,14"] },
      { number: 2, text: "Und wie dem Volk, so ergeht es dem Priester; wie dem Knecht, so seinem Herrn; wie der Magd, so ihrer Gebieterin; wie dem Käufer, so dem Verkäufer; wie dem Verleiher, so dem Borger; wie dem Schuldner, so seinem Gläubiger*.", footnotes: ["℘ Kla 4,6; Hes 7,12.13; Hos 4,9"] },
      { number: 3, text: "Völlig ausgeleert wird die Erde und geplündert*, denn der HERR hat dieses Wort geredet.", footnotes: ["℘ Kap. 42,22"] },
      { number: 4, text: "Es vertrocknet, es welkt das Land, es schmachtet, es welkt der Erdkreis, es schmachten die Hohen des Volkes im Land.*", footnotes: ["Ein hebr. Wortspiel, das etwa so nachgeahmt werden könnte: Bekümmert verkümmert die Erde; in Kummer kümmert hin das Festland. In Kummer sind die Hohen des Volkes.\n℘ Kap. 33,9; Hos 4,3"] },
      { number: 5, text: "Und die Erde ist entweiht worden unter ihren Bewohnern. Denn sie haben die Gesetze übertreten, die Ordnungen überschritten*, den ewigen Bund ungültig gemacht*!", footnotes: ["℘ 2Kö 21,12-15", "℘ Jos 23,16; Jer 11,10; Hes 16,59; Hos 6,7"] },
      { number: 6, text: "Darum hat der Fluch die Erde verzehrt, und es büßen, die auf ihr wohnen. Darum sind die Bewohner der Erde dahingeschwunden*, und wenig Menschen bleiben übrig*.", footnotes: ["o. verbrannt", "℘ Kap. 1,9; 2Kö 24,12; Jer 12,4"] },
      { number: 7, text: "Es vertrocknet der Most, es welkt der Weinstock, es seufzen alle, die frohen Herzens waren*.", footnotes: ["℘ Kap. 32,12-14; Hes 6,14"] },
      { number: 8, text: "Ins Stocken geraten ist die Freude der Tamburine, der Lärm der Ausgelassenen hat aufgehört, es stockt die Freude der Zither*.", footnotes: ["℘ Jer 7,34; Hes 26,13; Am 6,7"] },
      { number: 9, text: "Man trinkt keinen Wein mehr mit Gesang, bitter schmeckt der Rauschtrank denen, die ihn trinken." },
      { number: 10, text: "Zertrümmert ist die öde Stadt, verschlossen jedes Haus, so dass niemand hineinkommt*.", footnotes: ["℘ Kap. 25,2; 26,5; 27,10; 32,14"] },
      { number: 11, text: "Klagegeschrei um den Wein hallt auf den Straßen; untergegangen ist alle Festfreude, verschwunden die Freude der Erde*.", footnotes: ["℘ Kap. 32,10; Jer 14,2; Joe 1,12"] },
      { number: 12, text: "In der Stadt ist nur Verwüstung übrig geblieben, und das Tor wurde zu Trümmern zerschlagen*.", footnotes: ["℘ Kla 2,9"] },
      { number: 13, text: "Denn so wird es geschehen mitten auf der Erde, mitten unter den Völkern: wie beim Abschlagen der Oliven, wie bei der Nachlese, wenn die Weinernte zu Ende ist*.", footnotes: ["℘ Kap. 17,4-6"] },
      { number: 14, text: "Jene* werden ihre Stimme erheben, werden jubeln. Über die Hoheit des HERRN jauchzen sie vom Meer her*:", footnotes: ["d. h. die Entkommenen aus der Zerstreuung Israels", "℘ Jer 51,10"] },
      { number: 15, text: "Darum gebt dem HERRN Ehre im Osten*, auf den Inseln des Meeres* dem Namen des HERRN, des Gottes Israels*!", footnotes: ["w. in den Lichtgegenden", "o. an den Küsten des Meeres; d. i. im Westen", "℘ Kap. 42,10-12; Zef 2,11"] },
      { number: 16, text: "Vom Ende der Erde her hören wir Gesänge: Herrlichkeit dem Gerechten! — Da sagte ich: Ich vergehe, ich vergehe, wehe mir!* Räuber rauben, und räuberisch raubend rauben sie*.", footnotes: ["℘ Kap. 6,5", "℘ Kap. 21,2; 33,1"] },
      { number: 17, text: "Grauen und Grube und Garn über dich, Bewohner der Erde!*", footnotes: ["℘ Jer 48,43.44; Lk 21,35"] },
      { number: 18, text: "Und es geschieht, wer vor der Stimme des Grauens flieht, fällt in die Grube; und wer aus der Grube heraufsteigt, wird im Garn gefangen*. Denn die Fenster in der Höhe tun sich auf*, und es erbeben die Grundfesten der Erde*.", footnotes: ["℘ Hi 20,24; Kla 3,47; Am 5,18.19", "℘ 1Mo 7,11", "℘ Ps 18,8"] },
      { number: 19, text: "Berstend zerbirst die Erde, brechend zerbricht die Erde, wankend wankt die Erde," },
      { number: 20, text: "taumelnd taumelt die Erde wie ein Betrunkener und schwankt hin und her wie eine Nachthütte*. Und schwer lastet auf ihr ihr Treuebruch; sie fällt und steht nicht wieder auf.", footnotes: ["für den Feldhüter, z. B. im Gurkenfeld, vgl. Jes 1,8\n℘ Jer 4,24; 51,29"] },
      { number: 21, text: "Und an jenem Tag wird es geschehen, da wird der HERR das Heer der Höhe heimsuchen in der Höhe* und die Könige der Erde auf der Erde*.", footnotes: ["℘ Offb 12,7-9", "℘ Ps 76,13; Hes 39,1-5; Offb 19,19-21"] },
      { number: 22, text: "Sie werden eingesperrt, wie man Gefangene in die Grube einsperrt, ja, sie werden in den Kerker eingeschlossen und nach vielen Tagen heimgesucht* werden*.", footnotes: ["Das hebr. Wort für »heimsuchen« kann bedeuten: zur Gnade oder zum Gericht heimsuchen.", "℘ 2Petr 2,4"] },
      { number: 23, text: "Da wird der Mond schamrot werden und die Sonne sich schämen*. Denn der HERR der Heerscharen herrscht als König auf dem Berg Zion* und in Jerusalem, und vor seinen Ältesten ist Herrlichkeit.*", footnotes: ["℘ Kap. 13,10; 60,19", "℘ Kap. 33,22; 52,7; Mi 4,7; Ob 21", "℘ Offb 4,4"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "HERR, du bist mein Gott*! Ich will dich erheben, preisen will ich deinen Namen*. Denn du hast Wunder gewirkt*, Ratschlüsse von fern her, Treue und Wahrheit*.", heading: "Loblied der Geretteten nach dem Gericht", footnotes: ["℘ Ps 31,15; 118,28", "℘ 2Mo 15,2.3; Ps 7,18; 118,28", "℘ Ps 40,6; 75,2; Joe 2,26", "o. Ratschlüsse seit langem, fest und zuverlässig\n℘ Kap. 46,10.11"] },
      { number: 2, text: "Denn du hast aus einer Stadt einen Steinhaufen gemacht, die uneinnehmbare Stadt zu einem Trümmerhaufen*, den Palast der Fremden, dass sie keine Stadt mehr ist; sie wird in Ewigkeit nicht mehr aufgebaut werden*.", footnotes: ["℘ Kap. 24,10.12", "℘ Kap. 13,20"] },
      { number: 3, text: "Darum wird ein starkes Volk dich ehren, Städte gewalttätiger Nationen werden dich fürchten*.", footnotes: ["℘ Ps 66,3; Hes 38,23"] },
      { number: 4, text: "Denn du bist dem Geringen eine Festung gewesen, eine Festung dem Armen in seiner Bedrängnis*, eine Zuflucht vor dem Wolkenbruch, ein Schatten vor der Hitze*. Denn das Schnauben* der Gewalttätigen ist wie ein Unwetter im Winter*,", footnotes: ["℘ Kap. 14,32; Ps 9,10; Jer 16,19", "℘ Kap. 4,6; 32,2; Ps 91,1", "w. der Hauch o. Geist", "so wahrscheinlich der ursprüngliche Text; Mas. T.: wie ein Gewitter gegen eine Wand"] },
      { number: 5, text: "wie Hitze in einer dürren Gegend. Du demütigst das Lärmen der Fremden. Wie die Hitze durch den Schatten einer Wolke, so wird der Gesang der Gewalttätigen gedämpft*.", footnotes: ["℘ Kap. 13,11"] },
      { number: 6, text: "Und der HERR der Heerscharen wird auf diesem Berg allen Völkern ein Mahl von fetten Speisen bereiten, ein Mahl von alten Weinen*, von markigen fetten Speisen, geläuterten alten Weinen.", heading: "Das Festmahl auf dem Berg Zion", footnotes: ["o. von Bodensatz. — Aus ihm wird durch Läutern ein noch guter Wein gewonnen."] },
      { number: 7, text: "Dann wird er auf diesem Berg *die Hülle verschlingen, die das Gesicht aller Völker* verhüllt, und die Decke, die über alle Nationen gedeckt ist*.", footnotes: ["w. die Oberfläche der Hülle verschlingen, die alle Völker", "w. die Oberfläche der Hülle verschlingen, die alle Völker", "℘ 2Kor 3,14-18"] },
      { number: 8, text: "Den Tod verschlingt er auf ewig*, und der Herr, HERR, wird die Tränen abwischen von jedem Gesicht*, und die Schmach seines Volkes wird er von der ganzen Erde hinwegtun*. Denn der HERR hat geredet.", footnotes: ["2 griech. Üs. lesen: in Sieg\n℘ Hos 13,14; 1Kor 15,54", "℘ Kap. 30,19; 35,10; Ps 116,8; Offb 7,17", "℘ Kap. 60,15"] },
      { number: 9, text: "An jenem Tag wird man sagen: Siehe da, unser Gott*, auf den wir hofften, dass er uns rette!* Da ist der HERR, auf den wir hofften! Wir wollen jauchzen und uns freuen in seiner Rettung*!", footnotes: ["℘ Kap. 40,9", "℘ 1Mo 49,18; Ps 33,20", "℘ Kap. 33,22; 35,4; Ps 33,21; 40,17; Hab 3,18; Sach 10,7"] },
      { number: 10, text: "Denn die Hand des HERRN wird auf diesem Berg ruhen. Aber Moab wird unter ihm zertreten werden, wie man Stroh zertritt in einer Mistlache*.", footnotes: ["℘ Kap. 16,6.7; Zef 2,9.10"] },
      { number: 11, text: "Und breitet es seine Hände darin aus, wie der Schwimmer sie ausbreitet, um zu schwimmen, dann wird er seinen Hochmut erniedrigen trotz der geschickten Bewegungen seiner Hände*.", footnotes: ["℘ Jer 48,47"] },
      { number: 12, text: "Und deine festen, hochragenden Mauern wird er niederwerfen, niederstürzen, zu Boden stoßen bis in den Staub.*", footnotes: ["℘ Kap. 26,5; Jer 48,1; Hes 28,17"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "An jenem Tag wird dieses Lied im Land Juda gesungen werden: Wir haben eine starke Stadt. Zur Rettung setzt er Mauern und Bollwerk*.", heading: "Zwei Lieder: Lob Gottes, des Richters (1—6) und Lob Gottes, des Retters (7—21)", footnotes: ["℘ Kap. 60,18; Ps 48,4"] },
      { number: 2, text: "Macht die Tore auf, dass eine gerechte Nation, die einzieht, Treue bewahrt*!", footnotes: ["℘ Ps 118,19"] },
      { number: 3, text: "Bewährten Sinn bewahrst du in Frieden, in Frieden*, weil er auf dich vertraut*.", footnotes: ["℘ Kap. 32,17.18; Phil 4,7", "℘ Kap. 50,10; Jer 39,18"] },
      { number: 4, text: "Vertraut auf den HERRN für immer*! Denn in Jah, dem HERRN, ist ein Fels der Ewigkeiten*.", footnotes: ["℘ Ps 62,9", "℘ 5Mo 33,27; Ps 125,1"] },
      { number: 5, text: "Denn die, die in der Höhe wohnen, hat er niedergeworfen, die hochragende Stadt; er hat sie niedergestürzt, hat sie zu Boden niedergestürzt, hat sie niedergestoßen bis in den Staub*.", footnotes: ["℘ Kap. 24,10; 25,12; 32,19; Hes 28,17"] },
      { number: 6, text: "Es zertritt sie der Fuß, die Füße der Elenden, die Tritte der Geringen*. —", footnotes: ["℘ Mal 3,21"] },
      { number: 7, text: "Der Pfad für den Gerechten ist Geradheit*; gerade* ist der Weg* des Gerechten*, den du bahnst.", footnotes: ["o. eben", "o. eben", "w. die Wagenspur; o. sind die Gleise . . . die", "℘ Spr 3,6; 11,5; 21,8"] },
      { number: 8, text: "Selbst auf dem Pfad deiner Gerichte*, HERR, haben wir auf dich gewartet. Nach deinem Namen und nach deinem Lobpreis* ging das Verlangen der Seele*.", footnotes: ["℘ Kap. 30,18", "w. deiner Anrufung; vgl. 2Mo 3,15", "℘ Ps 42,2"] },
      { number: 9, text: "Mit meiner Seele verlangte ich nach dir in der Nacht*; ja, mit meinem Geist in meinem Innern suchte ich dich*. Denn wenn deine Gerichte die Erde treffen, lernen die Bewohner des Erdkreises Gerechtigkeit*.", footnotes: ["℘ Hl 3,1", "Manche nehmen an, dass die Version »in meinem Innern« durch Verschreibung zustande kam und üs.: ja, mit meinem Geist suchte ich dich noch am Morgen.", "℘ Ps 58,12"] },
      { number: 10, text: "Wird dem Gottlosen Gnade zuteil, lernt er nicht Gerechtigkeit*; im Land der Geradheit handelt er unrecht* und sieht nicht die Hoheit des HERRN*.", footnotes: ["℘ Pred 8,11", "℘ Kap. 1,21; 2Kö 13,6", "℘ Hos 11,7"] },
      { number: 11, text: "HERR, deine Hand ist hoch erhoben, sie wollen es nicht sehen*. Sehen werden sie den Eifer um das Volk und zuschanden werden*; ja, Feuer gegen deine Gegner wird sie verzehren*. —", footnotes: ["℘ Ps 28,5; Jer 5,3", "℘ Kap. 66,5; Mi 7,10", "℘ Kap. 10,16; Mal 3,19; Hebr 10,27"] },
      { number: 12, text: "HERR, du wirst uns Frieden geben*, denn du hast ja alle unsere Werke für uns vollbracht*.", footnotes: ["℘ 4Mo 6,26; Ps 29,11", "℘ Ps 57,3; 90,17; Röm 8,3.4"] },
      { number: 13, text: "HERR, unser Gott, über uns haben außer dir andere Herren geherrscht*; allein durch dich haben wir an deinen Namen gedacht.", footnotes: ["℘ 2Chr 12,8; Joh 8,33"] },
      { number: 14, text: "Tote werden nicht lebendig, Schatten* stehen nicht wieder auf*. Darum hast du sie heimgesucht und ausgerottet und hast jede Erinnerung an sie verloren gehen lassen*.", footnotes: ["o. die Totengeister", "℘ Hi 7,9", "℘ Hi 18,17; 24,20; Ps 9,6.7"] },
      { number: 15, text: "Du hast die Nation vermehrt*, HERR, du hast die Nation vermehrt, du hast dich verherrlicht*. Du hast alle Grenzen des Landes erweitert*.", footnotes: ["℘ Jer 30,19", "℘ Kap. 40,5", "w. hast weit entfernt alle Enden der Erde\n℘ Kap. 33,17; 54,2.3"] },
      { number: 16, text: "HERR, in der Not haben sie dich gesucht*. Als deine Züchtigung sie bedrängte, schrien sie*.", footnotes: ["Viele Handschr. und LXX lesen: haben wir dich gesucht\n℘ Ri 10,15; Ps 27,8; 77,3; 78,34; Jer 2,27", "o. Als deine Züchtigung uns bedrängte, schrien wir. — Die Üs. ist ein Versuch, den stark entstellten Text wiederzugeben. Mas. T.: Sie gossen Beschwörung aus — deine Züchtigung für ihn.\n℘ Jer 29,12; Hos 5,15"] },
      { number: 17, text: "Wie eine Schwangere, die, dem Gebären nahe, sich windet, um Hilfe schreit in ihren Wehen*, so sind wir, HERR, vor deinem Angesicht gewesen*.", footnotes: ["℘ Kap. 13,8; 1Mo 3,16", "℘ Jer 4,31"] },
      { number: 18, text: "Wir gingen schwanger, wir wanden uns. Doch es war, als ob wir Wind geboren hätten: Rettung verschafften wir dem Land nicht, und Bewohner der Welt wurden nicht geboren." },
      { number: 19, text: "Deine Toten werden lebendig, meine Leichen wieder auferstehen*. Wacht auf und jubelt, Bewohner des Staubes*! Denn ein Tau der Lichter ist dein Tau, und die Erde wird die Schatten* gebären.", footnotes: ["℘ Ps 88,11; Hes 37,5.6.12; Hos 6,2", "d. h. die Toten\n℘ Dan 12,2", "o. die Totengeister"] },
      { number: 20, text: "Geh hin, mein Volk, tritt ein in deine Zimmer und schließ deine Tür hinter dir zu*! Verbirg dich einen kleinen Augenblick, bis die Verwünschung vorübergeht!*", footnotes: ["℘ Mt 6,6", "℘ 2Mo 12,22.23; Ps 57,2; 94,13"] },
      { number: 21, text: "Denn siehe, der HERR zieht aus seiner Stätte aus*, um die Schuld der Erdenbewohner an ihnen heimzusuchen*. Dann wird die Erde ihr Blut enthüllen und nicht länger ihre Erschlagenen bedecken*.", footnotes: ["℘ Mi 1,3; Sach 2,17", "℘ Kap. 66,6; Jud 14.15", "℘ Hes 24,7.8"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "An jenem Tag wird der HERR mit seinem harten, großen und starken Schwert heimsuchen den Leviatan, die flüchtige Schlange, und den Leviatan, die gewundene Schlange, und wird das Ungeheuer erschlagen*, das im Meer ist*.", heading: "Drohendes Gericht über die Weltmächte — Sammlung Israels", footnotes: ["o. umbringen", "Das Ungeheuer im Meer ist ein Symbol für Ägypten.\n℘ Kap. 51,9; Hi 26,13; Hes 29,3"] },
      { number: 2, text: "An jenem Tag wird man sagen: Ein prächtiger Weinberg*! Besingt ihn!*", footnotes: ["so mit einigen Handschr., LXX, syr. und aram. Üs.; Mas. T.: ein Weinberg des Weines", "℘ Kap. 5,1; Ps 80,9"] },
      { number: 3, text: "Ich, der HERR, behüte ihn, bewässere ihn alle Augenblicke*. Damit ihm nichts zustößt*, behüte ich ihn Nacht und Tag*.", footnotes: ["℘ Kap. 44,3", "T.; Mas. T.: dass man ihn nicht heimsucht", "℘ 1Kö 8,59"] },
      { number: 4, text: "Zorn habe ich nicht*. Oh, fände ich Dornen und Disteln darin, im Kampf würde ich auf sie losgehen, sie allesamt verbrennen!*", footnotes: ["℘ Jer 29,11", "℘ 2Sam 23,7"] },
      { number: 5, text: "Oder man müsste meinen Schutz ergreifen, Frieden mit mir machen, Frieden machen mit mir." },
      { number: 6, text: "In den kommenden Tagen wird Jakob Wurzeln schlagen, Israel blühen und knospen*; und sie werden mit Früchten füllen die Fläche des Erdkreises.", footnotes: ["℘ Kap. 37,31; Hos 14,6.7"] },
      { number: 7, text: "Hat er es geschlagen, wie er die schlug, die es schlugen? Oder ist er ermordet worden, wie seine Mörder* ermordet wurden?*", footnotes: ["so mit Qu.; Mas. T.: seine Gemordeten", "℘ Jer 30,11"] },
      { number: 8, text: "Mit Maßen*, als du es verstießest, hast du mit ihm einen Rechtsstreit geführt*. Er trieb es fort* mit seinem heftigen Hauch am Tag des Ostwindes*.", footnotes: ["so mit der aram., syr. und mehreren griech. Üs.; Mas. T. vielleicht: Als du es verjagtest", "℘ Kap. 57,16; Ps 103,9; Kla 3,31.32", "w. als du sie verstießest, hast du mit ihr einen Rechtsstreit geführt, er trieb sie fort. — Das Wort »sie« bezieht sich dann auf Israel als Frau.", "℘ Kap. 64,5"] },
      { number: 9, text: "Wahrlich, dadurch wird die Schuld Jakobs gesühnt werden*. Und dies ist die ganze Frucht der Hinwegnahme seiner Sünde*: dass es alle Altarsteine zerschlagenen Kalksteinen gleichmachen wird und Bilder der Ascherim und Räucheraltäre sich nicht mehr erheben*.", footnotes: ["℘ Kap. 4,4; 40,2", "℘ Röm 11,27", "℘ Kap. 17,8; 30,22; 2Kö 23,14; Mi 5,11-13"] },
      { number: 10, text: "Denn die befestigte Stadt ist einsam*, eine preisgegebene Wohnstätte* und verlassen wie die Steppe. Dort weidet der Jungstier, und dort lagert er und frisst ihre Zweige kahl.", footnotes: ["℘ Kap. 24,10", "w. ein preisgegebener Weideplatz"] },
      { number: 11, text: "Wenn ihre Zweige dürr geworden sind, werden sie abgebrochen; Frauen kommen, zünden sie an*. Denn es ist kein verständiges Volk.* Darum erbarmt sich über sie nicht, der es gemacht hat, und der es gebildet hat, erweist ihm keine Gnade.*", footnotes: ["℘ Hes 15,6-8", "℘ Kap. 1,3; 44,18; Hos 4,14", "℘ 1Mo 6,7; Jer 13,14"] },
      { number: 12, text: "Und an jenem Tag wird es geschehen, da wird der HERR Ähren ausklopfen vom Euphratstrom an bis zum Bach Ägyptens*, und ihr werdet zusammengelesen werden, einer nach dem andern, ihr Söhne Israel*.", footnotes: ["℘ Jos 15,4; 1Kö 8,65", "℘ 5Mo 30,3.4; Jer 3,14; Am 9,9.11"] },
      { number: 13, text: "Und an jenem Tag wird es geschehen, da wird in ein großes Horn gestoßen werden*, und die Verlorenen im Land Assur und die Vertriebenen im Land Ägypten werden kommen* und den HERRN anbeten* auf dem heiligen Berg in Jerusalem.*", footnotes: ["℘ Kap. 11,16; Mt 24,31", "℘ Kap. 11,12; 43,6; Sach 10,10", "w. sich vor dem HERRN niederwerfen", "℘ Jer 31,6.12; Mi 7,14"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Wehe der stolzen Krone* der Betrunkenen Ephraims* und der welkenden Blume seiner herrlichen Pracht auf dem Haupt des fetten Tales* der vom Wein Bezwungenen*!", heading: "Gerichtsdrohung über Samaria", footnotes: ["Gemeint ist wahrscheinlich Samaria.", "℘ Kap. 7,9; 9,8; Am 4,1; 6,8", "Samaria lag auf einem Hügel.", "℘ Am 6,4-6"] },
      { number: 2, text: "Siehe, einen Starken und Mächtigen hat der Herr. Wie ein Hagelwetter, wie ein verheerender Sturmwind*, wie ein Unwetter gewaltiger, überflutender Wasser reißt er zu Boden mit Macht*.", footnotes: ["w. Sturm von Stacheln", "℘ Dan 9,26"] },
      { number: 3, text: "Mit Füßen wird zertreten die stolze Krone der Betrunkenen Ephraims." },
      { number: 4, text: "Und der welkenden Blume seiner herrlichen Pracht auf dem Haupt des fetten Tales ergeht es wie dessen* Frühfeige vor der Obsternte: Kaum ist sie in der Hand dessen, der sie erblickt, da verschlingt er sie*.", footnotes: ["d. i. des Tales", "℘ Kap. 8,4; Nah 3,12"] },
      { number: 5, text: "An jenem Tag wird der HERR der Heerscharen für den Rest seines Volkes zur herrlichen Krone und zum prächtigen Kranz" },
      { number: 6, text: "und zum Geist des Rechts* dem, der zu Gericht sitzt*, und zur Heldenkraft denen, die den Kampf zurückdrängen ans Tor*.", footnotes: ["o. des Gerichts", "℘ 1Kö 3,28", "℘ Sach 12,5"] },
      { number: 7, text: "Und auch diese wanken vom Wein und taumeln vom Rauschtrank*: Priester und Prophet wanken vom Rauschtrank, sind verwirrt vom Wein, taumeln vom Rauschtrank. Sie wanken beim Weissagen*, torkeln beim Rechtsprechen*.", heading: "Gericht über die Priester, Propheten und Spötter in Jerusalem", footnotes: ["℘ Kap. 56,12", "w. beim Gesicht", "℘ Kap. 5,11.22.23; 3Mo 10,9-11; Spr 20,1; Hos 4,11; 7,5"] },
      { number: 8, text: "Denn alle Tische sind voll Unflat und Erbrochenem, dass kein Platz mehr da ist." },
      { number: 9, text: "Wen will er Erkenntnis lehren und wem die Botschaft verständlich machen?* Kindern, die von der Milch entwöhnt, die von den Brüsten abgesetzt sind?", footnotes: ["℘ Jer 6,10"] },
      { number: 10, text: "Denn er sagt: Zaw la zaw, zaw la zaw, kaw la kaw, kaw la kaw*; hier ein wenig, da ein wenig! —", footnotes: ["Man vermutet hinter dieser lautmalenden Wendung eine spöttische Nachahmung von Jesajas prophetischer Rede. Vielleicht soll sie auch ein Nachplappern des Alphabets darstellen. Die Worte zu übersetzen fällt schwer. Möglicherweise bedeuten sie: Gebot auf Gebot, Messschnur auf Messschnur."] },
      { number: 11, text: "Ja, durch stammelnde Lippen und durch eine fremde Sprache wird er zu diesem Volk reden*,", footnotes: ["℘ Jer 5,15"] },
      { number: 12, text: "er, der zu ihnen sprach: Das ist die Ruhe! Schafft Ruhe dem Erschöpften! Und das ist die Erquickung! Aber sie wollten nicht hören*.", footnotes: ["℘ Jer 6,16; Sach 7,11; 1Kor 14,21"] },
      { number: 13, text: "Und das Wort des HERRN für sie wird sein: Zaw la zaw, zaw la zaw, kaw la kaw, kaw la kaw*; hier ein wenig, da ein wenig; damit sie hingehen und rückwärts stürzen und zerschmettert werden, sich verstricken lassen und gefangen werden*.", footnotes: ["Man vermutet hinter dieser lautmalenden Wendung eine spöttische Nachahmung von Jesajas prophetischer Rede. Vielleicht soll sie auch ein Nachplappern des Alphabets darstellen. Die Worte zu übersetzen fällt schwer. Möglicherweise bedeuten sie: Gebot auf Gebot, Messschnur auf Messschnur.", "℘ Kap. 6,9.10; 8,15"] },
      { number: 14, text: "Darum hört das Wort des HERRN, ihr Männer der Prahlerei, Beherrscher dieses Volkes, das in Jerusalem ist*!", footnotes: ["℘ Kap. 1,23; 46,12"] },
      { number: 15, text: "Denn ihr sagt: Wir haben einen Bund mit dem Tod geschlossen* und mit dem Scheol einen Vertrag gemacht. Wenn die einherflutende Geißel hindurchfährt*, wird sie uns nicht erreichen, denn wir haben Lüge zu unserer Zuflucht gemacht und in Trug uns geborgen*.", footnotes: ["℘ Dan 9,27", "℘ Kap. 8,7.8", "℘ Kap. 30,10.12; 1Mo 37,20; Jer 5,12.31; 13,25; Hes 22,28"] },
      { number: 16, text: "Darum, so spricht der Herr, HERR: Siehe, ich lege in Zion einen Grundstein, einen bewährten Stein*, einen kostbaren Eckstein, felsenfest gegründet*. Wer glaubt*, wird nicht ängstlich eilen*.", footnotes: ["w. einen Bewährungsstein, o. einen Prüfstein. — Das hebr. Wort kann auch bedeuten »Schiefergneisstein«, d. i. ein besonders harter Stein.", "w. der gegründeten Gründung\n℘ Ps 118,22; Dan 2,45; Sach 3,9; 10,4; Mt 21,42; 1Kor 3,11", "2 griech. Handschr. lesen: Wer an ihn glaubt", "o. davoneilen; o. fliehen. — LXX: wird nicht zuschanden\n℘ 2Chr 20,20; Röm 9,33; 1Petr 2,6"] },
      { number: 17, text: "Und ich werde das Recht zur Richtschnur machen und die Gerechtigkeit zur Waage. Hagel wird die Zuflucht der Lüge hinwegfegen, und das Wasser wird das Versteck wegschwemmen*.", footnotes: ["℘ Mt 7,27"] },
      { number: 18, text: "Und euer Bund mit dem Tod wird aufgehoben werden*, und euer Vertrag mit dem Scheol wird nicht bestehen bleiben. Wenn die einherflutende Geißel hindurchfährt, dann werdet ihr von ihr zertreten werden*.", footnotes: ["w. überdeckt werden. — Die aram. Üs. liest: wird vereitelt werden o. zerbrochen werden", "w. werdet ihr für sie zum zertretenen Land\n℘ Jer 2,37; Kla 4,17; Hes 13,11-14; Nah 1,8"] },
      { number: 19, text: "Sooft sie hindurchfährt, wird sie euch erfassen; denn Morgen für Morgen wird sie hindurchfahren, bei Tag und bei Nacht. Dann wird es lauter Schrecken sein, die Botschaft verständlich zu machen*.", footnotes: ["℘ Jer 4,5-13"] },
      { number: 20, text: "Denn das Bett ist zu kurz, um sich auszustrecken, und die Decke zu schmal, um sich einzuhüllen*.", footnotes: ["℘ Kap. 10,3"] },
      { number: 21, text: "Denn der HERR wird sich aufmachen wie am Berg Perazim*, wie im Tal bei Gibeon* wird er toben, um sein Werk zu tun — befremdend ist sein Werk — und um seine Arbeit zu verrichten; seltsam ist seine Arbeit*.", footnotes: ["℘ 2Sam 5,20", "℘ Jos 10,10-14; 1Chr 14,16", "℘ Kap. 29,14.23; 64,2; Hab 1,5"] },
      { number: 22, text: "Und nun, treibt nicht Spott, damit eure Fesseln nicht fester gemacht werden*! Denn ich habe von fest beschlossener Vernichtung gehört durch den Herrn*, den HERRN der Heerscharen, über die ganze Erde*.", footnotes: ["℘ 2Mo 8,25; 2Chr 36,16; Spr 19,29", "℘ Kap. 10,22.23; Lk 21,24", "℘ Spr 29,1; Hes 22,14"] },
      { number: 23, text: "Horcht auf und hört meine Stimme! Gebt acht und hört meine Rede*!", heading: "Gleichnis von der Weisheit des Bauern", footnotes: ["℘ Ps 81,9; Mt 11,15"] },
      { number: 24, text: "Pflügt denn der Pflüger den ganzen Tag, um zu säen? Bricht er nur um und eggt den ganzen Tag sein Ackerland?*", footnotes: ["℘ Pred 3,2"] },
      { number: 25, text: "Ist es nicht so: Wenn er dessen Fläche geebnet hat, streut er Dill und sät Kümmel, er wirft Weizen, Hirse und Gerste auf das abgesteckte Stück* und das Korn* an seinen Rand.", footnotes: ["»auf das abgesteckte Stück« ist ein Üs.-Versuch. Das hebr. Wort ist unbekannt.", "unbekannte Kornart; vielleicht Emmer; vgl. 2Mo 9,32"] },
      { number: 26, text: "So unterwies ihn sein Gott zum richtigen Verfahren, er belehrte ihn.*", footnotes: ["℘ Hi 32,8"] },
      { number: 27, text: "Denn Dill wird nicht mit dem Dreschschlitten ausgedroschen und das Wagenrad nicht über Kümmel gerollt, sondern Dill wird mit dem Stab ausgeschlagen und Kümmel mit dem Stock." },
      { number: 28, text: "Wird Brotkorn zermalmt? Nein, nicht unaufhörlich drischt es der Drescher*. Und wenn er das Rad seines Wagens und seine Pferde darüber treibt, zermalmt er es doch nicht*.", footnotes: ["T.; Mas. T.: drischt er es mit Dreschen", "℘ Jer 10,24"] },
      { number: 29, text: "Auch dies geht aus vom HERRN der Heerscharen*. Er führt seinen Plan wunderbar aus, seine Weisheit* lässt er groß sein*.", footnotes: ["℘ Kap. 41,20; Ps 118,23", "o. seine Rettung", "℘ Ps 92,6; Jer 32,19"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Wehe Ariël*, Ariël*, du Stadt, wo David lagerte! Fügt Jahr zu Jahr, lasst die Feste kreisen*!", heading: "Bedrohung und Rettung Jerusalems", footnotes: ["Gemeint ist Jerusalem. Das Wort bedeutet wahrscheinlich Gottesherd.", "℘ Hes 43,15.16", "℘ Kap. 1,14; 3Mo 23,4-37"] },
      { number: 2, text: "Aber ich werde Ariël* bedrängen, dass es Weh und Wehgeschrei geben wird*. Dann wird sie mir wie ein Ariël sein*.", footnotes: ["Gemeint ist Jerusalem. Das Wort bedeutet wahrscheinlich Gottesherd.", "℘ Kap. 33,7-9", "d. h. so blutig und qualmend wie ein Altar. — Andere übersetzen mit geringfügiger Veränderung: Du wirst mir ein rechter Ariël sein."] },
      { number: 3, text: "Und ich werde mein Lager ringsum gegen dich aufschlagen und dich mit einem Wall* einschließen und Belagerungswerke gegen dich errichten*.", footnotes: ["o. Wachtposten", "℘ Kap. 1,8; Lk 19,43"] },
      { number: 4, text: "Dann bist du erniedrigt und wirst aus der Erde* reden, und aus dem Staub wird deine Rede dumpf ertönen. Und deine Stimme wird sein wie die eines Totengeistes aus der Erde, und aus dem Staub wird deine Rede flüstern.", footnotes: ["o. vom Erdboden her"] },
      { number: 5, text: "Aber wie feiner Staub wird die Menge deiner Feinde* sein und wie dahinfahrende Spreu die Menge der Gewalttätigen. Und plötzlich, in einem Augenblick, wird es geschehen*:", footnotes: ["T.; Mas. T.: deiner Fremden; Qu.: deiner Frechen o. Vermessenen", "℘ Kap. 17,13; 37,36"] },
      { number: 6, text: "Vom HERRN der Heerscharen wird sie heimgesucht werden* mit Donner und Erdbeben und großem Getöse, mit Wind und Sturm und mit der Flamme eines verzehrenden Feuers*.", footnotes: ["d. h. der HERR wird sich der Stadt wieder annehmen", "℘ Kap. 30,30.31; 31,9; Hes 38,22"] },
      { number: 7, text: "Und wie ein Traum, wie eine Vision in der Nacht* wird die Menge all der Nationen sein, die Krieg führen gegen Ariël*, und alle, die gegen sie und ihre Befestigung* zu Felde ziehen und sie bedrängen*.", footnotes: ["℘ Hi 20,8", "Gemeint ist Jerusalem. Das Wort bedeutet wahrscheinlich Gottesherd.", "so mit Qu.; Mas. T.: und gegen ihr Netz", "℘ Sach 14,3"] },
      { number: 8, text: "Und es wird sein wie wenn der Hungrige träumt: siehe, er isst — dann wacht er auf, und seine Seele* ist leer; und wie wenn der Durstige träumt: siehe, er trinkt — dann wacht er auf, und siehe, er ist erschöpft, und seine Seele* ist ausgedörrt: So wird die Menge all der Nationen sein, die Krieg führen gegen den Berg Zion*.", footnotes: ["Das hebr. Wort kann auch »Kehle« bedeuten.", "Das hebr. Wort kann auch »Kehle« bedeuten.", "℘ Kap. 41,11.12; 2Chr 32,21; Ps 129,5; Nah 2,1"] },
      { number: 9, text: "Stutzt und staunt*! Seid verblendet und erblindet*! Sie sind betrunken, doch nicht vom Wein*; sie taumeln*, doch nicht vom Rauschtrank.", heading: "Verblendung und Verwandlung des Volkes durch Gott", footnotes: ["℘ Jer 2,12", "℘ 2Kor 4,4", "℘ Kap. 19,14; 51,21; Jer 13,13", "Mit LXX und entsprechend den Befehlsformen in der ersten Vershälfte üs. andere mit Änderung der Vokale: Seid betrunken . . ., taumelt"] },
      { number: 10, text: "Denn der HERR hat einen Geist tiefen Schlafs über euch ausgegossen*, ja, verschlossen hat er eure Augen; die Propheten und eure Häupter, die Seher, hat er verhüllt*.", footnotes: ["℘ Röm 11,8", "℘ Kap. 6,10; Mi 3,6"] },
      { number: 11, text: "Und jedes Gesicht* ist für euch geworden wie die Worte einer versiegelten Buchrolle, die man einem gibt, der zu lesen versteht*, indem man sagt: Lies das doch! Er aber sagt: Ich kann nicht, denn es ist versiegelt*.", footnotes: ["o. die Offenbarung von alledem", "o. zu lesen erkannt hat", "℘ Dan 12,4; Offb 5,1.5"] },
      { number: 12, text: "Und man gibt die Buchrolle einem, der nicht lesen kann, indem man sagt: Lies das doch! Er aber sagt: Ich kann nicht lesen*.", footnotes: ["℘ 2Kor 3,14"] },
      { number: 13, text: "Und der Herr hat gesprochen: Weil dieses Volk mit seinem Mund sich naht und mit seinen Lippen mich ehrt, aber sein Herz fern von mir hält* *und ihre Furcht vor mir nur angelerntes Menschengebot ist*;", footnotes: ["℘ Kap. 30,11; Jer 3,10; Hos 7,14", "LXX und die alte lat. Üs. lesen: vergeblich verehren sie mich, indem sie Gebote und Lehren von Menschen lehren", "LXX und die alte lat. Üs. lesen: vergeblich verehren sie mich, indem sie Gebote und Lehren von Menschen lehren\n℘ Jer 12,2; Mt 15,8.9; Kol 2,22"] },
      { number: 14, text: "darum, siehe, will ich weiterhin wunderbar mit diesem Volk handeln*, wunderbar und wundersam. Und die Weisheit seiner Weisen wird verloren gehen und der Verstand seiner Verständigen sich verbergen*.", footnotes: ["℘ Kap. 28,21", "℘ Kap. 19,11; 44,25; Hi 12,17; Jer 19,7; 49,7; Joh 9,30"] },
      { number: 15, text: "Wehe denen, die ihren Plan tief verbergen vor dem HERRN und deren Werke im Finstern geschehen*, und die sagen: Wer sieht uns, und wer erkennt uns*?", footnotes: ["℘ Kap. 30,1; 2Sam 11,27; 2Kö 17,9", "℘ Kap. 47,10; Hes 8,12"] },
      { number: 16, text: "Oh, eure Verkehrtheit! Soll denn der Töpfer dem Ton gleichgeachtet werden? — dass das Werk von seinem Meister sagt: Er hat mich nicht gemacht! — und ein Gebilde von* seinem Bildner sagt: Er versteht nichts*?", footnotes: ["o. zu", "℘ Kap. 45,9; Röm 9,20"] },
      { number: 17, text: "Dauert es nicht nur noch eine ganz kurze Weile, dass sich der Libanon in einen Fruchtgarten verwandelt und der Karmel* dem Wald gleichgeachtet wird*?", footnotes: ["Das hebr. Wort karmel bezeichnet ein Gebirge, bedeutet aber auch »Fruchtgarten«.", "℘ Kap. 32,15"] },
      { number: 18, text: "An jenem Tag werden die Tauben die Worte des Buches* hören, und aus Dunkel und Finsternis hervor werden die Augen der Blinden sehen*.", footnotes: ["o. die Schriftworte; das sind geschriebene Worte", "℘ Kap. 32,3; 35,5; 42,7; Lk 4,18; Apg 26,18"] },
      { number: 19, text: "Und die Demütigen* werden mehr Freude im HERRN haben, und die Armen unter den Menschen werden jubeln über den Heiligen Israels*.", footnotes: ["o. die Elenden", "℘ Kap. 41,16; Ps 22,27; Zef 3,12-15"] },
      { number: 20, text: "Denn der Gewalttätige ist nicht mehr da, und der Spötter geht zugrunde. Und ausgerottet werden alle, die auf Unheil bedacht sind*,", footnotes: ["℘ Mi 2,1-3"] },
      { number: 21, text: "die den Menschen in einer Rechtssache schuldig sprechen* und dem Schlingen legen*, der im Tor über Recht und Unrecht entscheidet, und mit nichtigen Beweisgründen den Gerechten aus seinem Recht verdrängen*.", footnotes: ["o. zur Sünde verführen", "℘ Mk 12,13", "℘ Kap. 5,20.23"] },
      { number: 22, text: "Darum, so spricht der HERR, der Abraham erlöst hat, zum Haus Jakob*: Jetzt wird Jakob nicht mehr beschämt werden, und sein Gesicht wird jetzt nicht mehr erblassen*.", footnotes: ["℘ Kap. 41,8", "℘ Kap. 45,17; 54,4"] },
      { number: 23, text: "Denn wenn er, wenn seine Kinder das Werk meiner Hände* in seiner Mitte sehen, werden sie meinen Namen heiligen; und sie werden den Heiligen Jakobs heiligen und den Gott Israels fürchten*.", footnotes: ["℘ Kap. 28,21", "℘ Kap. 8,13; Mt 6,9"] },
      { number: 24, text: "Und die mit irrendem Geist werden Einsicht kennen*, und Murrende werden Belehrung annehmen*.", footnotes: ["℘ Kap. 32,4", "℘ Jer 31,34"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Wehe den widerspenstigen Söhnen*, spricht der HERR*, die einen Plan machen*, aber nicht von mir aus*, und Bündnisse weihen*, aber nicht nach meinem Geist, um Sünde auf Sünde zu häufen*;", heading: "Warnung vor Hilferuf an Ägypten und Mahnung, dem HERRN zu vertrauen — Zukünftige Erneuerung Jerusalems", footnotes: ["℘ Kap. 1,2; Hes 2,3.4", "w. ist der Ausspruch des HERRN", "o. ausführen", "℘ Kap. 31,1", "w. um Trankopfer auszugießen; wie z. B. beim feierlichen Abschluss eines Vertrages", "℘ Kap. 1,4.5; 29,15; Hos 11,6"] },
      { number: 2, text: "die sich aufmachen, um nach Ägypten hinabzuziehen — aber meinen Mund haben sie nicht befragt* —, um unter den Schutz des Pharao zu flüchten und um Zuflucht zu suchen im Schatten Ägyptens*!", footnotes: ["℘ Jos 9,14; 1Kö 22,7", "℘ Kap. 36,6; 2Kö 18,21.24; Jer 2,18; 42,14; Hos 7,13; 8,9.10"] },
      { number: 3, text: "Doch der Schutz des Pharao wird euch zur Schande werden und die Zuflucht im Schatten Ägyptens zur Schmach*.", footnotes: ["℘ Kap. 20,5; Jer 2,36; 46,25; Hes 29,7"] },
      { number: 4, text: "Denn seine Obersten* waren zwar in Zoan*, und seine Gesandten erreichten Hanes;", footnotes: ["d. h. die Obersten von Juda", "℘ Kap. 19,11"] },
      { number: 5, text: "doch jeder wird zuschanden an einem Volk*, das ihm nichts nutzt, das nicht zur Hilfe und nicht zum Nutzen, sondern zur Schande und auch zur Schmach dient. —", footnotes: ["o. sie machen sich verhasst wegen eines Volkes"] },
      { number: 6, text: "Ausspruch über die Tiere* des Südens*: Durch ein Land der Not und der Angst, aus dem Löwin und Löwe, Giftschlange und fliegende feurige Schlangen* kommen, tragen sie auf dem Rücken von Eseln ihren Reichtum und auf den Höckern der Kamele ihre Schätze* zu einem Volk, das nichts nützt.", footnotes: ["hebr. behemot. Das Wort bedeutet auch »Nilpferd« und ist ein Sinnbild für Ägypten.", "℘ Sach 6,6", "w. und der fliegende Saraf\n℘ Kap. 14,29; 4Mo 21,6", "℘ Hos 8,9.10; 12,2"] },
      { number: 7, text: "Denn umsonst und vergebens wird Ägypten helfen*. Darum nenne ich es Rahab, die zum Schweigen Gebrachte.*", footnotes: ["℘ Kap. 31,3; Spr 25,19; Jer 37,7", "T.; Mas. T.: Rahab sind sie! Untätigkeit!"] },
      { number: 8, text: "Geh nun hin, schreib es bei ihnen auf eine Tafel* und zeichne es in ein Buch ein*, damit es für einen künftigen Tag bleibe als Zeuge* bis in Ewigkeit!", footnotes: ["℘ Kap. 8,1", "℘ Jer 36,2", "so mit der aram., syr. Üs. und der Vulg.; Mas. T.: für immer"] },
      { number: 9, text: "Denn ein widerspenstiges Volk ist es*, verlogene Söhne, Söhne, die das Gesetz* des HERRN nicht hören wollen*,", footnotes: ["℘ Kap. 48,4; 5Mo 31,27; Apg 7,51", "o. die Weisung", "℘ Kap. 1,4; 5,24; 10,5; Ps 81,12; Jer 7,28; Sach 1,4"] },
      { number: 10, text: "die zu den Sehern sagen: Seht nicht! und zu den Schauenden: Schaut uns nicht das Richtige*! Sagt uns Schmeicheleien*! Schaut uns Täuschungen*!", footnotes: ["℘ 2Chr 25,16; Jer 11,21; Am 2,12", "℘ 1Kö 22,8-13; 2Tim 4,3", "℘ Mi 2,6.11"] },
      { number: 11, text: "Weicht ab vom Weg, biegt ab vom Pfad! Lasst uns in Ruhe mit dem Heiligen Israels*!", footnotes: ["w. Macht ein Ende mit dem Heiligen Israels von unserm Gesicht weg\n℘ Kap. 29,13; Hi 21,14"] },
      { number: 12, text: "Darum, so spricht der Heilige Israels: Weil ihr dieses Wort verwerft und auf Unterdrückung und Arglist vertraut und euch darauf stützt*,", footnotes: ["℘ Kap. 28,15"] },
      { number: 13, text: "darum wird für euch diese Schuld wie ein sturzbringender Riss sein, der sich vorschiebt an einer hochragenden Mauer*, deren Zusammenbruch in einem Augenblick, plötzlich kommt*.", footnotes: ["℘ Ps 62,4", "℘ Spr 29,1; Hes 13,14"] },
      { number: 14, text: "Und er wird sie zerbrechen, wie man einen Töpferkrug zerbricht*, mitleidslos zertrümmert, und unter dessen Bruchstücken man nicht ein ganzes Tongefäß findet, um damit Feuer vom Herd zu holen oder Wasser aus einer Wassergrube* zu schöpfen.*", footnotes: ["℘ Jer 19,11", "o. aus einem Teich", "℘ Jer 48,38"] },
      { number: 15, text: "Denn so spricht der Herr, HERR, der Heilige Israels: Durch Umkehr und durch Ruhe werdet ihr gerettet. In Stillsein und in Vertrauen ist eure Stärke*. Aber ihr habt nicht gewollt*.", footnotes: ["℘ Kap. 7,4; 40,31; 2Mo 14,14", "℘ Mt 23,37"] },
      { number: 16, text: "Ihr sagtet: »Nein, sondern auf Pferden wollen wir fliegen«, darum werdet ihr fliehen; und: »Auf Rennern wollen wir reiten«, darum werden eure Verfolger hinter euch herrennen*.", footnotes: ["℘ 2Kö 25,5; Kla 4,19"] },
      { number: 17, text: "Je ein Tausend wird fliehen vor dem Drohen eines Einzigen*. Vor dem Drohen von Fünfen werdet ihr alle fliehen, bis ihr nur noch ein Rest seid wie eine Signalstange auf der Spitze des Berges und wie ein Feldzeichen auf dem Hügel*.", footnotes: ["℘ 3Mo 26,17.36; 5Mo 32,30", "℘ Kap. 1,8; 5Mo 28,25"] },
      { number: 18, text: "Und darum wird der HERR darauf warten, euch gnädig zu sein, und darum wird er sich erheben, sich über euch zu erbarmen*. Denn ein Gott des Rechts ist der HERR*. Glücklich alle, die auf ihn harren!*", footnotes: ["℘ Kap. 57,16-18; Jer 31,20", "℘ Kap. 26,7-11", "℘ Ps 2,12; Jer 17,7; Kla 3,25"] },
      { number: 19, text: "Ja, du Volk aus Zion, das in Jerusalem wohnt, du wirst nicht mehr weinen*! Er wird dir gewiss Gnade erweisen auf die Stimme deines Hilfegeschreis. Sobald er hört, wird er dir antworten*.", footnotes: ["℘ Kap. 25,8; 65,19", "℘ Kap. 58,9; 65,24; Jer 29,12"] },
      { number: 20, text: "Und hat der Herr euch auch Brot der Not und Wasser der Bedrängnis* gegeben*, so wird dein Lehrer sich nicht mehr verbergen, sondern deine Augen werden deinen Lehrer sehen.", footnotes: ["Das ist die Not und Bedrängnis durch Belagerung; gemeint ist: Hat der Herr euch auch verkürzte Ration gegeben", "℘ Kap. 33,16; 51,14"] },
      { number: 21, text: "Und wenn ihr zur Rechten oder wenn ihr zur Linken abbiegt, werden deine Ohren ein Wort hinter dir her hören: Dies ist der Weg*, den geht*!", footnotes: ["℘ 1Sam 12,23", "℘ Kap. 48,17; 5Mo 5,32; Jer 6,16"] },
      { number: 22, text: "Dann wirst du* den Überzug deiner silbernen Schnitzbilder und die Bekleidung deiner goldenen Gussbilder unrein machen*. Du wirst sie wegwerfen wie etwas Unreines: Dreck!, wirst du dazu sagen*. —", footnotes: ["so mit einer griech., der alten lat. Üs. und der Vulg.; Mas. T.: werdet ihr", "o. entweihen; d. h. für den Gottesdienst unbrauchbar machen", "℘ Kap. 2,20; 27,9; 5Mo 7,25; Hes 7,20"] },
      { number: 23, text: "Und er wird Regen geben deiner Saat, mit der du den Erdboden besäst*, und Brot als Ertrag des Erdbodens, und alles wird saftig und fett sein*. Deine Herden werden an jenem Tag weiden auf weitem Weidegrund*.", footnotes: ["℘ Joe 2,23", "℘ 3Mo 26,3-5; Ps 67,7", "℘ Kap. 32,20"] },
      { number: 24, text: "Und die Rinder und Esel, die den Erdboden bearbeiten, werden gemischtes Sauerfutter fressen, das man mit Schaufel und mit der Gabel geworfelt hat." },
      { number: 25, text: "Und auf jedem hohen Berg und auf jedem hochragenden Hügel werden Bäche, Wasserläufe sein* am Tag des großen Mordens*, wenn Türme fallen*.", footnotes: ["℘ Joe 4,18", "℘ Joe 4,13", "℘ Kap. 2,15"] },
      { number: 26, text: "Dann wird das Licht des Mondes sein wie das Licht der Sonne, und das Licht der Sonne wird siebenfach sein wie das Licht von sieben Tagen, an dem Tag, da der HERR den Bruch seines Volkes verbinden und die Wunde seines Schlages heilen wird*.", footnotes: ["℘ Jer 30,17; Mal 3,20"] },
      { number: 27, text: "Siehe, der Name des HERRN kommt von weit her* mit seinem brennenden Zorn und wuchtigem Auffahren. Seine Lippen sind voller Grimm, und seine Zunge ist wie ein verzehrendes Feuer", heading: "Drohendes Gericht über die Feinde, besonders über Assur", footnotes: ["℘ Mal 1,11"] },
      { number: 28, text: "und sein Atem wie ein überflutender Bach, der bis an den Hals reicht: um die Nationen zu schwingen mit dem Schwingsieb des Nichts und einen irreführenden Zaum an die Kinnbacken der Völker zu legen*.", footnotes: ["℘ Kap. 17,13.14"] },
      { number: 29, text: "Das Lied werdet ihr auf den Lippen haben wie in der Nacht, in der das Fest gefeiert* wird, und Freude im Herzen wie der, der unter Flötenspiel hinaufzieht, um auf den Berg des HERRN zu kommen*, zum Felsen Israels*.", footnotes: ["w. der Reigentanz geheiligt", "℘ Ps 42,5", "℘ Kap. 44,8"] },
      { number: 30, text: "Dann wird der HERR hören lassen die Hoheit seiner Stimme* und sehen lassen das Niederfahren seines Armes* mit wütendem Zorn und einer Flamme verzehrenden Feuers*, unter Platzregen und Wolkenbruch und Hagelsteinen*.", footnotes: ["℘ Ps 29,4; Joe 4,16", "℘ Kap. 52,10", "℘ Kap. 10,16; 29,6; 66,15; Hebr 12,29; Kap. 4,6", "℘ 2Mo 9,24; Jos 10,10.11"] },
      { number: 31, text: "Ja, von der Stimme des HERRN wird Assur zerschlagen*, wenn er mit dem Stock dreinschlägt.", footnotes: ["o. niedergeschlagen; o. erschrocken sein\n℘ Kap. 37,36"] },
      { number: 32, text: "Und es wird geschehen, jeder Hieb der Zuchtrute*, die der HERR auf es niedersausen lässt*, erfolgt unter Tamburin- und Zitherspiel. Und mit geschwungenem Arm* wird er gegen es kämpfen*.", footnotes: ["so mit einigen hebr. Handschr.; Mas. T.: Rute der Anordnung", "℘ Kap. 10,26", "w. Und mit Kämpfen, in denen er es als Schwingopfer schwingt", "℘ Kap. 31,4; 2Chr 32,8"] },
      { number: 33, text: "Denn längst ist eine Feuerstätte* hergerichtet. Auch für den König* ist sie bereitet, tief und weit hat er sie gemacht. Ihr Scheiterhaufen ist für das Feuer und hat Holz in Menge. Wie ein Schwefelstrom setzt der Atem des HERRN ihn in Brand*.", footnotes: ["hebr. tafte; ein von dem Ort Tofet abgeleitetes Wort, das den Sitz des Molochkultes bezeichnet\n℘ 2Kö 23,10", "hebr. melech; klingt an »Moloch« an\n℘ Dan 11,36", "℘ Kap. 33,14; 5Mo 4,24; Offb 19,20"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Wehe denen, die nach Ägypten hinabziehen um Hilfe, sich auf Pferde stützen und die ihr Vertrauen auf Wagen setzen, weil es viele sind, und auf Reiter, weil sie zahlreich sind*; die aber auf den Heiligen Israels nicht schauen und nach dem HERRN nicht fragen*!", heading: "Warnung vor Hilferuf an Ägypten — Ansage der Hilfe des HERRN gegen Assur", footnotes: ["℘ Kap. 30,1.2.16; 5Mo 17,16", "℘ Kap. 9,12; 2Chr 16,7-9; Sach 10,5"] },
      { number: 2, text: "Doch auch er ist weise* und bringt Unglück herbei und nimmt seine Worte nicht zurück*. Sondern er steht auf gegen das Haus der Übeltäter und gegen die Hilfe derer, die Unrecht tun*.", footnotes: ["℘ Hi 12,13", "℘ Kap. 21,17", "℘ Kap. 20,4-6; 30,7"] },
      { number: 3, text: "Auch die Ägypter sind Menschen und nicht Gott*, und ihre Pferde sind Fleisch und nicht Geist*. Und der HERR streckt seine Hand aus, da stürzt der Helfer, und der, dem geholfen wird, fällt. Und alle miteinander gehen sie zugrunde*.", footnotes: ["℘ Ps 146,3-5; Hes 28,2", "℘ 2Chr 32,8", "℘ Kap. 20,4-6; 30,7"] },
      { number: 4, text: "Denn so hat der HERR zu mir gesprochen: Wie der Löwe und der Junglöwe, gegen den die Menge der Hirten zusammengerufen wird, über seinem Raub knurrt, vor ihrer Stimme nicht erschrickt und vor ihrem Lärmen sich nicht duckt, so wird der HERR der Heerscharen herabsteigen, um auf dem Berg Zion und auf seinem Hügel zu kämpfen*.", footnotes: ["d. h. um Jerusalem gegen Assur zu schützen, wie der Löwe seine Beute schützt\n℘ Kap. 30,30-32; 42,13; 2Mo 14,14.25"] },
      { number: 5, text: "Wie schwebende Vögel, so wird der HERR der Heerscharen Jerusalem beschirmen: beschirmen und retten, schonen und befreien*. —", footnotes: ["℘ Kap. 35,4; 37,35; 2Kö 19,34; Ps 46,6"] },
      { number: 6, text: "Kehrt um, Söhne Israel, zu dem, von dem ihr so tief abgefallen seid*!", footnotes: ["w. von dem gilt: ihr habt den Abfall tief gemacht\n℘ Jer 3,12.22; Sach 1,3"] },
      { number: 7, text: "Denn an jenem Tag wird jeder von ihnen seine Götzen aus Silber und seine Götzen aus Gold verwerfen, die eure Hände euch zur Sünde gemacht haben*.", footnotes: ["℘ Kap. 2,20"] },
      { number: 8, text: "Und Assur wird fallen durch das Schwert, aber nicht durch das eines Mannes; und das Schwert, aber nicht das eines Menschen, wird es fressen*. Und es wird vor dem Schwert fliehen*, und seine jungen Krieger werden zur Zwangsarbeit gezwungen werden.", footnotes: ["w. Und fallen wird Assur durch das Schwert eines Nicht-Mannes, und das Schwert eines Nicht-Menschen wird es fressen\n℘ Kap. 10,25; 37,36", "℘ Kap. 17,13; 37,37"] },
      { number: 9, text: "Und sein Fels* wird vor Schrecken vergehen*, und seine Obersten werden fahnenflüchtig*, spricht der HERR*, der sein Feuer in Zion und seinen Ofen in Jerusalem hat*.", footnotes: ["d. h. wahrscheinlich der König von Assur", "℘ Kap. 17,13; 37,37", "w. werden schreckerfüllt vom Feldzeichen weglaufen", "w. ist der Ausspruch des HERRN", "℘ Kap. 10,16.17; 29,6"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Siehe, ein König wird in Gerechtigkeit regieren*; und die Obersten, sie werden nach Recht herrschen*.", heading: "Das zukünftige Reich der Gerechtigkeit", footnotes: ["℘ Kap. 9,6; 11,4.5; 33,5; Ps 72,2; Jer 23,5.6; Mal 3,20", "T.; Mas. T.: für Oberste werden sie . . . herrschen"] },
      { number: 2, text: "Und jeder wird sein wie ein Bergungsort vor dem Wind und ein Schutz vor dem Wolkenbruch, wie Wasserbäche in dürrer Gegend, wie der Schatten eines gewaltigen Felsens im lechzenden Land*.", footnotes: ["℘ Kap. 4,6; Kla 4,20"] },
      { number: 3, text: "Da werden die Augen der Sehenden nicht mehr verklebt sein*, und die Ohren der Hörenden werden aufmerksam sein*.", footnotes: ["T.; Mas. T.: nicht mehr sehen", "℘ Kap. 29,18; Mt 13,16"] },
      { number: 4, text: "Und das Herz der Unbesonnenen wird auf Erkenntnis achtgeben*, und die Zunge der Stammelnden wird fließend Deutliches reden.", footnotes: ["℘ Kap. 29,24"] },
      { number: 5, text: "Der Törichte wird nicht mehr edel genannt und der Schurke nicht mehr vornehm geheißen werden*.", footnotes: ["℘ Kap. 5,20"] },
      { number: 6, text: "Denn ein törichter Mensch redet Törichtes*. Und sein Herz bereitet Unheil, Ruchloses zu tun und Irreführendes gegen den HERRN zu reden*, um die Seele des Hungrigen leer zu lassen und dem Durstigen den Trank zu verweigern*.", footnotes: ["o. der Gottlose redet Gottloses\n℘ Mt 12,34", "℘ Kap. 59,13", "℘ Hes 34,18; Mt 25,42"] },
      { number: 7, text: "Und die Werkzeuge des Schurken sind böse: er beschließt böse Anschläge*, um die Elenden* durch Lügenreden zugrunde zu richten, selbst wenn der Arme redet, was Recht ist*.", footnotes: ["℘ Mi 2,1", "o. Demütigen", "℘ Kap. 5,23"] },
      { number: 8, text: "Aber der Edle beschließt Edles, und auf Edlem besteht er*.", footnotes: ["℘ Mt 12,35"] },
      { number: 9, text: "Steht auf, ihr sorglosen Frauen*, hört meine Stimme, ihr Töchter, die ihr so sicher seid, nehmt zu Ohren meine Rede*!", heading: "Die Ausgießung des Geistes nach der Demütigung Jerusalems", footnotes: ["℘ Am 6,1", "℘ Jer 9,19"] },
      { number: 10, text: "Über Jahr und Tag, da werdet ihr zittern, ihr Sicheren. Denn die Weinlese ist dahin, die Obsternte kommt nicht*.", footnotes: ["℘ Kap. 24,7.11"] },
      { number: 11, text: "Bebt, ihr Sorglosen; zittert, ihr Sicheren! Zieht euch aus und entblößt euch und umgürtet die Lenden mit Sacktuch*!", footnotes: ["℘ 2Mo 33,4; Jer 4,8; Jak 5,1"] },
      { number: 12, text: "An die Brust schlägt man sich* wegen der prächtigen Fluren, wegen des fruchtbaren Weinstocks*,", footnotes: ["Andere üs. mit leichter Veränderung: Schlagt euch an die Brust!; vgl. die Befehlsformen in V. 11", "℘ Joe 1,7.8"] },
      { number: 13, text: "wegen des Ackerlandes meines Volkes, das in Gestrüpp und Dornen aufgeht*, ja, wegen aller Häuser voller Freude in der ausgelassenen Stadt*.", footnotes: ["℘ Kap. 5,6; 7,23; Hos 9,6", "℘ Kap. 22,2"] },
      { number: 14, text: "Denn der Palast ist aufgegeben, verödet das Getümmel der Stadt*. Ofel* und Wachtturm* dienen als Höhlen für ewig, zur Freude der Wildesel, zur Weidefläche der Herden*,", footnotes: ["℘ Kap. 24,10.12", "w. Buckel. — Damit ist öfter der von Jotam befestigte Südabhang des Tempelberges gemeint.", "℘ 2Chr 33,14; Neh 3,26.27", "℘ Kap. 3,26; 24,1; 34,13; Mi 3,12"] },
      { number: 15, text: "bis der Geist aus der Höhe über uns ausgegossen wird* und die Wüste zum Fruchtgarten wird und der Fruchtgarten dem Wald gleichgeachtet wird*.", footnotes: ["℘ Kap. 44,3; Hes 37,14", "℘ Kap. 29,17; 35,1.2"] },
      { number: 16, text: "In der Wüste wird das Recht sich niederlassen und die Gerechtigkeit im Fruchtgarten wohnen*.", footnotes: ["℘ Kap. 11,9; Jer 31,23; Sach 8,3"] },
      { number: 17, text: "Und das Werk der Gerechtigkeit wird Friede sein* und der Ertrag der Gerechtigkeit Ruhe und Sicherheit für ewig*.", footnotes: ["℘ Est 9,30", "℘ Kap. 54,14; Spr 1,33; Mi 4,4"] },
      { number: 18, text: "Dann wird mein Volk wohnen an einer Wohnstätte des Friedens* und in sicheren Wohnungen und an sorgenfreien Ruheplätzen*. —", footnotes: ["w. an einem Weideplatz des Friedens", "w. sorglosen Rastplätzen\n℘ Kap. 26,3; 33,6.20; 2Mo 9,26; Hes 34,28"] },
      { number: 19, text: "Und stürzen wird mit mächtigem Sturz der Wald* und die Stadt in Niedrigkeit versinken*. —", footnotes: ["so mit einer hebr. Handschr. und der aram. Üs.; ähnlich die syr. Üs.; Mas. T.: Es wird hageln beim Sturz des Waldes", "℘ Kap. 10,33.34; 26,5"] },
      { number: 20, text: "Glücklich ihr, die ihr an allen Wassern sät* und Rind und Esel freien Lauf lasst*!*", footnotes: ["℘ Pred 11,1", "w. den Fuß von Rind und Esel frei umherstreifen lasst", "℘ Kap. 30,23.24"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Wehe dir, Verwüster, der du selbst nicht verwüstet wurdest, und dir, Treuloser, an dem man nicht treulos gehandelt hat! Sobald du das Verwüsten beendet hast, wirst du verwüstet werden. Sobald du mit der Treulosigkeit fertig bist*, wirst du treulos behandelt werden*. —", heading: "Jerusalems Not, Rettung und zukünftiges Glück", footnotes: ["so mit Qu.; Mas. T.: Sobald du es völlig erreicht hast, treulos zu handeln", "℘ Kap. 17,14; 24,16; Ri 1,7; Spr 22,23"] },
      { number: 2, text: "HERR, sei uns gnädig! Auf dich hoffen wir*. Sei unser* Arm jeden Morgen, ja, unsere Rettung zur Zeit der Not*! —", footnotes: ["℘ Kap. 8,17; Ps 33,22", "so mit einigen hebr. Handschr., der aram., syr. Üs. und der Vulg.; Mas. T.: Sei ihr", "℘ Jer 14,8"] },
      { number: 3, text: "Vor dem gewaltigen Tosen fliehen die Völker, vor deinem Aufstehen zerstreuen sich die Nationen*.", footnotes: ["℘ Kap. 17,13; Ps 68,2.3"] },
      { number: 4, text: "Und weggerafft wird eure Beute, wie die Heuschreckenlarve alles wegrafft. Wie Heuschreckenschwärme herabstürzen, stürzt man sich darauf*. —", footnotes: ["℘ Joe 2,3"] },
      { number: 5, text: "Hoch erhaben ist der HERR. Denn in der Höhe wohnt er*. Er füllt Zion mit Recht und Gerechtigkeit*.", footnotes: ["℘ Ps 97,9", "℘ Kap. 1,26; 32,1; Jer 23,5.6; 31,23"] },
      { number: 6, text: "Und sichere Zeiten wirst du haben*: Fülle von Heil, von Weisheit und Erkenntnis*. Die Furcht des HERRN, sie wird sein Schatz sein*.", footnotes: ["w. Es wird Festigkeit deiner Zeiten geben\n℘ Kap. 32,17.18", "℘ Kap. 11,9; Jer 31,34; Hab 2,14", "℘ Hi 4,6; Spr 2,5; 14,26"] },
      { number: 7, text: "Siehe, ihre Helden schreien* draußen, die Friedensboten weinen bitterlich*.", footnotes: ["so mit einigen hebr. Handschr.; andere lesen: Ariël schreit. Die Bedeutung des im Mas. T. stehenden Wortes ist nicht zu bestimmen. Mit Ariël ist Jerusalem gemeint. Das Wort bedeutet wahrscheinlich Gottesherd.", "℘ Kap. 29,2"] },
      { number: 8, text: "Verödet sind die Straßen, der Wanderer zieht nicht mehr hindurch*. Man hat den Bund ungültig gemacht, die Städte* verworfen*, keinen Menschen geachtet.", footnotes: ["w. der wandernd Hindurchziehende ruht\n℘ Ri 5,6.7", "Qu.: die Zeugen", "℘ Kap. 10,9; 36,1"] },
      { number: 9, text: "Es vertrocknet, es welkt das Land*. Beschämt steht der Libanon da, er ist schwarz geworden. Scharon ist einer Steppe gleich geworden, Baschan und Karmel schütteln ihr Laub ab*.", footnotes: ["℘ Kap. 24,4", "℘ Am 1,2; Nah 1,4"] },
      { number: 10, text: "Jetzt will ich aufstehen, spricht der HERR. Jetzt will ich mich aufrichten, jetzt mich erheben*.", footnotes: ["℘ Ps 12,6"] },
      { number: 11, text: "Ihr geht schwanger mit Heu, Strohstoppeln werdet ihr gebären*. Euer Schnauben ist ein Feuer, das euch verzehren wird.", footnotes: ["℘ Kap. 59,4; Ps 7,15"] },
      { number: 12, text: "Und die Völker werden zu Kalk verbrannt, wie abgehauene Dornen, die im Feuer verbrennen*.", footnotes: ["℘ Kap. 9,17; Ps 118,12"] },
      { number: 13, text: "Hört, ihr Fernen, was ich getan habe, und ihr Nahen, erkennt meine Macht*!", footnotes: ["℘ Kap. 52,10"] },
      { number: 14, text: "Die Sünder in Zion sind erschrocken, Zittern hat die Gottlosen gepackt. »Wer von uns kann sich bei verzehrendem Feuer aufhalten? Wer von uns kann sich bei ewigen Gluten aufhalten*?« —", footnotes: ["℘ Kap. 30,33; Nah 1,6; Hebr 12,29"] },
      { number: 15, text: "Wer in Gerechtigkeit lebt* und Wahrheit* redet*, wer den Gewinn der Erpressungen verwirft, wer seine Hände schüttelt, um keine Bestechung anzunehmen*, wer sein Ohr verstopft, um nicht von Bluttaten zu hören, und seine Augen verschließt, um Böses nicht zu sehen*:", footnotes: ["w. in Gerechtigkeit geht", "w. Aufrichtigkeit, o. Geradheit", "℘ Ps 15,2", "℘ 2Mo 23,8; Ps 15,5", "℘ Hi 31,7; Spr 1,10-16"] },
      { number: 16, text: "Der wird auf Höhen wohnen, Felsenfesten sind seine Burg*. Sein Brot wird ihm gegeben, sein Wasser versiegt nie*. —", footnotes: ["℘ 5Mo 33,29; Ps 62,7.8", "℘ Kap. 30,20; Joh 6,48; 7,37"] },
      { number: 17, text: "Deine Augen werden den König schauen in seiner Schönheit*, sehen werden sie ein weithin offenes Land*.", footnotes: ["℘ Hi 19,27; Ps 45,2.3; Offb 22,3", "℘ Kap. 26,15"] },
      { number: 18, text: "Dein Herz wird an den Schrecken denken: Wo ist der, der zählte? Wo der, der abwog*? Wo ist der, der die Türme zählte?", footnotes: ["d. h. der das Geld des eingetriebenen Tributs zählte und dessen Silber abwog"] },
      { number: 19, text: "Du wirst das freche Volk nicht mehr sehen, das Volk mit dunkler Sprache*, die man nicht versteht, mit stammelnder Zunge ohne Sinn*.", footnotes: ["w. Lippe", "℘ Kap. 37,34.37; Jer 5,15; Hes 3,5.6"] },
      { number: 20, text: "Schau Zion an*, die Stadt unserer Festversammlungen*! Deine Augen werden Jerusalem sehen, eine sorgenfreie Wohnstätte*, ein Zelt, das nicht wandern wird*, dessen Pflöcke man ewig nicht herauszieht und von dessen Stricken keiner je zerreißen wird.", footnotes: ["℘ Ps 48,13.14; 128,5", "℘ 5Mo 16,16", "w. ein sorgloser Weideplatz; vgl. Kap 32,18", "o. das man nicht zusammenpacken muss\n℘ Kap. 4,5.6; 32,18; Ps 46,6"] },
      { number: 21, text: "Sondern — dort ist ein Mächtiger* bei uns, der HERR* — es ist ein Ort mit Flüssen, mit breiten Strömen*; keine Ruderflotte fährt darauf, und kein mächtiges Schiff zieht darüber hin.", footnotes: ["o. ein Herrlicher", "℘ Kap. 12,6; 5Mo 23,15; Sach 2,9.14", "w. mit nach beiden Seiten ausgedehnten Strömen"] },
      { number: 22, text: "Denn der HERR ist unser Richter*, der HERR unser Anführer, der HERR unser König*. Er wird uns retten*. —", footnotes: ["℘ Kap. 11,4; Ps 50,6", "℘ Kap. 24,23; 41,21; 1Sam 12,12; Ps 44,5", "℘ Kap. 12,2; 25,9; 44,6"] },
      { number: 23, text: "Schlaff hängen deine Taue. Sie halten das Gestell ihres Mastes nicht fest, halten das Segel nicht ausgebreitet*. — Dann wird die Ausbeute des Plündergutes ausgeteilt in Menge*, selbst Lahme plündern die Beute.", footnotes: ["o. die Flagge hissen sie nicht", "℘ Ps 68,13"] },
      { number: 24, text: "Und kein Einwohner wird sagen: Ich bin schwach*. Dem Volk, das darin wohnt, wird die Schuld vergeben sein*.", footnotes: ["o. krank\n℘ Joe 4,10; Sach 12,8", "℘ Kap. 44,22"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "*Tretet heran, ihr Nationen, um zu hören! Und ihr Völkerschaften, hört aufmerksam zu! Es höre die Erde und was sie erfüllt, der Erdkreis und alles, was ihm entsprosst!*", heading: "Zukünftiges Gericht über die Feinde Israels, besonders über Edom", footnotes: ["℘ V. 1-8: Kap. 63,1-6; V. 1-17: Jer 49,7-22", "℘ Ps 49,2.3"] },
      { number: 2, text: "Denn der HERR hat einen Zorn auf alle Nationen, und sein Grimm richtet sich auf ihr ganzes Heer*. Er hat an ihnen den Bann vollstreckt, sie zur Schlachtung dahingegeben*.", footnotes: ["℘ Jer 25,15; Hes 36,5; Zef 3,8", "℘ Kap. 66,16; Jos 11,20; Jer 25,31.33"] },
      { number: 3, text: "Und ihre Erschlagenen werden hingeworfen, und der Gestank ihrer Leichen steigt auf, und die Berge zerfließen von ihrem Blut*.", footnotes: ["℘ Hes 32,4-6; Nah 3,3"] },
      { number: 4, text: "Und alles Heer des Himmels zergeht*. Und der Himmel wird zusammengerollt wie eine Buchrolle*. Und sein gesamtes Heer verwelkt, wie das Laub am Weinstock verwelkt und wie Welkes am Feigenbaum*.", footnotes: ["w. verfault. — Andere lesen mit geringfügiger Veränderung: alle Hügel vergehen", "℘ Offb 6,14", "℘ Kap. 14,12; Mt 24,29"] },
      { number: 5, text: "*Denn trunken ist im Himmel mein Schwert*. Siehe, auf Edom fährt es herab und auf das Volk meines Bannes* zum Gericht*.", footnotes: ["℘ (Kap. 21,11.12); Hes 25,12-14; 35; Am 1,11.12; Ob", "℘ Jer 46,10; Zef 1,7", "d. h. das Volk, an dem ich den Bann vollstreckt habe; vgl. V. 2", "℘ Hes 36,5; Mal 1,4"] },
      { number: 6, text: "Ein Schwert hat der HERR, voll von Blut, es trieft von Fett, vom Blut der Lämmer und Böcke, vom Nierenfett der Widder. Denn ein Schlachtopfer* hält der HERR in Bozra und ein großes Schlachten im Land Edom.", footnotes: ["℘ Jer 46,10; Zef 1,7"] },
      { number: 7, text: "Da stürzen Büffel mit ihnen hin und Stiere samt den starken Stieren*. Und ihr Land wird trunken von Blut, und ihr Boden trieft von Fett*.", footnotes: ["℘ Jer 50,27", "℘ Hes 39,18"] },
      { number: 8, text: "Denn einen Tag der Rache hat der HERR, ein Jahr der Vergeltungen für die Rechtssache Zions*.", footnotes: ["℘ Kap. 13,6.9; 35,4; Joe 4,2"] },
      { number: 9, text: "Und Edoms Bäche* verwandeln sich in Pech und sein Boden in Schwefel; und sein Land wird zu brennendem Pech.", footnotes: ["w. seine Bäche"] },
      { number: 10, text: "Tag und Nacht erlischt es nicht, ewig steigt sein Rauch empor*. Von Generation zu Generation liegt es in Trümmern, für immer und ewig zieht niemand hindurch*.", footnotes: ["℘ Offb 14,11", "℘ Jer 49,18"] },
      { number: 11, text: "Wüstenkauz und Igel nehmen es in Besitz, Eule und Rabe wohnen darin*. Und er spannt darüber die Messschnur der Öde und das Senkblei der Leere*.", footnotes: ["℘ Kap. 14,23; Zef 2,14", "℘ 2Kö 21,13"] },
      { number: 12, text: "*Seine Edlen* — keine sind da, die das Königtum ausrufen; und alle seine Obersten nehmen ein Ende.", footnotes: ["LXX: Und Bocksdämonen wohnen darin, und es gibt keine Edlen", "LXX: Und Bocksdämonen wohnen darin, und es gibt keine Edlen"] },
      { number: 13, text: "Und in seinen Palästen gehen Dornen auf, Nesseln und Disteln in seinen befestigten Städten*. Und es wird zur Wohnstätte der Schakale, zur Siedlung* für Strauße.*", footnotes: ["℘ Kap. 32,13.14", "so mit Qu., der griech. und aram. Üs.; Mas. T.: zum Grasplatz", "℘ Kap. 13,21; Jer 49,33; 51,37; Mal 1,3"] },
      { number: 14, text: "Da treffen Wüstentiere mit wilden Hunden zusammen, und Bocksdämonen* begegnen einander. Ja, dort rastet die Lilit* und findet einen Ruheplatz für sich*.", footnotes: ["w. Haarige", "d. i. ein Nachtdämon", "℘ Kap. 13,21; Jer 49,33; 51,37; Mal 1,3"] },
      { number: 15, text: "Dort nistet die Pfeilschlange und legt ihre Eier* und brütet und spaltet sie*. Ja, dort versammeln sich die Geier, einer zum andern. —", footnotes: ["T.; Mas. T.: und legt in ihrem Schatten Eier", "d. h. sie brütet die Eier, bis sie sich spalten"] },
      { number: 16, text: "Forscht im Buch des HERRN nach und lest! Es fehlt nicht eins von diesen, keins vermisst das andere. Denn der Mund des HERRN*, er hat es befohlen*; und sein Geist, er hat sie zusammengebracht.*", footnotes: ["so mit 5 Handschr.; Qu.: sein Mund; Mas. T.: mein Mund", "℘ Kap. 21,17; 40,5", "℘ Sach 4,6"] },
      { number: 17, text: "Und er selbst hat ihnen das Los geworfen, und seine Hand hat es* ihnen mit der Messschnur zugeteilt*. Ewig werden sie es besitzen, von Generation zu Generation darin wohnen*.", footnotes: ["d. i. das Land Edom", "℘ 5Mo 32,9", "℘ Joe 4,20"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "Freuen werden sich die Wüste und das dürre Land, jauchzen wird die Steppe und aufblühen wie eine Narzisse*.", heading: "Die Heimkehr Israels", footnotes: ["℘ Kap. 51,3"] },
      { number: 2, text: "Sie wird in voller Blüte stehen und jauchzen, ja, jauchzend und jubelnd*. Die Herrlichkeit des Libanon ist ihr gegeben, die Pracht von Karmel* und Scharon*: Sehen werden sie die Herrlichkeit des HERRN, die Pracht unseres Gottes*.", footnotes: ["℘ Kap. 55,12; Ps 65,14; 96,12", "℘ Jos 19,26", "℘ Kap. 32,15; 60,13; 1Chr 27,29; Hos 14,6-8", "℘ Kap. 40,5"] },
      { number: 3, text: "Stärkt die schlaffen Hände* und festigt die wankenden* Knie!*", footnotes: ["℘ Sach 8,9.13", "w. stürzenden", "℘ Hebr 12,12"] },
      { number: 4, text: "Sagt zu denen, die ein ängstliches Herz haben: Seid stark*, fürchtet euch nicht*! Siehe, da ist euer Gott*, Rache kommt, die Vergeltung Gottes*! Er selbst kommt und wird euch retten*.", footnotes: ["℘ Dan 10,19", "℘ Kap. 41,10.13; 1Sam 23,17; Zef 3,16; 1Thes 5,14", "℘ Kap. 40,9; Ps 50,3", "℘ Kap. 34,8; 47,3; 61,2; Lk 1,71", "℘ Kap. 25,9; 31,5"] },
      { number: 5, text: "Dann werden die Augen der Blinden aufgetan und die Ohren der Tauben geöffnet*.", footnotes: ["℘ Kap. 29,18"] },
      { number: 6, text: "Dann wird der Lahme springen wie ein Hirsch, und jauchzen wird die Zunge des Stummen*. Denn in der Wüste bricht Wasser hervor und Bäche in der Steppe*.", footnotes: ["℘ Mt 9,8; 11,3-5", "℘ Kap. 41,18; 44,3; Ps 107,35"] },
      { number: 7, text: "Und die Wüstenglut* wird zum Teich und das dürre Land zu Wasserquellen. An der Stelle, wo die Schakale lagerten, wird Gras sowie Rohr und Schilf sein*.", footnotes: ["w. die Sonnenhitze; nach anderen: die Fata Morgana", "so mit versuchter Verbesserung; Mas. T.: An der Stelle für Schakale, ihrem (der Schakalin) Lagerplatz, ist Gras für Rohr und Schilf\n℘ Kap. 41,18; 44,3; Ps 107,35"] },
      { number: 8, text: "Und dort wird eine Straße sein und ein Weg, und er wird der heilige Weg genannt werden. Kein Unreiner wird darüber hinziehen*, sondern er wird für sie sein*. Wer auf dem Weg geht — selbst* Einfältige werden nicht irregehen*.", footnotes: ["℘ Kap. 52,1; Joe 4,17", "℘ Kap. 43,19; 62,10.12; 3Mo 26,6", "Mit geringfügiger Veränderung eines Wortes üs. andere: darüber hinziehen, sie gehören seinem Volk, das den Weg geht. Selbst", "o. und Toren werden nicht auf ihm umherirren\n℘ Spr 9,4"] },
      { number: 9, text: "Kein Löwe wird dort sein, und kein reißendes Tier wird auf ihm hinaufgehen noch dort gefunden werden*, sondern die Erlösten werden darauf gehen*.", footnotes: ["℘ Hes 34,25", "℘ Kap. 43,19; 62,10.12; 3Mo 26,6"] },
      { number: 10, text: "Und die Befreiten* des HERRN werden zurückkehren und nach Zion kommen mit Jubel, und ewige Freude wird über ihrem Haupt sein*. Sie werden Wonne und Freude erlangen, und Kummer und Seufzen werden entfliehen*.", footnotes: ["w. die Freigekauften", "℘ Kap. 61,7; Ps 14,7", "℘ Kap. 25,8; 51,10.11; 60,20; 65,18.19; Jer 31,12.13; Offb 7,17"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "*Und es geschah im vierzehnten Jahr des Königs Hiskia, da zog Sanherib, der König von Assur, herauf gegen alle befestigten Städte Judas und nahm sie ein*.", heading: "Belagerung Jerusalems durch Assur zur Zeit des Königs Hiskia", footnotes: ["℘ 2Kö 18,13-37; 2Chr 32,1-19", "℘ Kap. 7,17.20; 8,8; 33,8"] },
      { number: 2, text: "Und der König von Assur sandte den Rabschake mit einem gewaltigen Heer von Lachisch aus zum König Hiskia nach Jerusalem. Und er stellte sich an der Wasserleitung des oberen Teiches auf, an der Straße des Walkerfeldes*.", footnotes: ["℘ Kap. 7,3; Mi 1,9"] },
      { number: 3, text: "Da gingen zu ihm hinaus der Palastvorsteher* Eljakim, der Sohn des Hilkija, und der Schreiber Schebna* und der Berater* Joach, der Sohn Asafs.", footnotes: ["w. der, der über das Haus war", "℘ Kap. 22,15.20", "w. der Bekanntmachende"] },
      { number: 4, text: "Und der Rabschake sprach zu ihnen: Sagt doch zu Hiskia: So spricht der große König, der König von Assur: Was ist das für ein Vertrauen, mit dem du vertraust?" },
      { number: 5, text: "Du sagst*: Fürwahr, ein bloßes Wort* ist schon Rat und Macht zum Krieg! Nun, auf wen vertraust du, dass du dich gegen mich empört hast?", footnotes: ["so mit vielen Handschr. und Qu.; Mas. T.: Ich sage", "w. ein Wort der beiden Lippen"] },
      { number: 6, text: "Siehe, du vertraust auf diesen geknickten Rohrstab, auf Ägypten, der jedem, der sich auf ihn stützt, in seine Hand dringt und sie durchbohrt. So ist der Pharao, der König von Ägypten, für alle, die auf ihn vertrauen*.", footnotes: ["℘ Kap. 20,5; 30,2; Jer 37,7; Hes 17,17; 29,16"] },
      { number: 7, text: "Wenn du aber zu mir sagst: Auf den HERRN, unsern Gott, vertrauen wir — ist er es nicht, dessen Höhen und Altäre Hiskia beseitigt hat, als er zu Juda und zu Jerusalem sagte: Vor diesem Altar sollt ihr euch niederwerfen?*", footnotes: ["℘ 2Chr 30,14"] },
      { number: 8, text: "Und nun, geh doch mit meinem Herrn, dem König von Assur, eine Wette ein! Ich will dir zweitausend Pferde stellen, wenn du dir die nötigen Reiter dafür aufstellen kannst." },
      { number: 9, text: "Doch wie willst du auch nur einen einzigen Provinzstatthalter zurücktreiben, einen von den geringsten Knechten* meines Herrn? Aber du vertraust auf Ägypten wegen der Wagen und Pferde.", footnotes: ["w. wie willst du das Gesicht eines einzigen Statthalters abwenden, eines von den kleinen Knechten"] },
      { number: 10, text: "Und nun, bin ich ohne den HERRN gegen dieses Land heraufgezogen, um es zu verheeren? Der HERR hat zu mir gesagt: Zieh hinauf in dieses Land und verheere es!" },
      { number: 11, text: "Da sagten Eljakim und Schebna und Joach zum Rabschake: Rede doch zu deinen Knechten aramäisch*, denn wir verstehen es, und rede nicht judäisch zu uns vor den Ohren des Volkes, das auf der Mauer ist!", footnotes: ["℘ Dan 2,4"] },
      { number: 12, text: "Doch der Rabschake sagte: Hat mich mein Herr etwa nur zu deinem Herrn und zu dir gesandt, um diese Worte zu reden, und nicht zu den Männern, die auf der Mauer sitzen, um mit euch ihren Kot zu essen und ihren Harn zu trinken?" },
      { number: 13, text: "Und der Rabschake trat hin und rief mit lauter Stimme auf Judäisch und sagte: Hört die Worte des großen Königs, des Königs von Assur!" },
      { number: 14, text: "So spricht der König: Hiskia täusche euch nicht! Denn er kann euch nicht retten." },
      { number: 15, text: "Und Hiskia vertröste euch nicht auf den HERRN, indem er sagt: Der HERR wird uns gewiss retten; diese Stadt wird nicht in die Hand des Königs von Assur gegeben werden*!", footnotes: ["℘ Kap. 37,10"] },
      { number: 16, text: "Hört nicht auf Hiskia! Denn so spricht der König von Assur: Macht Frieden mit mir* und kommt zu mir heraus! Dann soll jeder von seinem Weinstock und jeder von seinem Feigenbaum essen und jeder das Wasser seiner Zisterne trinken,", footnotes: ["w. Macht Segen mit mir"] },
      { number: 17, text: "bis ich komme und euch in ein Land hole wie euer Land, ein Land von Korn und Most, ein Land von Brot und Weinbergen." },
      { number: 18, text: "Hiskia verführe euch nicht, indem er sagt: Der HERR wird uns retten! Haben etwa die Götter der Nationen jeder sein Land aus der Hand des Königs von Assur gerettet*?", footnotes: ["℘ Kap. 10,7; 37,12"] },
      { number: 19, text: "Wo sind die Götter von Hamat und Arpad? Wo die Götter von Sefarwajim? Und haben sie etwa Samaria aus meiner Hand gerettet*?", footnotes: ["℘ Kap. 10,7; 37,12"] },
      { number: 20, text: "Welche sind es unter allen Göttern dieser Länder, die ihr Land aus meiner Hand gerettet haben, dass der HERR Jerusalem aus meiner Hand retten sollte*?", footnotes: ["℘ Kap. 37,4"] },
      { number: 21, text: "Da schwiegen sie still und antworteten ihm kein Wort. Denn das war der Befehl des Königs: Ihr sollt ihm nicht antworten! —" },
      { number: 22, text: "Und Eljakim, der Sohn des Hilkija, der Palastvorsteher* und der Schreiber Schebna und der Berater* Joach, der Sohn Asafs, kamen mit zerrissenen Kleidern zu Hiskia und berichteten ihm die Worte des Rabschake.", footnotes: ["w. der, der über das Haus war", "w. der Bekanntmachende"] },
    ]},
    { number: 37, verses: [
      { number: 1, text: "*Und es geschah, als der König Hiskia es hörte, zerriss er seine Kleider, hüllte sich in Sacktuch und ging in das Haus des HERRN*.", heading: "Hiskias Hilferuf an Jesaja, sein Gebet und die Rettung Jerusalems", footnotes: ["℘ 2Kö 19,1-37; 2Chr 32,20-23", "℘ V. 14"] },
      { number: 2, text: "Dann sandte er Eljakim, den Palastvorsteher*, den Schreiber Schebna* und die Ältesten der Priester, in Sacktuch gehüllt*, zum Propheten Jesaja, dem Sohn des Amoz.", footnotes: ["w. den, der über das Haus war", "℘ Kap. 22,15.20", "℘ Kap. 22,12; Est 4,1"] },
      { number: 3, text: "Und sie sagten zu ihm: So spricht Hiskia: Ein Tag der Bedrängnis und der Züchtigung und der Schmähung ist dieser Tag. Denn die Kinder sind bis an den Muttermund gekommen, aber da ist keine Kraft zu gebären*.", footnotes: ["℘ Kap. 66,9"] },
      { number: 4, text: "Vielleicht hört der HERR, dein Gott, die Worte des Rabschake, den sein Herr, der König von Assur, gesandt hat, um den lebendigen Gott zu verhöhnen, und bestraft ihn wegen der Worte, die der HERR, dein Gott, gehört hat*. Erhebe doch ein Gebet für den Rest, der sich noch findet!*", footnotes: ["℘ Kap. 36,18-20", "℘ Kap. 1,8.9; 2Chr 34,21; Jer 42,2"] },
      { number: 5, text: "So kamen die Knechte des Königs Hiskia zu Jesaja." },
      { number: 6, text: "Und Jesaja sagte zu ihnen: So sollt ihr zu eurem Herrn sagen: So spricht der HERR: Fürchte dich nicht vor den Worten, die du gehört hast, mit denen die Diener des Königs von Assur mich gelästert haben*!", footnotes: ["℘ Kap. 10,24; 41,10-14; 51,7.12; 2Chr 20,15.17"] },
      { number: 7, text: "Siehe, ich will ihm einen Geist eingeben, dass er ein Gerücht hören und in sein Land zurückkehren wird*. Dann will ich ihn in seinem Land durchs Schwert fällen.", footnotes: ["℘ V. 29.37.38"] },
      { number: 8, text: "Und der Rabschake kehrte zurück und fand den König von Assur im Kampf gegen Libna, denn er hatte gehört, dass er von Lachisch aufgebrochen wäre." },
      { number: 9, text: "Der König hatte nämlich über Tirhaka, den König von Kusch, sagen hören: Er ist ausgezogen, um gegen dich zu kämpfen. Und als er es hörte, sandte er Boten zu Hiskia und ließ ihm sagen:" },
      { number: 10, text: "So sollt ihr zu Hiskia, dem König von Juda, sagen: Dein Gott täusche dich nicht, auf den du vertraust, indem du sagst: Jerusalem wird nicht in die Hand des Königs von Assur gegeben werden!*", footnotes: ["℘ Kap. 36,15"] },
      { number: 11, text: "Siehe, du hast gehört, was die Könige von Assur mit allen Ländern getan haben, indem sie an ihnen den Bann vollstreckten*. Und du solltest gerettet werden?", footnotes: ["℘ Nah 3,19"] },
      { number: 12, text: "Haben die Götter der Nationen, die meine Väter vernichtet haben, sie gerettet: Gosan, Haran und Rezef und die Söhne Edens, die in Telassar waren*?", footnotes: ["℘ Kap. 36,18.19"] },
      { number: 13, text: "Wo ist der König von Hamat und der König von Arpad und der König der Stadt Sefarwajim, von Hena und Awa?" },
      { number: 14, text: "Da nahm Hiskia den Brief* aus der Hand der Boten und las ihn. Dann ging er hinauf ins Haus des HERRN*, und Hiskia breitete ihn vor dem HERRN aus.", footnotes: ["w. die Briefe", "℘ V. 1"] },
      { number: 15, text: "Und Hiskia betete zum HERRN*:", footnotes: ["℘ 1Kö 8,28-30"] },
      { number: 16, text: "HERR der Heerscharen, Gott Israels, der du über den Cherubim thronst*, du bist es, der da Gott ist, du allein, für alle Königreiche der Erde*. Du hast den Himmel und die Erde gemacht.", footnotes: ["℘ 1Kö 8,6", "℘ Ps 83,19"] },
      { number: 17, text: "Neige, HERR, dein Ohr und höre! Tue HERR, deine Augen auf und sieh!* Ja, höre all die Worte Sanheribs, der hierher gesandt hat, um den lebendigen Gott zu verhöhnen!", footnotes: ["℘ 2Chr 7,15.16; Dan 9,18"] },
      { number: 18, text: "Es ist wahr, HERR, die Könige von Assur haben alle Nationen* und ihr Land in Trümmer gelegt.", footnotes: ["so mit vielen hebr. Handschr.; Mas. T.: Länder"] },
      { number: 19, text: "Und ihre Götter haben sie ins Feuer geworfen, denn sie waren ja keine Götter, sondern ein Werk von Menschenhänden, Holz und Stein, und so konnte man sie vernichten*.", footnotes: ["℘ Kap. 10,10.11; Gal 4,8"] },
      { number: 20, text: "Nun aber, HERR, unser Gott, rette uns aus seiner Hand, damit alle Königreiche der Erde erkennen, dass du allein der HERR bist*!", footnotes: ["℘ Kap. 45,5.6; 1Kö 8,59.60; Hes 39,21"] },
      { number: 21, text: "Da sandte Jesaja, der Sohn des Amoz, zu Hiskia und ließ ihm sagen: So spricht der HERR, der Gott Israels: Was du zu mir gebetet hast* wegen Sanheribs, des Königs von Assur, habe ich gehört.", footnotes: ["℘ Kap. 38,5; Jak 5,16"] },
      { number: 22, text: "Dies ist das Wort, das der HERR über ihn geredet hat: Es verachtet dich, es verspottet dich die Jungfrau, die Tochter Zion; die Tochter Jerusalem schüttelt das Haupt hinter dir her." },
      { number: 23, text: "Wen hast du verhöhnt und gelästert und gegen wen die Stimme erhoben? Gegen den Heiligen Israels hast du deine Augen emporgerichtet!*", footnotes: ["℘ Kap. 10,15; 1Sam 17,26; Ps 74,18"] },
      { number: 24, text: "Durch deine Knechte hast du den Herrn verhöhnt und hast gesagt: Mit der Menge meiner Wagen habe ich die Höhe der Berge erstiegen, das äußerste Ende des Libanon. Ich haue den Hochwald seiner Zedern um, die Auslese seiner Wacholderbäume, ich komme auf seine äußerste Höhe, in das Dickicht seines Baumbestandes*.", footnotes: ["℘ Jer 22,6; Hes 21,2"] },
      { number: 25, text: "Ich habe gegraben und Wasser getrunken, und mit der Sohle meiner Füße trockne ich alle Ströme* Mazors aus*.", footnotes: ["Stehende Bezeichnung für die Arme und Kanäle des Nil.", "℘ Kap. 10,13.14; 19,5.6"] },
      { number: 26, text: "Hast du nicht gehört, dass ich lange vorher* es gewirkt und von den Tagen der Vorzeit her es gebildet habe*? Nun habe ich es kommen lassen, dass du befestigte Städte verwüstest zu öden Steinhaufen.", footnotes: ["o. von fern her", "o. es geplant habe\n℘ Kap. 22,11"] },
      { number: 27, text: "Und ihre Bewohner waren machtlos*, sie wurden schreckerfüllt und zuschanden. Sie waren wie Kraut des Feldes und grünes Gras, wie Gras auf den Dächern*, das vor dem Ostwind verdorrt*.", footnotes: ["w. ihre Bewohner hatten eine zu kurze Hand", "℘ Ps 129,6", "so mit Qu.; Mas. T.: Gras auf den Dächern und wie Weinpflanzungen vor dem Getreide. — Gemeint ist Getreide, das auf dem Halm steht.\n℘ Hes 35,13"] },
      { number: 28, text: "Dein Sitzen und dein Aus- und Eingehen kenne ich, ja, dein Toben gegen mich." },
      { number: 29, text: "Wegen deines Tobens gegen mich, und weil dein Übermut in meine Ohren heraufgekommen ist, werde ich meinen Ring in deine Nase legen und meinen Zaum an deine Lippen* und werde dich zurückführen auf dem Weg, auf dem du gekommen bist*. —", footnotes: ["℘ Hi 40,26; Hes 38,4", "℘ V. 7; Hes 29,4; Nah 2,14"] },
      { number: 30, text: "Und dies soll dir* das Zeichen sein*: Man wird in diesem Jahr den Nachwuchs der Ernte essen und im zweiten Jahr den Wildwuchs. Aber im dritten Jahr sollt ihr säen und ernten, Weinberge pflanzen und ihre Frucht essen.", footnotes: ["d. h. Hiskia", "℘ Kap. 38,7"] },
      { number: 31, text: "Und was vom Haus Juda entkommen, was übrig geblieben ist, wird wieder wurzeln nach unten und Frucht tragen nach oben*.", footnotes: ["℘ Kap. 10,21.22; 27,6"] },
      { number: 32, text: "Denn von Jerusalem wird ein Rest ausgehen und das Entkommene vom Berg Zion. Der Eifer des HERRN der Heerscharen wird das tun*.", footnotes: ["℘ Kap. 9,6"] },
      { number: 33, text: "Darum, so spricht der HERR über den König von Assur: Er wird nicht in diese Stadt kommen. Und er wird keinen Pfeil hineinschießen und ihr nicht mit dem Schild entgegentreten, und er wird keinen Wall gegen sie aufschütten." },
      { number: 34, text: "Auf dem Weg, den er gekommen ist, auf ihm wird er zurückkehren und wird nicht in diese Stadt kommen, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 35, text: "Denn ich will diese Stadt beschirmen, um sie zu retten, um meinetwegen und meines Knechtes David wegen*.", footnotes: ["℘ Kap. 31,5; 48,11; 1Chr 17,19"] },
      { number: 36, text: "Da zog ein Engel des HERRN aus und schlug im Lager von Assur 185 000 Mann. Und als man früh am Morgen aufstand, siehe, da fand man sie alle tot, lauter Leichen*.", footnotes: ["℘ Kap. 10,17.25; 29,5; 30,31; 31,8; Hi 34,20; Nah 1,12"] },
      { number: 37, text: "Und Sanherib, der König von Assur, brach auf, zog fort* und kehrte zurück; und er blieb in Ninive.", footnotes: ["℘ Kap. 31,8.9; 33,19"] },
      { number: 38, text: "Und es geschah, als er sich niederwarf im Haus seines Gottes Nisroch, da erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert*; und sie entkamen in das Land Ararat*. Und sein Sohn Asarhaddon wurde an seiner Stelle König.", footnotes: ["℘ V. 7", "℘ Jer 51,27"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "*In jenen Tagen wurde Hiskia todkrank. Und der Prophet Jesaja, der Sohn des Amoz, kam zu ihm und sagte zu ihm: So spricht der HERR: Bestelle dein Haus, denn du wirst sterben und nicht am Leben bleiben!", heading: "Hiskias Krankheit und Genesung — Sein Loblied an seinen Retter", footnotes: ["℘ V. 1-8: 2Kö 20,1-11; 2Chr 32,24"] },
      { number: 2, text: "Da wandte Hiskia sein Gesicht zur Wand und betete zu dem HERRN." },
      { number: 3, text: "Und er sprach: Ach, HERR! Denke doch daran, dass ich vor deinem Angesicht in Treue* und mit ungeteiltem Herzen gelebt habe* und dass ich getan habe, was gut ist in deinen Augen*! Und Hiskia weinte sehr.", footnotes: ["o. Wahrheit; o. Zuverlässigkeit", "w. gegangen bin", "℘ 2Kö 18,3-6"] },
      { number: 4, text: "Da geschah das Wort des HERRN zu Jesaja:" },
      { number: 5, text: "Geh hin und sage zu Hiskia: So spricht der HERR, der Gott deines Vaters David: Ich habe dein Gebet gehört*, ich habe deine Tränen gesehen*! Siehe, ich will zu deinen Tagen fünfzehn Jahre hinzufügen.", footnotes: ["℘ Kap. 37,21", "℘ Ps 6,9"] },
      { number: 6, text: "Und aus der Hand des Königs von Assur will ich dich und diese Stadt retten und will diese Stadt beschirmen." },
      { number: 7, text: "Und dies wird dir das Zeichen vom HERRN sein*, dass der HERR dieses Wort, das* er geredet hat, tun wird:", footnotes: ["℘ V. 22; Kap. 7,11.14; 37,30", "o. diese Sache, die"] },
      { number: 8, text: "Siehe, ich lasse den Schatten der Sonnenuhr um so viele Stufen zurückkehren, wie die Sonne von den Stufen an der Sonnenuhr des Ahas bereits abwärts gegangen ist, zehn Stufen zurück*. Da kehrte die Sonne zehn Stufen zurück, an den Stufen, die sie abwärts gegangen war.", footnotes: ["so mit der griech., aram. und syr. Üs.; ähnlich Qu.; Mas. T.: den Schatten der Stufen, der an den Stufen des Ahas durch die Sonne hinabgegangen ist, zurückgehen, zehn Stufen"] },
      { number: 9, text: "Aufzeichnung Hiskias, des Königs von Juda, als er krank gewesen und von seiner Krankheit genesen war." },
      { number: 10, text: "Ich sagte: In der Mitte meiner Tage soll ich hingehen zu den Pforten des Scheols. Ich bin beraubt des Restes meiner Jahre*.", footnotes: ["℘ Ps 31,23; 102,25"] },
      { number: 11, text: "Ich sagte: Ich werde Jah nicht sehen, Jah im Land der Lebendigen*, auch nicht Menschen mehr erblicken bei den Bewohnern des Totenreiches*.", footnotes: ["℘ Ps 27,13", "w. bei den Bewohnern des Aufhörens; einige Handschr. und die aram. Üs. lesen: bei den Bewohnern der Welt\n℘ Pred 9,6"] },
      { number: 12, text: "Meine Hütte ist abgebrochen und wurde von mir weggenommen* wie ein Hirtenzelt. Wie ein Weber habe ich mein Leben zu Ende gewebt*: Vom Kettgarn* schnitt er mich los. Vom Tag bis zur Nacht wirst du ein Ende mit mir machen!*", footnotes: ["w. aufgedeckt; o. enthüllt. — Andere üs. mit Textänderung: wurde zusammengerollt", "w. aufgerollt", "d. i. die Kette, mit der das Gewebe am Webgestell festgehalten wurde", "℘ Hi 7,6; Ps 90,5.6"] },
      { number: 13, text: "Ich schrie um Hilfe* bis zum Morgen, aber wie ein Löwe*, so zerbrach er alle meine Gebeine*. Vom Tag bis zur Nacht wirst du ein Ende mit mir machen!*", footnotes: ["T. in Anlehnung an die aram. Üs.; Mas. T.: ich glättete meine Seele; d. h. ich beruhigte mich; andere üs. mit Qu.: ich wurde glatt; d. h. mager", "℘ Hi 10,16", "℘ Kla 3,4", "℘ Hi 7,6; Ps 90,5.6"] },
      { number: 14, text: "Wie eine Schwalbe, eine Drossel*, so zwitscherte ich, ich gurrte wie die Taube*. Verschmachtend blickten meine Augen zur Höhe: Herr, ich bin in Bedrängnis! Tritt als Bürge für mich ein!*", footnotes: ["nach anderen: ein Schwan, o. ein Kranich", "℘ Kap. 59,11; Nah 2,8", "℘ Hi 17,3"] },
      { number: 15, text: "Was soll ich reden, nachdem er zu mir gesprochen und es selbst ausgeführt hat?* Ich will dich loben alle meine Jahre trotz* der Betrübnis meiner Seele,", footnotes: ["Die aram. Üs. liest: Was soll ich reden, was ihm sagen? Er selbst hat es ausgeführt.\n℘ Ps 116,1-8", "T.; Mas. T.: Ich wandle . . . trotz, o. wegen"] },
      { number: 16, text: "Herr! Ich will dich loben wegen derer, die leben, und für alles, worin mein Geist lebt. Und du machst mich gesund und erhältst mich am Leben*.", footnotes: ["℘ Ps 30,3.4"] },
      { number: 17, text: "Siehe, zum Heil wurde mir bitteres Leid*: Du, du hast liebevoll meine Seele von der Grube der Vernichtung zurückgehalten*, denn alle meine Sünden hast du hinter deinen Rücken geworfen*.", footnotes: ["℘ Hebr 12,11", "so mit LXX und der Vulg.; Mas. T.: Du hingst in Liebe an meiner Seele mehr als an der Grube der Vernichtung\n℘ Jon 2,7", "℘ Ps 103,3.4.12; Mi 7,18.19; Jak 5,15"] },
      { number: 18, text: "Denn der Scheol preist dich nicht, der Tod lobsingt dir nicht*; die in die Grube hinabgefahren sind, hoffen nicht auf deine Treue*.", footnotes: ["℘ Ps 6,6", "o. Wahrheit; o. Zuverlässigkeit\n℘ Pred 9,10"] },
      { number: 19, text: "Der Lebende, der Lebende, der preist dich*, wie heute ich: Der Vater erzählt den Kindern von deiner Treue*.", footnotes: ["℘ Ps 119,175", "o. Wahrheit; o. Zuverlässigkeit\n℘ 2Mo 10,2; 5Mo 4,9; Ps 78,3-7"] },
      { number: 20, text: "Der HERR war bereit, mich zu retten*. Und wir wollen das Saitenspiel erklingen lassen alle Tage unseres Lebens im Haus des HERRN*.", footnotes: ["℘ Kap. 12,2; Jon 2,10", "℘ Ps 145,1.2; 150,4"] },
      { number: 21, text: "Und Jesaja sagte, man solle einen Feigenkuchen aus Feigenfrüchten nehmen und ihn auf dem Geschwür verstreichen, damit er genese." },
      { number: 22, text: "Da sprach Hiskia: Was ist das Zeichen, dass ich in das Haus des HERRN hinaufgehen werde*?*", footnotes: ["Vermutlich gehört V. 22 zwischen V. 6 und 7 sowie V. 21 zwischen V. 8 und 9.", "℘ V. 7; Lk 1,18"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "*In jener Zeit sandte Merodach-Baladan, der Sohn Baladans, der König von Babel, Brief und Geschenk an Hiskia, denn er hatte gehört, dass er krank gewesen und wieder zu Kräften gekommen war*.", heading: "Gesandtschaft aus Babel bei Hiskia und Gottes Gerichtsandrohung", footnotes: ["℘ 2Kö 20,12-19; 2Chr 32,25-31", "℘ 2Sam 8,10"] },
      { number: 2, text: "Und Hiskia freute sich über sie und zeigte ihnen* sein Schatzhaus: das Silber und Gold, Balsamöle und das köstliche Öl, sein ganzes Vorratshaus* und alles, was sich in seinen Schatzkammern vorfand. Es gab nichts in seinem Haus und in seiner ganzen Herrschaft, das Hiskia ihnen nicht gezeigt hätte*.", footnotes: ["d. i. den Boten", "o. Waffenhaus; o. seinen ganzen Weinkeller", "℘ Hi 31,25"] },
      { number: 3, text: "Da kam der Prophet Jesaja zum König Hiskia und sprach zu ihm: Was haben diese Männer gesagt, und woher sind sie zu dir gekommen? Da sagte Hiskia: Aus einem fernen Land sind sie zu mir gekommen*, von Babel.", footnotes: ["℘ Jer 4,16"] },
      { number: 4, text: "Er aber sprach: Was haben sie in deinem Haus gesehen? Und Hiskia sagte: Sie haben alles gesehen, was in meinem Haus ist. Es gibt nichts in meinen Schatzkammern, das ich ihnen nicht gezeigt hätte." },
      { number: 5, text: "Da sprach Jesaja zu Hiskia: Höre das Wort des HERRN der Heerscharen!" },
      { number: 6, text: "Siehe, Tage kommen, da wird alles, was in deinem Haus ist und was deine Väter bis zum heutigen Tag angehäuft haben, nach Babel weggebracht werden. Nichts wird übrig bleiben*, spricht der HERR.", footnotes: ["℘ Hes 23,26"] },
      { number: 7, text: "Und von deinen Söhnen, die von dir abstammen, die du zeugen wirst, wird man einige nehmen, und sie werden im Palast des Königs von Babel Hofbeamte sein*.", footnotes: ["℘ Dan 1,3"] },
      { number: 8, text: "Da sagte Hiskia zu Jesaja: Das Wort des HERRN ist gut, das du geredet hast. Denn er sagte sich: In meinen Tagen wird ja Friede und Sicherheit sein." },
    ]},
    { number: 40, verses: [
      { number: 1, text: "Tröstet, tröstet mein Volk!, spricht euer Gott*.", heading: "Botschaft des HERRN von der Erlösung", footnotes: ["℘ Kap. 49,13; 51,3.12; Sach 1,13.17; Lk 2,25"] },
      { number: 2, text: "Redet zum Herzen Jerusalems*, und ruft ihm* zu, dass sein Frondienst* vollendet*, dass seine Schuld abgetragen ist*! Denn es hat von der Hand des HERRN das Doppelte empfangen für all seine Sünden*.", footnotes: ["℘ Hos 2,16", "d. i. Jerusalem", "w. sein Heeresdienst", "℘ Kap. 14,3; Ps 102,14", "℘ Ps 85,3; Pred 3,4; Kla 4,22", "℘ Kap. 27,9; 51,17; 2Mo 22,3; Jer 16,18; Zef 3,15"] },
      { number: 3, text: "Eine Stimme ruft:* In der Wüste bahnt* den Weg des HERRN*! Ebnet in der Steppe eine Straße für unseren Gott!*", footnotes: ["o. Horch! Es ruft einer!", "w. räumt auf; d. h. durch Beseitigung der Hindernisse", "℘ Mal 3,1; Joh 1,23", "LXX: Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn! Macht gerade die Steige unseres Gottes!\n℘ Mt 3,3"] },
      { number: 4, text: "Jedes Tal soll erhöht und jeder Berg und Hügel erniedrigt werden! Und das Unebene soll zur Ebene werden und das Hügelige zur Talebene!*", footnotes: ["℘ Kap. 42,16; 45,2; 62,10; Sach 4,7"] },
      { number: 5, text: "Und die Herrlichkeit des HERRN wird sich offenbaren*, und alles Fleisch miteinander wird es sehen.* Denn der Mund des HERRN hat geredet*.", footnotes: ["℘ Kap. 26,15; 35,2", "℘ Kap. 6,3; 66,18; Ps 97,6; 102,17; Lk 3,4-6", "℘ Kap. 1,20; 34,16; 1Kö 14,11"] },
      { number: 6, text: "Eine Stimme spricht: Rufe! Und ich sage*: Was soll ich rufen? — Alles Fleisch ist Gras, und all seine Anmut* wie die Blume des Feldes.", footnotes: ["so mit Qu., LXX und Vulg.; Mas. T.: er sagt", "o. seine Güte; o. Gnade; aram. Üs.: seine Kraft; LXX: die Herrlichkeit des Menschen"] },
      { number: 7, text: "Das Gras ist verdorrt, die Blume ist verwelkt*, denn der Hauch des HERRN hat sie angeweht. Fürwahr, das Volk ist Gras*.", footnotes: ["LXX: abgefallen", "℘ Kap. 51,12; Ps 90,5.6; 103,15.16; Jak 1,10.11"] },
      { number: 8, text: "Das Gras ist verdorrt, die Blume ist verwelkt*. Aber das Wort unseres Gottes besteht in Ewigkeit.*", footnotes: ["LXX: abgefallen", "℘ Ps 119,89; Mt 5,18; 1Petr 1,24.25"] },
      { number: 9, text: "Auf einen hohen Berg steig hinauf, du Freudenbotin Zion! Erhebe mit Macht deine Stimme, du Freudenbotin Jerusalem! Erhebe sie, fürchte dich nicht! Sprich zu den Städten Judas: Siehe da, euer Gott*!", footnotes: ["℘ Kap. 25,9; 35,4; 52,6"] },
      { number: 10, text: "Siehe, der Herr, HERR, kommt* mit Kraft*, und sein Arm übt die Herrschaft für ihn aus*. Siehe, sein Lohn ist bei ihm*, und seine Belohnung geht vor ihm her*.", footnotes: ["℘ Sach 2,14; Mal 3,1", "so mit Qu., LXX und anderen alten Üs.; Mas. T.: als Starker", "℘ Kap. 51,5.9", "℘ 1Mo 15,1; Jer 31,16", "℘ Kap. 62,11; Offb 22,12"] },
      { number: 11, text: "Er wird seine Herde weiden wie ein Hirte*, die Lämmer wird er in seinen Arm nehmen und in seinem Gewandbausch* tragen*, die säugenden Muttertiere wird er fürsorglich leiten.", footnotes: ["℘ Ps 23,1; Hes 34,12-16; Mt 2,6; Offb 7,17", "s. Anm. zu 2Mo 4,6", "℘ Ps 28,9; Sach 11,7"] },
      { number: 12, text: "Wer hat das Wasser* gemessen mit seiner hohlen Hand und den Himmel abgemessen mit der Spanne? Und wer hat den Staub der Erde mit einem Maß* erfasst* und die Berge mit der Waage gewogen, die Hügel mit Waagschalen?", heading: "Die Größe Gottes gegenüber der Erbärmlichkeit der Götterbilder", footnotes: ["Qu.: das Wasser des Meeres", "w. mit dem Dreiling; d. i. ein Drittel Efa", "℘ Hi 28,25; Spr 30,4"] },
      { number: 13, text: "Wer hat den Geist des HERRN ermessen, und wer ist der Mann seines Rates, den er unterwiese*?", footnotes: ["o. und wer ist der Mann, dem er seinen Plan mitteilte. — Andere üs.: und wer hat ihn als sein Ratgeber unterwiesen\n℘ Hi 21,22"] },
      { number: 14, text: "Mit wem beriet er sich, dass er ihm Einsicht gegeben und ihn belehrt hätte über den Pfad des Rechts und ihn Erkenntnis gelehrt und ihn über den Weg der Einsicht* unterwiesen hätte?*", footnotes: ["w. der Einsichten; d. h. der vollen Einsicht", "℘ Hi 36,23; 1Kor 2,16"] },
      { number: 15, text: "Siehe, Nationen gelten wie ein Tropfen am Eimer und wie Staub auf der Waagschale*. Siehe, Inseln hebt er hoch* wie ein Stäubchen.", footnotes: ["℘ Ps 62,10; Dan 4,32", "Andere üs. mit Textänderung: Siehe, Inseln wiegen"] },
      { number: 16, text: "Und der Libanon reicht nicht hin zum Brennholz*, und sein Wild reicht nicht hin zum Brandopfer.", footnotes: ["w. zur Feuerung"] },
      { number: 17, text: "Alle Nationen sind wie nichts vor ihm und gelten ihm als* nichtig und leer*. —", footnotes: ["im Hebr. Komparativ: weniger als", "℘ Ps 62,10; Dan 4,32"] },
      { number: 18, text: "*Mit wem wollt ihr Gott vergleichen, und was für ein Abbild wollt ihr ihm gegenüberstellen?*", footnotes: ["℘ V. 18-26: Kap. 44,6-21; Jer 10,1-16", "℘ Kap. 46,5.9; 2Mo 15,11; Ps 89,7.9; Apg 17,29"] },
      { number: 19, text: "Der Kunsthandwerker gießt das Götterbild, der Goldschmied beschlägt es mit Gold und mit silbernen Ketten vom Goldschmied*.", footnotes: ["℘ Kap. 41,7; 46,6; Ps 135,15"] },
      { number: 20, text: "Maulbeerholz* wählt er*, ein Holz, das nicht fault. Er sucht sich einen geschickten Kunsthandwerker, um ein Götterbild aufzustellen, das nicht wackelt. —", footnotes: ["w. Maulbeer des Hebopfers; o. Opfermaulbeer", "Andere nehmen eine andere Wortbedeutung an und üs.: Wer zu arm ist für ein Hebopfer, wählt"] },
      { number: 21, text: "Habt ihr es nicht erkannt? Hört ihr es nicht? Ist es euch nicht von Anfang an verkündet worden? Habt ihr nicht Einsicht gewonnen von der Gründung der Erde her*?", footnotes: ["T.; Mas. T.: in die Grundfesten der Erde"] },
      { number: 22, text: "Er ist es, der da thront über dem Kreis der Erde, dass ihre Bewohner wie Heuschrecken erscheinen, der den Himmel ausspannt wie einen Schleier* und ihn ausbreitet wie ein Zelt zum Wohnen*,", footnotes: ["℘ Hi 26,7; 37,18", "℘ Kap. 42,4; 44,24; 51,13; Hi 9,8"] },
      { number: 23, text: "der die Fürsten dem Nichts übergibt, die Richter der Erde der Nichtigkeit gleichmacht*.", footnotes: ["℘ Kap. 2,12; Hi 12,19"] },
      { number: 24, text: "Kaum sind sie gepflanzt, kaum sind sie gesät, kaum hat ihr Stamm Wurzeln in der Erde getrieben, da bläst er sie schon an. Sie verdorren, und ein Sturmwind trägt sie wie Stoppeln hinweg*.", footnotes: ["℘ Kap. 17,13"] },
      { number: 25, text: "Mit wem denn wollt ihr mich vergleichen, dem ich gleich wäre*?, spricht der Heilige.", footnotes: ["℘ Kap. 46,5.9; 2Mo 15,11; Ps 89,7.9; Apg 17,29"] },
      { number: 26, text: "Hebt zur Höhe eure Augen empor und seht: Wer hat diese da geschaffen*? Er, der ihr Heer hervortreten lässt nach der Zahl, ruft sie alle mit Namen: Vor ihm, reich* an Macht* und stark an Kraft, fehlt kein Einziger*.", footnotes: ["Hier steht dasselbe Wort wie 1Mo 1,1. Es wird nur für das Schaffen Gottes verwendet, nie für das der Götzen oder Menschen.", "so mit geringfügiger Abweichung von der mas. Vokalisierung; Mas. T.: dem Reichtum", "℘ Ps 66,3", "℘ Kap. 45,12; 48,13; 1Mo 1,14; Ps 147,4.5; Röm 1,20"] },
      { number: 27, text: "Warum sagst du, Jakob, und sprichst du, Israel: Mein Weg ist verborgen vor dem HERRN, und meinem Gott entgeht mein Recht*?", footnotes: ["℘ Kap. 44,21; 49,14"] },
      { number: 28, text: "Hast du es nicht erkannt, oder hast du es nicht gehört? Ein ewiger Gott* ist der HERR, der Schöpfer der Enden der Erde*. Er ermüdet nicht und ermattet nicht, unergründlich ist seine Einsicht*.", footnotes: ["℘ 1Mo 21,33", "℘ Jer 32,17", "℘ Röm 11,33"] },
      { number: 29, text: "Er gibt dem Müden Kraft und dem Ohnmächtigen mehrt er die Stärke*.", footnotes: ["℘ Kap. 50,4; 1Sam 2,4; Ps 68,10; 2Kor 12,9"] },
      { number: 30, text: "Jünglinge ermüden und ermatten*, und junge Männer straucheln und stürzen.", footnotes: ["℘ 1Sam 30,10; Jer 48,15"] },
      { number: 31, text: "Aber die auf den HERRN hoffen, gewinnen neue Kraft*; sie heben die Schwingen empor* wie die Adler*, sie laufen und ermatten nicht, sie gehen und ermüden nicht*.", footnotes: ["℘ Kap. 30,15; 5Mo 33,25; Jos 14,11", "o. sie treiben Schwingen", "℘ Ps 103,5", "℘ Ps 20,9"] },
    ]},
    { number: 41, verses: [
      { number: 1, text: "Hört mir schweigend zu*, ihr Inseln! Und die Völkerschaften sollen neue Kraft gewinnen.* Sie sollen herzutreten, dann mögen sie reden: Lasst uns miteinander vor Gericht treten*!", heading: "Gottes Rettung durch den Eroberer Kyros", footnotes: ["℘ Kap. 49,1; Sach 2,17", "Andere vermuten, der Text habe ursprünglich gelautet: Ihr Völkerschaften, wartet auf meine Zurechtweisung!", "℘ V. 21"] },
      { number: 2, text: "Wer hat vom Sonnenaufgang her den erweckt*, dessen Fuß Gerechtigkeit* begegnet? Wer gibt Nationen vor ihm dahin* und stürzt Könige hinab?* Sein Schwert macht sie wie Staub, sein Bogen wie verwehte Strohstoppeln*.", footnotes: ["℘ Kap. 45,13; 46,11; Esr 1,2", "hier vielleicht im Sinne von Gelingen", "o. Er legt Nationen vor sich nieder", "so mit Qu. und einer griech. Üs.; Mas. T.: Wer lässt Könige niedertreten?; o. er lässt Könige niedertreten", "℘ V. 25; Kap. 45,1"] },
      { number: 3, text: "Er jagt ihnen nach, zieht wohlbehalten einher, berührt den Weg nicht mit seinen Füßen." },
      { number: 4, text: "Wer hat es gewirkt und getan*? Der die Generationen ruft von Anbeginn. Ich, der HERR, bin der Erste, und bei den Letzten bin ich derselbe*.", footnotes: ["℘ V. 20", "w. bin ich es; vgl. Anm. zu Ps 102,28\n℘ Kap. 43,10.11; 44,6; 48,12; Ps 102,28"] },
      { number: 5, text: "Die Inseln haben es gesehen und fürchten sich, es erbeben die Enden der Erde*. Sie näherten sich und kamen herbei.", footnotes: ["℘ Ps 65,9"] },
      { number: 6, text: "Einer hilft dem andern und sagt zu seinem Bruder: Sei mutig!" },
      { number: 7, text: "Und der Kunsthandwerker ermutigt den Goldschmied. Der mit dem Hammer glättet, ermutigt den, der auf den Amboss schlägt*, und sagt von der Lötung: Sie ist gut. Und er befestigt es* mit Nägeln, dass es nicht wackelt*.", footnotes: ["o. den, der mit dem Klöppel schlägt", "d. i. das Götzenbild", "℘ Kap. 40,19.20"] },
      { number: 8, text: "Du aber, Israel, mein Knecht, Jakob, den ich erwählt habe*, Nachkomme Abrahams, meines Freundes*,", heading: "Trost für Israel, den Knecht Gottes", footnotes: ["℘ Kap. 29,22; 43,10; 44,1.2; 45,4; 49,3; 5Mo 7,6; 1Chr 16,13; Ps 136,21", "℘ 2Chr 20,7; Jak 2,23"] },
      { number: 9, text: "du, den ich ergriffen von den Enden der Erde und von ihren fernsten Gegenden her gerufen habe*, zu dem ich sprach: Mein Knecht bist du, ich habe dich erwählt und nicht verworfen* —", footnotes: ["℘ Neh 9,7", "℘ Röm 11,2.29; Hebr 2,16"] },
      { number: 10, text: "fürchte dich nicht, denn ich bin mit dir*! Habe keine Angst, denn ich bin dein Gott*! Ich stärke dich*, ja, ich helfe dir, ja, ich halte dich mit der Rechten meiner Gerechtigkeit*.", footnotes: ["℘ Kap. 35,4; 43,5; 44,2.8; 1Mo 26,24", "℘ Ps 33,12", "℘ Sach 10,6", "℘ 2Sam 22,19; Ps 18,36; 37,17; Lk 1,54"] },
      { number: 11, text: "Siehe, beschämt und zuschanden werden alle, die in Feindschaft gegen dich entbrannt sind*. Es werden wie nichts und gehen zugrunde die Männer, die den Rechtsstreit mit dir führen*.", footnotes: ["℘ Kap. 45,24", "w. die Männer deines Rechtsstreites\n℘ Kap. 54,15.17; 60,12; 2Mo 12,29; Jer 12,17"] },
      { number: 12, text: "Du wirst sie suchen und nicht finden, die Männer, die mit dir zanken*. Wie nichts und wie Nichtigkeit werden die Männer, die mit dir Krieg führen*.", footnotes: ["w. die Männer deines Zankes", "w. die Männer deines Krieges\n℘ Kap. 29,8; 49,25; Zef 3,19"] },
      { number: 13, text: "Denn ich bin der HERR, dein Gott, der deine Rechte ergreift, der zu dir spricht: Fürchte dich nicht! Ich, ich helfe dir!* —", footnotes: ["℘ Ps 118,7; Jer 30,10"] },
      { number: 14, text: "Fürchte dich nicht, du Wurm* Jakob, du Häuflein* Israel! Ich, ich helfe dir, spricht der HERR*, und dein Erlöser ist der Heilige Israels*.", footnotes: ["℘ Hi 25,6", "w. Männer. — Andere nehmen an, dass bei dem Wort ein Buchstabe verloren gegangen ist, und lesen: Würmchen\n℘ Kap. 37,4.6; Lk 12,32", "w. ist der Ausspruch des HERRN", "℘ Kap. 43,3.14; 63,16; Hi 19,25"] },
      { number: 15, text: "Siehe, ich habe dich zu einem scharfen, neuen Dreschschlitten gemacht, mit Doppelschneiden versehen: du wirst Berge dreschen und zermalmen und Hügel der Spreu gleichmachen*.", footnotes: ["℘ Jos 17,18; Ri 6,16; Mi 4,13"] },
      { number: 16, text: "Du wirst sie worfeln*, und der Wind wird sie forttragen und der Sturm sie zerstreuen. Du aber, du wirst jubeln in dem HERRN und dich rühmen in dem Heiligen Israels.*", footnotes: ["℘ Jer 51,2", "℘ Kap. 29,19; Joe 2,23"] },
      { number: 17, text: "Die Elenden und die Armen suchen nach Wasser, und es gibt keins, ihre Zunge vertrocknet vor Durst. Ich, der HERR, werde sie erhören*, ich, der Gott Israels, werde sie nicht verlassen*.", footnotes: ["℘ Kap. 55,1", "℘ Ps 94,14; Jer 31,25; Hebr 13,5"] },
      { number: 18, text: "Ich werde Ströme öffnen auf den kahlen Höhen und Quellen mitten in den Talebenen. Ich werde die Wüste zum Wasserteich machen und das dürre Land zu Wasserquellen*.", footnotes: ["℘ Kap. 35,6.7; 43,19.20; Ri 15,19; Ps 126,4"] },
      { number: 19, text: "Ich werde Zedern in die Wüste setzen, Akazien, Myrten und Olivenbäume, werde Wacholderbäume in die Steppe pflanzen, Platanen und Zypressen miteinander*,", footnotes: ["℘ Kap. 51,3; 55,13"] },
      { number: 20, text: "damit sie sehen und erkennen, es merken* und verstehen allesamt, dass die Hand des HERRN dies getan und der Heilige Israels es geschaffen hat*.", footnotes: ["so mit Qu.; Mas. T.: im Gedächtnis aufrichten", "℘ V. 4; Kap. 28,29; 66,2"] },
      { number: 21, text: "Bringt eure Rechtssache vor!, spricht der HERR. Bringt eure Beweise herbei*!, spricht der König Jakobs*.", footnotes: ["℘ V. 1; Kap. 1,18", "℘ Kap. 33,22; 43,15"] },
      { number: 22, text: "Sie sollen sie herbeibringen* und uns verkünden, was sich ereignen wird; das Frühere, was war es? Verkündet es, damit wir es uns zu Herzen nehmen! *Oder lasst uns das Künftige hören*, damit wir seinen Ausgang erkennen*!", footnotes: ["LXX, Vulg., syr. und aram. Üs. lesen: Sie sollen herantreten", "Im Mas. T. stehen die beiden Satzhälften in umgekehrter Reihenfolge.", "℘ Kap. 42,9; 43,9-12; 45,21; 46,10; 48,14", "Im Mas. T. stehen die beiden Satzhälften in umgekehrter Reihenfolge."] },
      { number: 23, text: "Verkündet das später Kommende, damit wir erkennen, dass ihr Götter seid!* Ja, lasst es gut sein oder schlimm sein*, dass wir uns gegenseitig ansehen und miteinander erschrecken*!", footnotes: ["℘ Kap. 19,12", "d. h. den Inhalt der Ankündigung. Andere üs.: tut etwas Gutes oder tut etwas Böses\n℘ Jer 10,5", "o. damit wir miteinander erschrecken und es sehen"] },
      { number: 24, text: "Siehe, ihr seid nichts, und euer Tun ist Nichtigkeit*. Ein Gräuel ist, wer euch erwählt*!", footnotes: ["so in Anlehnung an die aram. Üs.; Mas. T.: Siehe, ihr seid weniger als nichts, und eure Taten sind weniger als Wertloses\n℘ Kap. 44,9.10; 1Kor 8,4", "℘ 5Mo 7,25.26"] },
      { number: 25, text: "Ich habe ihn von Norden her erweckt, und er kam herbei — von Sonnenaufgang her* *den, der meinen Namen anruft*. Und er zertritt* Befehlshaber wie Lehm und wie ein Töpfer, der Ton stampft.", footnotes: ["℘ V. 2", "Mit geringfügiger Änderung und teilweise mit Qu. lesen andere: rief ich ihn beim Namen; vgl. Kap. 45,3", "Mit geringfügiger Änderung und teilweise mit Qu. lesen andere: rief ich ihn beim Namen; vgl. Kap. 45,3", "so wahrscheinlich der ursprüngliche Text; Mas. T.: er kommt über"] },
      { number: 26, text: "Wer hat es von Anfang an verkündet, dass wir es erkannt hätten, und von jeher, dass wir sagen könnten: Richtig! Ja, da war keiner, der es verkündete, ja, keiner, der es hören ließ, ja, keiner, der eure Sprüche gehört hätte*.", footnotes: ["℘ Kap. 44,7"] },
      { number: 27, text: "*Als Erster habe ich zu Zion gesagt: Siehe, siehe, da sind sie*, und Jerusalem gebe ich einen Freudenboten!", footnotes: ["Andere üs. mit geringfügiger Textänderung: Meine Sprüche habe ich Zion verkündet", "Andere üs. mit geringfügiger Textänderung: Meine Sprüche habe ich Zion verkündet"] },
      { number: 28, text: "Und ich sehe hin, doch da ist niemand, und unter diesen da ist kein Ratgeber, dass ich sie fragen könnte und sie mir Antwort gäben." },
      { number: 29, text: "Siehe, sie alle sind Betrug. Nichtigkeit sind ihre Machwerke, Wind und Leere ihre gegossenen Bilder*.", footnotes: ["℘ Kap. 46,7; 1Sam 12,21; Ps 96,5; Sach 10,2"] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "Siehe, mein Knecht*, den ich halte, mein Auserwählter*, an dem meine Seele Wohlgefallen hat: Ich habe meinen Geist auf ihn gelegt*, er wird das Recht zu den Nationen hinausbringen*.", heading: "Erstes Lied: Der Knecht Gottes bringt Recht und Licht", footnotes: ["℘ Kap. 49,3; 50,10; 52,13; Sach 3,8; Apg 3,13; Phil 2,7", "℘ Ps 89,4.20-28; Lk 23,35", "℘ Kap. 11,2; 61,1; Mt 3,16.17", "℘ Kap. 2,4; 63,1; Ps 72,4"] },
      { number: 2, text: "Er wird nicht schreien und die Stimme nicht erheben und seine Stimme nicht hören lassen auf der Straße*.", footnotes: ["℘ Mk 7,24"] },
      { number: 3, text: "Das geknickte Rohr wird er nicht zerbrechen, und den glimmenden* Docht wird er nicht auslöschen. In Treue* bringt er das Recht hinaus*.", footnotes: ["w. den farblosen, o. den trüben", "o. In Wahrheit", "℘ Kap. 2,4; 63,1; Ps 72,4"] },
      { number: 4, text: "Er wird nicht verzagen* noch zusammenbrechen*, bis er das Recht auf Erden aufgerichtet hat*. Und die Inseln warten auf seine Weisung*. —", footnotes: ["w. ausdruckslos (o. lichtlos) werden", "w. nicht knicken; vgl. V. 3", "℘ Dan 9,24", "℘ Kap. 11,10; 60,9; 1Mo 49,10; Mt 12,17-21"] },
      { number: 5, text: "So spricht Gott, der HERR, der den Himmel schuf* und ihn ausspannte, der die Erde ausbreitete und was ihr entsprosst, der dem Volk auf ihr den Atem gab* und den Lebenshauch denen, die auf ihr gehen*:", footnotes: ["s. Anm. zu Kap. 40,26\n℘ Ps 96,5", "o. gibt", "℘ Kap. 40,22; 45,12; 57,16; Jer 38,16; Hes 18,4; Apg 17,25"] },
      { number: 6, text: "Ich, der HERR, ich habe dich in Gerechtigkeit gerufen und ergreife dich bei der Hand. Und ich behüte dich und mache dich* zum Bund des Volkes*, zum Licht der Nationen*,", footnotes: ["o. ich habe dich gebildet und dich gesetzt", "Das Wort Bund steht hier in seiner Grundbedeutung »Verpflichtung, Bestimmung« (für das Volk). Gott hat den Gerufenen (zum Heil) für das Volk verpflichtet oder bestimmt.\n℘ Kap. 49,8", "℘ Kap. 49,6; 51,4; Lk 2,32; Apg 26,18.23"] },
      { number: 7, text: "blinde Augen aufzutun*, um Gefangene aus dem Kerker herauszuführen und aus dem Gefängnis, die in der Finsternis sitzen*. —", footnotes: ["℘ Kap. 29,18; Mk 10,52", "℘ Kap. 49,9; 61,1; Lk 1,79; Kol 1,13"] },
      { number: 8, text: "Ich bin Jahwe, das ist mein Name*. Und meine Ehre gebe ich keinem anderen* noch meinen Ruhm den Götterbildern.", footnotes: ["℘ 2Mo 3,14.15; Ps 83,19; Jer 33,2", "℘ Kap. 48,11"] },
      { number: 9, text: "Das Frühere, siehe, es ist eingetroffen, und Neues verkündige ich. Bevor es aufsprosst, lasse ich es euch hören*.", footnotes: ["℘ Kap. 41,22; 48,5.6; 1Petr 1,10-12"] },
      { number: 10, text: "Singt dem HERRN ein neues Lied*, seinen Ruhm vom Ende der Erde: Es brause das Meer* und seine Fülle, die Inseln und ihre Bewohner*!", heading: "Gott kommt zur Rettung um seiner Gerechtigkeit willen", footnotes: ["℘ Ps 33,3; Offb 5,9", "T.; Mas. T.: Die zum Meer herabsteigen. — Andere üs. mit anderer Wortabtrennung: Es verherrliche ihn das Meer", "℘ Kap. 24,15; Ps 97,1"] },
      { number: 11, text: "Die Stimme sollen erheben die Steppe und ihre Städte, die Dörfer, die Kedar* bewohnt*! Jubeln sollen die Bewohner von Sela*, jauchzen vom Gipfel der Berge her!", footnotes: ["d. i. ein Nomadenstamm in der syrisch-arabischen Wüste", "℘ Kap. 60,7; Hes 27,21", "o. die Bewohner des Felsens"] },
      { number: 12, text: "Dem HERRN sollen sie Ehre geben* und seinen Ruhm auf den Inseln verkündigen*!", footnotes: ["℘ Offb 14,7", "℘ Kap. 24,15; Ps 97,1"] },
      { number: 13, text: "Der HERR zieht aus wie ein Held, wie ein Kriegsmann weckt er den Eifer*. Er erhebt einen Schlachtruf, ja, ein gellendes Feldgeschrei, er beweist sich als Held gegen seine Feinde*.", footnotes: ["℘ Kap. 59,17", "℘ Kap. 31,4; Ps 78,65.66; Jer 25,30"] },
      { number: 14, text: "Seit ewigen Zeiten habe ich geschwiegen, war still, habe an mich gehalten*. Wie eine Gebärende will ich nun stöhnen, schnauben und nach Luft schnappen zugleich.", footnotes: ["℘ Ps 50,21"] },
      { number: 15, text: "Ich will Berge und Hügel ausdörren und all ihr Kraut vertrocknen lassen. Und ich will Ströme zu Inseln machen und Teiche trockenlegen*.", footnotes: ["℘ Kap. 50,2; Ps 107,33"] },
      { number: 16, text: "Und ich will die Blinden auf einem Weg gehen lassen, den sie nicht kennen*, auf Pfaden, die sie nicht kennen, will ich sie schreiten lassen*. Die Finsternis vor ihnen will ich zum Licht machen und das Holperige zur Ebene*. Das sind die Dinge, die ich tun und von denen ich nicht ablassen werde.", footnotes: ["℘ Jer 31,8.9", "℘ Kap. 40,4", "℘ Kap. 40,4"] },
      { number: 17, text: "Es weichen zurück, es werden völlig zuschanden alle, die auf ein Götterbild vertrauen, die zum gegossenen Bild sagen: Ihr seid unsere Götter*.", footnotes: ["℘ Kap. 44,11; Ps 97,7; 135,18"] },
      { number: 18, text: "Hört, ihr Tauben! Und ihr Blinden, schaut her, um zu sehen*!", footnotes: ["℘ Kap. 43,8; Mt 11,5"] },
      { number: 19, text: "Wer ist blind, wenn nicht mein Knecht, und taub, wenn nicht* mein Bote, den ich sende? Wer ist blind wie Meschullam* und blind wie der Knecht des HERRN?", footnotes: ["so mit LXX und Vulg.; Mas. T.: taub wie", "d. i. ein Personenname; vielleicht bedeutet er: der Vertraute, der Gottergebene"] },
      { number: 20, text: "Er hat* vieles gesehen, aber es nicht beachtet*, hat offene Ohren, aber hört nicht*.", footnotes: ["o. Du hast", "so mit zwei hebr. Handschr.; Mas. T.: du hast es nicht beachtet", "℘ Kap. 6,9; 48,8; Hes 33,32"] },
      { number: 21, text: "Dem HERRN hat es gefallen um seiner Gerechtigkeit willen. Er macht das Gesetz groß und herrlich*.", footnotes: ["Qu.: Dem HERRN gefiel es . . ., dass er das Gesetz groß und herrlich mache\n℘ 5Mo 4,6.8; Mt 5,17"] },
      { number: 22, text: "Doch ist es jetzt noch ein beraubtes und ausgeplündertes Volk*. Sie sind allesamt in Löchern gefesselt, und in Kerkern werden sie versteckt gehalten. Sie sind zur Beute geworden, und da ist kein Erretter*, zur Plünderung, und niemand sagt: Gib wieder her*!", footnotes: ["℘ Kap. 24,3; Jer 51,34", "℘ Kap. 5,29", "℘ 5Mo 28,33"] },
      { number: 23, text: "Wer unter euch will das zu Ohren nehmen, will achtgeben und für die Zukunft hören*?", footnotes: ["℘ 5Mo 32,29"] },
      { number: 24, text: "Wer hat Jakob der Plünderung preisgegeben und Israel den Räubern? Nicht der HERR, gegen den wir gesündigt haben*? Und sie wollten nicht auf seinen Wegen gehen und hörten nicht auf sein Gesetz*.", footnotes: ["℘ Ri 2,14", "℘ Ps 81,12; Jer 44,10; Lk 13,34"] },
      { number: 25, text: "Da hat er die Glut seines Zornes* und die Gewalt des Krieges über es ausgegossen. Und er hat es ringsum versengt, aber es kommt nicht zur Erkenntnis, und er hat es in Brand gesteckt, aber es nimmt es nicht zu Herzen*.", footnotes: ["so mit Qu.; Mas. T.: Da hat er die Erregung, seinen Zorn; o. . . . in Erregung seinen Zorn", "℘ Jer 5,3; 12,11"] },
    ]},
    { number: 43, verses: [
      { number: 1, text: "Aber jetzt, so spricht der HERR, der dich geschaffen*, Jakob, und der dich gebildet hat, Israel*: Fürchte dich nicht, denn ich habe dich erlöst*! Ich habe dich bei deinem Namen gerufen, du bist mein*.", heading: "Israels Rettung aus Gnade", footnotes: ["s. Anm. zu Kap. 40,26", "℘ Kap. 44,2; 45,11; 51,13; 5Mo 32,6.15", "℘ Kap. 44,6.23; 48,20; 49,26; 54,5; 63,9", "℘ Hes 16,8"] },
      { number: 2, text: "Wenn du durchs Wasser gehst, ich bin bei dir*, und durch Ströme, sie werden dich nicht überfluten. Wenn du durchs Feuer gehst, wirst du nicht versengt werden, und die Flamme wird dich nicht verbrennen*.", footnotes: ["℘ Ps 23,4; 32,6", "℘ Hi 5,19"] },
      { number: 3, text: "Denn ich bin der HERR, dein Gott, ich, der Heilige Israels, dein Retter*. Ich gebe Ägypten als Lösegeld für dich, Kusch und Seba an deiner Stelle*.", footnotes: ["o. Helfer\n℘ Kap. 41,14; 45,15; 63,8; Tit 3,4.5", "℘ Kap. 45,14"] },
      { number: 4, text: "Weil du teuer bist in meinen Augen und wertvoll bist und ich dich lieb habe*, so gebe ich Menschen hin an deiner Stelle und Völkerschaften anstelle deines Lebens.", footnotes: ["℘ 5Mo 4,37; Jer 31,3; Hos 11,1.4; Offb 3,9"] },
      { number: 5, text: "Fürchte dich nicht, denn ich bin mit dir*! Vom Sonnenaufgang her werde ich deine Nachkommen bringen, und vom Sonnenuntergang her werde ich dich sammeln*.", footnotes: ["℘ Kap. 41,10", "℘ Kap. 54,7"] },
      { number: 6, text: "Ich werde zum Norden sagen: Gib her!, und zum Süden: Halte nicht zurück*! Bring meine Söhne von fern her und meine Töchter vom Ende der Erde*,", footnotes: ["℘ Kap. 27,13; Jer 3,18; 23,8", "℘ Kap. 11,12; 49,12; Hes 36,24; Joe 4,7; Mk 13,27"] },
      { number: 7, text: "jeden, der mit meinem Namen genannt ist* und den ich zu meiner Ehre geschaffen*, den ich gebildet, ja, gemacht habe!*", footnotes: ["℘ Jer 14,9; Dan 9,19", "℘ Kap. 60,21", "℘ 1Sam 12,22"] },
      { number: 8, text: "Lass hervortreten* das blinde Volk, das doch Augen hat, und die Tauben, die doch Ohren haben*!", footnotes: ["So konnte der Text vor der Vokalisierung durch die Masoreten verstanden werden. Mas. T.: Er hat hervortreten lassen", "℘ Kap. 6,9; 42,18-20"] },
      { number: 9, text: "Alle Nationen sind miteinander versammelt, und die Völkerschaften sind zusammengekommen! Wer unter ihnen verkündet dies*? Auch Früheres* sollen sie uns hören lassen! Sie sollen ihre Zeugen stellen, dass sie gerecht sind*! Und sie sollen es hören und sagen: Es ist wahr!*", footnotes: ["Gemeint sind zukünftige Ereignisse.", "d. h. früher Geweissagtes, das in Erfüllung gegangen ist", "o. im Recht sind; o. damit sie Recht behalten", "℘ Kap. 41,21.22"] },
      { number: 10, text: "Ihr seid meine Zeugen*, spricht der HERR*, und mein Knecht, den ich erwählt habe*, damit ihr erkennt und mir glaubt und einseht, dass ich es bin*. Vor mir wurde kein Gott gebildet, und nach mir wird keiner sein*.", footnotes: ["℘ Kap. 44,8; 55,4", "w. ist der Ausspruch des HERRN", "℘ Kap. 41,8", "o. dass ich derselbe bin\n℘ Kap. 41,4", "℘ Kap. 44,6; 45,5.6; 46,9; 2Mo 8,6"] },
      { number: 11, text: "Ich, ich bin der HERR, und außer mir gibt es keinen Retter*.", footnotes: ["o. Helfer\n℘ Hos 13,4"] },
      { number: 12, text: "Ich habe verkündigt und gerettet und hören lassen, und kein fremder Gott war* unter euch*. Und ihr seid meine Zeugen*, spricht der HERR*; ich bin Gott*.", footnotes: ["o. und ich war kein Fremder", "℘ 5Mo 32,12", "℘ Kap. 44,8; 55,4", "w. ist der Ausspruch des HERRN", "℘ 5Mo 32,39"] },
      { number: 13, text: "Ja, auch weiterhin bin ich es*, und da ist niemand, der aus meiner Hand rettet*. Ich wirke, und wer kann es rückgängig machen?*", footnotes: ["o. auch in Zukunft bin ich derselbe\n℘ Ps 102,28", "℘ Kap. 14,27", "℘ Kap. 14,27"] },
      { number: 14, text: "So spricht der HERR, euer Erlöser, der Heilige Israels*: Euretwegen* habe ich nach Babel gesandt*. Und ich stoße herunter all die Riegel. Und die Chaldäer — zur Klage wird ihr Jubel*.", footnotes: ["℘ Kap. 48,17", "o. euch zuliebe", "℘ Jer 51,2-4", "So lässt sich der Text in seiner ursprünglichen Form (ohne Vokale) verstehen. Die Masoreten lasen: Und die Chaldäer auf den Schiffen ihres Jubels o. ihres Klagens. Das hebr. Wort kann beides bedeuten."] },
      { number: 15, text: "Ich bin der HERR, euer Heiliger, der Schöpfer Israels*, euer König*.", footnotes: ["℘ Hab 1,12", "℘ Kap. 41,21; 47,4"] },
      { number: 16, text: "So spricht der HERR, der einen Weg gibt im Meer und einen Pfad in mächtigen Wassern*,", footnotes: ["℘ Kap. 51,10; Ps 77,20"] },
      { number: 17, text: "der ausziehen lässt Wagen und Pferd, Heer und Held — zusammen liegen sie da, stehen nicht wieder auf; sie sind erloschen, verglommen wie ein Docht* —:", footnotes: ["℘ Ri 4,16"] },
      { number: 18, text: "Denkt nicht an das Frühere, und auf das Vergangene achtet nicht!" },
      { number: 19, text: "Siehe, ich wirke Neues*! Jetzt sprosst es auf. Erkennt ihr es nicht*? Ja, ich lege durch die Wüste einen Weg, Ströme* durch die Einöde*.", footnotes: ["℘ Offb 21,5", "℘ Kap. 48,6", "Qu.: Pfade", "℘ Kap. 35,6-8; Jer 31,9"] },
      { number: 20, text: "Die Tiere des Feldes werden mich ehren*, Schakale und Strauße, weil ich in der Wüste Wasser gegeben habe, Ströme in der Einöde, um mein Volk zu tränken, mein auserwähltes*.", footnotes: ["℘ Ps 148,10", "℘ Kap. 41,17.18; 48,21"] },
      { number: 21, text: "Dieses Volk, das ich mir gebildet habe, sie sollen meinen Ruhm erzählen*.", footnotes: ["℘ Ps 79,13; 102,19; Jer 33,9; 1Petr 2,9"] },
      { number: 22, text: "Nicht mich hast du angerufen, Jakob*, dass du dich um mich gemüht hättest, Israel!", footnotes: ["℘ Kap. 64,6; Dan 9,13"] },
      { number: 23, text: "Du hast mir nicht das Lamm deiner Brandopfer gebracht und mit deinen Schlachtopfern mich nicht geehrt*. Ich habe dir nicht mit Opfergaben Arbeit gemacht* noch mit Weihrauch dich ermüdet*.", footnotes: ["℘ Mal 3,8", "w. Ich habe dich nicht . . . zur Arbeit angehalten", "℘ Mi 6,3"] },
      { number: 24, text: "Du hast mir nicht für Geld Würzrohr gekauft* noch mit dem Fett deiner Schlachtopfer mich gesättigt*. Vielmehr hast du mir Arbeit gemacht* mit deinen Sünden, du hast mich ermüdet mit deinen Sünden*.", footnotes: ["℘ 2Mo 30,23", "℘ Lk 7,44", "w. du hast mich zur Arbeit angehalten", "℘ Kap. 7,13; Mal 2,17"] },
      { number: 25, text: "Ich, ich bin es, der deine Verbrechen auslöscht* um meinetwillen*, und deiner Sünden will ich nicht gedenken*.", footnotes: ["℘ Kap. 44,22; Ps 51,3; 103,3; Apg 3,19", "℘ Kap. 48,11", "℘ Kap. 64,8; Jer 31,34"] },
      { number: 26, text: "Zeige mich an*! Wir wollen miteinander vor Gericht treten*! Erzähle du, damit du recht behältst*!", footnotes: ["o. Klage mich an", "℘ Kap. 1,18", "℘ Hi 40,8"] },
      { number: 27, text: "Dein erster Vater* hat schon gesündigt, und deine Vermittler haben mit mir gebrochen*.", footnotes: ["℘ Hes 16,3", "℘ Jer 8,8-10"] },
      { number: 28, text: "So entweihe ich die Obersten des Heiligtums*. Und ich gebe Jakob dem Bann und Israel den Hohnreden preis.*", footnotes: ["LXX: Und die Obersten entweihten mein Heiligtum\n℘ 1Chr 24,5; 2Chr 36,17", "℘ Ps 79,4; Jer 24,9; Dan 9,11.12"] },
    ]},
    { number: 44, verses: [
      { number: 1, text: "Aber nun höre, Jakob, mein Knecht, und Israel, den ich erwählt habe*.", heading: "Der segnende, lebendige Gott und die Torheit des Götzendienstes", footnotes: ["℘ V. 21; Kap. 41,8.9; 48,12"] },
      { number: 2, text: "So spricht der HERR, der dich gemacht und von Mutterleibe an dich gebildet hat*, der dir hilft*: Fürchte dich nicht, mein Knecht Jakob, und Jeschurun*, den ich erwählt habe!", footnotes: ["℘ V. 24; Kap. 43,1.7.21; Ps 95,6", "℘ Kap. 41,10.13.14", "d. h. vielleicht »der Rechtschaffene«; ein Ehrenname für Jakob-Israel\n℘ 5Mo 32,15"] },
      { number: 3, text: "Denn ich werde Wasser gießen auf das durstige und Bäche auf das trockene Land*. Ich werde meinen Geist ausgießen auf deine Nachkommen* und meinen Segen auf deine Sprösslinge*.", footnotes: ["℘ Kap. 27,3; 35,7", "℘ Kap. 32,15; 59,21; Hes 36,27; Joe 3,1", "℘ Apg 2,17"] },
      { number: 4, text: "Und sie werden aufsprossen wie Schilf zwischen Wassern*, wie Pappeln an Wasserläufen*.", footnotes: ["so in Anlehnung an Qu. und LXX; Mas. T.: sie werden aufsprossen im Zwischenraum des Schilfes, o. des Grases", "℘ Kap. 58,11; Ps 1,3"] },
      { number: 5, text: "Dieser wird sagen: Ich gehöre dem HERRN! Und jener wird sich mit dem Namen Jakob nennen*. Und jener wird auf seine Hand schreiben: Dem HERRN eigen!, und wird mit dem Namen Israel genannt werden*.", footnotes: ["so mit zwei griech. Üs.; Mas. T.: Und der wird mit dem Namen Jakob einen anderen nennen\n℘ Kap. 2,3; 2Chr 36,23", "so mit der syr. und aram. Üs.; Mas. T.: wird mit dem Namen Israel jemandem einen Ehrennamen verleihen"] },
      { number: 6, text: "*So spricht der HERR, der König Israels und sein Erlöser*, der HERR der Heerscharen: Ich bin der Erste und bin der Letzte*, und außer mir gibt es keinen Gott*.", footnotes: ["℘ V. 6-21: Kap. 40,18-26; Jer 10,1-16", "℘ Kap. 33,22; 43,1.11.14", "℘ Kap. 41,4; Offb 1,17", "℘ Kap. 43,9-12"] },
      { number: 7, text: "Und wer ist wie ich*? Er rufe und verkünde es und lege es mir dar! — *Wer hat von Urzeiten her das Kommende hören lassen?* Und was eintreten wird, sollen sie uns* verkünden*!", footnotes: ["℘ Kap. 43,9-12", "Diese Üs. ergibt sich aus einem Versuch, den ursprünglichen Text wiederherzustellen. Mas. T.: Seit ich gesetzt habe das Volk der Urzeit; und das Kommende.", "Diese Üs. ergibt sich aus einem Versuch, den ursprünglichen Text wiederherzustellen. Mas. T.: Seit ich gesetzt habe das Volk der Urzeit; und das Kommende.", "so mit der aram. Üs.; Mas. T.: ihnen; o. ihm", "℘ Kap. 19,12; 41,26"] },
      { number: 8, text: "Erschreckt nicht und zittert nicht! Habe ich es dich nicht schon längst hören lassen und es dir verkündet? Und ihr seid meine Zeugen: Gibt es einen Gott außer mir*? Es gibt keinen Fels*, ich kenne keinen.", footnotes: ["℘ Kap. 43,9-12", "℘ Kap. 17,10; 30,29; 1Sam 2,2; Ps 18,32"] },
      { number: 9, text: "Die Bildner von Götterbildern sind allesamt nichtig*, und ihre Lieblinge nützen nichts*. Und ihre Zeugen* sehen nicht und erkennen nicht, damit sie zuschanden werden*.", footnotes: ["s. Anm. zu »wüst« in 1Mo 1,2", "℘ Kap. 41,24.29; 57,12", "d. h. die, die für die Götterbilder eintreten", "℘ Kap. 42,17; 45,16; 5Mo 4,28; Jer 2,26-28"] },
      { number: 10, text: "Wer hat je einen Gott gebildet und ein Götterbild gegossen, damit es nichts nützt?*", footnotes: ["℘ Kap. 45,20; Ps 115,4-8; Jer 10,5; Hab 2,18; 1Kor 8,4"] },
      { number: 11, text: "Siehe, alle seine Anhänger* werden zuschanden. Und die Kunsthandwerker sind ja nur Menschen*. Sollen sie sich alle versammeln, hintreten; erschrecken müssen sie, zuschanden werden allesamt!*", footnotes: ["w. alle, die mit ihm Gemeinschaft haben", "w. die Kunsthandwerker, sie sind vom Menschen her\n℘ Hos 13,2", "℘ Kap. 42,17; 45,16; 5Mo 4,28; Jer 2,26-28"] },
      { number: 12, text: "Der Handwerker in Eisen schärft* das Beil und arbeitet mit Kohlenglut, und er formt es* mit Hämmern und verarbeitet es mit seinem kräftigen Arm. Er wird dabei auch hungrig und kraftlos, er trinkt kein Wasser und ermüdet.", footnotes: ["so mit LXX. Im Mas. T. fehlt ein entsprechendes Verb.", "d. i. das Götterbild"] },
      { number: 13, text: "Der Handwerker in Holz spannt die Schnur, zeichnet es mit dem Stift vor, führt es mit den Schnitzmessern aus und umreißt mit dem Zirkel. Und er macht es wie das Bild eines Mannes*, wie das Prachtstück von einem Menschen, damit es in einem Haus wohnt*.", footnotes: ["℘ 5Mo 4,16; Röm 1,23", "℘ 5Mo 27,15"] },
      { number: 14, text: "Er geht, um sich Zedern zu fällen, oder nimmt eine Steineiche oder eine Eiche und zieht sie sich groß unter den Bäumen des Waldes. Er pflanzt eine Fichte*, und der Regen lässt sie wachsen.", footnotes: ["o. einen Lorbeerbaum"] },
      { number: 15, text: "Und das alles dient dem Menschen zur Feuerung, und er nimmt davon und wärmt sich. Teils heizt er und bäckt Brot, teils verarbeitet er es zu einem Gott und wirft sich davor nieder, macht ein Götzenbild daraus und beugt sich vor ihm." },
      { number: 16, text: "Die Hälfte davon verbrennt er im Feuer. Auf dieser seiner Hälfte brät er Fleisch, isst den Braten* und sättigt sich. Auch wärmt er sich und sagt: Ha! Mir wird es warm, ich spüre Feuer.", footnotes: ["so mit LXX; Mas. T.: isst er Fleisch, brät einen Braten"] },
      { number: 17, text: "Und den Rest davon macht er zu einem Gott*, zu seinem Götterbild. Er beugt sich vor ihm und wirft sich nieder, und er betet zu ihm und sagt: Errette mich, denn du bist mein Gott!*", footnotes: ["℘ Kap. 2,8; Mi 5,12", "℘ Kap. 46,6.7; Jer 2,27; Hab 2,19"] },
      { number: 18, text: "— Sie haben keine Erkenntnis und keine Einsicht*, denn ihre Augen sind verklebt, dass sie nicht sehen, und ihre Herzen, dass sie nicht verstehen*. —", footnotes: ["℘ Kap. 27,11; 45,20; Röm 1,21.22", "℘ Jer 5,21"] },
      { number: 19, text: "Und er nimmt es nicht zu Herzen und hat keine Erkenntnis und keine Einsicht, dass er sagte: Die Hälfte davon habe ich im Feuer verbrannt, auch habe ich auf seinen Kohlen Brot gebacken, ich brate Fleisch und esse; und den Rest davon mache ich zu einem Gräuel, vor einem Holzklotz beuge ich mich!" },
      { number: 20, text: "Wer sich mit Asche einlässt, ist betrogen, sein Herz hat* ihn irregeführt*. Er rettet seine Seele nicht und sagt nicht: Ist nicht Lüge in meiner Rechten?", footnotes: ["T.; Mas. T.: einlässt — sein Herz ist betrogen, es hat", "℘ Hos 4,12"] },
      { number: 21, text: "Denke daran, Jakob und Israel, denn du bist mein Knecht*. Ich habe dich gebildet, du bist mein Knecht. Israel, du wirst nicht von mir vergessen*.", footnotes: ["℘ V. 1.2", "℘ Kap. 40,27"] },
      { number: 22, text: "Ich habe deine Verbrechen ausgelöscht wie einen Nebel und wie eine Wolke deine Sünden*. Kehre um zu mir*, denn ich habe dich erlöst*!", footnotes: ["℘ Kap. 33,24; 43,25; 5Mo 32,43; 2Sam 12,13; Ps 103,12; 130,8; Jer 50,20; Mi 7,18.19; Sach 3,4", "℘ Jer 3,12.14.22; Hos 14,2", "℘ Kap. 43,1; 52,9; 2Mo 18,9"] },
      { number: 23, text: "Juble, du Himmel, denn der HERR hat es getan! Jauchzt, ihr Tiefen der Erde! Brecht in Jubel aus, ihr Berge, du Wald und all ihr Bäume darin*! Denn der HERR hat Jakob erlöst*, und an Israel verherrlicht er sich*.", footnotes: ["℘ Kap. 49,13; 55,12; 1Chr 16,32.33", "℘ Kap. 43,1; 52,9; 2Mo 18,9", "℘ Kap. 49,3"] },
      { number: 24, text: "So spricht der HERR, dein Erlöser und der dich vom Mutterleib an gebildet hat*: Ich, der HERR, bin es, der alles wirkt, der den Himmel ausspannte, ich allein, der die Erde ausbreitete — wer war da bei mir?*", heading: "Ankündigung der Herrschaft des Kyrus zum Heil Israels", footnotes: ["℘ V. 2.6", "so mit Qu., vielen hebr. Handschr., LXX und Vulg.; Mas. T.: von mir her ist es\n℘ Kap. 40,22; 45,7.8; 48,13; Jer 10,12; 51,15; Sach 12,1"] },
      { number: 25, text: "Ich bin es, der die Wunderzeichen der Orakelpriester platzen lässt und die Wahrsager zu Narren macht*, der die Weisen zur Umkehr zwingt und ihr Wissen zur Torheit macht*,", footnotes: ["℘ Kap. 19,3; 4Mo 23,23; Jer 50,36; Sach 10,2", "℘ Kap. 29,14; 47,13; Hi 5,12.13"] },
      { number: 26, text: "der das Wort seines Knechtes aufrichtet und den Plan seiner Boten ausführt*, der von Jerusalem sagt: Es soll bewohnt werden!, und von den Städten Judas: Sie sollen aufgebaut werden, und seine Trümmerstätten werde ich wieder aufrichten*! —", footnotes: ["℘ 2Kö 7,20; Jer 28,9.17; Sach 1,6", "℘ Ps 69,36; 102,17; Jer 30,18"] },
      { number: 27, text: "der zur Meerestiefe spricht: Versiege!, und deine Ströme will ich austrocknen* —,", footnotes: ["℘ Kap. 50,2; 63,12; 1Mo 8,1; Jer 50,38; Sach 10,11"] },
      { number: 28, text: "der von Kyrus* spricht*: Mein Hirte, er wird alles ausführen, was mir gefällt*, indem er von Jerusalem sagen wird: Es werde aufgebaut, und der Grundstein des Tempels werde gelegt*!", footnotes: ["hebr. koräsch", "℘ Kap. 45,1-4; 2Chr 36,22", "w. er wird all meinen Willen zur Vollendung bringen\n℘ Kap. 48,15; Jer 25,9", "℘ Kap. 45,13; Esr 1,1-4"] },
    ]},
    { number: 45, verses: [
      { number: 1, text: "So spricht der HERR zu seinem Gesalbten, zu Kyrus*, den ich bei seiner Rechten ergriffen habe, um Nationen vor ihm zu unterwerfen — und die Hüften der Könige entgürte ich* —, um Türen vor ihm zu öffnen, und Tore bleiben nicht verschlossen:", footnotes: ["℘ Kap. 44,28", "℘ Kap. 41,2.25"] },
      { number: 2, text: "Ich, ich werde vor dir herziehen und werde die Berge einebnen*. Eherne Türen werde ich zerbrechen und eiserne Riegel zerschlagen*.", footnotes: ["So mit Qu. und LXX; Mas. T.: Bevorzugte gleichmachen\n℘ Kap. 40,4", "℘ Kap. 13,2.5; Ps 107,16; Jer 51,30; Dan 8,4; Nah 3,13"] },
      { number: 3, text: "Ich gebe dir verborgene Schätze* und versteckte Vorräte, damit du erkennst, dass ich der HERR bin, der dich bei deinem Namen ruft, der Gott Israels.", footnotes: ["w. Schätze der Dunkelheit"] },
      { number: 4, text: "Wegen meines Knechtes Jakob und Israels, meines Auserwählten*, habe ich dich bei deinem Namen gerufen. Ich gebe dir einen Ehrennamen, ohne dass du mich gekannt hast*.", footnotes: ["℘ Kap. 41,8; Ps 105,6", "℘ Joh 1,30.33; 4,10"] },
      { number: 5, text: "Ich bin der HERR und sonst keiner. Außer mir gibt es keinen Gott*. Ich gürte dich*, ohne dass du mich erkannt hast*,", footnotes: ["℘ V. 14.18.21.22; Kap. 37,20; 43,10; 44,6.8; 46,9; Ps 86,10", "℘ Ps 18,33", "℘ Joh 1,30.33; 4,10"] },
      { number: 6, text: "damit man erkennt vom Aufgang der Sonne und von ihrem Untergang her*, dass es außer mir gar keinen gibt. Ich bin der HERR — und sonst keiner —,", footnotes: ["℘ Kap. 59,19"] },
      { number: 7, text: "der das Licht bildet und die Finsternis schafft*, der Frieden* wirkt und das Unheil schafft*. Ich, der HERR, bin es, der das alles wirkt*.", footnotes: ["℘ 1Mo 1,3; Ps 74,16; Am 4,13", "o. Heil", "℘ Kla 3,38; Am 3,6", "℘ Kap. 44,24; 2Kö 19,25"] },
      { number: 8, text: "Träufle, du Himmel, von oben! Und ihr Wolken, fließt über von Gerechtigkeit*! Das Land öffne seine Ackerfurchen, und sie sollen fruchtbar sein mit Heil*, und es lasse Gerechtigkeit hervorwachsen zugleich*! Ich, der HERR, habe es geschaffen*.", footnotes: ["℘ Ps 72,3.6; 85,12; Hos 10,12", "o. Hilfe; o. Befreiung", "℘ Kap. 46,13; 61,11", "℘ Kap. 44,24; 2Kö 19,25"] },
      { number: 9, text: "Weh dem, der mit seinem Bildner rechtet* — eine Scherbe unter irdenen Scherben! Sagt etwa der Ton zu seinem Bildner: Was machst du?, *und sagt etwa dein Werk von dir: Er hat keine Hände?*", footnotes: ["℘ Hi 9,4; 40,2; Pred 6,10", "Die syr. Üs. liest: Ich bin nicht das Werk deiner Hände.", "Die syr. Üs. liest: Ich bin nicht das Werk deiner Hände.\n℘ Kap. 29,16; 64,7; Hi 9,12; Jer 18,6"] },
      { number: 10, text: "Weh dem, der zum Vater sagt: Warum zeugst du?, und zur Frau: Warum hast du Wehen?" },
      { number: 11, text: "So spricht der HERR, der Heilige Israels und sein Bildner*: Wollt ihr mich etwa wegen meiner Kinder fragen* und über das Werk meiner Hände mir Befehl geben?*", footnotes: ["℘ Kap. 43,1", "℘ Kap. 63,16", "So hat die zweite Vershälfte von V. 11 wohl ursprünglich gelautet. Mas. T.: Fragt mich das Kommende! Über meine Kinder und über das Werk meiner Hände gebt mir Befehl!"] },
      { number: 12, text: "Ich, ich habe die Erde gemacht und den Menschen auf ihr geschaffen. Ich war es, meine Hände haben den Himmel ausgespannt, und all seinem Heer habe ich Befehl gegeben*.", footnotes: ["℘ Kap. 40,26; 42,5; Jer 27,5"] },
      { number: 13, text: "Ich, ich habe ihn* erweckt in Gerechtigkeit*, und alle seine Wege ebne ich*. Er wird meine Stadt bauen* und meine Weggeführten* freilassen*, nicht für einen Kaufpreis und nicht für ein Geschenk*, spricht der HERR der Heerscharen.", footnotes: ["d. i. Kyrus", "℘ Kap. 41,2", "℘ Kap. 48,15", "℘ Kap. 44,28", "LXX: die Weggeführten meines Volkes", "℘ 2Chr 36,22.23", "℘ Kap. 52,3"] },
      { number: 14, text: "So spricht der HERR: Der Erwerb Ägyptens und der Handelsgewinn von Kusch und die Sebäer*, hochgewachsene Männer, werden zu dir übergehen* und dir gehören*. Sie werden dir nachfolgen, in Fesseln werden sie zu dir übergehen. Und sie werden sich vor dir niederwerfen*, werden zu dir flehen*: Ja, bei dir ist Gott*. Es gibt keinen sonst, keinen Gott*! —", footnotes: ["℘ Hi 1,15", "o. an dir vorbeiziehen; d. h. als Gefangene", "℘ Kap. 18,7; 43,3", "℘ Offb 3,9", "℘ Kap. 60,14", "℘ Sach 8,23", "℘ 1Kor 8,6"] },
      { number: 15, text: "Wahrlich, du bist ein Gott, der sich verborgen hält*, Gott Israels, ein Retter*! —", footnotes: ["℘ Hi 23,3.9", "℘ Kap. 43,3"] },
      { number: 16, text: "Sie werden zuschanden und auch zunichte, sie alle miteinander. Sie gehen allesamt in Schmach dahin, die Götzenmacher*.", footnotes: ["w. die Handwerker von Götzengestalten\n℘ Kap. 44,9.11"] },
      { number: 17, text: "Israel findet Rettung in dem HERRN, ewige Rettung*. Ihr werdet nicht zuschanden und nicht zunichte werden in alle Ewigkeiten*.", footnotes: ["w. Rettung für Ewigkeiten\n℘ Kap. 51,6.8; Lk 1,68-71; Hebr 5,9", "℘ Kap. 29,22; Joe 2,26; Zef 3,11"] },
      { number: 18, text: "Denn so spricht der HERR, der den Himmel geschaffen hat — er ist Gott —, der die Erde gebildet und sie gemacht hat — er hat sie gegründet, nicht als eine Öde hat er sie geschaffen, sondern zum Bewohnen hat er sie gebildet* —: Ich bin der HERR, und sonst gibt es keinen Gott*!", footnotes: ["℘ Ps 115,16", "℘ 1Kor 8,6"] },
      { number: 19, text: "Nicht im Verborgenen habe ich geredet, *am Ort eines finsteren Landes*.* Ich sprach zu den Nachkommen Jakobs nicht: Sucht mich vergeblich*! Ich bin der HERR, der Gerechtigkeit redet, Wahrheit* verkündet*.", footnotes: ["o. an einem finsteren Erdenort", "o. an einem finsteren Erdenort", "℘ Kap. 48,16; 5Mo 30,11-14", "Nimmt man an, dass ein Buchstabe ausgefallen ist, ergibt sich: Sucht mich in der Öde! — Vgl. V. 18.\n℘ 2Chr 7,14; Jer 29,13.14", "o. Aufrichtigkeit; o. Geradheit", "℘ Ps 19,9"] },
      { number: 20, text: "Versammelt euch und kommt! Nähert euch allesamt, ihr Entkommenen der Nationen! Keine Erkenntnis* haben die, die das Holz ihres Götterbildes tragen und zu einem Gott flehen, der nicht retten kann*.", footnotes: ["℘ Kap. 44,18; Jer 48,47", "℘ Kap. 44,9.10; 46,7; 57,13; 2Chr 25,15"] },
      { number: 21, text: "Berichtet und bringt Beweise herbei! Ja, sollen sie sich miteinander beraten! Wer hat dies von alters her hören lassen, schon längst es verkündet? Nicht ich, der HERR? Und sonst gibt es keinen Gott außer mir*. Einen gerechten und rettenden Gott gibt es außer mir nicht!", footnotes: ["℘ V. 5.6; Kap. 41,22"] },
      { number: 22, text: "Wendet euch zu mir und lasst euch retten, alle ihr Enden der Erde*! Denn ich bin Gott und keiner sonst*.", footnotes: ["℘ Ps 22,28; 65,6", "℘ V. 5.6; Kap. 41,22"] },
      { number: 23, text: "Ich habe bei mir selbst geschworen*, aus meinem Mund ist Gerechtigkeit hervorgegangen*, ein Wort, das nicht zurückkehrt*: Ja, jedes Knie wird sich vor mir beugen, jede Zunge mir schwören*", footnotes: ["℘ 1Mo 22,16", "℘ Ps 98,2.3", "℘ Kap. 21,17", "℘ Kap. 65,16; Röm 14,11"] },
      { number: 24, text: "und sagen: Nur in dem HERRN ist Gerechtigkeit* und Stärke*. Zu ihm wird man kommen, und es werden alle beschämt werden, die gegen ihn entbrannt waren*.", footnotes: ["so mit LXX und der alten lat. Üs.; Mas. T.: jede Zunge mir schwören: 24 Nur in dem HERRN, hat man von mir gesagt, ist Gerechtigkeit", "℘ Ps 71,16; 89,17; Jer 23,5.6; Sach 10,12", "℘ Kap. 41,11; Lk 13,17"] },
      { number: 25, text: "In dem HERRN werden gerecht sein* und sich rühmen alle Nachkommen Israels*.", footnotes: ["o. zu ihrem Recht kommen", "℘ Apg 13,39; 1Kor 1,31"] },
    ]},
    { number: 46, verses: [
      { number: 1, text: "Bel bricht in die Knie*, Nebo* krümmt sich. Ihre Götzenbilder sind dem Saumtier und dem Lastvieh aufgelegt worden; eure Tragbilder* sind aufgeladen*, eine Last für das erschöpfte Vieh.", heading: "Vernichtung der Götzen — Heil in Gott", footnotes: ["℘ Kap. 21,9; Jer 50,2", "Bel und Nebo waren die Hauptgottheiten von Babel.", "w. die Getragenen. — Das sind Götzenbilder, die in Prozessionen umhergetragen wurden.", "℘ Jer 10,5"] },
      { number: 2, text: "Sie krümmen sich, brechen in die Knie allesamt, sie können die Last nicht retten; und sie selbst ziehen in die Gefangenschaft*.", footnotes: ["℘ 2Sam 5,21"] },
      { number: 3, text: "Hört auf mich, Haus Jakob und der ganze Rest des Hauses Israel*, die ihr von Mutterleib an mir aufgeladen, von Mutterschoß an von mir getragen worden seid*!", footnotes: ["℘ Kap. 10,20.21", "In V. 3 stehen im Hebr. für »aufgeladen« und »getragen« dieselben Wörter wie in V. 1: »Tragbilder«, die den Tieren »aufgeladen« wurden.\n℘ Kap. 63,9; 5Mo 1,31"] },
      { number: 4, text: "Auch bis in euer Greisenalter bin ich derselbe*, und bis zu eurem grauen Haar werde ich selbst euch tragen*. Ich, ich habe es getan, und ich selbst werde heben, und ich selbst werde tragen und werde retten.", footnotes: ["o. bin ich es, der euch trägt\n℘ Mal 3,6", "℘ Ps 71,9.18"] },
      { number: 5, text: "Mit wem wollt ihr mich vergleichen und gleichstellen und mich ähnlich machen, dass wir uns gleichen?*", footnotes: ["℘ Kap. 40,18.25"] },
      { number: 6, text: "Sie, die Gold aus dem Beutel schütten und Silber auf der Waage abwiegen, heuern einen Goldschmied an, dass er einen Gott daraus macht*. Sie beugen sich, ja, sie werfen sich nieder*.", footnotes: ["℘ Ri 17,4", "℘ Kap. 40,19; 44,12-17; 2Mo 32,4.8"] },
      { number: 7, text: "Sie heben ihn auf die Schulter, tragen ihn umher und setzen ihn nieder an seine Stelle, und er steht da: von seinem Platz weicht er nicht*. Auch schreit man zu ihm, aber er antwortet nicht, hilft ihm* nicht aus seiner Not*.", footnotes: ["℘ 1Sam 5,3", "d. i. dem, der zum Götzen schreit", "℘ Kap. 41,29; 45,20; Jer 2,28; 11,12"] },
      { number: 8, text: "Denkt daran und ermannt euch*, nehmt es wieder zu Herzen, ihr Abtrünnigen!", footnotes: ["lat. Üs. liest: schämt euch"] },
      { number: 9, text: "Gedenket des Früheren von der Urzeit her*, dass ich Gott bin. Es gibt keinen sonst*, keinen Gott gleich mir*,", footnotes: ["℘ Ps 78,2; Jer 6,16", "℘ Kap. 43,10; Joe 2,27; Mk 12,32", "℘ 2Mo 15,11"] },
      { number: 10, text: "der ich von Anfang an den Ausgang verkünde und von alters her, was noch nicht geschehen ist*, — der ich spreche: Mein Ratschluss soll zustande kommen, und alles, was mir gefällt, führe ich aus*,", footnotes: ["℘ Kap. 41,21.22.26.27; Hes 39,8", "℘ Kap. 14,24; 48,3; Ps 33,11; Eph 1,11"] },
      { number: 11, text: "der ich den Raubvogel rufe von Osten her, aus fernem Land den Mann meines Ratschlusses*. Ja, ich habe es geredet, ja, ich werde es auch kommen lassen. Ich habe es gebildet, ja, ich führe es auch aus*. —", footnotes: ["℘ Kap. 41,2.25; Jer 50,44", "℘ Kap. 10,12; 14,27; 25,1; Hi 23,13"] },
      { number: 12, text: "Hört auf mich, ihr Trotzigen*, die ihr fern seid von Gerechtigkeit*!", footnotes: ["w. ihr, die ihr starken Herzens seid. — LXX liest: ihr, die ihr das Herz o. den Mut verloren habt\n℘ Kap. 28,14", "℘ Kap. 5,7; 48,1; 59,15; Am 5,7"] },
      { number: 13, text: "Ich habe meine Gerechtigkeit nahe gebracht, sie ist nicht fern*, und mein Heil* zögert nicht*. Und ich gebe in Zion Heil, für Israel meine Herrlichkeit*.", footnotes: ["℘ Kap. 51,5", "o. meine Hilfe, Rettung", "℘ Kap. 45,8; 56,1", "℘ Kap. 60,9; Ps 85,10; Lk 2,32"] },
    ]},
    { number: 47, verses: [
      { number: 1, text: "*Steig herunter und setz dich in den Staub, Jungfrau, Tochter Babel! Setz dich auf die Erde ohne Thron, Tochter der Chaldäer! Denn man wird dich nicht länger die Verwöhnte und Verzärtelte nennen*.", heading: "Triumph und Spott über den Untergang Babels", footnotes: ["℘ Kap. 13; 14; 21,1-10; Jer 50; 51", "℘ 5Mo 28,56"] },
      { number: 2, text: "Nimm die Mühle und mahle Mehl! Schlage deinen Schleier zurück, hebe die Schleppe, entblöße die Schenkel, wate durch Ströme!" },
      { number: 3, text: "Deine Blöße soll aufgedeckt, ja, deine Schande gesehen werden!* Ich werde *Rache nehmen* und Menschen nicht verschonen*. —", footnotes: ["℘ Kap. 3,17; Jer 13,26; Nah 3,5.6", "Andere üs. mit geringfügiger Änderung und in Anlehnung an LXX: Rache nehmen, ohne mich bitten zu lassen, 4 sagt unser Erlöser", "℘ Kap. 35,4", "w. dem Menschen nicht entgegenkommen"] },
      { number: 4, text: "Unser Erlöser*, HERR der Heerscharen ist sein Name, der Heilige Israels!* —", footnotes: ["Andere üs. mit geringfügiger Änderung und in Anlehnung an LXX: Rache nehmen, ohne mich bitten zu lassen, 4 sagt unser Erlöser", "℘ Kap. 43,14.15; 51,15"] },
      { number: 5, text: "Setze dich stumm hin und geh in die Finsternis*, Tochter der Chaldäer! Denn du sollst nicht länger Herrin der Königreiche genannt werden.", footnotes: ["℘ 1Sam 2,9"] },
      { number: 6, text: "Ich war erzürnt über mein Volk, ich entweihte mein Erbteil, und ich gab sie in deine Hand*. Du hast ihnen kein Erbarmen erwiesen, auf den Greis legtest du schwer dein Joch*.", footnotes: ["℘ 2Chr 36,17-20; Sach 1,12.15", "℘ 5Mo 28,50; Esr 5,12; Kla 4,16"] },
      { number: 7, text: "Und du sagtest: Auf ewig werde ich Herrin sein, für immer*! Du nahmst dir dies nicht zu Herzen, das Ende davon bedachtest du nicht*.", footnotes: ["℘ Offb 18,7", "℘ 2Mo 7,23; 5Mo 32,29; Kla 1,9"] },
      { number: 8, text: "Und nun höre dies, du Wollüstige, die in Sicherheit wohnt*, die in ihrem Herzen sagt: Ich, und sonst gar nichts*! Ich werde nicht als Witwe sitzen noch Kinderlosigkeit kennen!", footnotes: ["℘ Hes 16,49", "℘ Dan 4,27; Zef 2,15"] },
      { number: 9, text: "Dies beides wird über dich kommen in einem Augenblick, an einem einzigen Tag: Kinderlosigkeit und Witwenschaft*. In vollem Maße werden sie über dich kommen trotz der Menge deiner Zaubereien, trotz der gewaltigen Fülle deiner Bannsprüche*.", footnotes: ["℘ Offb 18,7.8.23", "℘ Nah 3,4"] },
      { number: 10, text: "Aber du vertrautest auf deine Bosheit*. Du sagtest: Niemand sieht mich*. Deine Weisheit und dein Wissen, das hat dich irregeführt. Und du sagtest in deinem Herzen: Ich, und sonst gar nichts*!", footnotes: ["℘ Pred 8,8", "℘ Kap. 29,15; Ps 94,7; Hes 8,12", "℘ Dan 4,27; Zef 2,15"] },
      { number: 11, text: "So kommt Unheil über dich, gegen das du keinen Zauber kennst. Und ein Verderben wird über dich herfallen, das du nicht abwenden* kannst. Und plötzlich wird ein Sturm* über dich kommen, den du nicht ahnst*. —", footnotes: ["w. zudecken", "o. plötzlicher Untergang", "℘ Dan 5,25-30"] },
      { number: 12, text: "Tritt doch auf mit deinen Bannsprüchen und mit der Menge deiner Zaubereien, mit denen du dich abgemüht* hast von deiner Jugend an! Vielleicht kannst du Hilfe schaffen, vielleicht wirst du Schrecken einflößen*.", footnotes: ["o. um die du dich gemüht", "℘ Kap. 19,3.12; Hes 21,26"] },
      { number: 13, text: "Du bist müde geworden durch die Menge deiner Beratungen. Sie sollen doch auftreten und dich retten, die Himmelszerleger, die Sternebeschauer, die an jedem Neumond wissen lassen, was* über dich kommen soll*!", footnotes: ["T.; Mas. T.: woher es", "℘ Kap. 44,25; Dan 2,2.10.11"] },
      { number: 14, text: "Siehe, sie sind wie Strohstoppeln geworden, Feuer hat sie verbrannt! Vor der Gewalt der Flamme haben sie ihr Leben nicht gerettet* — es gab keine Kohle, um sich zu wärmen, kein Feuer, um davor zu sitzen.", footnotes: ["℘ Nah 1,10"] },
      { number: 15, text: "So sind dir die geworden, für die du dich abgemüht hast, deine Handelspartner* von deiner Jugend an. Sie taumeln, jeder nach seiner Seite hin; niemand rettet dich*.", footnotes: ["w. deine fahrenden Händler. — Manche nehmen an, dass der Text ursprünglich hieß: deine Zauberer", "℘ Offb 18,15"] },
    ]},
    { number: 48, verses: [
      { number: 1, text: "Hört dies, Haus Jakob, die mit dem Namen Israel benannt und aus den Wassern* Judas hervorgegangen sind*, die beim Namen des HERRN schwören und den Gott Israels bekennen, doch nicht in Wahrheit und nicht in Gerechtigkeit*;", heading: "Weitere Mahnung an Israel und erneute Verheißung der Rettung", footnotes: ["Andere nehmen an, dass es ursprünglich hieß: aus dem Leib", "℘ Kap. 51,1.2; Ps 68,27; Mi 2,7", "℘ Kap. 46,12; 3Mo 19,12; 2Kö 5,20; Jer 5,2; Zef 1,5"] },
      { number: 2, text: "ja, nach der heiligen Stadt* nennen sie sich, und sie stützen sich* auf den Gott Israels*, HERR der Heerscharen ist sein Name*:", footnotes: ["℘ Kap. 52,1; Jer 7,4", "o. und nicht in Gerechtigkeit, wenn sie sich auch . . . nennen und sich stützen", "℘ Mi 3,11; Röm 2,17", "℘ Kap. 51,15"] },
      { number: 3, text: "Das Frühere habe ich längst schon verkündet. Aus meinem Mund ist es hervorgegangen, und ich habe es hören lassen; plötzlich tat ich es, und es traf ein*.", footnotes: ["℘ Kap. 46,9.10; Jos 21,45"] },
      { number: 4, text: "Weil ich wusste, dass du hart bist und dass dein Nacken eine eiserne Sehne* und deine Stirn aus Erz ist*,", footnotes: ["℘ Kap. 30,9; 2Mo 33,3", "℘ Jer 5,3; Hes 2,4"] },
      { number: 5, text: "so habe ich es dir schon längst verkündet, ehe es eintraf, habe ich es dich hören lassen, damit du nicht sagst: Mein Götze hat es getan, und mein Götterbild und mein gegossenes Bild haben es befohlen*.", footnotes: ["℘ Kap. 42,8.9; 43,19"] },
      { number: 6, text: "Du hast es gehört, betrachte es nun alles! Und ihr, wollt ihr es nicht verkünden?* Von nun an lasse ich dich Neues hören und Verborgenes, das du nicht kanntest*.", footnotes: ["Andere nehmen als ursprünglichen Text an: Du hast dies alles gehört, hast es gesehen. Willst du es nicht bezeugen?", "℘ Kap. 42,8.9; 43,19"] },
      { number: 7, text: "Jetzt ist es geschaffen und nicht schon früher und vor dem heutigen Tag. Und du hast nicht davon gehört*, damit du nicht sagst: Siehe, ich habe es gewusst.", footnotes: ["Mit anderer Wortabtrennung lesen manche: Und vor seinem Tag hast du nicht davon gehört"] },
      { number: 8, text: "Du hast es weder gehört noch gewusst, noch war dein Ohr früher schon geöffnet*. Denn ich wusste, dass du völlig treulos bist* und dass man dich »Abtrünnig von Mutterleib an« genannt hat*.", footnotes: ["T.; Mas. T.: noch hat dein Ohr dein Herz geöffnet\n℘ Kap. 42,20", "℘ 5Mo 31,16-21.29", "℘ 5Mo 9,24"] },
      { number: 9, text: "Wegen meines Namens halte ich meinen Zorn zurück, und wegen meines Ruhmes bezähme ich mich dir zugute, um dich nicht auszurotten*.", footnotes: ["℘ Ps 78,38; 79,9; 106,8; Hes 36,21"] },
      { number: 10, text: "Siehe, ich habe dich geläutert, doch nicht im Silberschmelzofen; ich habe dich geprüft im Schmelzofen des Elends*.", footnotes: ["℘ Ps 66,10; Sach 13,9; 1Petr 4,12"] },
      { number: 11, text: "Um meinetwillen, um meinetwillen will ich es tun* — denn wie würde mein Name* entweiht werden!* —, und meine Ehre gebe ich keinem andern*.", footnotes: ["℘ Kap. 37,35; 43,25; Ps 25,7.11; Hes 36,22", "w. er", "℘ 5Mo 32,27", "℘ Kap. 42,8; Ps 115,1"] },
      { number: 12, text: "Höre auf mich, Jakob, und Israel, mein Berufener*! Ich bin, der da ist*, ich der Erste, ich auch der Letzte*.", footnotes: ["℘ Kap. 44,1", "o. Ich bin es", "℘ Kap. 41,4"] },
      { number: 13, text: "Ja, meine Hand hat die Grundmauern der Erde gelegt und meine Rechte den Himmel ausgespannt; ich rufe ihnen zu: allesamt stehen sie da*.", footnotes: ["℘ Kap. 40,12.26; 44,24; Röm 4,17"] },
      { number: 14, text: "Versammelt euch, ihr alle, und hört*! *Wer unter ihnen hat dies verkündet*? Der HERR liebt ihn*. Er wird an Babel ausführen, was ihm gefällt, und sein Arm* wird die Chaldäer richten.*", footnotes: ["℘ 1Mo 49,1.2", "Andere üs. in Anlehnung an Qu. und LXX: Wer . . . hat dies verkündet? Mein Liebling vollzieht meinen Willen an Babel und an den Nachkommen der Chaldäer.", "℘ Kap. 41,22", "d. i. Kyrus", "d. i. der Arm des Kyrus", "d. i. der Arm des Kyrus\n℘ Kap. 44,28; 45,13; Jer 50,21.44"] },
      { number: 15, text: "Ich, ich selbst habe geredet, ja, ich habe ihn gerufen. Ich habe ihn kommen lassen, und sein Weg wird gelingen*.", footnotes: ["℘ Kap. 44,28; 45,13; Jer 50,21.44"] },
      { number: 16, text: "Tretet her zu mir, hört dies! Ich habe von Anfang an nicht im Verborgenen geredet*; von der Zeit an, da es geschah, bin ich da. — Und nun hat der Herr, HERR, mich gesandt und seinen Geist verliehen*. —", footnotes: ["℘ Kap. 45,19", "o. und sein Geist hat mich gesandt\n℘ Kap. 61,1"] },
      { number: 17, text: "So spricht der HERR, dein Erlöser, der Heilige Israels*: Ich bin der HERR, dein Gott, der dich lehrt zu deinem Nutzen, der dich leitet auf dem Weg, den du gehen sollst*.", footnotes: ["℘ Kap. 43,14; 49,7", "℘ Kap. 30,21; Jos 3,4; Ps 32,8; 73,24"] },
      { number: 18, text: "Ach, hättest du doch auf meine Gebote geachtet! Dann wäre wie der Strom dein Friede gewesen und deine Gerechtigkeit wie die Wogen des Meeres*.", footnotes: ["℘ Kap. 54,13; 66,12"] },
      { number: 19, text: "Dann wäre wie der Sand deine Nachkommenschaft gewesen und die Sprösslinge deines Leibes wie seine Körner*. Ihr* Name würde nicht ausgerottet und nicht ausgetilgt werden vor meinem Angesicht*.", footnotes: ["℘ 1Mo 22,17", "LXX: Dein", "℘ 5Mo 9,14"] },
      { number: 20, text: "Zieht aus Babel fort! Flieht aus Chaldäa*! Mit jubelnder Stimme verkündet, lasst es hören, breitet es aus bis an die Enden der Erde! Sprecht: Erlöst hat der HERR seinen Knecht Jakob*!", footnotes: ["℘ Kap. 52,11; Esr 2,1; Jer 50,8; Sach 2,10; Offb 18,4", "℘ Kap. 43,1; Jer 31,11; Sach 10,8"] },
      { number: 21, text: "Und sie dürsteten nicht, als er sie durch die Trümmerstätten führte. Wasser aus dem Felsen ließ er ihnen rinnen, er spaltete den Felsen, und Wasser floss heraus*. —", footnotes: ["℘ Kap. 43,19.20; 2Mo 17,6; Neh 9,15.20"] },
      { number: 22, text: "Kein Friede den Gottlosen, spricht der HERR*. —", footnotes: ["℘ Kap. 57,20.21; 66,24; 2Kö 9,18.19"] },
    ]},
    { number: 49, verses: [
      { number: 1, text: "Hört auf mich, ihr Inseln, und horcht auf, ihr Völkerschaften, die ihr von fern her seid*! Der HERR hat mich berufen vom Mutterleib an, hat von meiner Mutter Schoß an meinen Namen genannt*.", heading: "Zweites Lied: Der Knecht Gottes bringt Heil für alle", footnotes: ["℘ Kap. 41,1", "℘ Lk 1,31"] },
      { number: 2, text: "Er hat meinen Mund wie ein scharfes Schwert gemacht*, hält mich versteckt im Schatten seiner Hand*. Und er hat mich zu einem geschärften Pfeil gemacht, hat mich verborgen in seinem Köcher.", footnotes: ["℘ Hebr 4,12; Offb 1,16", "℘ Kap. 51,16"] },
      { number: 3, text: "Und er sprach zu mir: Mein Knecht bist du, Israel*, an dem* ich mich verherrlichen werde*. —", footnotes: ["℘ Kap. 41,8; 42,1", "o. durch den", "℘ Kap. 44,23"] },
      { number: 4, text: "Ich aber sagte: Umsonst habe ich mich abgemüht, vergeblich und für nichts meine Kraft verbraucht*. Doch mein Recht ist bei dem HERRN und mein Lohn bei meinem Gott*. —", footnotes: ["℘ 1Kö 19,10; Mt 23,37; Phil 2,16", "℘ Kap. 53,10-12"] },
      { number: 5, text: "Und nun spricht der HERR, der mich von Mutterleib an für sich zum Knecht gebildet hat*, um Jakob zu ihm zurückzubringen und damit Israel zu ihm* gesammelt werde — und ich bin geehrt in den Augen des HERRN*, und mein Gott ist meine Stärke geworden* —,", footnotes: ["℘ Lk 1,31", "so mit Qu., einigen hebr. Handschr. und zwei alten Üs.; Mas. T.: damit Israel nicht", "℘ Joh 8,50; 2Petr 1,17", "℘ Kap. 12,2"] },
      { number: 6, text: "ja, er spricht: Es ist zu wenig, dass du mein Knecht bist, um die Stämme Jakobs aufzurichten und die Bewahrten Israels zurückzubringen. So mache ich dich auch zum Licht der Nationen, dass mein Heil reiche bis an die Enden der Erde*.", footnotes: ["℘ Kap. 42,6; 56,8; Mi 5,3; Apg 4,12; 13,47; 1Tim 3,16"] },
      { number: 7, text: "So spricht der HERR, der Erlöser Israels, sein Heiliger*, zu dem ganz und gar* Verachteten*, zu dem Verabscheuten der Nation*, zu dem Knecht der Herrscher: Könige werden es sehen und aufstehen, auch Oberste, und sie werden sich niederwerfen* um des HERRN willen, der treu ist, um des Heiligen Israels willen, der dich erwählt hat.", heading: "Gott stellt Zion wieder her", footnotes: ["℘ Kap. 48,17", "w. von jeder Seele", "℘ Ps 22,7", "so mit Qu.; Mas. T.: zu dem, der die Seele verachtet und die Nation verabscheut\n℘ Kap. 53,3; Mt 26,67", "℘ Kap. 52,15; Ps 72,11"] },
      { number: 8, text: "So spricht der HERR: Zur Zeit des Wohlgefallens habe ich dich erhört*, und am Tag des Heils habe ich dir geholfen*. Und ich werde dich behüten und dich zum Bund des Volkes machen*, das Land aufzurichten, die verödeten Erbteile auszuteilen*,", footnotes: ["℘ Kap. 61,2", "℘ 2Kor 6,2", "℘ Kap. 42,6", "℘ Kap. 61,4"] },
      { number: 9, text: "den Gefangenen zu sagen: Geht hinaus*!, und zu denen, die in Finsternis sind: Kommt ans Licht*! Sie werden an den Wegen weiden, und auf allen kahlen Höhen wird ihre Weide sein*.", footnotes: ["℘ Kap. 42,7; Sach 9,11.12; Lk 4,18", "w. Zeigt euch, o. Werdet sichtbar", "℘ Hes 34,13; Joh 10,9"] },
      { number: 10, text: "Sie werden nicht hungern und nicht dürsten*, und weder Wüstenglut* noch Sonne wird sie treffen. Denn ihr Erbarmer wird sie leiten und wird sie zu Wasserquellen führen*.", footnotes: ["℘ Jer 31,9", "w. die Sonnenhitze; nach anderen: die Fata Morgana", "℘ Ps 121,6; Offb 7,16.17"] },
      { number: 11, text: "Alle meine Berge will ich zum Weg machen, und meine Straßen werden hoch dahinführen*.", footnotes: ["℘ Kap. 57,14; 62,10; Lk 3,5"] },
      { number: 12, text: "Siehe, diese kommen von fern her*, und siehe, die von Norden und von Westen* und jene aus dem Land Sewenim*.", footnotes: ["℘ Jer 30,10; Sach 6,15; Kap. 11,11.12; 43,5.6", "℘ Mt 8,11", "so mit Qu.; Sewenim ist eine jüdische Kolonie bei Syene (Assuan) im südlichen Ägypten; Mas. T.: Sinim (ein bisher unbekanntes Land, vielleicht China?)"] },
      { number: 13, text: "Juble, du Himmel, und jauchze, du Erde! Und ihr Berge, brecht in Jubel aus! Denn der HERR hat sein Volk getröstet*, und über seine Elenden erbarmt er sich*.", footnotes: ["℘ Kap. 40,1; 51,3", "℘ Kap. 44,23; Ps 65,13; 89,13; 148,9; Offb 12,12"] },
      { number: 14, text: "Zion sagt: Verlassen hat mich der HERR, der Herr hat mich vergessen*.", footnotes: ["℘ Kap. 40,27; 54,6; Jer 31,3; Kla 5,20-22"] },
      { number: 15, text: "Vergisst etwa eine Frau ihren Säugling, dass sie sich nicht erbarmt über den Sohn ihres Leibes*? Sollten selbst diese vergessen, ich werde dich niemals vergessen*.", footnotes: ["℘ 1Kö 3,26", "℘ Kap. 54,10; 1Sam 12,22; Jer 51,5"] },
      { number: 16, text: "Siehe, in meine beiden Handflächen habe ich dich eingezeichnet. Deine Mauern sind beständig vor mir." },
      { number: 17, text: "Deine Erbauer* eilen herbei*, deine Zerstörer und deine Verwüster ziehen aus dir fort.", footnotes: ["so mit Qu. und Vulg.; Mas. T.: Deine Söhne", "℘ Kap. 60,4.8"] },
      { number: 18, text: "Erhebe ringsum deine Augen und sieh: Sie alle versammeln sich, kommen zu dir*! So wahr ich lebe, spricht der HERR*, ja, du wirst sie alle wie ein Schmuckstück anlegen und dich mit ihnen gürten wie eine Braut.", footnotes: ["℘ Kap. 60,4.8", "w. ist der Ausspruch des HERRN"] },
      { number: 19, text: "Denn deine Trümmerstätten, deine verödeten Orte und dein zerstörtes Land — ja, nun wird es dir* zu eng werden vor Menge an Bewohnern*; und die dich verschlangen, werden fernbleiben.", footnotes: ["w. wirst du", "℘ Kap. 54,3; Sach 2,8; 10,10"] },
      { number: 20, text: "Die Kinder deiner Kinderlosigkeit* werden noch vor deinen Ohren sagen: Der Raum ist mir zu eng. Mach mir Platz, dass ich wohnen kann*!", footnotes: ["d. h. die Kinder, die der Kinderlosen gehören werden", "℘ Kap. 54,1.2"] },
      { number: 21, text: "Da wirst du in deinem Herzen sagen: Wer hat mir diese geboren? Ich war doch der Kinder beraubt und unfruchtbar, in der Verbannung und abtrünnig*! Und diese, wer hat sie großgezogen? Siehe, ich war ja allein übrig geblieben*; diese also, wo waren sie?", footnotes: ["w. abgewichen. — Nach anderen: gefangen gehalten", "℘ Kla 1,1"] },
      { number: 22, text: "So spricht der Herr, HERR: Siehe, ich werde meine Hand zu den Nationen hin erheben und zu den Völkern hin mein Feldzeichen aufrichten. Und sie werden deine Söhne auf den Armen* bringen, und deine Töchter werden auf der Schulter getragen werden*.", footnotes: ["w. im Gewandbausch; d. i. die Falte des Obergewandes, die man auch als Tasche benutzte", "℘ Kap. 14,2; 66,20"] },
      { number: 23, text: "Und Könige werden deine Betreuer sein und ihre Fürstinnen deine Ammen*. Sie werden sich vor dir niederwerfen mit dem Gesicht zur Erde und den Staub deiner Füße lecken*. Da wirst du erkennen, dass ich der HERR bin*; die auf mich hoffen, werden nicht beschämt werden*.", footnotes: ["℘ Kap. 60,11.16", "℘ Kap. 60,14; Ps 72,9; Offb 3,9", "℘ 2Mo 6,7", "℘ Kap. 50,7; Ps 25,3"] },
      { number: 24, text: "Kann man einem Helden die Beute nehmen, oder kann der Gefangene eines Gewaltigen* entkommen?", footnotes: ["so mit Qu., Vulg. und der syr. Üs.; Mas. T.: eines Gerechten"] },
      { number: 25, text: "Ja, so spricht der HERR: Auch der Gefangene des Helden wird ihm genommen, und die Beute des Gewaltigen wird entkommen*. Wer dich angreift, den werde ich angreifen*; und deine Söhne werde ich retten*.", footnotes: ["℘ Kap. 51,14; Mt 12,29", "Das Wort bedeutet einen Angriff mit Vorwürfen in einem Rechtsstreit.\n℘ Kap. 41,11.12; Lk 1,71", "℘ Jer 31,11"] },
      { number: 26, text: "Ich werde deine Unterdrücker speisen mit ihrem eigenen Fleisch, und von ihrem Blut sollen sie trunken werden wie von Most*. Und alles Fleisch wird erkennen, dass ich, der HERR, dein Retter* bin*, und der Mächtige Jakobs, dein Erlöser*.", footnotes: ["℘ Offb 16,6", "o. dein Helfer", "℘ 2Mo 6,7", "℘ Kap. 43,1; 60,16"] },
    ]},
    { number: 50, verses: [
      { number: 1, text: "So spricht der HERR: Wo ist denn der Scheidebrief eurer Mutter, mit dem ich sie entlassen hätte*? Oder wer ist es von meinen Gläubigern, dem ich euch verkauft hätte*? Siehe, eurer Sünden wegen seid ihr verkauft, und wegen eurer Verbrechen ist eure Mutter entlassen*.", footnotes: ["℘ 5Mo 24,1; Hos 2,4", "℘ Mt 18,25", "℘ Kap. 52,3; 59,2; 5Mo 32,30; Jer 4,18; Hos 4,5"] },
      { number: 2, text: "Warum bin ich gekommen, und kein Mensch war da, habe gerufen, und niemand antwortete*? Ist meine Hand etwa zu kurz zur Erlösung? Oder ist in mir keine Kraft, um zu retten*? Siehe, durch mein Drohen trockne ich das Meer aus, mache Ströme zu einer Wüste*; es stinken ihre Fische, weil kein Wasser da ist und sie vor Durst sterben.", footnotes: ["℘ Kap. 64,6; 65,12; 66,4; Spr 1,24", "℘ Kap. 59,1; 4Mo 11,23", "℘ Kap. 42,15; 44,27; Nah 1,4"] },
      { number: 3, text: "Ich kleide den Himmel in Trauerschwärze und lege ihm Sacktuch als Kleidung an*.", footnotes: ["℘ Kap. 8,22; 13,10; Ps 18,12; Offb 6,12"] },
      { number: 4, text: "Der Herr, HERR, hat mir die Zunge eines Jüngers* gegeben, damit ich erkenne, den Müden durch ein Wort aufzurichten*. Er weckt mich, ja Morgen für Morgen weckt er mir das Ohr*, damit ich höre, wie Jünger hören.", heading: "Drittes Lied: Der Knecht Gottes im Leiden, aber Gott schafft ihm Recht", footnotes: ["w. eine Zunge von Jüngern", "Die Bedeutung des hebr. Wortes ist unbekannt. Die Üs. lehnt sich an eine griech. Üs. und die Vulg. an.\n℘ Kap. 40,29; Hi 4,4; Spr 25,11", "℘ 5Mo 18,17.18; Ps 40,7; Joh 8,28"] },
      { number: 5, text: "Der Herr, HERR, hat mir das Ohr geöffnet*, und ich, ich bin nicht widerspenstig gewesen, bin nicht zurückgewichen*.", footnotes: ["℘ 5Mo 18,17.18; Ps 40,7; Joh 8,28", "℘ Hebr 5,8"] },
      { number: 6, text: "Ich bot meinen Rücken den Schlagenden* und meine Wangen den Raufenden*, mein Angesicht verbarg ich nicht vor Schmähungen und Speichel*.", footnotes: ["℘ Joh 19,1", "℘ Kap. 53,7", "℘ Hi 30,10; Kla 3,30; Mt 26,67; 27,26.30"] },
      { number: 7, text: "Aber der Herr, HERR, hilft mir*. Darum bin ich nicht zuschanden geworden*, darum habe ich mein Gesicht hart wie Kieselstein* gemacht. Ich habe erkannt, dass ich nicht beschämt werde*.", footnotes: ["℘ Ps 54,6", "℘ Kap. 49,23; Joh 8,29; Hebr 5,7", "℘ Hes 3,8.9", "℘ 5Mo 18,17.18; Ps 40,7; Joh 8,28"] },
      { number: 8, text: "Nahe ist, der mir Recht schafft*: Wer will mit mir einen Rechtsstreit führen? Lasst uns zusammen hintreten! Wer ist mein Rechtsgegner? Er trete her zu mir*!", footnotes: ["℘ 1Tim 3,16", "℘ Hi 13,19; Joh 8,46; Röm 8,33.34"] },
      { number: 9, text: "Siehe, der Herr, HERR, hilft mir*. Wer ist es, der mich schuldig* erklären will*? Siehe, allesamt werden sie zerfallen wie ein Kleid, die Motte wird sie fressen*.", footnotes: ["℘ Hi 13,19; Joh 8,46; Röm 8,33.34", "o. für gottlos", "℘ Hi 13,19; Joh 8,46; Röm 8,33.34", "℘ Kap. 51,8"] },
      { number: 10, text: "Wer ist unter euch, der den HERRN fürchtet*, der auf die Stimme seines Knechtes hört*? Wer in Finsternis lebt* und wem kein Lichtglanz scheint, vertraue auf den Namen des HERRN und stütze sich auf seinen Gott*!", heading: "Gottes Treue und Heil für Israel bleiben wirksam", footnotes: ["℘ Mal 3,16", "℘ Kap. 42,1", "w. geht", "℘ Kap. 8,17; 26,3; 2Sam 22,29; Mi 7,8; Nah 1,7; Zef 3,12"] },
      { number: 11, text: "Siehe, ihr alle, die ihr ein Feuer anzündet, mit Brandpfeilen euch rüstet*: Lauft hinein in die Glut eures Feuers und in die Brandpfeile, die ihr angesteckt habt*! Von meiner Hand geschieht euch das. In Qualen* sollt ihr daliegen*.", footnotes: ["w. umgürtet", "℘ Jer 17,4", "o. Am Ort der Qual", "℘ Kap. 65,14"] },
    ]},
    { number: 51, verses: [
      { number: 1, text: "Hört auf mich, die ihr der Gerechtigkeit nachjagt*, die ihr den HERRN sucht*! Blickt hin auf den Felsen, aus dem ihr gehauen, und auf den Brunnenschacht, aus dem ihr gegraben seid*!", footnotes: ["℘ Spr 15,9; Mt 5,6", "℘ 2Chr 15,2", "℘ Kap. 48,1"] },
      { number: 2, text: "Blickt hin auf Abraham, euren Vater*, und auf Sara, die euch geboren hat*! Denn ich rief ihn als einen Einzelnen*, und ich segnete ihn und mehrte ihn*.", footnotes: ["℘ Röm 4,1", "℘ Kap. 48,1", "℘ Hes 33,24", "℘ 1Mo 12,1-3; 24,1; 5Mo 26,5"] },
      { number: 3, text: "Denn der HERR tröstet Zion, tröstet alle seine Trümmerstätten*. Und er macht seine Wüste wie Eden und seine Steppe wie den Garten des HERRN*. Jubel und Freude findet man darin, Lobpreis und Stimme des Gesanges*.", footnotes: ["℘ Kap. 49,13; 52,9; Ps 102,14", "℘ Kap. 35,1; 41,19; Hes 36,35", "℘ Jer 31,13; 33,11"] },
      { number: 4, text: "Merkt auf mich, mein Volk, und meine Nation*, hört auf mich! Denn Weisung* geht von mir aus, und mein Recht werde zum Licht der Völker*. Im Nu", footnotes: ["w. meine Völkerschaft", "o. Gesetz", "℘ Kap. 42,4.6; Mi 4,2"] },
      { number: 5, text: "ist nahe meine Gerechtigkeit, mein Heil ist hervorgetreten*, und meine Arme werden die Völker richten*. Auf mich hoffen die Inseln, und auf meinen Arm warten sie*.", footnotes: ["℘ Kap. 46,13", "℘ Kap. 40,10; 60,9; Mt 12,21", "℘ Kap. 48,1"] },
      { number: 6, text: "Erhebt zum Himmel eure Augen und blickt auf die Erde unten! Denn der Himmel wird wie Rauch zerfetzt werden, und die Erde wird zerfallen wie ein Kleid*, und ihre Bewohner werden dahinsterben wie Mücken*. Aber mein Heil wird in Ewigkeit bestehen, und meine Gerechtigkeit wird nicht zerschlagen werden*.", footnotes: ["℘ Mt 5,18; Hebr 1,11; Offb 20,11", "T.; Mas. T.: dahinsterben wie so\n℘ 1Kor 7,31; 2Petr 3,7", "LXX und Vulg. üs.: nicht aufhören\n℘ Kap. 45,17; 54,9.10; Dan 9,24; Hebr 12,27"] },
      { number: 7, text: "Hört auf mich, die ihr Gerechtigkeit kennt, du Volk, in dessen Herzen mein Gesetz ist*: Fürchtet nicht die Schmähung der Menschen und erschreckt nicht vor ihren Hohnreden*!", footnotes: ["℘ 5Mo 6,6; Jer 31,33", "℘ Kap. 37,6; Mt 10,28"] },
      { number: 8, text: "Denn wie ein Kleid wird die Motte sie verzehren und wie Wolle die Schabe sie verzehren*. Aber meine Gerechtigkeit wird in Ewigkeit bestehen und mein Heil von Generation zu Generation.*", footnotes: ["℘ Kap. 50,9", "℘ Kap. 45,17; 54,9.10; Dan 9,24; Hebr 12,27"] },
      { number: 9, text: "Wach auf, wach auf*! Kleide dich in Kraft, du Arm des HERRN*! Wach auf wie in den Tagen der Vorzeit*, wie bei den längst vergangenen Generationen! Bist du es nicht, der Rahab* zerhauen, das Seeungeheuer durchbohrt hat*?", heading: "Rettung und Trost", footnotes: ["℘ Ps 44,24", "℘ Kap. 59,16", "℘ Ps 44,2", "d. h. Stürmer, Dränger; ein sinnbildlicher Name für Ägypten", "℘ Kap. 27,1; Ps 74,13; 89,11"] },
      { number: 10, text: "Bist du es nicht, der das Meer ausgetrocknet hat, das Wasser der großen Flut, der die Tiefen des Meeres zu einem Weg gemacht hat, damit die Erlösten hindurchzogen*?", footnotes: ["℘ Kap. 43,16; 2Mo 14,21.22; Mi 7,15"] },
      { number: 11, text: "Und die Befreiten des HERRN werden zurückkehren und nach Zion kommen mit Jubel, und ewige Freude wird über ihrem Haupt sein. Sie werden Wonne und Freude erlangen, Kummer und Seufzen werden entfliehen*.", footnotes: ["℘ Kap. 35,10; Jer 30,19"] },
      { number: 12, text: "Ich, ich bin es, der euch tröstet*. Wer bist du, dass du dich vor dem Menschen fürchtest*, der hinstirbt, und vor dem Menschenkind, das wie Gras dahingegeben wird*,", footnotes: ["℘ Kap. 40,1; 52,9; 57,18; 61,2; 66,13; 2Kor 1,3.4", "℘ Kap. 8,12; 12,2; 1Sam 17,11", "℘ Kap. 40,6.7; 1Petr 1,24"] },
      { number: 13, text: "und dass du den HERRN vergisst*, der dich macht*, der den Himmel ausspannt und die Grundmauern der Erde legt*, und dass du dich beständig, den ganzen Tag, vor dem Zorn des Bedrängers fürchtest, wenn er zielt*, um dich zu vernichten? Wo ist denn der Zorn des Bedrängers?", footnotes: ["℘ Ps 106,13", "℘ Kap. 17,10; 43,1", "℘ Kap. 40,22; Jer 51,19", "w. wenn er den Pfeil fest auf den Bogen legt"] },
      { number: 14, text: "Der in Fesseln Gekrümmte wird bald losgelassen werden* und wird nicht hinsterben ins Grab*, und sein Brot wird ihm nicht mangeln*.", footnotes: ["℘ Kap. 49,25; 52,2", "℘ Sach 9,11", "℘ Kap. 30,20"] },
      { number: 15, text: "Denn ich bin der HERR, dein Gott*, der das Meer erregt, dass seine Wogen brausen*, HERR der Heerscharen ist sein Name*. —", footnotes: ["℘ 2Mo 6,7", "℘ Hi 26,12", "℘ Kap. 47,4; 48,2; 54,5; Jer 51,5"] },
      { number: 16, text: "Und ich habe meine Worte in deinen Mund gelegt* und dich bedeckt mit dem Schatten meiner Hand*, um den Himmel wie ein Zelt aufzuschlagen* und die Grundmauern der Erde zu legen und zu Zion zu sagen: Mein Volk bist du*!", footnotes: ["℘ Kap. 59,21; 2Mo 4,15", "℘ Kap. 49,2", "w. um die Himmels-Zeltpflöcke einzuschlagen. — Die syr. Üs. liest mit V. 13: um den Himmel auszuspannen", "℘ Hos 2,25"] },
      { number: 17, text: "Raff dich auf, raff dich auf! Erhebe dich, Jerusalem*, die du aus der Hand des HERRN den Becher seines Zornes getrunken! Den Kelch, den Becher des Taumels, hast du getrunken, hast ihn ausgeschlürft*.", heading: "Gott nimmt den Zornbecher von Jerusalem", footnotes: ["℘ Kap. 52,1", "℘ Kap. 40,2; 63,6; Ps 60,5; Offb 14,10"] },
      { number: 18, text: "Da war niemand, der sie leitete, von allen Kindern, die sie geboren, und niemand, der sie bei der Hand nahm, von allen Kindern, die sie großgezogen hatte*.", footnotes: ["℘ Jer 10,20; Hes 34,6"] },
      { number: 19, text: "Dies beides hat dich getroffen — wer bekundet dir Beileid*? Verwüstung und Zusammenbruch, Hungersnot und Schwert* — wie könnte ich dich trösten*?", footnotes: ["w. wer schüttelt deinetwegen den Kopf zum Zeichen der Trauer\n℘ Jer 15,5; Nah 3,7", "℘ Kla 3,47; Hes 14,21", "℘ Kla 1,9.16"] },
      { number: 20, text: "Deine Kinder sind ohnmächtig hingesunken, sie lagen an allen Straßenecken* wie die Antilope im Netz, voll getroffen vom Zorn des HERRN und dem Drohen deines Gottes*.", footnotes: ["℘ Kla 2,11", "℘ Kla 4,11"] },
      { number: 21, text: "Darum höre doch dies, die du elend bist und trunken, aber nicht vom Wein*!", footnotes: ["℘ Kap. 29,9; Kla 3,15"] },
      { number: 22, text: "So spricht der HERR, dein Herr, und dein Gott, der den Rechtsstreit seines Volkes führt*: Siehe, ich nehme aus deiner Hand den Taumelbecher, den Kelch, den Becher meines Zorns*; du wirst ihn nicht mehr länger trinken*.", footnotes: ["℘ Kla 3,58", "℘ Kap. 29,9; Kla 3,15", "℘ Kap. 54,9"] },
      { number: 23, text: "Ich gebe ihn in die Hand deiner Peiniger, die zu deiner Seele sagten: Bück dich, dass wir hinüberschreiten! Und du machtest deinen Rücken der Erde gleich, wie eine Straße für die Hinüberschreitenden*.", footnotes: ["℘ Ps 66,12; 129,3"] },
    ]},
    { number: 52, verses: [
      { number: 1, text: "Wach auf, wach auf*! Kleide dich, Zion, in deine Kraft! Kleide dich in deine Prachtgewänder, Jerusalem, du heilige Stadt*! Denn nicht mehr länger soll dich ein Unbeschnittener und ein Unreiner betreten*.", heading: "Gott verheißt Zion eine neue Rettungstat", footnotes: ["℘ Kap. 51,9.17; 60,1", "℘ Kap. 48,2; Neh 11,1", "℘ Kap. 35,8; 60,21; Offb 21,27"] },
      { number: 2, text: "Schüttle den Staub von dir ab! Steh auf, setz dich hin, Jerusalem*! Mach dich los von den Fesseln deines Halses, du gefangene Tochter Zion*!", footnotes: ["Andere nehmen als ursprünglichen Text an: Steh auf, du gefangenes Jerusalem", "℘ Kap. 51,14"] },
      { number: 3, text: "Denn so spricht der HERR: Umsonst seid ihr verkauft worden*, und nicht für Geld sollt ihr gelöst werden*.", footnotes: ["℘ Kap. 50,1; Ps 44,13", "℘ Kap. 45,13; 1Petr 1,18"] },
      { number: 4, text: "Denn so spricht der Herr, HERR: Nach Ägypten zog mein Volk im Anfang hinab, um sich dort als Fremder aufzuhalten*; und Assur hat es am Ende* bedrückt.", footnotes: ["℘ 1Mo 46,6", "o. um Nichts; d. h. grundlos"] },
      { number: 5, text: "Aber nun, was habe ich hier zu schaffen?, spricht der HERR*. Denn mein Volk ist umsonst weggenommen worden. Seine Beherrscher höhnen*, spricht der HERR*, und ständig, den ganzen Tag, wird mein Name gelästert*.", footnotes: ["w. ist der Ausspruch des HERRN", "so mit Qu.; Mas. T.: heulen", "so mit Qu.; Mas. T.: heulen", "℘ Hes 36,20; Röm 2,24"] },
      { number: 6, text: "Darum wird mein Volk meinen Namen erkennen*, darum an jenem Tag erkennen, dass ich es bin, der da spricht: Hier bin ich!*", footnotes: ["℘ Kap. 60,16; 2Mo 3,13; Jer 31,34", "℘ Kap. 40,9"] },
      { number: 7, text: "Wie lieblich sind auf den Bergen die Füße dessen, der frohe Botschaft bringt*, der Frieden verkündet*, der gute Botschaft bringt, der Heil verkündet, der zu Zion spricht: Dein Gott herrscht als König*!", footnotes: ["℘ Kap. 61,1; Nah 2,1", "℘ Eph 6,15", "℘ Kap. 24,23; Ps 93,1; 96,10; Sach 9,9; Lk 11,2"] },
      { number: 8, text: "Horch! Deine Wächter erheben die Stimme*, sie jubeln allesamt*. Denn Auge in Auge sehen sie, wie der HERR nach Zion zurückkehrt*.", footnotes: ["℘ Kap. 62,6", "℘ Jer 31,7.12", "℘ Kap. 12,6; Jer 33,7"] },
      { number: 9, text: "Brecht in Jubel aus, jubelt allesamt, ihr Trümmerstätten Jerusalems!* Denn der HERR hat sein Volk getröstet, hat Jerusalem erlöst*!", footnotes: ["℘ Ps 102,22", "℘ Kap. 44,23; 51,3.12; Zef 3,14.15; Lk 1,68; 2,38"] },
      { number: 10, text: "Der HERR hat seinen heiligen Arm* entblößt vor den Augen aller Nationen, und alle Enden der Erde sehen die Rettung unseres Gottes*. —", footnotes: ["℘ Kap. 30,30; 53,1; Hi 40,9", "℘ Kap. 33,13; Ps 98,1-3"] },
      { number: 11, text: "Weicht, weicht! Geht von dort hinaus*, rührt nichts Unreines an! Geht hinaus aus ihrer* Mitte*, reinigt euch*, die ihr die Geräte des HERRN tragt*!", footnotes: ["℘ Kap. 48,20; Sach 2,10.11", "Gemeint ist die Stadt Babel.", "℘ 4Mo 16,26; 2Kor 6,17", "o. haltet euch rein", "℘ 3Mo 21,6; 22,2; 1Chr 15,12"] },
      { number: 12, text: "Denn nicht in Hast sollt ihr ausziehen und nicht in Flucht weggehen. Denn der HERR zieht vor euch her, und eure Nachhut ist der Gott Israels*.", footnotes: ["℘ 2Mo 14,19; Jos 4,11"] },
      { number: 13, text: "Siehe, mein Knecht* wird einsichtig handeln*. Er wird erhoben und erhöht werden und sehr hoch sein*.", heading: "Viertes Lied: Der Knecht Gottes — Sein Leiden zur Gerechtigkeit für viele", footnotes: ["℘ Kap. 42,1", "o. erfolgreich sein", "℘ Jer 23,5; Phil 2,9"] },
      { number: 14, text: "Wie sich viele über dich* entsetzt haben — so entstellt war sein Aussehen, mehr als das irgendeines Mannes, und seine Gestalt mehr als die der Menschenkinder* —,", footnotes: ["Die syr. und aram. Üs. lesen: über ihn", "℘ Kap. 53,2"] },
      { number: 15, text: "ebenso wird er viele Nationen besprengen*; über ihn werden Könige ihren Mund schließen*. Denn sie werden sehen, was ihnen nicht erzählt worden war, und was sie nicht gehört hatten, werden sie wahrnehmen*.", footnotes: ["andere mit LXX: ebenso werden viele Nationen über ihn erstaunt sein", "℘ Kap. 49,7", "℘ Röm 15,21"] },
    ]},
    { number: 53, verses: [
      { number: 1, text: "Wer hat unserer Verkündigung* geglaubt*? An wem ist der Arm des HERRN offenbar geworden?* —", footnotes: ["o. der Botschaft an uns", "℘ Röm 10,16", "℘ Kap. 52,10; Joh 12,38"] },
      { number: 2, text: "Er ist wie ein Trieb vor ihm aufgeschossen und wie ein Wurzelspross aus dürrem Erdreich*. Er hatte keine Gestalt und *keine Pracht. Und als wir ihn sahen, da hatte er kein Aussehen*, dass wir Gefallen an ihm gefunden hätten*.", footnotes: ["℘ Kap. 11,1", "Mit Änderung der mas. Zeichensetzung üs. andere: keine Pracht, die wir angesehen hätten, und kein Aussehen", "Mit Änderung der mas. Zeichensetzung üs. andere: keine Pracht, die wir angesehen hätten, und kein Aussehen", "o. kein Aussehen, das uns gefallen hätte\n℘ Kap. 52,14; Mk 6,3"] },
      { number: 3, text: "Er war verachtet und von den Menschen verlassen, ein Mann der Schmerzen und mit Leiden* vertraut*, wie einer, vor dem man das Gesicht verbirgt. Er war verachtet, und wir haben ihn nicht geachtet*.", footnotes: ["w. Krankheit", "o. bekannt\n℘ Ps 88,4", "℘ Kap. 49,7; Phil 2,7"] },
      { number: 4, text: "Jedoch unsere Leiden* — er hat sie getragen, und unsere Schmerzen — er hat sie auf sich geladen*. Wir aber, wir hielten ihn für bestraft*, von Gott geschlagen und niedergebeugt*.", footnotes: ["w. Krankheiten", "℘ Mt 8,17", "w. für einen von göttlichen Plagen Getroffenen", "℘ Ps 69,8"] },
      { number: 5, text: "Doch er war durchbohrt um unserer Vergehen* willen, zerschlagen um unserer Sünden willen*. Die Strafe* lag auf ihm zu unserm Frieden*, und durch seine Striemen ist uns Heilung geworden*.", footnotes: ["w. unserer Treuebrüche Gott gegenüber", "℘ Röm 4,25; 2Kor 5,21; Gal 3,13", "w. Züchtigung", "℘ Röm 5,1", "℘ Joh 19,1; 1Petr 2,24.25"] },
      { number: 6, text: "Wir alle irrten umher wie Schafe*, wir wandten uns jeder auf seinen eigenen Weg*; aber der HERR ließ ihn treffen unser aller Schuld. —", footnotes: ["℘ Jer 50,6", "℘ Ri 21,25"] },
      { number: 7, text: "Er wurde misshandelt*, aber er beugte sich und tat seinen Mund nicht auf* wie das Lamm*, das zur Schlachtung geführt wird und wie ein Schaf, das stumm ist vor seinen Scherern; und er tat seinen Mund nicht auf*. —", footnotes: ["℘ Kap. 50,6", "℘ Mt 26,63; 1Petr 2,23", "℘ Joh 1,29.36", "so mit Qu.; Mas. T.: er wird seinen Mund nicht auftun"] },
      { number: 8, text: "Aus Bedrängnis und Gericht wurde er hinweggenommen*. *Und wer wird über seine Generation* nachsinnen? Denn er wurde abgeschnitten vom Lande der Lebendigen*.* Wegen des Vergehens seines* Volkes hat ihn Strafe* getroffen*.", footnotes: ["o. Von Hass und Gericht wurde er weggerafft", "o. Bei seinem Geschlecht — wer wird bedenken, dass er abgeschnitten wurde . . .?", "o. sein Geschlecht", "℘ Kla 3,54; Apg 8,32.33", "o. sein Geschlecht", "so mit Qu.; Mas. T.: meines", "w. Schlag, o. Plage", "Andere nehmen in Anlehnung an Qu. und LXX als ursprünglichen Text an: Für ihre Sünden wurde er zu Tode getroffen.\n℘ Mt 26,24; Joh 11,50-52"] },
      { number: 9, text: "Und man gab ihm bei Gottlosen sein Grab, aber bei einem Reichen ist er gewesen in seinem Tod*, weil* er kein Unrecht* begangen hat und kein Trug in seinem Mund gewesen ist*.", footnotes: ["℘ Mt 27,57-60; 1Kor 15,3.4", "Qu.: Bei einem Reichen war sein Steingrab, weil. — Andere meinen, der Text habe ursprünglich gelautet: bei Gottlosen sein Grab und bei Übeltätern sein Steingrab, obwohl", "w. keine Gewalttat", "℘ Mk 15,14; Joh 18,38; 19,4.6; 1Petr 2,22; 1Jo 3,5"] },
      { number: 10, text: "*Doch dem HERRN gefiel es, ihn zu zerschlagen. Er hat ihn leiden lassen*. Wenn er sein Leben als Schuldopfer eingesetzt hat*, wird er* Nachkommen sehen*, er wird seine Tage verlängern*. Und was dem HERRN gefällt, wird durch seine Hand gelingen*.", footnotes: ["Andere nehmen als ursprünglichen Text an: Doch der HERR hatte Gefallen an seinem Zerschlagenen. Er ließ den erstarken, der sein Leben als Schuldopfer eingesetzt hatte. Er wird", "w. Er hat ihn krank gemacht\n℘ Sach 13,7; Lk 24,26.46", "so mit Vulg.; Mas. T.: Wenn sein Leben das Schuldopfer eingesetzt hat\n℘ Hebr 9,26", "so mit Vulg.; Mas. T.: Wenn sein Leben das Schuldopfer eingesetzt hat", "℘ Ps 22,31", "℘ Röm 6,9", "o. wird durch ihn wirksam werden"] },
      { number: 11, text: "Um der Mühsal seiner Seele willen wird er Frucht* sehen, er wird sich sättigen*. Durch seine Erkenntnis wird der Gerechte, mein Knecht*, den Vielen zur Gerechtigkeit verhelfen*, und ihre Sünden wird er sich selbst aufladen*.", footnotes: ["Qu. und LXX: Licht. — Im Mas. T. fehlt das Objekt.", "℘ Joh 12,24", "℘ Apg 3,13", "℘ Dan 9,24", "℘ Joh 1,29"] },
      { number: 12, text: "Darum werde ich ihm Anteil geben unter den Großen, und mit Gewaltigen wird er die Beute teilen*: dafür, dass er seine Seele ausgeschüttet hat in den Tod* und sich zu den Verbrechern* zählen ließ*. Er aber hat die Sünde vieler getragen* und für die Verbrecher* Fürbitte getan*.", footnotes: ["℘ Kap. 49,4", "℘ Joh 10,11", "o. den bzw. die von Gott Abgefallenen", "℘ Mt 27,38; Lk 22,37", "℘ Mt 20,28; Hebr 9,28", "o. den bzw. die von Gott Abgefallenen", "Qu.: und hat sich für ihre Verbrechen treffen lassen\n℘ Lk 23,34"] },
    ]},
    { number: 54, verses: [
      { number: 1, text: "Juble, du Unfruchtbare, die nicht geboren, brich in Jubel aus und jauchze, die keine Wehen gehabt hat! Denn die Söhne der Einsamen* sind zahlreicher als die Söhne der Verheirateten*, spricht der HERR.", heading: "Israels Wiederannahme, sein Gebiets- und Bevölkerungszuwachs, seine Herrlichkeit und Sicherheit", footnotes: ["d. h. der von ihrem Mann Verstoßenen; w. der Verödeten", "℘ Kap. 49,20; 1Sam 2,5; Ps 113,9; Gal 4,27"] },
      { number: 2, text: "Mache weit den Raum deines Zeltes, und deine Zeltdecken spanne aus*! Spare nicht! Mache deine Seile lang, und deine Pflöcke stecke fest*!", footnotes: ["so mit LXX; Mas. T.: die Zeltdecken deiner Wohnstätten sollen sie ausspannen", "℘ Kap. 26,15; Mi 7,11"] },
      { number: 3, text: "Denn du wirst dich nach rechts und links ausbreiten, und deine Nachkommen werden Nationen beerben* und verödete Städte besiedeln*.", footnotes: ["℘ Kap. 61,6", "℘ Kap. 49,8.19"] },
      { number: 4, text: "Fürchte dich nicht, denn du wirst nicht zuschanden, und schäme dich nicht, denn du wirst nicht beschämt dastehen*! Sondern du wirst die Schande deiner Jugend vergessen und nicht mehr an die Schmach deiner Witwenschaft denken*.", footnotes: ["℘ Kap. 29,22", "℘ Kap. 4,1; 65,16"] },
      { number: 5, text: "Denn dein Gemahl ist dein Schöpfer*, HERR der Heerscharen ist sein Name*, und dein Erlöser ist der Heilige Israels*: Gott der ganzen Erde wird er genannt*.", footnotes: ["Andere üs. mit Umstellung der Wörter: Denn der dich gemacht hat, ist dein Gemahl\n℘ Hos 2,18", "℘ Kap. 51,15", "℘ Kap. 43,1.3; Hi 19,25", "℘ Jos 3,11; Sach 14,9; Röm 3,29"] },
      { number: 6, text: "Denn wie eine entlassene und tiefgekränkte* Frau hat dich der HERR gerufen* und wie die Frau der Jugend, wenn sie verstoßen ist — spricht dein Gott*.", footnotes: ["w. eine bis zum Lebensodem gekränkte", "℘ Kap. 49,14", "℘ Kap. 62,4; Jer 30,17"] },
      { number: 7, text: "Einen kleinen Augenblick habe ich dich verlassen*, aber mit großem Erbarmen werde ich dich sammeln*.", footnotes: ["℘ Kla 3,31.32", "℘ Kap. 43,5; 5Mo 30,3; Ps 107,3"] },
      { number: 8, text: "Im aufwallenden Zorn habe ich einen Augenblick mein Angesicht vor dir verborgen*, aber mit ewiger Gnade werde ich mich über dich erbarmen*, spricht der HERR, dein Erlöser.", footnotes: ["℘ Kap. 8,17", "℘ Kap. 60,10; Ps 103,4; Hes 39,29"] },
      { number: 9, text: "Wie die Tage* Noahs gilt mir dies, als ich schwor, dass die Wasser Noahs die Erde nicht mehr überfluten sollten*, so habe ich geschworen, dass ich dir nicht mehr zürnen noch dich bedrohen* werde*.", footnotes: ["so mit einigen Handschr. und alten Üs. sowie Qu. — Die meisten Handschr. lesen: Denn wie die Wasser", "℘ 1Mo 8,21", "w. anschreien", "℘ Kap. 51,22; Jer 31,36"] },
      { number: 10, text: "Denn die Berge mögen weichen und die Hügel wanken, aber meine Gnade wird* nicht von dir weichen* und mein Friedensbund nicht wanken*, spricht der HERR, dein Erbarmer*.", footnotes: ["o. Wenn auch die Berge wichen . . ., so wird doch meine Gnade", "℘ Kap. 51,6", "℘ Kap. 61,8; Ps 46,3; Hes 34,25", "℘ Kap. 49,15"] },
      { number: 11, text: "Du Elende, Sturmbewegte, Ungetröstete*! Siehe, ich lege deine Steine in Hartmörtel* und lege deine Grundmauern mit Saphiren.", footnotes: ["℘ Kla 1,16", "w. Stibium. — Damit färbten die orientalischen Frauen ihre Augenlider schwarz, um den Glanz der Augen zu erhöhen. Hier ist an Mörtel gedacht. LXX versteht das Wort als »Karfunkel«."] },
      { number: 12, text: "Ich mache deine Zinnen aus Rubinen und deine Tore aus Karfunkeln und deine ganze Einfassung* aus Edelsteinen*.", footnotes: ["w. Grenze", "℘ Sach 9,16; Offb 21,18-21"] },
      { number: 13, text: "Und alle deine Kinder werden von dem HERRN gelehrt*,* und der Friede deiner Kinder* wird groß sein*.", footnotes: ["Der ursprüngliche Text lässt auch die Lesart zu: all deine Erbauer sind Schüler des HERRN", "℘ Ps 119,33; Jer 31,34; Joh 6,45", "Qu.: deiner Erbauer", "℘ Kap. 48,18"] },
      { number: 14, text: "Durch Gerechtigkeit wirst du fest gegründet sein*. Sei fern von Bedrängnis, denn du brauchst dich nicht zu fürchten, und von Schrecken, denn er wird sich dir nicht nähern*!", footnotes: ["℘ Kap. 32,17; Hos 10,12", "℘ Spr 3,24-26"] },
      { number: 15, text: "Siehe, wenn man auch angreift, so geschieht es nicht von mir aus. Wer dich angreift, wird deinetwegen fallen*.", footnotes: ["℘ Sach 12,9"] },
      { number: 16, text: "Siehe, ich selbst habe den Schmied geschaffen, der das Kohlenfeuer anbläst und die Waffe hervorbringt als sein Werk*; und ich selbst habe den Verderber geschaffen, um zugrunde zu richten*.", footnotes: ["o. für ihr (der Waffe) Werk", "℘ Sach 2,1-5"] },
      { number: 17, text: "Keiner Waffe, die gegen dich geschmiedet wird, soll es gelingen*; und jede Zunge, die vor Gericht gegen dich aufsteht, wirst du schuldig sprechen*. Das ist das Erbteil der Knechte des HERRN und ihre Gerechtigkeit von mir her*, spricht der HERR*.", footnotes: ["℘ Röm 8,31", "℘ Kap. 41,11", "o. mit veränderter Zeichensetzung: und ihre Gerechtigkeit kommt von mir\n℘ Kap. 60,21", "w. ist der Ausspruch des HERRN"] },
    ]},
    { number: 55, verses: [
      { number: 1, text: "Auf, ihr Durstigen, alle, kommt zum Wasser*! Und die ihr kein Geld habt, kommt, kauft und esst! Ja, kommt, kauft ohne Geld und ohne Kaufpreis Wein und Milch*!", heading: "Sabbatheiligung öffnet auch Fremden die Tür zum Volk Gottes", footnotes: ["℘ Kap. 41,17; Joh 7,37; Offb 21,6", "℘ Spr 9,1-5"] },
      { number: 2, text: "Warum wiegt ihr Geld ab für das, was kein Brot ist, und euren Verdienst für das, was nicht sättigt*? Hört doch auf mich, und esst das Gute, und eure Seele labe sich am Fetten*!", footnotes: ["℘ Joh 6,27", "℘ Kap. 1,19"] },
      { number: 3, text: "Neigt euer Ohr und kommt zu mir*! Hört, und eure Seele wird leben*! Und ich will einen ewigen Bund mit euch schließen*, getreu den unverbrüchlichen Gnadenerweisen an David*. —", footnotes: ["℘ Mt 11,28", "℘ 2Mo 15,26", "℘ Kap. 61,8; 2Sam 23,5; Jer 32,40", "℘ 2Sam 7,29; 2Chr 6,42; Apg 13,34"] },
      { number: 4, text: "Siehe, ich habe ihn zu einem Zeugen für Völkerschaften gesetzt*, zum Fürsten und Gebieter von Völkerschaften*.", footnotes: ["℘ Kap. 43,10; Offb 1,5", "℘ Ps 2,6.8"] },
      { number: 5, text: "Siehe, du wirst eine Nation herbeirufen, die du nicht kennst*; und eine Nation, die dich nicht kannte, wird zu dir laufen wegen des HERRN, deines Gottes, und wegen des Heiligen Israels. Denn er hat dich herrlich gemacht*.", footnotes: ["℘ 2Sam 22,44; Sach 8,23", "℘ Kap. 60,9"] },
      { number: 6, text: "Sucht den HERRN, während er sich finden lässt*! Ruft ihn an, während er nahe ist*.", footnotes: ["℘ Ps 32,6; Spr 8,17; Jer 29,13.14; Hos 10,12", "℘ Ps 34,19"] },
      { number: 7, text: "Der Gottlose verlasse seinen Weg und der Mann der Bosheit seine Gedanken*! Und er kehre um zu dem HERRN*, so wird er sich über ihn erbarmen, und zu unserem Gott, denn er ist reich an Vergebung*!", footnotes: ["℘ Kap. 1,16; Kla 3,40", "℘ 2Chr 30,6", "℘ Hes 18,32; Lk 15,20-24"] },
      { number: 8, text: "Denn meine Gedanken sind nicht eure Gedanken*, und eure Wege sind nicht meine Wege, spricht der HERR*.", footnotes: ["℘ 1Sam 16,7", "w. ist der Ausspruch des HERRN"] },
      { number: 9, text: "Denn so viel der Himmel höher ist als die Erde, so sind meine Wege höher als eure Wege und meine Gedanken als eure Gedanken." },
      { number: 10, text: "Denn wie der Regen fällt und vom Himmel der Schnee und nicht dahin zurückkehrt, sondern die Erde tränkt, sie befruchtet und sie sprießen lässt, dass sie dem Sämann Samen gibt und Brot dem Essenden*,", footnotes: ["℘ Ps 104,15; Mk 4,28; 2Kor 9,10"] },
      { number: 11, text: "so wird mein Wort sein, das aus meinem Mund hervorgeht. Es wird nicht leer zu mir zurückkehren, sondern es wird bewirken, was mir gefällt, und ausführen, wozu ich es gesandt habe*.", footnotes: ["℘ 1Sam 3,19; Jer 1,12; 25,13; Sach 1,6; Kol 1,6; Hebr 4,12"] },
      { number: 12, text: "Denn in Freuden werdet ihr ausziehen und in Frieden geleitet werden. Die Berge und die Hügel werden vor euch in Jubel ausbrechen, und alle Bäume des Feldes werden in die Hände klatschen*.", footnotes: ["℘ Kap. 35,1.2; 44,23"] },
      { number: 13, text: "Statt der Dornsträucher werden Wacholderbäume aufschießen*, und statt der Brennnesseln schießen Myrten auf. Und es wird dem HERRN zum Ruhm*, zu einem ewigen Denkzeichen sein, das nicht ausgelöscht wird*.", footnotes: ["℘ Kap. 41,19; 60,17", "w. zum Namen", "℘ Jer 33,9"] },
    ]},
    { number: 56, verses: [
      { number: 1, text: "So spricht der HERR: Wahret das Recht und übt Gerechtigkeit*! Denn mein Heil* ist nahe, dass es kommt, und meine Gerechtigkeit, dass sie offenbart wird*.", heading: "Heil für die Nationen bei Sabbatheiligung", footnotes: ["℘ Ps 106,3; Hos 12,7", "o. meine Hilfe o. Rettung", "℘ Kap. 46,13; Mt 3,2; Röm 1,17"] },
      { number: 2, text: "Glücklich der Mensch, der dies tut*, und das Menschenkind*, das daran festhält; der den Sabbat bewahrt, ihn nicht zu entweihen*, und seine Hand davor bewahrt, irgendetwas Böses zu tun*!", footnotes: ["℘ Lk 11,28", "w. der Sohn des Menschen, der", "℘ Kap. 58,13", "℘ 1Thes 5,22"] },
      { number: 3, text: "Und der Sohn der Fremde, der sich dem HERRN angeschlossen hat*, soll nicht sagen: Der HERR wird mich sicher von seinem Volk ausschließen*. Und der Eunuch* sage nicht: Siehe, ich bin ein dürrer Baum!", footnotes: ["℘ Kap. 14,1; Est 9,27", "℘ 5Mo 23,2-9; Apg 8,27", "℘ Kap. 32,17; Hos 10,12"] },
      { number: 4, text: "Denn so spricht der HERR: Den Eunuchen, die meine Sabbate bewahren und das erwählen, woran ich Gefallen habe, und festhalten an meinem Bund*,", footnotes: ["℘ Ps 25,10"] },
      { number: 5, text: "denen gebe ich in meinem Haus und in meinen Mauern einen Platz* und einen Namen, besser als Söhne und Töchter. Einen ewigen Namen werde ich ihnen* geben, der nicht ausgelöscht werden soll*.", footnotes: ["o. ein Denkmal", "so mit Qu.; Mas. T.: ihm; d. h. vielleicht jedem Einzelnen von ihnen", "℘ Offb 2,17; 3,5"] },
      { number: 6, text: "Und die Söhne der Fremde, die sich dem HERRN angeschlossen haben, um ihm zu dienen und den Namen des HERRN zu lieben, ihm zu Knechten zu sein, jeden, der den Sabbat bewahrt, ihn nicht zu entweihen, und alle, die an meinem Bund festhalten;" },
      { number: 7, text: "die werde ich zu meinem heiligen Berg bringen* und sie erfreuen in meinem Bethaus*. Ihre Brandopfer und ihre Schlachtopfer sollen mir ein Wohlgefallen sein auf meinem Altar*. Denn mein Haus wird ein Bethaus genannt werden für alle Völker*.", footnotes: ["℘ Kap. 57,13; 65,11; Röm 2,26; Hebr 12,22", "℘ 1Kö 8,41-43", "℘ Ps 51,21; Hes 20,40; 47,22", "℘ Mt 21,13"] },
      { number: 8, text: "So spricht der Herr, HERR*, der die Vertriebenen Israels sammelt*: Zu ihm, zu seinen Gesammelten, werde ich noch mehr hinzusammeln*.", footnotes: ["w. ist der Ausspruch des Herrn, HERRN", "℘ Ps 147,2", "℘ Kap. 49,6; Lk 13,29.30; Joh 10,16"] },
      { number: 9, text: "Kommt her, um zu fressen, all ihr Tiere des Feldes, all ihr Tiere im Wald*!", heading: "Gegen die politischen und geistlichen Führer", footnotes: ["℘ Jer 12,9"] },
      { number: 10, text: "Seine Wächter sind blind, sie alle erkennen nichts*. Sie alle sind stumme Hunde, die nicht bellen können. Sie träumen*, liegen da, lieben den Schlummer.", footnotes: ["℘ Mt 15,14", "o. reden irre; d. h. im Schlaf"] },
      { number: 11, text: "Und die Hunde sind gefräßig, kennen keine Sättigung*. Und das sind Hirten! Sie kennen keine Einsicht. Sie alle wenden sich auf ihren eigenen Weg, jeder seinem ungerechten Gewinn zu*, ohne Ausnahme:", footnotes: ["℘ Hes 34,2.3; Phil 3,2", "℘ Ri 18,20; Jer 6,13; Mi 3,11; Tit 1,11; 1Petr 5,2"] },
      { number: 12, text: "»Kommt her, ich will Wein holen, und lasst uns Rauschtrank saufen*! Und der morgige Tag soll wie dieser sein, herrlich über alle Maßen*!«", footnotes: ["℘ Kap. 5,12.22; 28,7; Lk 12,45", "℘ Kap. 22,13; Spr 23,35; Am 4,1"] },
    ]},
    { number: 57, verses: [
      { number: 1, text: "Der Gerechte kommt um, aber es gibt keinen, der es zu Herzen nimmt. Und die treuen Männer* werden hinweggerafft, ohne dass jemand es beachtet. Ja, vor der Bosheit wird der Gerechte hinweggerafft*;", footnotes: ["w. Männer der Treue, o. Männer der Gnade", "℘ 2Kö 22,20"] },
      { number: 2, text: "er geht ein zum Frieden*. Sie ruhen auf ihren Lagerstätten, jeder, der seinen geraden Weg geht*.", footnotes: ["℘ Offb 14,13", "℘ Jer 6,16"] },
      { number: 3, text: "Ihr aber, tretet hierher, Kinder der Zauberin, Brut des Ehebrechers und der Hure*!", footnotes: ["℘ Jer 3,6-9; Hos 2,4.6; Joh 8,41"] },
      { number: 4, text: "Über wen macht ihr euch lustig? Über wen reißt ihr das Maul auf und streckt die Zunge heraus*? Seid ihr nicht Kinder des Verbrechens, eine Brut der Lüge*,", footnotes: ["℘ 2Chr 36,16; Jer 20,8; Mt 21,36", "℘ Kap. 1,4"] },
      { number: 5, text: "die ihr brünstig geworden seid bei den Terebinthen*, unter jedem grünen Baum*, die ihr Kinder in den Tälern schlachtet unterhalb der Felsspalten*?", footnotes: ["LXX: bei den Götzen", "℘ Kap. 1,29; 2Kö 16,3.4; Jer 2,20; Hos 4,13", "℘ Jer 7,31; Hes 16,20.21"] },
      { number: 6, text: "An den glatten Steinen des Bachtales ist dein Teil. Sie, sie sind dein Los. Auch hast du ihnen Trankopfer ausgegossen, hast ihnen Speisopfer aufgetragen. Sollte ich mich dabei beruhigen?*", footnotes: ["o. Sollte ich deshalb Mitleid haben? — Manche nehmen an, dieser Satz habe ursprünglich am Ende von V. 7 gestanden."] },
      { number: 7, text: "Auf einem hohen und erhabenen Berg schlugst du dein Lager auf. Auch stiegst du dort hinauf, um Schlachtopfer zu opfern*.", footnotes: ["w. zu schlachten\n℘ Hes 6,13"] },
      { number: 8, text: "Und hinter die Tür und den Pfosten setztest du deine Zeichen der Erinnerung. Denn von mir abgewendet* hast du dein Lager aufgedeckt, hast es bestiegen und breit gemacht, und du hast dir Hurenlohn von ihnen ausgehandelt*; du liebtest ihr Lager, sahst ihre Blöße*.", footnotes: ["w. von mir hinweg", "so lautete der Text vielleicht ursprünglich; Mas. T.: abgeschnitten", "w. sahst ihre Hand; d. i. ein verhüllender Ausdruck für das Geschlechtsteil"] },
      { number: 9, text: "Du zogest mit Öl zum König* und mehrtest deine wohlriechenden Salben. Du sandtest deine Boten in die Ferne* und tief hinab bis zum Scheol.", footnotes: ["hebr. melech klingt an »Moloch« an\n℘ Dan 11,36", "℘ Hes 16,33; 23,16.41"] },
      { number: 10, text: "Durch deinen weiten Weg bist du müde geworden, doch du sagtest nicht: Es ist umsonst! Du fandest Belebung deiner Kraft, darum bist du nicht schwach geworden." },
      { number: 11, text: "Und wen hast du gescheut und gefürchtet, dass du gelogen hast und nicht an mich dachtest, es nicht zu Herzen nahmst? Habe ich nicht geschwiegen und meine Augen verhüllt*? Doch mich fürchtest du nicht*.", footnotes: ["So lesen LXX und Vulg.; Mas. T.: und zwar von Ewigkeit her", "℘ Ps 50,21"] },
      { number: 12, text: "Ich, ich werde deine Gerechtigkeit verkünden; und deine Machwerke, sie werden dir nichts nützen*.", footnotes: ["℘ Kap. 44,9; Jer 10,14.15; 51,18"] },
      { number: 13, text: "Wenn du um Hilfe schreist, sollen dich deine Götzenhaufen retten*! Aber ein Wind wird sie allesamt entführen, ein Hauch sie hinwegnehmen. Wer aber bei mir seine Zuflucht sucht, wird das Land erben* und meinen heiligen Berg in Besitz nehmen*.", footnotes: ["℘ Kap. 45,20.21; Jer 2,28", "℘ Ps 37,9", "℘ Kap. 56,7"] },
      { number: 14, text: "Und er sagt: Macht Bahn, macht Bahn*! Bahnt* einen Weg! Beseitigt jedes Hindernis aus dem Weg meines Volkes*!", heading: "Friede den Bußfertigen, kein Friede den Unbußfertigen", footnotes: ["w. Schüttet auf, schüttet auf; d. h. eine Straße", "w. Räumt auf; d. h. durch Beseitigung der Hindernisse", "℘ Kap. 49,11; Mt 3,3"] },
      { number: 15, text: "Denn so spricht der Hohe und Erhabene, der in Ewigkeit wohnt und dessen Name der Heilige ist*: In der Höhe* und im Heiligen* wohne ich und bei dem, der zerschlagenen und gebeugten Geistes ist*, um zu beleben den Geist der Gebeugten und zu beleben das Herz der Zerschlagenen*.", footnotes: ["℘ Lk 1,49", "℘ Kap. 18,4; 63,15; Ps 113,5", "w. und heilig\n℘ 2Mo 15,13; 40,34; Kla 3,41; Eph 2,21.22", "℘ Kap. 66,2; Ps 34,19; 51,19; Mt 5,3", "℘ Kap. 61,1; Hi 22,29; Mt 12,20"] },
      { number: 16, text: "Denn nicht ewig rechte ich, und nicht für immer zürne ich*; denn ihr Lebenshauch würde vor mir* verschmachten und die Menschenseelen*, die ich ja gemacht habe*.", footnotes: ["℘ Kap. 27,8; 64,8; 2Sam 24,16; Ps 103,9", "T.; Mas. T.: der Lebenshauch würde von mir weg", "w. Lebensodem. — Das hebr. Wort steht in der Mehrzahl.", "℘ Kap. 42,5; Hi 12,10; Hes 18,4; Sach 12,1"] },
      { number: 17, text: "Wegen der Sünde seiner Habsucht* zürnte ich und schlug es*, indem ich mich verbarg* und erzürnt war; doch es ging abtrünnig auf dem Weg seines Herzens*.", footnotes: ["w. Wegen der Schuld, nämlich wegen seines ungerechten Gewinns", "℘ Jer 6,13", "℘ Kap. 8,17", "℘ Jer 8,6"] },
      { number: 18, text: "Seine Wege habe ich gesehen und werde es heilen*. Und ich werde es leiten* und ihm Tröstungen gewähren und seinen Trauernden*", footnotes: ["℘ Jer 30,17; 33,6; Hos 14,5", "℘ Kap. 58,11", "℘ Kap. 30,18; 51,12; 61,2"] },
      { number: 19, text: "die Frucht der Lippen schaffen. Friede, Friede den Fernen und den Nahen*!, spricht der HERR. Ich will es heilen*. —", footnotes: ["℘ Apg 2,39; Eph 2,17", "℘ Jer 30,17; 33,6; Hos 14,5"] },
      { number: 20, text: "Aber die Gottlosen sind wie das aufgewühlte Meer. Denn es kann nicht ruhig sein, und sein Wasser wühlt Kot und Schlamm auf*.", footnotes: ["℘ Jer 49,23; Jud 13"] },
      { number: 21, text: "Kein Friede den Gottlosen!, spricht mein Gott*. —", footnotes: ["℘ Kap. 48,22"] },
    ]},
    { number: 58, verses: [
      { number: 1, text: "Rufe aus voller Kehle, halte nicht zurück! Erhebe deine Stimme wie ein Horn und verkünde meinem Volk sein* Vergehen und dem Haus Jakob seine* Sünden*!", heading: "Falsche und echte Frömmigkeit", footnotes: ["w. ihr bzw. ihre", "w. ihr bzw. ihre", "℘ Hes 16,2; Mi 3,8"] },
      { number: 2, text: "Zwar befragen sie mich Tag für Tag, und es gefällt ihnen, meine Wege zu kennen. Wie eine Nation, die Gerechtigkeit übt und das Recht ihres Gottes nicht verlassen hat, fordern sie von mir gerechte Entscheidungen*, haben Gefallen daran, Gott zu nahen*. —", footnotes: ["w. Rechtsbestimmungen der Gerechtigkeit", "℘ Hes 20,3; Am 5,18"] },
      { number: 3, text: "»Warum fasten wir, und du siehst es nicht, demütigen wir uns*, und du merkst es nicht*?« — Siehe, am Tag eures Fastens geht ihr euren Geschäften nach* und drängt alle eure Arbeiter*.", footnotes: ["w. erniedrigen unsere Seelen durch Fasten", "℘ 3Mo 16,31; Mal 3,14", "℘ Sach 7,5", "Manche vermuten, dass der Text ursprünglich lautete: eure Schuldner"] },
      { number: 4, text: "Siehe, zu Streit und Zank fastet ihr, und um mit gottloser Faust* zu schlagen*. Zur Zeit fastet ihr nicht so, dass ihr eure Stimme in der Höhe zu Gehör brächtet.", footnotes: ["o. Hacke", "℘ 1Kö 21,9.13"] },
      { number: 5, text: "Ist ein Fasten, an dem ich Gefallen habe, etwa wie dies: Ein Tag, an dem der Mensch sich demütigt*? Seinen Kopf zu beugen wie eine Binse und sich in Sacktuch und Asche zu betten? Nennst du das ein Fasten und einen dem HERRN wohlgefälligen Tag*?", footnotes: ["w. seine Seele erniedrigt; d. h. durch Fasten", "℘ Mt 6,16-18"] },
      { number: 6, text: "Ist nicht vielmehr das ein Fasten, an dem ich Gefallen habe: Ungerechte Fesseln* zu lösen*, die Knoten des Joches zu öffnen, gewalttätig Behandelte als Freie zu entlassen und dass ihr jedes Joch zerbrecht?*", footnotes: ["w. Fesseln der Gottlosigkeit", "℘ Jon 3,8", "℘ 2Chr 28,11; Neh 5,11"] },
      { number: 7, text: "Besteht es nicht darin, dein Brot dem Hungrigen zu brechen und dass du heimatlose Elende ins Haus führst? Wenn du einen Nackten* siehst, dass du ihn bedeckst und dass du dich deinem Nächsten* nicht entziehst?*", footnotes: ["o. einen notdürftig Bekleideten", "w. deinem Fleisch", "℘ Hi 31,19.20; Hes 18,7.8; Mt 25,35"] },
      { number: 8, text: "Dann wird dein Licht hervorbrechen wie die Morgenröte*, und deine Heilung wird schnell sprossen*. Deine Gerechtigkeit wird vor dir herziehen, die Herrlichkeit des HERRN wird deine Nachhut sein*.", footnotes: ["℘ Hi 11,17; Ps 37,6; 112,4; Spr 11,25", "℘ Spr 11,17", "T.; Mas. T.: wird dich einsammeln\n℘ Kap. 60,2"] },
      { number: 9, text: "Dann wirst du rufen, und der HERR wird antworten. Du wirst um Hilfe schreien, und er wird sagen: Hier bin ich*! Wenn du aus deiner Mitte fortschaffst das Joch, das Fingerausstrecken* und böses Reden", footnotes: ["℘ Kap. 30,19; 65,24; Hi 22,27; Ps 145,18", "d. i. eine Geste des Schmähens\n℘ Spr 6,13"] },
      { number: 10, text: "und wenn du dem Hungrigen dein Brot* darreichst und die gebeugte Seele sättigst*, dann wird dein Licht aufgehen in der Finsternis, und dein Dunkel wird sein wie der Mittag*.", footnotes: ["so mit LXX; Mas. T.: deine Seele", "℘ Hi 31,31; Ps 41,1", "℘ Hi 11,17; Ps 37,6; 112,4; Spr 11,25"] },
      { number: 11, text: "Und beständig wird der HERR dich leiten*, und er wird deine Seele sättigen an Orten der Dürre* und deine Gebeine stärken. Dann wirst du sein wie ein bewässerter Garten* und wie ein Wasserquell, dessen Wasser nicht versiegt*.", footnotes: ["℘ Kap. 57,18; Ps 48,15", "℘ 5Mo 15,4", "℘ Jer 31,12", "℘ Kap. 44,4; Ps 84,7; Jer 17,8; Joh 7,38"] },
      { number: 12, text: "Und die von dir kommen, werden die uralten Trümmerstätten aufbauen*; die Grundmauern vergangener Generationen wirst du aufrichten*. Und du wirst genannt werden: Vermaurer von Breschen, Wiederhersteller von Straßen zum Wohnen.", footnotes: ["o. einige von dir werden . . . aufbauen. — Mit Änderung eines Buchstabens ergibt sich: von dir werden . . . aufgebaut werden", "℘ Kap. 61,4; Mi 7,11"] },
      { number: 13, text: "Wenn du deinen Fuß vom Sabbat zurückhältst, deine Geschäfte an meinem heiligen Tag zu treiben*, und nennst den Sabbat eine Wonne und den heiligen Tag des HERRN ehrwürdig, und wenn du ihn ehrst, so dass du nicht deine Gänge machst, deinem Geschäft nachgehst und eitle Worte redest*,", footnotes: ["℘ Kap. 56,2.4; 2Mo 20,8-11; Jer 17,21-26; Hes 44,24", "o. Verhandlungen führst"] },
      { number: 14, text: "dann wirst du deine Lust am HERRN haben*. Und ich werde dich einherfahren lassen auf den Höhen der Erde* und werde dich speisen mit dem Erbteil Jakobs, deines Vaters*. Ja, der Mund des HERRN hat geredet*.", footnotes: ["℘ Hi 22,26", "℘ 5Mo 32,13; Hab 3,19", "℘ Kap. 1,19.20", "℘ Hi 11,17; Ps 37,6; 112,4; Spr 11,25"] },
    ]},
    { number: 59, verses: [
      { number: 1, text: "Siehe, die Hand des HERRN ist nicht zu kurz, um zu retten*, und sein Ohr nicht zu schwer, um zu hören*;", heading: "Israels Scheitern und Gottes neuer Anfang", footnotes: ["℘ Kap. 50,1.2; 1Sam 4,3; Lk 8,50", "℘ Ps 94,9"] },
      { number: 2, text: "sondern eure Vergehen sind es, die eine Scheidung gemacht haben zwischen euch und eurem Gott*, und eure Sünden haben sein Angesicht* vor euch verhüllt, dass er nicht hört*.", footnotes: ["℘ Kap. 50,1.2; 1Sam 4,3; Lk 8,50", "so mit LXX, der syr. und aram. Üs.; Mas. T.: das Angesicht", "℘ Spr 15,29; Hes 39,23"] },
      { number: 3, text: "Denn eure Hände sind mit Blut befleckt und eure Finger mit Sündenschuld*. Eure Lippen reden Lüge, eure Zunge murmelt Verkehrtheit*.", footnotes: ["℘ Kap. 1,15; Hes 9,9; Mi 3,4; Spr 6,17", "℘ Jer 9,2-5; Mi 6,12"] },
      { number: 4, text: "Niemand lädt vor* in Gerechtigkeit, und niemand tritt vor Gericht in Wahrhaftigkeit*. Sondern bei euch gilt dies: Auf Leeres vertrauen*, Gehaltloses reden, mit Mühsal schwanger gehn, Unrecht zeugen*!", footnotes: ["w. ruft das Gericht an", "o. Wahrheit; o. Treue", "℘ Jer 7,4.8", "℘ Kap. 33,11; Hi 15,35; Ps 12,3"] },
      { number: 5, text: "Viperneier brüten sie aus, und Gewebe von Spinnen weben sie! Wer von ihren Eiern isst, muss sterben, und zerdrückt man eins, fährt eine Giftschlange heraus*.", footnotes: ["w. wird es herausgepresst, wird eine Giftschlange ausgebrütet\n℘ Mt 3,7"] },
      { number: 6, text: "Ihr Gewebe taugt nicht zur Bekleidung, und mit ihrem Gewirke kann man sich nicht bedecken. Ihre Werke sind Werke des Unrechts, und Gewalttat ist in ihren Händen*.", footnotes: ["℘ Ps 55,11; Jer 6,7; Hes 9,9"] },
      { number: 7, text: "Ihre Füße laufen zum Bösen und eilen, unschuldiges Blut zu vergießen*. Ihre Gedanken sind Gedanken des Unrechts, Verwüstung und Zerbruch ist auf ihren Straßen.", footnotes: ["℘ Spr 1,16"] },
      { number: 8, text: "Den Weg des Friedens kennen sie nicht, und kein Recht ist in ihren Spuren. Ihre Pfade machen sie sich krumm*; jeder, der sie betritt, kennt keinen Frieden*.", footnotes: ["℘ Spr 2,13.15; 21,8", "℘ Kap. 65,2; Lk 19,42; Röm 3,15-17"] },
      { number: 9, text: "Darum ist das Recht fern von uns, und Gerechtigkeit erreicht uns nicht. Wir hoffen auf Licht, und siehe, da ist Finsternis, auf Lichtglanz, aber in dichtem Dunkel gehen wir umher*.", footnotes: ["℘ Hi 19,8; 30,26"] },
      { number: 10, text: "Wir tappen herum wie Blinde an der Wand und wie die, die keine Augen haben*, tappen wir herum. Wir stürzen am Mittag wie in der Dämmerung*. Wir sind unter Gesunden den Toten gleich*.", footnotes: ["℘ 5Mo 28,29", "℘ Spr 4,19; Jer 13,16", "℘ Kla 3,6"] },
      { number: 11, text: "Wir brummen alle wie die Bären, und wie die Tauben gurren wir*. Wir hoffen auf Recht, aber da ist keins, auf Rettung, doch sie ist fern von uns.", footnotes: ["℘ Kap. 38,14"] },
      { number: 12, text: "Denn zahlreich sind unsere Vergehen* vor dir, und unsere Sünden zeugen gegen uns. Denn unserer Vergehen sind wir uns bewusst, und unsere Sünden, die kennen wir*:", footnotes: ["o. Treuebrüche", "℘ Kap. 64,4; Jer 14,7; Hes 7,16"] },
      { number: 13, text: "brechen mit dem HERRN und ihn verleugnen und zurückweichen von unserem Gott*, reden von Unterdrückung und Abfall*, mit Lügenworten schwanger werden und sie aus dem Herzen sprechen.", footnotes: ["w. von der Nachfolge hinter unserem Gott her\n℘ Kap. 32,6; Jer 2,17.19", "o. Ungehorsam"] },
      { number: 14, text: "So ist das Recht zurückgedrängt, und die Gerechtigkeit steht ferne. Denn die Wahrheit* ist gestürzt auf dem Marktplatz, und die Geradheit findet keinen Eingang*.", footnotes: ["o. Treue; o. Zuverlässigkeit", "℘ 1Kö 21,11; Ps 119,150; Pred 3,16; Hos 7,1"] },
      { number: 15, text: "So geschieht es, dass die Wahrheit* fehlt, und wer sich vom Bösen fernhält, wird beraubt. Und der HERR sah es, und es war böse in seinen Augen*, dass es kein Recht gab*.", footnotes: ["o. Treue; o. Zuverlässigkeit", "℘ Kap. 65,12; 66,4", "℘ Kap. 46,12"] },
      { number: 16, text: "Er sah, dass kein Mann da war, und er wunderte sich, dass es keinen gab, der Fürbitte tat*. Da half ihm sein Arm*, und seine Gerechtigkeit, sie unterstützte ihn.", footnotes: ["℘ Hes 22,30", "℘ Kap. 51,9; 53,1; 62,8; 63,5; Lk 1,51"] },
      { number: 17, text: "Er zog Gerechtigkeit an wie einen Panzer und setzte den Helm des Heils auf sein Haupt*, und er zog Rachegewänder an als Kleidung* und hüllte sich in Eifer wie in einen Mantel*.", footnotes: ["℘ Eph 6,14.17; 1Thes 5,8", "℘ Ps 94,1", "℘ Kap. 42,13; Sach 1,14"] },
      { number: 18, text: "Gemäß den Taten, wie es angemessen ist, wird er vergelten*: Zorn seinen Gegnern, Vergeltung seinen Feinden*; den Inseln wird er ihr Tun vergelten*.", footnotes: ["℘ Jer 32,19; Joe 4,4.7; Offb 2,23", "℘ Kap. 66,14; 5Mo 32,41; Jer 50,15; 2Thes 1,6", "o. Vergeltung erfüllen"] },
      { number: 19, text: "Dann werden sie den Namen des HERRN fürchten* vom Sonnenuntergang an und vom Sonnenaufgang seine Herrlichkeit*. Denn er wird kommen wie ein drängender* Strom*, den der Hauch des HERRN vorwärtstreibt.", footnotes: ["℘ Ps 102,16", "℘ Kap. 45,6; Mal 1,11", "w. eingeengter", "℘ Kap. 8,7; Offb 12,15"] },
      { number: 20, text: "Und ein Erlöser wird kommen für Zion* und für die, die in Jakob vom Treubruch umkehren*, spricht der HERR*.", footnotes: ["℘ Kap. 62,11; Hi 19,25", "℘ Kap. 10,21", "w. ist der Ausspruch des HERRN"] },
      { number: 21, text: "Ich aber — dies ist mein Bund mit ihnen*, spricht der HERR: Mein Geist, der auf dir ruht, und meine Worte, die ich in deinen Mund gelegt habe*, werden nicht aus deinem Mund weichen noch aus dem Mund deiner Nachkommen, noch aus dem Mund der Nachkommen deiner Nachkommen, spricht der HERR, von nun an bis in Ewigkeit*.", footnotes: ["℘ Jer 31,33; Röm 11,26.27", "℘ Kap. 51,16; Ps 119,43; Jer 1,9", "℘ Kap. 44,3; 66,22; Spr 7,3; Hes 39,29"] },
    ]},
    { number: 60, verses: [
      { number: 1, text: "Steh auf*, werde licht! Denn dein Licht ist gekommen*, und die Herrlichkeit des HERRN ist über dir aufgegangen*.", heading: "Die zukünftige Herrlichkeit Zions", footnotes: ["℘ Kap. 52,1.2", "℘ Mt 4,16; Offb 22,5", "℘ Hes 43,4.5; Lk 2,32; 1Petr 1,11"] },
      { number: 2, text: "Denn siehe, Finsternis bedeckt die Erde und Dunkel die Völkerschaften*; aber über dir strahlt der HERR auf, und seine Herrlichkeit erscheint über dir*.", footnotes: ["℘ Kap. 8,22", "℘ Kap. 58,8; 62,1.2; Mal 3,20; Lk 1,78"] },
      { number: 3, text: "Und es ziehen Nationen zu deinem Licht hin und Könige zum Lichtglanz deines Aufgangs*.", footnotes: ["℘ Kap. 2,2.3; Ps 102,16; Offb 21,24"] },
      { number: 4, text: "Erhebe ringsum deine Augen und sieh! Sie alle versammeln sich, kommen zu dir*: Deine Söhne kommen von fern her, und deine Töchter werden auf den Armen* herbeigetragen*. —", footnotes: ["℘ Kap. 49,18", "w. auf der Seite o. Hüfte", "℘ Kap. 14,2; 66,12.20"] },
      { number: 5, text: "Dann wirst du es sehen und vor Freude strahlen, und dein Herz wird beben* und weit werden; denn die Fülle des Meeres wird sich zu dir wenden, der Reichtum der Nationen zu dir kommen*.", footnotes: ["℘ Jer 33,9; Hos 3,5", "℘ Kap. 61,6; 5Mo 33,19"] },
      { number: 6, text: "Eine Menge Kamele wird dich bedecken, junge Kamele von Midian und Efa*. Sie alle werden aus Saba kommen*. Gold und Weihrauch tragen sie*, und sie werden das Lob* des HERRN fröhlich verkündigen*.", footnotes: ["℘ 1Mo 25,4", "℘ Ps 72,10", "℘ Jer 6,20; Mt 2,11", "o. die Ruhmestaten", "℘ 5Mo 32,43; Ps 67,4-6"] },
      { number: 7, text: "Alle Schafherden von Kedar werden sich zu dir versammeln, die Widder Nebajots* werden dir zu Diensten stehen: Mir zum Wohlgefallen werden sie auf meinen Altar kommen. Und das Haus meiner Herrlichkeit werde ich herrlich machen*. —", footnotes: ["℘ Kap. 21,16; 42,11; Hes 27,21", "℘ Mi 4,1; Hag 2,7.9"] },
      { number: 8, text: "Wer sind diese, die wie eine Wolke geflogen kommen und wie Tauben zu ihren Schlägen?" },
      { number: 9, text: "Denn auf mich hoffen die Inseln*, und die Schiffe von Tarsis ziehen voran*, um deine Kinder aus der Ferne zu bringen*, ihr Silber und ihr Gold mit ihnen*, zum Namen* des HERRN, deines Gottes, und zu dem Heiligen Israels, weil er dich herrlich gemacht hat*. —", footnotes: ["Andere nehmen an, dass der Text ursprünglich gelautet hat: Zu dir versammeln sich die Boote\n℘ Kap. 42,4; 51,5; Ps 97,1", "℘ Kap. 2,16", "℘ Ps 72,10", "℘ Ps 72,10", "d. h. zum Ruhm", "℘ Kap. 46,13; 55,5"] },
      { number: 10, text: "Und die Söhne der Fremde werden deine Mauern bauen* und ihre Könige dich bedienen; denn in meinem Zorn habe ich dich geschlagen, aber in meiner Huld habe ich mich über dich erbarmt*.", footnotes: ["℘ Kap. 61,5; Sach 6,15", "℘ Kap. 12,1; 54,7.8"] },
      { number: 11, text: "Und deine Tore werden beständig offenstehen*. Tag und Nacht werden sie nicht geschlossen*, um zu dir zu bringen den Reichtum der Nationen und ihre gefangen weggeführten Könige.", footnotes: ["so mit den alten Üs.; Mas. T.: deine Tore öffnen beständig ihre Flügel", "℘ Offb 21,24-26"] },
      { number: 12, text: "Denn die Nation und das Königreich, die dir nicht dienen wollen, werden zugrunde gehen. Diese Nationen werden verheert werden, ja, verheert*.", footnotes: ["℘ Kap. 41,11; Sach 14,17.18"] },
      { number: 13, text: "Die Herrlichkeit des Libanon* wird zu dir kommen, Wacholder, Platane und Zypresse miteinander, um die Stätte meines Heiligtums zu schmücken*. Und ich werde die Stätte meiner Füße herrlich machen*.", footnotes: ["℘ Kap. 35,2", "℘ 1Kö 5,22-24", "℘ Kap. 66,1"] },
      { number: 14, text: "Und gebeugt werden zu dir kommen die Söhne deiner Unterdrücker, und alle, die dich geschmäht haben, werden sich niederwerfen zu deinen Fußsohlen*. Und sie werden dich nennen: Stadt des HERRN, Zion des Heiligen Israels*.", footnotes: ["℘ Kap. 14,2; 45,14; 49,23; Spr 14,19", "℘ Ps 48,2.3"] },
      { number: 15, text: "Anstatt dass du eine Entlassene bist und eine Verhasste und niemand hindurchzieht, will ich dich zum ewigen Stolz machen, zur Freude von Generation zu Generation*.", footnotes: ["℘ Kap. 25,8; 61,7"] },
      { number: 16, text: "Du wirst saugen die Milch der Nationen und saugen an der Brust der Könige*. Und du wirst erkennen, dass ich der HERR, dein Retter* bin und ich, der Mächtige Jakobs, dein Erlöser*.", footnotes: ["℘ Kap. 49,23.26; 52,6", "o. Helfer", "℘ Kap. 66,1"] },
      { number: 17, text: "Statt der Bronze werde ich Gold bringen und statt des Eisens werde ich Silber bringen, statt der Hölzer Bronze und statt der Steine Eisen*. Als deine Wache* setze ich Frieden ein und als deine Obrigkeit* Gerechtigkeit*.", footnotes: ["℘ Kap. 55,13", "o. Behörde", "o. deine Machthaber", "℘ Ps 72,3"] },
      { number: 18, text: "Nicht mehr wird man von Gewalttat hören in deinem Land, von Verwüstung und Zusammenbruch in deinen Grenzen*; sondern deine Mauern wirst du Rettung nennen* und deine Tore Ruhm.", footnotes: ["℘ Kap. 11,9; 2Sam 7,10", "℘ Kap. 26,1; Sach 2,9"] },
      { number: 19, text: "Nicht mehr wird die Sonne dir als Licht am Tage dienen noch als heller Schein der Mond dir leuchten*; sondern der HERR wird dir zum ewigen Licht sein* und dein Gott zu deinem Glanz*.", footnotes: ["℘ Kap. 24,23", "℘ Ps 84,12; Offb 21,23", "℘ 5Mo 10,21; Sach 2,9; Lk 2,32"] },
      { number: 20, text: "Nicht mehr untergehen wird deine Sonne, noch wird dein Mond abnehmen*; denn der HERR wird dir zum ewigen Licht sein*. Und die Tage deiner Trauer werden ein Ende haben*.", footnotes: ["o. weggenommen werden", "℘ Sach 14,7", "℘ Kap. 35,10"] },
      { number: 21, text: "Und dein Volk, sie alle werden Gerechte sein*, werden das Land besitzen auf ewig*, sie, ein Schössling der Pflanzungen des HERRN*, ein Werk seiner Hände*, sich zu verherrlichen*.", footnotes: ["℘ Kap. 4,3; 52,1; 2Sam 7,10; Zef 3,13", "℘ Kap. 65,9; Ps 37,29; Hes 11,17; 37,25", "℘ Jer 24,6; Am 9,15", "so mit Qu.; Mas. T.: ein Schössling seiner Pflanzung, ein Werk meiner Hände\n℘ Kap. 54,17; Eph 2,10", "℘ Kap. 43,7; 61,3; Jer 32,41"] },
      { number: 22, text: "Der Kleinste wird zu Tausend werden und der Geringste zu einer gewaltigen Nation*. Ich, der HERR, werde es zu seiner Zeit schnell ausführen.", footnotes: ["℘ Mi 4,7"] },
    ]},
    { number: 61, verses: [
      { number: 1, text: "Der Geist des Herrn, HERRN, ist auf mir*; denn der HERR hat mich gesalbt*. Er hat mich gesandt, den Elenden* frohe Botschaft zu bringen*, zu verbinden, die gebrochenen Herzens sind*, Freilassung auszurufen den Gefangenen und Öffnung des Kerkers den Gebundenen*,", heading: "Gute Botschaft vom zukünftigen Heil", footnotes: ["℘ Kap. 42,1; 48,16; Mt 3,16; 12,18", "℘ 2Mo 28,41; Apg 4,27", "o. den Sanftmütigen", "℘ Kap. 52,7; Mt 11,5", "℘ Kap. 57,15; Ps 147,3", "LXX: den Blinden, dass sie wieder sehen\n℘ Kap. 42,7; Ps 68,7"] },
      { number: 2, text: "auszurufen das Gnadenjahr des HERRN* und den Tag der Rache für unsern Gott*, zu trösten alle Trauernden*,", footnotes: ["w. das Jahr des Wohlgefallens für den HERRN\n℘ Kap. 49,8; 3Mo 25,10-28; Lk 4,18.19", "℘ Kap. 35,4; 63,4; 2Thes 1,7.8", "℘ Kap. 51,12; 57,18; Mt 5,4"] },
      { number: 3, text: "den Trauernden Zions Frieden, ihnen Kopfschmuck* statt Asche zu geben, Freudenöl statt Trauer*, ein Ruhmesgewand statt eines verzagten Geistes, damit sie Terebinthen der Gerechtigkeit genannt werden, eine Pflanzung des HERRN, dass er sich durch sie verherrlicht*.", footnotes: ["w. Turban", "℘ Ps 30,12; Joh 16,20", "℘ Kap. 60,21"] },
      { number: 4, text: "Sie werden die uralten Trümmerstätten aufbauen, das früher Verödete* wieder aufrichten. Und sie werden die verwüsteten Städte erneuern, was verödet lag von Generation zu Generation*.", footnotes: ["w. die Verödungen der Früheren", "℘ Kap. 49,8; 58,12; Esr 9,9; Neh 3,34"] },
      { number: 5, text: "Dann werden Fremde dastehen und eure Schafherden weiden, und Ausländer* werden eure Bauern und eure Weingärtner sein*.", footnotes: ["w. Söhne der Fremde", "℘ Kap. 14,2; 60,10-16"] },
      { number: 6, text: "Ihr aber, ihr werdet Priester des HERRN genannt werden*; Diener unseres Gottes wird man zu euch sagen*. Ihr werdet den Reichtum der Nationen genießen und mit ihrer Herrlichkeit euch brüsten*.", footnotes: ["℘ 2Mo 19,6; Offb 1,6", "℘ Kap. 66,21; Jer 33,18", "so mit Qu. und mehreren alten Üs.; Mas. T.: und in ihre Herrlichkeit tauschweise eintreten\n℘ Kap. 54,3; 60,5.11.16"] },
      { number: 7, text: "Weil ihre Schande doppelt war und sie Schmach besaßen als ihr Erbteil*, darum werden sie in ihrem Land das Doppelte besitzen*; ewige Freude wird ihnen zuteil.", footnotes: ["T.; Mas. T.: Anstelle eurer Schande Doppeltes und Schmach — sie werden jubeln über ihr Teil\n℘ Kap. 60,15", "℘ Hi 42,10; Sach 9,12"] },
      { number: 8, text: "Denn ich, der HERR, liebe das Recht*, ich hasse den Raub mitsamt dem Unrecht*. Und ich werde ihnen ihren Lohn in Treue* geben und einen ewigen Bund mit ihnen schließen*.", footnotes: ["℘ Ps 11,7", "So mit einigen hebr. Handschr. und den alten Üs.; Mas. T.: Brandopfer", "o. in Wahrheit", "℘ Kap. 54,10; 55,3; Hes 16,60; 34,25; Hebr 8,8-13"] },
      { number: 9, text: "Und ihre Nachkommen werden bekannt werden unter den Nationen und ihre Sprösslinge inmitten der Völker. Alle, die sie sehen, werden erkennen, dass sie Nachkommen sind, die der HERR gesegnet hat*.", footnotes: ["℘ Kap. 65,23; 4Mo 22,12; Mal 3,12"] },
      { number: 10, text: "Freuen, ja, freuen will ich mich in dem HERRN! Jubeln soll meine Seele in meinem Gott*! Denn er hat mich bekleidet mit Kleidern des Heils*, den Mantel der Gerechtigkeit mir umgetan*, wie der Bräutigam sich nach Priesterart* mit dem Kopfschmuck und wie die Braut sich mit ihrem Geschmeide schmückt*.", footnotes: ["℘ Hab 3,18; Phil 4,4", "o. der Rettung", "℘ Ps 132,9.16; Sach 3,5", "so mit Qu.; Mas. T.: wie der Bräutigam als Priester dient", "℘ 2Mo 28,2.40; Lk 15,22; Offb 21,2"] },
      { number: 11, text: "Denn wie die Erde ihr Gewächs hervorbringt und wie ein Garten seine Saat aufsprossen lässt*, so wird der Herr, HERR, Gerechtigkeit und Ruhm aufsprossen lassen* vor allen Nationen*.", footnotes: ["℘ 1Mo 1,11", "℘ Kap. 45,8", "℘ Kap. 62,2"] },
    ]},
    { number: 62, verses: [
      { number: 1, text: "Zions wegen will ich nicht schweigen, und Jerusalems wegen will ich nicht ruhen, bis seine Gerechtigkeit hervorbricht wie Lichtglanz und sein Heil* wie eine Fackel brennt*.", heading: "Zion — das königliche Diadem in der Hand Gottes", footnotes: ["o. seine Rettung", "℘ Kap. 60,1-3; 61,11; Jer 33,9"] },
      { number: 2, text: "Und die Nationen werden deine Gerechtigkeit sehen und alle Könige deine Herrlichkeit*. Und du wirst mit einem neuen Namen genannt werden, den der Mund des HERRN bestimmen wird*.", footnotes: ["℘ Kap. 60,1-3; 61,11; Jer 33,9", "℘ Kap. 65,15; Offb 2,17"] },
      { number: 3, text: "Und du wirst eine prachtvolle Krone sein in der Hand des HERRN und ein königliches Diadem in der Hand deines Gottes*.", footnotes: ["℘ Sach 9,16"] },
      { number: 4, text: "Nicht länger wird man »Entlassene« zu dir sagen*, und zu deinem Land wird man nicht mehr »Öde« sagen*. Sondern man wird dich nennen »mein Gefallen an ihr«* und dein Land »Verheiratete*«*; denn der HERR wird Gefallen an dir haben, und dein Land wird verheiratet sein*.", footnotes: ["℘ Kap. 54,6", "℘ Hes 36,35", "℘ Ps 16,3; 149,4; Jer 32,41; Röm 9,25", "o. Beregnetes bzw. beregnet sein", "℘ Hos 2,21.22; Mal 3,12", "o. Beregnetes bzw. beregnet sein"] },
      { number: 5, text: "Denn wie der junge Mann die Jungfrau heiratet*, so werden deine Söhne* dich heiraten. Und wie der Bräutigam sich an der Braut freut, so wird dein Gott sich an dir freuen*.", footnotes: ["℘ Hos 2,21.22; Mal 3,12", "bei anderer Vokalisierung: deine Erbauer", "℘ Kap. 65,19; Zef 3,17"] },
      { number: 6, text: "Auf deine Mauern, Jerusalem, habe ich Wächter bestellt*. Den ganzen Tag und die ganze Nacht werden sie keinen Augenblick schweigen*. Ihr, die ihr den HERRN erinnert*, gönnt euch keine Ruhe*", footnotes: ["℘ Jer 6,17; Hes 3,17", "℘ Kap. 52,8", "℘ Ps 74,2", "℘ Lk 18,1-8"] },
      { number: 7, text: "und lasst ihm keine Ruhe, bis er Jerusalem wieder aufrichtet und bis er es zum Lobpreis macht auf Erden*! —", footnotes: ["℘ Ps 122,6-9"] },
      { number: 8, text: "Der HERR hat geschworen bei seiner Rechten und bei seinem starken Arm*: Wenn ich jemals deinen Feinden dein Korn zur Speise gebe und wenn Söhne der Fremde deinen Most trinken werden, für den du dich abgemüht hast*!", footnotes: ["℘ Kap. 59,16", "Die Bedingungssätze in V. 8 sind eine hebr. Schwurformel, deren zweite Hälfte — wahrscheinlich eine Verwünschung — nicht ausgesprochen wurde.\n℘ Kap. 65,21.22; 5Mo 28,30; Am 9,14"] },
      { number: 9, text: "Sondern die es einsammeln, sollen es auch essen und den HERRN loben. Und die ihn einbringen, sollen ihn auch trinken in den Vorhöfen meines Heiligtums*.", footnotes: ["℘ 5Mo 12,7; Jer 31,5.12"] },
      { number: 10, text: "Zieht hindurch, zieht hindurch durch die Tore*! Bereitet den Weg des Volkes! Bahnt, bahnt die Straße, reinigt sie von Steinen*! Richtet ein Feldzeichen auf über den Völkern*!", footnotes: ["℘ Ps 24,7", "℘ Kap. 40,4; 49,11", "℘ Kap. 11,12"] },
      { number: 11, text: "Siehe, der HERR lässt es hören bis ans Ende der Erde hin: Sagt der Tochter Zion: Siehe, dein Heil* kommt*. Siehe, sein Lohn ist bei ihm, und seine Belohnung geht vor ihm her*.", footnotes: ["o. deine Rettung", "℘ Kap. 59,20; Mt 21,5", "℘ Kap. 40,10"] },
      { number: 12, text: "Und man wird sie nennen: das heilige Volk*, die Erlösten des HERRN*; und dich wird man nennen: die Gesuchte*, die nie mehr verlassene Stadt.", footnotes: ["℘ Kap. 63,18; 1Petr 2,9", "℘ Kap. 35,8-10; Ps 107,2", "w. die, nach der man fragt"] },
    ]},
    { number: 63, verses: [
      { number: 1, text: "*Wer ist der, der von Edom kommt, von Bozra* in grellroten Kleidern*, er, der prächtig ist in seinem Gewand, der stolz einherzieht in der Fülle seiner Kraft*? — Ich bin es, der in Gerechtigkeit redet*, der mächtig ist zu retten*. —", heading: "Gericht über Edom und andere Völker", footnotes: ["℘ Kap. 34,1-8", "℘ 1Mo 36,33", "℘ Offb 19,13", "℘ Ps 45,4.5", "℘ Kap. 42,1.3; Ps 65,6", "Eine griech. Üs. und Vulg.: der den Rechtsstreit führt, um zu helfen"] },
      { number: 2, text: "Warum ist Rot an deinem Gewand und sind deine Kleider wie die eines Keltertreters*? —", footnotes: ["℘ Offb 19,13"] },
      { number: 3, text: "Ich habe die Kelter allein getreten*, und von den Völkern war kein Mensch bei mir. Ich zertrat sie* in meinem Zorn und zerstampfte sie in meiner Erregung. Und ihr Saft spritzte auf meine Kleider, und ich besudelte mein ganzes Gewand*.", footnotes: ["℘ Kla 1,15", "d. h. die Völker", "℘ 1Mo 49,11"] },
      { number: 4, text: "Denn der Tag der Rache war in meinem Herzen*, und das Jahr meiner Vergeltung* war gekommen.", footnotes: ["℘ Kap. 13,6.9; 61,2; Jer 50,15; Hes 25,14", "w. Blutrache\n℘ Offb 19,13"] },
      { number: 5, text: "Und ich blickte umher, aber da war keiner, der half. Und ich wunderte mich, aber da war keiner, der mich unterstützte*. Da hat mein Arm mir geholfen*, und mein Grimm, der hat mich unterstützt.", footnotes: ["℘ Ps 107,12", "℘ Kap. 59,16"] },
      { number: 6, text: "Und ich trat die Völker nieder in meinem Zorn und machte sie trunken in meiner Erregung*, und ich ließ ihren Saft zur Erde rinnen.", footnotes: ["℘ Kap. 51,17; Zef 3,8"] },
      { number: 7, text: "Ich will die Gnadenerweise* des HERRN bekennen*, die Ruhmestaten des HERRN, nach allem, was der HERR uns erwiesen hat, und die große Güte gegen das Haus Israel, die er ihnen erwiesen hat nach seinen Erbarmungen und nach der Fülle seiner Gnadenerweise.", heading: "Bußgebet um Erneuerung der Gnadenerweise Gottes", footnotes: ["℘ Ps 103,2; 145,7; Lk 1,78", "o. in Erinnerung bringen"] },
      { number: 8, text: "Er sprach: Fürwahr, mein Volk sind sie*, Söhne, die nicht trügerisch handeln werden*. Und er *wurde ihnen zum Retter*", footnotes: ["℘ Kap. 64,8; 1Sam 12,22", "℘ 5Mo 32,5.20", "so LXX mit der Schreibform des Mas. T. — Die Masoreten ändern das Wort »nicht« in »ihm« und lesen: wurde ihnen zum Retter. 9 In all ihrer Angst war ihm angst. Der Bote seines Angesichts hat sie gerettet.", "℘ Kap. 43,3"] },
      { number: 9, text: "in all ihrer Not*. Nicht Bote noch Engel — er selbst* hat sie gerettet.* In seiner Liebe und in seinem Erbarmen hat er sie erlöst*. Und er hob sie auf und trug sie alle Tage der Vorzeit*.", footnotes: ["o. Angst", "w. sein Angesicht", "so LXX mit der Schreibform des Mas. T. — Die Masoreten ändern das Wort »nicht« in »ihm« und lesen: wurde ihnen zum Retter. 9 In all ihrer Angst war ihm angst. Der Bote seines Angesichts hat sie gerettet.\n℘ 1Mo 48,16; 2Mo 23,20; 33,14", "℘ Kap. 43,1; 2Mo 15,13; 5Mo 7,8", "℘ Kap. 46,3.4; 5Mo 32,11.12"] },
      { number: 10, text: "Sie aber, sie sind widerspenstig gewesen* und haben seinen heiligen Geist betrübt*. Da wandelte er sich ihnen zum Feind: Er selbst kämpfte gegen sie*.", footnotes: ["℘ 5Mo 1,26.43", "℘ Ps 107,11; Apg 7,51; Eph 4,30", "℘ 3Mo 26,17; Ps 78,21.31.59"] },
      { number: 11, text: "Da dachte man wieder an die Tage der Vorzeit, *an Mose und sein Volk*: »Wo ist der, der den Hirten* seiner Herde aus dem Meer heraufführte*?* Wo ist der, der seinen heiligen Geist in ihre Mitte gab*,", footnotes: ["Einige hebr. Handschr. und die syr. Üs. lesen: an seinen Knecht Mose", "Einige hebr. Handschr. und die syr. Üs. lesen: an seinen Knecht Mose", "so mit den meisten hebr. Handschr., LXX und der aram. Üs.; Mas. T.: die Hirten", "so mit einigen hebr. Handschr., Qu. und LXX; Mas. T.: der sie aus dem Meer heraufführte, die Hirten seiner Herde", "℘ Ps 77,12.21; Jer 2,6", "d. h. in die Herde; möglich ist auch: seinen heiligen Geist in sein Inneres legte, d. i. in Mose\n℘ Neh 9,20"] },
      { number: 12, text: "der seinen herrlichen Arm zur Rechten des Mose einherziehen ließ*, der das Wasser vor ihnen spaltete*, um sich einen ewigen Namen zu machen,", footnotes: ["℘ 2Mo 15,6.16; 1Kö 8,42", "℘ Kap. 44,27; Neh 9,10.11; Ps 78,13"] },
      { number: 13, text: "der sie durch die Tiefen* ziehen ließ so sicher wie Pferde in der Steppe, die nicht stürzen*?", footnotes: ["o. Fluten", "℘ Ps 105,37; 106,9"] },
      { number: 14, text: "Wie das Vieh, das in das Tal hinabzieht, brachte der Geist des HERRN sie* zur Ruhe. So hast du dein Volk geleitet, um dir einen herrlichen Namen zu machen*.«", footnotes: ["so mit den alten Üs.; Mas. T.: es; d. i. das Haus Israel; vgl. V. 8", "℘ 2Sam 7,23; Jer 32,20.21"] },
      { number: 15, text: "Blicke vom Himmel herab und sieh von der Wohnstätte deiner Heiligkeit und deiner Majestät*! Wo sind dein Eifer und deine Machttaten? Die Regung deines Innern und deine Erbarmungen halten sich zurück mir gegenüber*.", footnotes: ["℘ 5Mo 26,15", "℘ Ps 77,10; Hos 11,8"] },
      { number: 16, text: "Denn du bist unser Vater*. Denn Abraham weiß nichts von uns, und Israel kennt uns nicht*. Du, HERR, bist unser Vater, unser Erlöser von alters her, das ist dein Name*.", footnotes: ["℘ Kap. 45,11; 64,7", "℘ Pred 9,5", "nach anderer Zeichensetzung: unser Erlöser ist dein Name von alters her\n℘ Kap. 41,14; Jer 3,23"] },
      { number: 17, text: "Warum, HERR, lässt du uns von deinen Wegen abirren, verhärtest unser Herz, dass wir dich nicht fürchten? Kehre zurück deiner Knechte*, der Stämme deines Erbteils wegen*!", footnotes: ["℘ Ps 90,13", "℘ Kap. 19,25"] },
      { number: 18, text: "Für eine kleine Zeit haben sie dein heiliges Volk* vertrieben, unsere Gegner* haben dein Heiligtum zertreten*.", footnotes: ["℘ Kap. 62,12", "Vielleicht lautete der Text ursprünglich: Warum achten die Gottlosen dein heiliges Volk gering? Unsere Gegner", "℘ Kap. 64,9.10; Ps 79,1"] },
      { number: 19, text: "Wir sind wie solche geworden, über die du von alters her nicht geherrscht hast, über denen dein Name nicht ausgerufen ist*. Ach, dass du den Himmel zerrissest, herabstiegest*, so dass vor deinem Angesicht die Berge erbeben*", footnotes: ["℘ Kap. 65,1; Jer 14,9; Dan 9,19", "℘ Ps 18,10", "℘ Ri 5,4.5"] },
    ]},
    { number: 64, verses: [
      { number: 1, text: "— wie Feuer Reisig entzündet, wie Feuer Wasser zum Wallen bringt —, um deinen Namen kundzutun deinen Gegnern*, so dass vor deinem Angesicht die Nationen erzittern,", footnotes: ["℘ Ps 79,10"] },
      { number: 2, text: "wenn du furchtgebietende Taten vollbringst, die wir nicht erwarteten*,", footnotes: ["Im Mas. T. steht an dieser Stelle noch: dass du herabstiegst, so dass vor deinem Angesicht die Berge erbebten\n℘ Kap. 28,21"] },
      { number: 3, text: "und die man von alters her nicht vernahm! Kein Ohr hörte*, kein Auge sah je einen Gott außer dir, der an dem handelt, der auf ihn harrt.", footnotes: ["w. Sie hörten nicht"] },
      { number: 4, text: "Ach, dass du einen anträfest, der freudig Gerechtigkeit übt*, solche*, die auf deinen Wegen an dich denken*! *Siehe, du, du zürntest, weil wir von jeher gegen dich gesündigt* und mit dir gebrochen haben.*", footnotes: ["℘ Apg 10,35", "o. Du nimmst dich dessen an, der freudig Gerechtigkeit übt, all derer", "℘ Ps 103,18", "T.; Mas. T.: Siehe, du, du zürntest, und wir haben dadurch (w. in ihnen) ewig gesündigt und werden gerettet.", "℘ Kap. 59,12; Esr 9,7; Dan 9,5", "T.; Mas. T.: Siehe, du, du zürntest, und wir haben dadurch (w. in ihnen) ewig gesündigt und werden gerettet."] },
      { number: 5, text: "Wir alle sind wie ein Unreiner geworden und all unsere Gerechtigkeiten wie ein beflecktes Kleid*. Wir alle sind verwelkt, wie das Laub welkt*, und unsere Sünden trugen uns davon wie der Wind.", footnotes: ["w. wie ein von der Monatsregel beflecktes Kleid; vgl. 3Mo 15,19—24\n℘ Sach 3,3; Phil 3,8.9", "℘ Kap. 1,30"] },
      { number: 6, text: "Und da war niemand, der deinen Namen anrief*, der sich aufraffte, an dir festzuhalten*. Denn du hast dein Angesicht vor uns verborgen* und uns preisgegeben* wegen unserer Sünden*. —", footnotes: ["℘ Hos 7,7", "℘ Kap. 43,22; 50,2; Dan 9,13", "℘ Kap. 8,17", "so mit LXX, der alten lat., der aram. und syr. Üs.; Mas. T. ist nicht übersetzbar", "w. in die Hand unserer Sünden\n℘ Kap. 1,28; 4Mo 17,27"] },
      { number: 7, text: "Aber nun, HERR, du bist unser Vater*. Wir sind der Ton, und du bist unser Bildner*, und wir alle sind das Werk deiner Hände*.", footnotes: ["℘ Kap. 63,16; Mal 1,6; 2,10", "℘ Kap. 45,9", "℘ Ps 100,3"] },
      { number: 8, text: "HERR, zürne nicht allzu sehr*, und nicht ewig erinnere dich an die Sünde*! Siehe, schau doch her, dein Volk sind wir alle*!", footnotes: ["℘ Kap. 57,16; 2Mo 32,12; Ps 74,1", "℘ Kap. 43,25", "℘ Kap. 63,8; 5Mo 9,29"] },
      { number: 9, text: "Deine heiligen Städte sind eine Wüste geworden, Zion ist eine Wüste geworden, Jerusalem eine Öde*.", footnotes: ["℘ 3Mo 26,31"] },
      { number: 10, text: "Unser heiliges und herrliches Haus*, worin unsere Väter dich lobten*, ist ein Raub des Feuers, und alle unsere Kostbarkeiten sind zu Trümmern geworden*.", footnotes: ["℘ Hag 2,3", "℘ 1Chr 23,5", "℘ Kap. 63,18; Ps 79,7; Kla 1,7.10"] },
      { number: 11, text: "Willst du, HERR, bei alldem an dich halten? Willst du schweigen und uns ganz und gar demütigen*?", footnotes: ["℘ Sach 1,12"] },
    ]},
    { number: 65, verses: [
      { number: 1, text: "Ich war zu erfragen* für die, die nicht nach mir fragten; ich war zu finden für die, die mich nicht suchten. Ich sprach: Hier bin ich, hier bin ich!, zu einer Nation, die meinen Namen nicht anrief*.", heading: "Gottes Urteil über Abtrünnige und Getreue", footnotes: ["o. zu suchen", "so mit LXX und Vulg.; Mas. T.: über der nicht mein Name ausgerufen war\n℘ Kap. 63,19; Apg 28,28"] },
      { number: 2, text: "Ich habe den ganzen Tag meine Hände ausgebreitet zu einem widerspenstigen Volk*, zu solchen, die auf dem Weg, der nicht gut ist*, ihren eigenen Gedanken nachlaufen.", footnotes: ["℘ Mt 23,37; Röm 10,20.21", "℘ Kap. 59,7.8; 66,4; Ps 36,5; Jer 18,12; Eph 2,3"] },
      { number: 3, text: "Die Leute, die mich beständig ins Angesicht reizen*, in den Gärten opfern* und auf Ziegelsteinen Rauchopfer darbringen,", footnotes: ["℘ 5Mo 32,21; 1Kor 10,22", "℘ Kap. 1,29"] },
      { number: 4, text: "die in den Gräbern sitzen und in verborgenen Orten übernachten, die Schweinefleisch essen und Gräuelbrühe* in ihren Gefäßen haben*,", footnotes: ["w. Brühe von unreinem Opferfleisch; vgl. 3Mo 7,18; 19,7", "℘ Kap. 66,17; 3Mo 11,7.8; 5Mo 14,3; Sach 9,7"] },
      { number: 5, text: "die da sagen: Bleib für dich und komm mir nicht nahe, denn ich bin heilig für dich! — diese sind Rauch in meiner Nase, Feuer, das den ganzen Tag brennt." },
      { number: 6, text: "Siehe, aufgeschrieben ist es vor mir. Ich werde nicht schweigen, es sei denn, ich habe vergolten*. In ihren Schoß* vergelte* ich", footnotes: ["℘ Ps 50,3.21", "o. Gewandbausch", "℘ Ps 79,12"] },
      { number: 7, text: "ihre Sünden und die Sünden ihrer Väter* miteinander, spricht der HERR, denen, die auf den Bergen Rauchopfer dargebracht und mich auf den Hügeln verhöhnt haben*. Ich werde ihnen den Lohn für ihr früheres Tun* in ihren Schoß* zumessen*.", footnotes: ["so mit mehreren alten Üs.; Mas. T.: eure Sünden . . . eurer Väter", "℘ 1Kö 22,44; 2Chr 21,11; Hes 20,27.28", "w. ihren früheren Lohn; o. ihre frühere Arbeit", "o. Gewandbausch", "℘ Jer 16,18"] },
      { number: 8, text: "So spricht der HERR: Wie sich Saft in der Traube findet, und man sagt: Vernichte sie nicht, denn ein Segen ist in ihr! — so will ich tun um meiner Knechte willen, dass ich nicht das Ganze vernichte*.", footnotes: ["℘ Kap. 6,13; 1Mo 18,26; Mt 13,29"] },
      { number: 9, text: "Ich werde aus Jakob Nachkommenschaft hervorgehen lassen und aus Juda einen Besitzer* meiner Berge*. Und meine Auserwählten* sollen es besitzen, und meine Knechte sollen dort wohnen*.", footnotes: ["o. Erben", "℘ Hes 36,8-12", "℘ Mt 24,22; Röm 11,5.7", "℘ Kap. 60,21; Ps 69,37; Ob 17"] },
      { number: 10, text: "Und Scharon* wird zum Weideplatz der Schafe und das Tal Achor* zum Lagerplatz der Rinder werden für mein Volk, das mich gesucht hat*.", footnotes: ["℘ 1Chr 27,29", "℘ Jos 7,26", "o. nach mir gefragt hat\n℘ Jer 29,13; 33,12"] },
      { number: 11, text: "Ihr aber, die ihr den HERRN verlasst, die ihr meinen heiligen Berg* vergesst, die ihr dem Gad einen Tisch zurichtet und der Meni* den Mischkrug füllt*:", footnotes: ["℘ Kap. 56,7", "Gad (d. i. der Planet Jupiter) wurde als Glücksgott verehrt, Meni (d. i. der Planet Venus) als Schicksals- oder Bestimmungsgöttin.", "℘ 2Kö 21,3; Jer 7,18"] },
      { number: 12, text: "Ich habe euch für das Schwert bestimmt*, und ihr alle werdet zur Abschlachtung in die Knie brechen*, weil ich gerufen habe, ihr aber nicht geantwortet habt, weil ich geredet habe, ihr aber nicht gehört, sondern getan habt, was böse ist in meinen Augen, und das erwählt habt, woran ich kein Gefallen habe*.", footnotes: ["Im Hebr. ein Wortspiel mit dem Namen der Schicksalsgöttin Meni.", "℘ 3Mo 26,25; Lk 19,44", "℘ Kap. 59,15; 66,4; Jer 35,17; Sach 7,11.12"] },
      { number: 13, text: "Darum, so spricht der Herr, HERR: Siehe, meine Knechte werden essen, ihr aber werdet hungern. Siehe, meine Knechte werden trinken, ihr aber werdet dürsten. Siehe, meine Knechte werden sich freuen, ihr aber werdet beschämt sein*.", footnotes: ["℘ Spr 13,25"] },
      { number: 14, text: "Siehe, meine Knechte werden jubeln von Herzenslust, ihr aber werdet schreien vor Herzeleid und heulen vor Verzweiflung*.", footnotes: ["w. vor Zerbruch des Geistes\n℘ Kap. 50,11; 66,14; Ps 109,28"] },
      { number: 15, text: "Und ihr werdet euren Namen meinen Auserwählten zum Fluchwort hinterlassen*: »Der Herr, HERR, wird dich töten*.« Meine* Knechte aber wird man mit einem andern Namen nennen*.", footnotes: ["℘ Jer 29,22", "℘ Mt 21,41", "so mit einigen LXX-Handschr.; Mas. T.: Seine", "℘ Kap. 62,2"] },
      { number: 16, text: "Daher, wer sich im Land segnet, wird sich bei dem Gott der Treue* segnen*, und wer im Land schwört, wird bei dem Gott der Treue schwören. Denn die früheren Nöte werden vergessen und vor meinen Augen verborgen sein*.", footnotes: ["o. der Wahrheit; w. des Amen", "℘ Kap. 45,23; 5Mo 6,13", "℘ Kap. 54,4; Hi 11,16; Offb 21,4"] },
      { number: 17, text: "Denn siehe, ich schaffe* einen neuen Himmel und eine neue Erde*. Und an das Frühere wird man nicht mehr denken, und es wird nicht mehr in den Sinn kommen.", heading: "Der neue Himmel und die neue Erde", footnotes: ["Hier steht dasselbe Wort wie in 1Mo 1,1.", "℘ Kap. 66,22; 2Petr 3,13"] },
      { number: 18, text: "Vielmehr freut euch und jauchzt allezeit über das, was ich schaffe*! Denn siehe, ich schaffe Jerusalem zum Frohlocken und sein Volk zur Freude*.", footnotes: ["Hier steht dasselbe Wort wie in 1Mo 1,1.\n℘ Kap. 66,10", "℘ 2Chr 6,41; Zef 3,14"] },
      { number: 19, text: "Und ich werde über Jerusalem jubeln und über mein Volk mich freuen*. Und die Stimme des Weinens und die Stimme des Wehgeschreis wird darin nicht mehr gehört werden*.", footnotes: ["℘ Kap. 62,4.5", "℘ Kap. 30,19; 35,10; Ps 144,14; Zef 3,15"] },
      { number: 20, text: "Und es wird dort keinen Säugling mehr geben*, der nur wenige Tage alt wird, und keinen Greis, der seine Tage nicht erfüllte*. Denn der Jüngste wird im Alter von hundert Jahren* sterben, und wer das Alter von hundert Jahren nicht erreicht*, wird als verflucht gelten*.", footnotes: ["w. von dort wird nicht mehr ein Säugling entstehen", "℘ Hi 5,26; Sach 8,4", "w. der Knabe wird als Sohn von hundert Jahren", "w. wer den Sohn von hundert Jahren verfehlt, o. der Sündigende (der Verfehlende) wird (erst) als Sohn von hundert Jahren verflucht werden", "℘ Pred 8,13"] },
      { number: 21, text: "Sie werden Häuser bauen und bewohnen, und Weinberge pflanzen und ihre Frucht essen*.", footnotes: ["℘ Jer 31,5; Am 9,14"] },
      { number: 22, text: "Sie werden nicht bauen und ein anderer bewohnt, sie werden nicht pflanzen, und ein anderer isst*. Denn wie die Lebenszeit des Baumes wird die Lebenszeit* meines Volkes sein, und meine Auserwählten werden das Werk ihrer Hände genießen.", footnotes: ["℘ Kap. 62,8", "w. wie die Tage des Baumes werden die Tage"] },
      { number: 23, text: "Nicht vergeblich werden sie sich mühen*, und nicht zum jähen Tod werden sie zeugen*. Denn sie sind die Nachkommen der Gesegneten des HERRN, und ihre Sprösslinge werden bei ihnen sein*.", footnotes: ["℘ Hes 36,29; Phil 2,16", "o. gebären\n℘ 5Mo 28,41", "℘ Kap. 61,9; Hi 21,8"] },
      { number: 24, text: "Und es wird geschehen: Ehe sie rufen, werde ich antworten; während sie noch reden, werde ich hören*.", footnotes: ["℘ Kap. 30,19; 58,9; 1Mo 24,15.45; 2Kö 19,20; Mt 6,8"] },
      { number: 25, text: "Wolf und Lamm werden zusammen weiden; und der Löwe wird Stroh fressen wie das Rind*; und die Schlange: Staub wird ihre Nahrung sein*. Man wird nichts Böses und nichts Schlechtes tun auf meinem ganzen heiligen Berg*, spricht der HERR.", footnotes: ["℘ Kap. 11,6-8", "℘ 1Mo 3,14", "℘ Kap. 11,9; Apg 3,21"] },
    ]},
    { number: 66, verses: [
      { number: 1, text: "So spricht der HERR: Der Himmel ist mein Thron und die Erde der Schemel meiner Füße*. Wo wäre denn das Haus, das ihr mir bauen könntet, und wo denn der Ort meines Ruhesitzes?*", heading: "Ablehnung von heuchlerischem Gottesdienst — Zukünftige Heilsvollendung für Jerusalem", footnotes: ["℘ Kap. 60,13; 1Chr 28,2; Mt 5,34.35", "℘ 2Sam 7,7; 1Kö 8,27; 2Chr 2,5"] },
      { number: 2, text: "Hat doch meine Hand dies alles gemacht, und alles dies ist geworden*, spricht der HERR*. Aber auf den will ich blicken: auf den Elenden und den, der zerschlagenen Geistes ist* und der da zittert vor meinem Wort*.", footnotes: ["LXX und die syr. Üs. lesen: und mir gehört dies alles", "w. ist der Ausspruch des HERRN\n℘ Kap. 41,20; Apg 7,49.50", "℘ Kap. 57,15", "o. die ihr wegen meines Wortes zittert\n℘ 1Kö 21,29; 2Kö 22,10; 2Chr 34,27; Esr 9,4; Ps 119,120.161"] },
      { number: 3, text: "Wer ein Rind schlachtet, ist wie einer, der einen Menschen erschlägt; wer ein Schaf opfert, ist wie einer, der einem Hund das Genick bricht*; wer Speisopfer opfert: es ist Schweineblut*; wer Weihrauch als Gedächtnisopfer darbringt, ist wie einer, der Unheil* segnet. Wie diese ihre eigenen Wege gewählt haben* und ihre Seele an ihren Scheusalen Gefallen hat,", footnotes: ["℘ Kap. 1,11.13", "℘ Hag 2,14", "w. Zauber", "℘ Kap. 53,6"] },
      { number: 4, text: "so werde auch ich Misshandlung für sie* wählen und über sie bringen, wovor ihnen graut*, weil ich gerufen habe und niemand geantwortet hat*, weil ich geredet und sie nicht gehört haben, sondern getan haben, was böse ist in meinen Augen, und das gewählt haben, woran ich kein Gefallen habe*.", footnotes: ["w. ihre Misshandlungen", "w. ihr Grauen", "℘ Kap. 50,2; 59,15", "℘ Kap. 65,2.12"] },
      { number: 5, text: "Hört das Wort des HERRN, die ihr zittert vor seinem Wort*! Es sagen eure Brüder, die euch hassen, die euch verstoßen meines Namens wegen*: Der HERR erweise sich herrlich*, dass wir auf eure Freude sehen können*! Aber sie werden zuschanden werden*.", footnotes: ["℘ 1Kö 21,29; 2Kö 22,10; 2Chr 34,27; Esr 9,4; Ps 119,120.161", "℘ Lk 6,22; 21,17", "so mit LXX und der syr. Üs.; Mas. T.: der HERR sei geehrt", "℘ Kap. 5,19", "℘ Kap. 26,11"] },
      { number: 6, text: "Schall eines Getöses von der Stadt her! Schall aus dem Tempel*! Schall vom HERRN*, der Vergeltung übt an seinen Feinden*!", footnotes: ["℘ Offb 16,1", "℘ Joe 4,16", "℘ Kap. 26,21; Lk 19,27"] },
      { number: 7, text: "Ehe sie Wehen hatte, hat sie geboren; ehe Geburtsschmerzen sie ankamen, wurde sie von einem Knaben entbunden." },
      { number: 8, text: "Wer hat so etwas je gehört, wer hat dergleichen je gesehen? Wird ein Land an einem einzigen Tag zur Welt gebracht oder eine Nation mit einem Mal geboren? Denn Zion bekam Wehen und gebar auch schon seine Söhne." },
      { number: 9, text: "Sollte ich zum Durchbruch bringen und dann nicht gebären lassen?, spricht der HERR*. Oder sollte ich gebären lassen und dabei den Schoß verschließen?, spricht dein Gott.", footnotes: ["℘ Kap. 37,3; Phil 1,6"] },
      { number: 10, text: "Freut euch mit Jerusalem und jubelt über sie, alle, die ihr sie liebt*! Jauchzt mit ihr in Freude, alle, die ihr über sie getrauert habt*!", footnotes: ["℘ Ps 122,6", "℘ Kap. 65,18; Röm 15,10"] },
      { number: 11, text: "Damit ihr saugt und euch sättigt an der Brust ihrer Tröstungen, damit ihr schlürft und euch labt an der Fülle ihrer Herrlichkeit*.", footnotes: ["℘ Offb 21,24"] },
      { number: 12, text: "Denn so spricht der HERR: Siehe, ich wende ihr Frieden zu wie einen Strom* und die Herrlichkeit der Nationen wie einen überflutenden Bach*. Und ihr werdet saugen. Auf den Armen* werdet ihr getragen und auf den Knien geliebkost werden*.", footnotes: ["℘ Kap. 48,18", "℘ Kap. 60,5-11", "w. An der Seite, o. Auf der Hüfte", "℘ Kap. 14,2"] },
      { number: 13, text: "Wie einen, den seine Mutter tröstet, so will ich euch trösten. An* Jerusalem sollt ihr getröstet werden*.", footnotes: ["o. Und in", "℘ Kap. 51,12"] },
      { number: 14, text: "Ihr werdet es sehen, und euer Herz wird sich freuen*, und eure Gebeine werden sprossen wie das junge Gras*. Und die Hand des HERRN wird sich an seinen Knechten zeigen, aber seine Feinde wird er bedrohen*.", footnotes: ["℘ Joh 16,22", "℘ Hos 14,6", "w. verwünschen\n℘ Kap. 59,18; 65,13-15"] },
      { number: 15, text: "Denn siehe, der HERR kommt im Feuer, und wie der Sturmwind sind seine Wagen*, um seinen Zorn auszulassen in Glut und sein Drohen in Feuerflammen*.", heading: "Gerichtswort über die Treulosen — Sammlung der Zerstreuten", footnotes: ["℘ Sach 6,1", "℘ Kap. 30,27.30; Ps 18,9; Dan 7,10; 2Thes 1,8"] },
      { number: 16, text: "Denn mit Feuer hält der HERR Gericht, mit seinem Schwert vollzieht er es an allem Fleisch*, und die Erschlagenen des HERRN werden zahlreich sein*.", footnotes: ["℘ Hes 28,18.23; 38,22", "℘ Kap. 34,2; Offb 19,17.18"] },
      { number: 17, text: "Die sich weihen und die sich reinigen für die Gärten*, dem einen nach, der* in der Mitte ist, die Schweinefleisch und Abscheuliches und Springmäuse* essen: Allesamt werden sie ein Ende nehmen, spricht der HERR*.*", footnotes: ["d. h. Gärten, in denen Götzendienst stattfand", "o. der einen . . ., die", "℘ 3Mo 11,29", "w. ist der Ausspruch des HERRN", "℘ Kap. 13,9; 65,3-5"] },
      { number: 18, text: "Ich aber, ich kenne ihre Taten und ihre Gedanken*, und ich bin gekommen*, alle Nationen und Sprachen zu versammeln. Und sie werden kommen und meine Herrlichkeit sehen*.", footnotes: ["℘ Ps 94,11; Jer 16,17", "so mit LXX und der alten lat. Üs.; Mas. T.: und ich — ihre Taten und ihre Gedanken — sie kommt", "℘ Kap. 40,5"] },
      { number: 19, text: "Ich richte unter ihnen ein Zeichen auf und sende Entkommene von ihnen zu den Nationen*, nach Tarsis, Put* und Lud, *zu denen, die den Bogen spannen*, nach Tubal und Jawan*, zu den fernen Inseln, die die Kunde von mir nicht gehört und meine Herrlichkeit nicht gesehen haben. Und sie verkünden meine Herrlichkeit unter den Nationen*.", footnotes: ["℘ Mt 28,19", "so mit LXX und Jer 46,9; Mas. T.: Pul", "Mit geringfügiger Änderung lesen andere in Anlehnung an LXX zwei Landesnamen: Meschech und Rosch", "Mit geringfügiger Änderung lesen andere in Anlehnung an LXX zwei Landesnamen: Meschech und Rosch", "d. i. Griechenland\n℘ 1Mo 10,2.4.6.13; Hes 27,10.12.13", "℘ Mal 1,11"] },
      { number: 20, text: "Und sie bringen alle eure Brüder aus allen Nationen als Opfergabe* für den HERRN, auf Pferden, auf offenen Wagen und in überdachten Wagen, auf Maultieren und auf Dromedaren zu meinem heiligen Berg, nach Jerusalem, spricht der HERR*, ebenso wie die Söhne Israel das Speisopfer in einem reinen Gefäß zum Haus des HERRN bringen.", footnotes: ["w. als Speisopfer", "℘ Kap. 49,12.22; 60,4; Zef 3,10"] },
      { number: 21, text: "Und auch von ihnen nehme ich mir einige zu Priestern und zu Leviten, spricht der HERR*.", footnotes: ["℘ Kap. 61,6.8"] },
      { number: 22, text: "Denn wie der neue Himmel und die neue Erde, die ich mache*, vor mir bestehen, spricht der HERR*, so werden eure Nachkommen und euer Name bestehen*.", footnotes: ["℘ Kap. 65,17", "w. ist der Ausspruch des HERRN", "℘ Kap. 59,21; Jer 33,20.21"] },
      { number: 23, text: "Und es wird geschehen: Neumond für Neumond und Sabbat für Sabbat wird alles Fleisch kommen, um vor mir anzubeten*, spricht der HERR*.", footnotes: ["w. um sich anbetend vor mir niederzuwerfen", "℘ Kap. 2,2; Ps 22,28; 65,3; Hes 46,1; Sach 14,16"] },
      { number: 24, text: "Und sie werden hinausgehen und sich die Leichen der Menschen ansehen, die mit mir gebrochen haben. Denn ihr Wurm wird nicht sterben und ihr Feuer nicht verlöschen*, und sie werden ein Abscheu sein für alles Fleisch.", footnotes: ["℘ Kap. 1,31; 48,22; Mal 3,19; Mt 18,9; Mk 9,48"] },
    ]},
  ]
};
